    for (int i = 0; i < sizeof(hmac_hash_functions) / sizeof(hmac_hash_functions[0]); ++i) {
        if (strcmp(hmac_hash_functions[i]->name, algorithm) == 0) {
            return hmac_hash_functions[i];
        }
    }
    // If no matching hash function is found, return the first one in the list
    return hmac_hash_functions[0];
}

// Function to perform the encryption and decryption operations
int encrypt_decrypt(const char *algorithm, const unsigned char *key, size_t key_length,
                    const unsigned char *plaintext, size_t plaintext_length,
                    unsigned char *ciphertext, size_t ciphertext_length,
                    int enc) {
    // Select the appropriate symmetric encryption algorithm based on user input
    EVP_CIPHER *cipher = select_cipher(algorithm);

    // Select the appropriate hash function based on user input
    EVP_MD *hash_function = select_hash_function(algorithm);

    // Select the appropriate key derivation algorithm based on user input
    EVP_PBKDF2_HMAC *key_derivation_algorithm = select_key_derivation_algorithm(algorithm);

    // Select the appropriate cipher mode based on user input
    EVP_CIPHER_CTX *cipher_mode = select_cipher_mode(algorithm);

    // Select the appropriate hash function for HMAC-based key derivation based on user input
    EVP_MD *hmac_hash_function = select_hmac_hash_function(algorithm);

    // Define the encryption and decryption parameters
    EVP_CIPHER_CTX ctx;
    int ciphertext_length_int;

    if (enc) {
        // Encrypt the plaintext using the selected symmetric encryption algorithm
        EVP_EncryptInit(&ctx, cipher, NULL, NULL);
        EVP_EncryptUpdate(&ctx, ciphertext, &ciphertext_length_int, plaintext, plaintext_length);
        EVP_EncryptFinal(&ctx, ciphertext + ciphertext_length_int, &ciphertext_length_int);
        ciphertext_length = ciphertext_length_int;
    } else {
        // Decrypt the ciphertext using the selected symmetric encryption algorithm
        EVP_DecryptInit(&ctx, cipher, NULL, NULL);
        EVP_DecryptUpdate(&ctx, plaintext, &plaintext_length_int, ciphertext, ciphertext_length);
        EVP_DecryptFinal(&ctx, plaintext + plaintext_length_int, &plaintext_length_int);
        plaintext_length = plaintext_length_int;
    }

    // Return the encrypted or decrypted data
    return 0;
}
```
