  if (!handle) {
    fprintf(stderr, "Failed to load library %s: %s\n", name, dlerror());
    return -1;
  }

  // Get function pointers for the implemented algorithms
  algo_t *algo = (algo_t *)dlsym(handle, "algo");
  if (!algo) {
    fprintf(stderr, "Failed to find algorithm %s in library %s\n", name, dlerror());
    return -1;
  }

  // Initialize the algorithm and check for errors
  int err = algo->init(ctx);
  if (err) {
    fprintf(stderr, "Failed to initialize algorithm %s: %d\n", name, err);
    dlclose(handle);
    return -1;
