// Multi-threaded library for managing concurrent access to shared resources using semaphores
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define a structure to hold information about each semaphore
typedef struct {
    int value; // Current value of the semaphore
    bool locked; // Whether the semaphore is currently being used
} SemaphoreInfo;

// Array to hold information about all semaphores
SemaphoreInfo *semaphores = NULL;
int num_semaphores = 0;

// Function to create a new semaphore
int create_semaphore(const char *name, int initial_value) {
    // Check if the semaphore already exists
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            return -1; // Semaphore already exists
        }
    }

    // Add a new semaphore to the array
    num_semaphores++;
    semaphores = realloc(semaphores, num_semaphores * sizeof(SemaphoreInfo));
    memset(&semaphores[num_semaphores - 1], 0, sizeof(SemaphoreInfo));
    strcpy(semaphores[num_semaphores - 1].name, name);
    semaphores[num_semaphores - 1].value = initial_value;
    return num_semaphores - 1;
}

// Function to delete a semaphore
int delete_semaphore(const char *name) {
    // Find the index of the semaphore with the given name
    int i;
    for (i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            break;
        }
    }

    // If the semaphore is not found, return an error
    if (i == num_semaphores) {
        return -1;
    }

    // Remove the semaphore from the array
    for (int j = i + 1; j < num_semaphores; j++) {
        memcpy(&semaphores[j - 1], &semaphores[j], sizeof(SemaphoreInfo));
    }
    num_semaphores--;
    semaphores = realloc(semaphores, num_semaphores * sizeof(SemaphoreInfo));
    return 0;
}

// Function to acquire a semaphore
int acquire_semaphore(const char *name) {
    // Find the index of the semaphore with the given name
    int i;
    for (i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            break;
        }
    }

    // If the semaphore is not found, return an error
    if (i == num_semaphores) {
        return -1;
    }

    // Lock the semaphore and increment its value
    pthread_mutex_lock(&(semaphores[i].mutex));
    semaphores[i].locked = true;
    semaphores[i].value++;
    return 0;
}

// Function to release a semaphore
int release_semaphore(const char *name) {
    // Find the index of the semaphore with the given name
    int i;
    for (i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            break;
        }
    }

    // If the semaphore is not found, return an error
    if (i == num_semaphores) {
        return -1;
    }

    // Decrement the value of the semaphore and unlock it
    semaphores[i].value--;
    pthread_mutex_unlock(&(semaphores[i].mutex));
    semaphores[i].locked = false;
    return 0;
}

// Function to query the value of a semaphore
int get_semaphore_value(const char *name) {
    // Find the index of the semaphore with the given name
    int i;
    for (i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            break;
        }
    }

    // If the semaphore is not found, return an error
    if (i == num_semaphores) {
        return -1;
    }

    // Return the value of the semaphore
    return semaphores[i].value;
}

// Function to clean up the library on shutdown
void cleanup() {
    for (int i = 0; i < num_semaphores; i++) {
        if (semaphores[i].locked) {
            release_semaphore(semaphores[i].name);
        }
    }
    free(semaphores);
}

// Main function for the library
int main() {
    // Register a cleanup function to be called on shutdown
    atexit(cleanup);

    // Add some semaphores to the array
    create_semaphore("my_semaphore", 10);
    create_semaphore("your_semaphore", 5);
    create_semaphore("her_semaphore", 2);

    // Acquire and release some semaphores
    acquire_semaphore("my_semaphore");
    release_semaphore("my_semaphore");
    acquire_semaphore("your_semaphore");
    release_semaphore("your_semaphore");

    // Delete some semaphores
    delete_semaphore("her_semaphore");

    // Clean up the library before exiting
    cleanup();
}']

