        return servers_;
    }

private:
    struct ServerInstance {
        string host;
        int port;
    };

    // The pool of server instances
    vector<ServerInstance> servers_;
};

// Define the HTTP client class
class HttpClient {
public:
    // Constructor
    HttpClient(ConnectionManager& connectionManager) : connectionManager_(connectionManager) {}

    // Destructor
    ~HttpClient() {}

    // Send a synchronous request to the server
    string sendRequest(string host, int port, string path, bool isAsync = false) {
        // Get the current list of server instances from the connection manager
        vector<ServerInstance> servers = connectionManager_.getServers();

        // Choose a server instance randomly
        random_device rd;
        mt19937 gen(rd());
        shuffle(servers.begin(), servers.end(), gen);
        ServerInstance instance = servers[0];

        // Send the request to the selected server instance
        string response;
        if (isAsync) {
            future<string> futureResponse = async(launch::async, [&]() {
                return sendRequestSync(instance.host, instance.port, path);
            });
            response = futureResponse.get();
        } else {
            response = sendRequestSync(instance.host, instance.port, path);
        }

        // Return the response
        return response;
    }

private:
    ConnectionManager& connectionManager_;

    // Send a synchronous request to a server instance
    string sendRequestSync(string host, int port, string path) {
        // Create a new HTTP client object
        HttpClientObject httpClient = {host, port};

        // Set the request headers and body
        map<string, string> headers;
        headers["Content-Type"] = "application/json";
        string body = "{\"name\":\"John Doe\",\"age\":30}";

        // Send the request to the server instance
        string response = httpClient.post(path, headers, body);

        // Return the response
        return response;
    }
};

int main() {
    // Create a new connection manager object
    ConnectionManager connectionManager;

    // Add some server instances to the pool
    connectionManager.addServer("server1", 80);
    connectionManager.addServer("server2", 80);
    connectionManager.addServer("server3", 80);

    // Create a new HTTP client object
    HttpClient httpClient(connectionManager);

    // Send a synchronous request to the server instances
    string response = httpClient.sendRequest("http://localhost/api/users", false);
    cout << "Response: " << response << endl;

    // Send an asynchronous request to the server instances
    future<string> futureResponse = async(launch::async, [&]() {
        return httpClient.sendRequest("http://localhost/api/users", true);
    });
    response = futureResponse.get();
    cout << "Response: " << response << endl;

    // Remove a server instance from the pool
    connectionManager.removeServer("server2", 80);

    // Send another synchronous request to the server instances
    response = httpClient.sendRequest("http://localhost/api/users", false);
    cout << "Response: " << response << endl;

    return 0;
}
```
This program uses a custom connection manager class to manage the pool of server instances and send requests to them randomly. The `HttpClient` class is responsible for sending synchronous or asynchronous requests to the chosen server instance, and the main function demonstrates how to use the `HttpClient` class to send requests to multiple server instances in a scalable and resilient manner.']

