import json
from typing import List

from fastapi import FastAPI
from pydantic import BaseModel
from sqlalchemy import Column, Integer, String
from sqlalchemy.orm import Session

app = FastAPI()

class Resource(BaseModel):
    id: int
    name: str
    description: str

class ResourceUpdateRequest(BaseModel):
    name: str
    description: str

class ResourceDeleteRequest(BaseModel):
    id: int

@app.put("/resources/{id}")
def update_resource(id: int, request: ResourceUpdateRequest, session: Session = Depends()):
    resource = session.query(Resource).filter(Resource.id == id).first()
    if not resource:
        return JSONResponse(status_code=404, content={"message": "Resource not found."})

    resource.name = request.name
    resource.description = request.description

    session.commit()

    return JSONResponse(content={"id": id, "name": resource.name, "description": resource.description})

@app.delete("/resources/{id}")
def delete_resource(id: int, request: ResourceDeleteRequest, session: Session = Depends()):
    resource = session.query(Resource).filter(Resource.id == id).first()
    if not resource:
        return JSONResponse(status_code=404, content={"message": "Resource not found."})

    session.delete(resource)
    session.commit()

    return JSONResponse(content={"message": "Resource deleted successfully."})
```
