<?php

function processUserRequest($request) {
    // validate input
    $validationErrors = validateInput($request);
    if (!empty($validationErrors)) {
        return json_encode(['status' => 'error', 'message' => 'Invalid input data']);
    }

    // determine action based on request method and sub-action
    $action = $_REQUEST['action'] ?? null;
    $subAction = $_REQUEST['sub_action'] ?? null;
    switch ($action) {
        case 'create':
            if ($subAction === 'delete') {
                // delete user with specified ID
                $id = $_REQUEST['id'] ?? null;
                if (!$id) {
                    return json_encode(['status' => 'error', 'message' => 'ID is required for deletion']);
                }
                try {
                    $result = deleteUser($id);
                } catch (Exception $e) {
                    // handle database connection issues and invalid input data
                    return json_encode(['status' => 'error', 'message' => 'Failed to delete user']);
                }
            } else {
                // create new user
                try {
                    $result = createUser($_REQUEST);
                } catch (Exception $e) {
                    // handle database connection issues and invalid input data
                    return json_encode(['status' => 'error', 'message' => 'Failed to create user']);
                }
            }
            break;
        case 'update':
            if (!$id) {
                return json_encode(['status' => 'error', 'message' => 'ID is required for update']);
            }
            try {
                $result = updateUser($_REQUEST);
            } catch (Exception $e) {
                // handle database connection issues and invalid input data
                return json_encode(['status' => 'error', 'message' => 'Failed to update user']);
            }
            break;
        default:
            return json_encode(['status' => 'error', 'message' => 'Invalid action']);
    }

    // log activity
    $log = [
        'action' => $action,
        'sub_action' => $subAction,
        'id' => $id ?? null,
        'user_data' => $_REQUEST,
        'result' => $result,
        'timestamp' => date('Y-m-d H:i:s'),
        'ip_address' => $_SERVER['REMOTE_ADDR']
    ];
    file_put_contents('activity.log', json_encode($log) . PHP_EOL, FILE_APPEND);

    // return JSON response
    return json_encode(['status' => 'success', 'message' => $result]);
}

function validateInput($request) {
    $errors = [];

    // check required fields
    if (!isset($_REQUEST['name'])) {
        $errors[] = 'Name is required';
    }
    if (!isset($_REQUEST['email'])) {
        $errors[] = 'Email is required';
    }
    if (!isset($_REQUEST['password'])) {
        $errors[] = 'Password is required';
    }

    // check email uniqueness
    if (isset($_REQUEST['email'])) {
        $email = $_REQUEST['email'];
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
        $stmt->bindParam(':email', $email);
        $stmt->execute();
        if ($stmt->fetchColumn() > 0) {
            $errors[] = 'Email is already in use';
        }
    }

    // check data types
    foreach ($request as $key => $value) {
        if (is_string($value)) {
            continue;
        }
        $errors[] = "Invalid value for '$key'";
    }

    return empty($errors) ? [] : $errors;
}

function createUser($request) {
    // prepare database query
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
    $stmt->bindParam(':name', $request['name']);
    $stmt->bindParam(':email', $request['email']);
    $stmt->bindParam(':password', $request['password']);

    // execute query and return result
    try {
        $result = $stmt->execute();
    } catch (Exception $e) {
        // handle database connection issues and invalid input data
        throw new Exception("Failed to create user");
    }
    return $result;
}

function updateUser($request) {
    // prepare database query
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
    $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
    $stmt->bindParam(':name', $request['name']);
    $stmt->bindParam(':email', $request['email']);
    $stmt->bindParam(':password', $request['password']);
    $stmt->bindParam(':id', $request['id']);

    // execute query and return result
    try {
        $result = $stmt->execute();
    } catch (Exception $e) {
        // handle database connection issues and invalid input data
        throw new Exception("Failed to update user");
    }
    return $result;
}

function deleteUser($id) {
