namespace WebApplication {
    public static class UpdateElementHandler {
        private const string CDN_URL = "https://cdn.example.com/";
        private const int MAX_CHARS = 10000; // maximum allowed HTML characters
        private const int MEMORY_LIMIT = 128; // MB
        private static readonly List<string> ALLOWED_TAGS = new List<string>() { "div", "p", "span" };
        private static readonly List<string> ALLOWED_ATTRS = new List<string>() { "id", "class", "style" };
        private static readonly List<string> ALLOWED_STYLES = new List<string>() { "color", "font-size", "background-color" };

        public static async Task<HttpResponseMessage> HandleRequest(string sectionId, string elementId, string htmlContent) {
            // validate input data
            if (sectionId == null || elementId == null || htmlContent == null) {
                return new HttpResponseMessage(HttpStatusCode.BadRequest);
            }
            if (!int.TryParse(sectionId, out int sectionInt) || sectionInt < 1) {
                return new HttpResponseMessage(HttpStatusCode.BadRequest);
            }
            if (!int.TryParse(elementId, out int elementInt) || elementInt < 1) {
                return new HttpResponseMessage(HttpStatusCode.BadRequest);
            }
            if (htmlContent.Length > MAX_CHARS) {
                return new HttpResponseMessage(HttpStatusCode.BadRequest);
            }

            // sanitize HTML content
            HtmlDocument doc = new HtmlDocument();
            doc.LoadHtml(htmlContent);
            SanitizeHtml(doc);

            // update element's HTML content
            var section = GetSection(sectionId);
            if (section != null) {
                var element = section.FindDescendant("div").Where(e => e.GetAttributeValue("id", "").Equals(elementId)).FirstOrDefault();
                if (element != null) {
                    element.InnerHtml = doc.DocumentNode.OuterHtml;
                }
            }

            // return response indicating refresh of the page
            HttpResponseMessage response = new HttpResponseMessage(HttpStatusCode.OK);
            response.Content = new StringContent("Refresh", Encoding.UTF8, "text/plain");

            return response;
        }

        private static void SanitizeHtml(HtmlDocument doc) {
            // remove unnecessary tags and attributes
            var nodesToRemove = doc.DocumentNode.SelectNodes("//*[@id or @class]").Where(n => !ALLOWED_TAGS.Contains(n.Name)).ToList();
            foreach (var node in nodesToRemove) {
                node.Remove();
            }

            // remove unwanted attributes and styles
            var attrsToRemove = doc.DocumentNode.SelectNodes("//*[@id or @class]").Where(n => !ALLOWED_ATTRS.Contains(n.GetAttributeValue("name", ""))).ToList();
            foreach (var node in nodesToRemove) {
                node.Attributes.RemoveAll();
            }

            // remove unwanted styles
            var stylesToRemove = doc.DocumentNode.SelectNodes("//*[@id or @class]").Where(n => !ALLOWED_STYLES.Contains(n.GetAttributeValue("style", ""))).ToList();
            foreach (var node in nodesToRemove) {
                node.Attributes["style"].RemoveAll();
            }
        }

        private static HtmlNode GetSection(string sectionId) {
            // get the section element by ID
            var section = doc.DocumentNode.SelectSingleNode($"//div[@id='{sectionId}']");
            if (section == null) {
                return null;
            }

            // check that the section is a div element
            if (!section.Name.Equals("div")) {
                return null;
            }

            return section;
        }
    }
}
