function processFiles(directory, extensions, contentTypes) {
  const cache = new Map(); // Initialize caching mechanism
  const files = []; // Store processed file metadata

  // Recursively walk through directory and filter files based on extensions and content types
  fs.readdirSync(directory).forEach((file) => {
    const fullPath = path.join(directory, file);
    if (fs.lstatSync(fullPath).isFile()) {
      // Check file extension against allowed extensions
      const ext = path.extname(file).toLowerCase();
      if (extensions.includes(ext)) {
        // Check MIME type of file using mime-type library
        const mimeType = mime.lookup(fullPath);
        if (contentTypes.includes(mimeType)) {
          // Add file to cache for faster retrieval later
          cache.set(file, { size: fs.statSync(fullPath).size, mimeType });
          files.push({ name: file, metadata: cache.get(file) });
        }
      }
    } else if (fs.lstatSync(fullPath).isDirectory()) {
      // Recursively call function on subdirectories
