function testModule(label, f, maxRetries = 5, performanceThreshold = 75) {
  let moduleName = label;
  let testName = 'Test';
  let executionDuration = null;

  // Set up mocking framework for each test
  resetMockingFramework();

  // Attempt to load the module up to `maxRetries` times
  let retries = 0;
  while (retries < maxRetries) {
    try {
      f();
      break;
    } catch (e) {
      console.log(`Error loading ${moduleName}:\n${e}`);
      retries++;
      if (retries === maxRetries) {
        throw new Error(`Maximum number of retries exceeded for ${moduleName}.`);
      }
    }
  }

  // Execute the test function and measure its execution time
  const startTime = Date.now();
  f();
  const endTime = Date.now();
  executionDuration = endTime - startTime;

  // Log information about the test run
  console.log(`${moduleName} (${testName}) took ${executionDuration} milliseconds.`);

  // Check if the test exceeded the performance threshold and log a warning
  if (executionDuration > performanceThreshold) {
