function renderFooterScripts(scripts, config) {
  // Initialize a string builder to store the rendered HTML
  const html = [];

  // Iterate over the scripts array
  for (const script of scripts) {
    // Check if the script type is disabled in the configuration
    if (!config.types[script.type]) {
      continue;
    }

    // Create a <script> tag with the appropriate attributes
    const tag = `<script${config.src ? ` src="${script.src}"` : ''} type="${script.type}">`;
    html.push(tag);

    // Add the innerHTML content if available
    if (script.innerHTML) {
      html.push(script.innerHTML);
