                if (!isPaused && streamingDataMap.size() >= serviceTriggerThreshold) {
                    // Aggregate and process data from all sources
                    aggregateAndProcessData();
                } else {
                    // Pause the service for a short duration to avoid excessive CPU usage
                    pauseService(1000);
                }
            }
