function loadLibrary(libraryName, version) {
  const libraryUrl = `https://cdn.example.com/${libraryName}/${version}.js`;
  let libraryScript;

  // Try to fetch the library from the CDN
  try {
    libraryScript = await fetch(libraryUrl);
  } catch (error) {
    console.log(`Error loading ${libraryName} library: ${error}`);
    return;
  }

  if (!libraryScript) {
    // If the script is not available, try to load it from a locally cached version
    const localLibraryUrl = `/${libraryName}/${version}.js`;
    try {
      libraryScript = await fetch(localLibraryUrl);
    } catch (error) {
      console.log(`Error loading ${libraryName} library: ${error}`);
      return;
    }
  }

  // Execute the loaded script within the current context
  const scriptElement = document.createElement('script');
  scriptElement.innerHTML = libraryScript;
  document.head.appendChild(scriptElement);

  // Handle any errors encountered during execution
  window.addEventListener('error', function(event) {
    console.log(`Error executing ${libraryName} library: ${event.message}`);
  });
}

// Load multiple libraries with different priorities
