    private static final int MAX_CACHE_SIZE = 50; // Maximum number of themes to cache
    private static final long DEFAULT_TTL = 24 * 60 * 60 * 1000; // Default theme TTL (24 hours)
    private static final int CLEAR_INTERVAL = 30 * 1000; // Cache clearing interval (30 seconds)

    private Map<String, Theme> cache; // Map of cached themes
    private long lastAccessTime; // Last access time for the cache

    public ThemeCacheManager() {
        this.cache = new HashMap<>();
        this.lastAccessTime = System.currentTimeMillis();
    }

    public void addTheme(String name, InputStream is) throws IOException {
        // Add a theme to the cache if it doesn't exist or if it has been updated recently
        Theme theme = new Theme(name);
        theme.readFromInputStream(is);
        long currentTime = System.currentTimeMillis();
        if (!cache.containsKey(name) || lastAccessTime + DEFAULT_TTL < currentTime) {
            cache.put(name, theme);
        }
    }

    public Theme getTheme(String name) {
        // Get a theme from the cache by its name
        long currentTime = System.currentTimeMillis();
        if (cache.containsKey(name) && lastAccessTime + DEFAULT_TTL > currentTime) {
            return cache.get(name);
        } else {
            return null;
        }
    }

    public void clearCache() {
        // Clear the cache and update the last access time
        cache.clear();
        lastAccessTime = System.currentTimeMillis();
    }

    public void evict(int numToEvict) {
        // Evict the least recently used themes from the cache
        List<String> keys = new ArrayList<>(cache.keySet());
        for (int i = 0; i < Math.min(numToEvict, keys.size()); i++) {
            String key = keys.get(i);
            cache.remove(key);
        }
