        new Thread(() -> {
            SharedPreferences prefs = getSharedPreferences("theme_cache", Context.MODE_PRIVATE);
            int cacheSize = prefs.getInt("cache_size", MAX_CACHE_SIZE);
            if (self.cache.size() > cacheSize) {
