import java.util.*;
import java.time.Duration;

public class MicroserviceOrchestrator {
  private Map<String, Service> services = new HashMap<>(); // map of service IDs to Service objects
  private List<Service> activeServices = new ArrayList<>(); // list of active services
  private long cooldownPeriod; // period for which services should be cooled down before starting again
  private long maxConcurrentServices; // maximum number of concurrently active services
  private double retryLimit; // maximum number of retries for failed service startups
  private double retryDelay; // delay between retries in case of failure
  private MonitoringService monitoringService; // external monitoring service

  public MicroserviceOrchestrator(long cooldownPeriod, long maxConcurrentServices, double retryLimit,
                                    double retryDelay, MonitoringService monitoringService) {
    this.cooldownPeriod = cooldownPeriod;
    this.maxConcurrentServices = maxConcurrentServices;
    this.retryLimit = retryLimit;
    this.retryDelay = retryDelay;
    this.monitoringService = monitoringService;
  }

  public void addService(String serviceId, ServiceConfig config) {
    services.put(serviceId, new Service(config));
  }

  public void startService(String serviceId) {
    Service service = services.get(serviceId);
    if (activeServices.size() < maxConcurrentServices) {
      activeServices.add(service);
      service.start();
      logEvent("Started " + serviceId, Duration.ZERO);
    } else {
      logEvent("Not starting " + serviceId + ", maximum number of concurrent services reached", Duration.ZERO);
    }
  }

  public void stopService(String serviceId) {
    Service service = services.get(serviceId);
    if (activeServices.contains(service)) {
      activeServices.remove(service);
      service.stop();
      logEvent("Stopped " + serviceId, Duration.ZERO);
    } else {
      logEvent("Not stopping " + serviceId + ", service is not active", Duration.ZERO);
    }
  }

  public void updateServiceConfig(String serviceId, ServiceConfig config) {
    services.get(serviceId).updateConfig(config);
  }

  public ServiceConfig getServiceConfig(String serviceId) {
    return services.get(serviceId).getConfig();
  }

