        self.logs.push(format!("INFO: {}", message));
    }

    fn warning(&mut self, message: &str) {
        self.logs.push(format!("WARNING: {}", message));
    }

    fn error(&mut self, message: &str) {
        self.logs.push(format!("ERROR: {}", message));
    }

    fn get_logs(&self) -> String {
        self.logs.join("\n")
    }
}
```
