    cur = db.cursor()
    try:
        cur.execute("INSERT INTO weather_data (city, temperature, humidity, wind_speed) VALUES (%s, %s, %s, %s)", (city, data["temperature"], data["humidity"], data["wind_speed"]))
        db.commit()
        return True
    except Exception as e:
