function fetchAndSaveCertificate(oauthRequest) {
  // Set up API client with OAuth credentials
  const apiClient = new ApiClient(oauthRequest);

  // Set up input stream for certificate data
  const inputStream = apiClient.getInputStream();

  // Create output file for certificate storage
  const outputFile = fs.createWriteStream('certificates.txt');

  // Define buffer size and chunksize for efficient data transfer
  const BUFFER_SIZE = 1024;
  const CHUNK_SIZE = 64 * 1024;

  // Initialize counters for tracking progress
  let totalSize = 0;
  let downloadedSize = 0;

  // Define callback function for data transfer events
  const onDataTransferEvent = (event) => {
    if (event.type === 'progress') {
      totalSize += event.total;
      downloadedSize += event.loaded;
      console.log(`Downloaded ${downloadedSize} of ${totalSize} bytes`);
    } else if (event.type === 'end') {
      console.log('Data transfer complete');
    }
  };

  // Define callback function for network errors and retries
  const onNetworkError = (error) => {
    console.log(`Network error: ${error}`);
    apiClient.retry(onNetworkError);
  };

  // Set up event listeners for data transfer events and network errors
  inputStream.on('data', onDataTransferEvent);
  inputStream.on('end', onDataTransferEvent);
  inputStream.on('error', onNetworkError);

  // Define callback function for memory usage monitoring
  const monitorMemoryUsage = () => {
    if (process.memoryUsage().heapTotal > MAX_MEMORY) {
      console.log(`Memory usage exceeded ${MAX_MEMORY} bytes`);
      apiClient.pause();
      setTimeout(() => {
        apiClient.resume();
      }, 1000);
    }
  };

  // Set up memory usage monitoring interval
  setInterval(monitorMemoryUsage, MEMORY_MONITORING_INTERVAL);

  // Start data transfer and save certificate to file
  inputStream.pipe(outputFile);
}
