#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>

#define MAX_IP_ADDR_LEN 16 // maximum length of an IPv4 or IPv6 address in dotted decimal notation
#define MAX_HOSTNAME_LEN 256 // maximum length of a hostname

typedef enum {
    SUCCESS = 0,
    FAILURE = 1,
    RESOLUTION_FAILURE = 2,
    API_CALL_FAILURE = 3,
} error_code;

// Global variables
static char* cached_ip_addrs[MAX_HOSTNAME_LEN] = {NULL}; // cache for previously resolved IP addresses
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // mutex to protect the cache

error_code resolve_hostname(const char* hostname, u_char** ip_addr) {
    error_code retval = SUCCESS;
    struct addrinfo hints, *res;

    // Validate input parameters
    if (hostname == NULL || ip_addr == NULL) {
        return FAILURE;
    }

    // Check if the hostname is already cached
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_HOSTNAME_LEN; i++) {
        if (cached_ip_addrs[i] != NULL && strcmp(hostname, cached_ip_addrs[i]) == 0) {
            *ip_addr = cached_ip_addrs[i];
            pthread_mutex_unlock(&mutex);
            return SUCCESS;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Resolve the hostname to an IP address using getaddrinfo()
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        retval = RESOLUTION_FAILURE;
        goto cleanup;
    }

    // Allocate memory for the IP address string
    *ip_addr = malloc(MAX_IP_ADDR_LEN);
    if (*ip_addr == NULL) {
        retval = FAILURE;
        goto cleanup;
    }

    // Convert the resolved IP address to a string and store it in the cache
    char ip_str[INET6_ADDRSTRLEN];
    if (getnameinfo(res->ai_addr, res->ai_addrlen, ip_str, sizeof(ip_str), NULL, 0, NI_NUMERICHOST) != 0) {
        retval = RESOLUTION_FAILURE;
        goto cleanup;
    }
    strcpy(*ip_addr, ip_str);

    // Store the resolved IP address in the cache
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_HOSTNAME_LEN; i++) {
        if (cached_ip_addrs[i] == NULL) {
            cached_ip_addrs[i] = *ip_addr;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

cleanup:
    freeaddrinfo(res);
    return retval;
}

error_code fetch_user_data(const char* hostname, const char* access_token) {
    error_code retval = SUCCESS;

    // Validate input parameters
    if (hostname == NULL || access_token == NULL) {
        return FAILURE;
    }

    // Perform an API call to fetch user data using the OAuth 2.0 access token
    // Note: This implementation assumes that the API endpoint is reachable and returns JSON data
    char api_url[MAX_HOSTNAME_LEN + MAX_PATH_LEN];
    sprintf(api_url, "%s%s", hostname, "/api/v1/user");
    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Authorization: Bearer " access_token);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            retval = API_CALL_FAILURE;
        }
    } else {
        retval = FAILURE;
    }

    // Handle potential errors during the API call
    if (retval != SUCCESS) {
        goto cleanup;
    }

cleanup:
    curl_easy_cleanup(curl);
    return retval;
}
```
