// Structure to represent a state in the linked list
typedef struct State {
    int id;
    struct State* next;
} State;

// Function to create a new state based on an FSA and a configuration structure
State* create_state(FSA* fsa, Configuration* config) {
    // Check for invalid pointers or configuration violations
    if (!fsa || !config || config->memory_threshold <= 0 || config->logging_level < 0 || config->logging_level > 3) {
        return NULL;
    }

    // Allocate memory for the new state
    State* new_state = (State*)malloc(sizeof(State));
    if (!new_state) {
        return NULL;
    }

    // Initialize the new state with the ID and next pointer
    new_state->id = fsa->initial_states[config->initial_state_index];
    new_state->next = NULL;

    // Check if memory allocation threshold is exceeded
    if (config->memory_threshold > 0 && config->num_states >= config->memory_threshold) {
        free(new_state);
        return NULL;
    }

    // Increment the number of states
    config->num_states++;

    // Execute the callback function for each state in the list
    if (config->callback) {
        config->callback(fsa, new_state, config);
    }

    return new_state;
}

// Function to delete a state from the linked list
void delete_state(State* state) {
    // Check for invalid pointers
    if (!state) {
        return;
    }

    // Free the memory allocated for the state
    free(state);

    // Decrement the number of states
    config->num_states--;
}

// Function to dynamically manage a linked list of states based on an FSA and a configuration structure
State* manage_states(FSA* fsa, Configuration* config) {
    // Check for invalid pointers or configuration violations
    if (!fsa || !config || config->memory_threshold <= 0 || config->logging_level < 0 || config->logging_level > 3) {
        return NULL;
    }

    // Initialize the head of the state list
    State* head = NULL;

    // Iterate over each initial state in the FSA
    for (int i = 0; i < fsa->num_initial_states; i++) {
        // Create a new state based on the FSA and configuration structure
        State* new_state = create_state(fsa, config);
        if (!new_state) {
            // Free the memory allocated for the states in the linked list
            delete_state(head);
            return NULL;
        }

        // Add the new state to the head of the linked list
        new_state->next = head;
        head = new_state;
    }

    return head;
}
