using namespace std;

// Define attack structs with cooldown and mana requirements
struct Attack {
    int cooldown;
    int mana;
};

Attack attackA = {9, 10};
Attack attackB = {12, 15};
Attack attackC = {6, 5};
Attack attackD = {8, 7};

// Define character struct with mana and attack history
struct Character {
    int mana;
    vector<Attack> attacks;
};

// Function to select attack dynamically based on cooldown and resource requirements
void selectAttack(Character &character) {
    // Check if any attack is on cooldown
    for (auto &attack : character.attacks) {
        if (attack.cooldown > 0) {
            cout << "Attack " << attack.cooldown << " on cooldown!" << endl;
            return;
        }
    }

    // Select attack with highest mana requirement and lowest cooldown time
    int bestMana = -1, bestCooldown = INT_MAX;
    for (auto &attack : character.attacks) {
        if (character.mana >= attack.mana && attack.cooldown < bestCooldown) {
            bestMana = attack.mana;
            bestCooldown = attack.cooldown;
        }
    }

    // If no attack can be selected, return early
    if (bestMana == -1 || bestCooldown == INT_MAX) {
        cout << "No attack available!" << endl;
        return;
    }

    // Select attack and update mana and cooldown
    character.attacks.push_back({ bestMana, bestCooldown });
    character.mana -= bestMana;
    cout << "Attack selected: " << bestMana << ", cooldown: " << bestCooldown << endl;
}

// Function to regenerate mana over time
void regenerateMana(Character &character) {
    character.mana = min(2, character.mana + 1);
}

int main() {
    Character character;
    character.mana = 20;
    character.attacks = { attackA, attackB, attackC, attackD };

    while (true) {
        selectAttack(character);
        regenerateMana(character);
        this_thread::sleep_for(chrono::seconds(1));
    }
}
```
