int load_config(const char* path) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        printf("Error opening config file\n");
        return -1;
    }

    // Get the number of lines in the file
    int num_lines = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file) != NULL) {
        num_lines++;
    }

    // Allocate memory for the keys and values
    char** keys = malloc(num_lines * sizeof(char*));
    if (keys == NULL) {
        printf("Error allocating memory\n");
        fclose(file);
        return -1;
    }

    // Read each line of the file and extract the key
    rewind(file);
    int i = 0;
    while (fgets(line, sizeof(line), file) != NULL) {
        char* token = strtok(line, "=");
        keys[i++] = strdup(token);
    }

    // Free the memory allocated for the file
    fclose(file);

    return keys;
}

void free_config(char** keys) {
    if (keys == NULL) {
        return;
    }

    for (int i = 0; keys[i] != NULL; ++i) {
        free(keys[i]);
    }
    free(keys);
}

// Example usage:
char* path = "config.txt";
char** keys = load_config(path);
if (keys == NULL) {
    printf("Error loading config file\n");
} else {
    for (int i = 0; keys[i] != NULL; ++i) {
        printf("%s\n", keys[i]);
    }
    free_config(keys);
}']

