char *traverseAndLimitString(const char *input, size_t limit, void (*selector)(void *), config_t *config) {
  if (!input || !selector || !config) {
    return NULL;
  }

  // Initialize result string and set current size to zero
  char *result = malloc(limit);
  memset(result, 0, limit);

  // Traverse DOM tree using selector function
  void (*traverse_dom)(void *) = (void (*)(void *))selector;
  traverse_dom((void *)input);

