    size_t text_size = strlen(text);
    if (current_size + text_size > limit) {
      free(result);
      return NULL;
    }

    // Append text content to result string
    memcpy(&result[current_size], text, text_size);
    current_size += text_size;
  }

  // Check if resulting string exceeds size limit
  if (current_size == 0 || current_size > limit) {
    free(result);
    return NULL;
