int extractTiffInfo(const char* filename, struct TiffInfo* info) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1;  // Error opening file
    }

    // Read the header of the TIFF file and check the byte order
    unsigned char header[4];
    fread(header, 1, 4, file);
    int byteOrder = (header[0] == 0x49 && header[1] == 0x49) ? 0 : 1;

    // Read the image width and height
    unsigned char widthAndHeight[4];
    fread(widthAndHeight, 1, 4, file);
    int width = byteOrder ? widthAndHeight[2] << 8 | widthAndHeight[3] : widthAndHeight[0] << 8 | widthAndHeight[1];
    int height = byteOrder ? widthAndHeight[4] << 8 | widthAndHeight[5] : widthAndHeight[6] << 8 | widthAndHeight[7];

    // Read the bits per sample and samples per pixel
    unsigned char bpsAndspp[2];
    fread(bpsAndspp, 1, 2, file);
    info->bitsPerSample = byteOrder ? bpsAndspp[0] : bpsAndspp[1];
    info->samplesPerPixel = byteOrder ? bpsAndspp[1] : bpsAndspp[0];

    // Read the number of extra samples
    unsigned char numExtraSamples[2];
    fread(numExtraSamples, 1, 2, file);
    info->numExtraSamples = byteOrder ? numExtraSamples[0] : numExtraSamples[1];

    // Read the details of each extra sample
    unsigned char extraSampleData[32 * info->numExtraSamples];
    fread(extraSampleData, 1, 32 * info->numExtraSamples, file);
    for (int i = 0; i < info->numExtraSamples; i++) {
        int sampleId = byteOrder ? extraSampleData[i * 32 + 0] : extraSampleData[i * 32 + 1];
        int sampleType = byteOrder ? extraSampleData[i * 32 + 1] : extraSampleData[i * 32 + 2];
        info->extraSamples[i].sampleId = sampleId;
        info->extraSamples[i].sampleType = sampleType;
    }

    // Close the file and return success
    fclose(file);
    return 0;
}

int calculateMd5Hash(const char* input) {
    // Create a MD5 context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Process the input string in chunks
    unsigned char chunk[16];
    int i = 0;
    while (i < strlen(input)) {
        int j = 0;
        while (j < 16 && i < strlen(input)) {
            chunk[j] = input[i++];
            j++;
        }
        MD5Update(&ctx, chunk, j);
    }

    // Finalize the hash and return it as a hex string
    unsigned char md5hash[16];
    MD5Final(md5hash, &ctx);
    char* hex = malloc(32 * sizeof(char));
    for (int i = 0; i < 16; i++) {
        sprintf(&hex[i * 2], "%02x", md5hash[i]);
    }
    return hex;
}
