// Define a structure to hold filename and metadata
typedef struct {
    char *filename;
    size_t filesize;
    time_t lastmodified;
} fileinfo_t;

// Function to process filenames according to specified criteria
void process_filenames(fileinfo_t *filenames, int num_filenames) {
    // Initialize variables for counting vowels and digits
    int num_vowels = 0;
    int num_digits = 0;

    // Loop through each filename and determine if it needs to be modified
    for (int i = 0; i < num_filenames; i++) {
        // Get the current filename and metadata
        fileinfo_t *current_filename = &filenames[i];

        // Check if the file is larger than the threshold size limit
        if (current_filename->filesize > 1024*1024) {
            // Extract the base name and extension from the filename
            char *base_name = strtok(current_filename->filename, ".");
            char *extension = strrchr(current_filename->filename, '.');
            if (extension != NULL) {
                // Count the number of vowels in the base name
                for (int j = 0; j < strlen(base_name); j++) {
                    if (base_name[j] == 'a' || base_name[j] == 'e' || base_name[j] == 'i' || base_name[j] == 'o' || base_name[j] == 'u') {
                        num_vowels++;
                    }
                }
                // Determine the number of digits to append to the extension
                if (num_vowels > 3) {
                    num_digits = 3;
                } else {
                    num_digits = num_vowels;
                }
            } else {
                // Handle filenames without extensions
                num_digits = 0;
            }

            // Construct the new filename using sprintf and strcat
            char new_filename[256];
            snprintf(new_filename, sizeof(new_filename), "%s.%.*d", base_name, num_digits, num_vowels);

            // Check if the new filename is too long
            if (strlen(new_filename) > 256) {
                printf("Error: New filename exceeds 256 characters\n");
            } else {
                // Modify the filename in the array of filenames
                strcpy(current_filename->filename, new_filename);
            }
        }
    }
}

int main() {
    // Define an array of filenames and their corresponding metadata
    fileinfo_t filenames[] = {
        {"file1.txt", 1024*1024, 1635849713},
        {"file2.docx", 1024*1024+100, 1635849723},
        {"file3.jpg", 1024*1024-100, 1635849733},
        {"file4.mp4", 1024*1024+1000, 1635849743}
    };

    // Call the process_filenames function to modify the filenames
    int num_filenames = sizeof(filenames) / sizeof(fileinfo_t);
    process_filenames(filenames, num_filenames);

    // Print the modified filenames
    for (int i = 0; i < num_filenames; i++) {
        printf("%s\n", filenames[i].filename);
    }

    return 0;
}
