int run_background_task(char *command, char *log_file) {
    // Check if the command is empty or NULL
    if (command == NULL || strlen(command) == 0) {
        return -1;
    }

    // Get the default background task from the environment variable
    const char *default_task = getenv(BACKGROUND_TASK_ENV);
    if (default_task != NULL) {
