    struct stat st;
    if (stat(command, &st) < 0) {
        syslog(LOG_WARNING, "Failed to access background task: %s", strerror(errno));
        return -1;
    }

    // Establish robust signal handling to ensure that the background process terminates gracefully when the parent process receives a termination signal
    struct sigaction act;
    memset(&act, 0, sizeof(struct sigaction));
    act.sa_handler = handle_signal;
    if (sigaction(SIGINT, &act, NULL) < 0 || sigaction(SIGTERM, &act, NULL) < 0 || sigaction(SIGHUP, &act, NULL) < 0) {
        syslog(LOG_WARNING, "Failed to set up signal handling for background task: %s", strerror(errno));
        return -1;
    }

    // Handle potential race conditions by ensuring that the command does not start until all required resources are available and that logs are updated accurately in case of rapid system changes
    struct BackgroundTaskQueue queue;
