    public class WebsiteDirectoryManager
    {
        private static readonly object _lock = new object();
        private static readonly Dictionary<int, string> _availablePorts = new Dictionary<int, string>();
        private static readonly int[] _portPool = Enumerable.Range(1024, 65536).ToArray();

        public WebsiteDirectoryManager()
        {
            InitializeAvailablePorts();
        }

        private void InitializeAvailablePorts()
        {
            // Populate the available ports dictionary with a range of ports
            foreach (var port in _portPool)
            {
                _availablePorts.Add(port, null);
            }
        }

        public Website AddSite(string siteName, string directoryPath)
        {
            // Verify the presence of a web.config file before adding the site
            if (!File.Exists($"{directoryPath}\\web.config"))
            {
                return null;
            }

            // Acquire a lock to prevent concurrent access to the available ports dictionary
            lock (_lock)
            {
                var port = GetNextAvailablePort();
                _availablePorts[port] = siteName;
            }

            // Create and return a new Website instance
            return new Website(siteName, directoryPath, port);
        }

        private int GetNextAvailablePort()
        {
            // Acquire the first available port from the pool
            var port = _portPool.FirstOrDefault(p => !_availablePorts.ContainsKey(p));
            if (port == null)
            {
                throw new InvalidOperationException("All ports are currently in use.");
            }

            return port;
        }
    }

