int processSecureMessage(struct SecureMessageProcessor *processor, const char *encrypted_message, const char *key, const char *iv) {
    if (processor->secure_token == NULL || processor->session_context == NULL || processor->callback == NULL) {
        return -1;
    }

    // Check that the provided IV is of the correct length
    if (strlen(iv) != 8) {
        return -2;
    }

    // Decrypt the Base64-encoded message using Triple DES encryption with the provided key and IV
    char *decrypted_message = NULL;
    int error = des_decode(encrypted_message, key, iv, &decrypted_message);
    if (error != 0) {
        // Handle potential decryption failures gracefully by invoking the callback mechanism if available
        if (processor->callback != NULL) {
            processor->callback();
        }
        return error;
    }

    // Ensure proper resource management and deallocation of any intermediate structures used during processing
    free(decrypted_message);
    return 0;
}
