struct jwt_claims {
    char *sub;
    char *iss;
    time_t exp;
    time_t nbf;
};

bool validate_jwt(const char *token, const char *secret, struct jwt_claims *claims) {
    bool valid = false;

    // Parse the JWT and retrieve the claims
    json_object *json = json_tokener_parse(token);
    if (!json || !json_is_object(json)) {
        return valid;
    }

    const char *sub = json_object_get_string(json, "sub");
    const char *iss = json_object_get_string(json, "iss");
    time_t exp = json_object_get_int(json, "exp");
    time_t nbf = json_object_get_int(json, "nbf");

    // Validate the claims
    if (!sub || !iss || exp == 0 || nbf == 0) {
        return valid;
    }

    // Verify the signature
    const char *alg = json_object_get_string(json, "alg");
    if (strcmp(alg, "HS256") == 0) {
        valid = HMAC_verify(EVP_sha256(), token, strlen(token), secret, strlen(secret));
    } else if (strcmp(alg, "HS512") == 0) {
        valid = HMAC_verify(EVP_sha512(), token, strlen(token), secret, strlen(secret));
    } else {
        return valid;
    }

    // Validate the issuer and subject
    const char *allowed_issuers[] = {"https://example.com", "https://example2.com"};
    const char *allowed_subjects[] = {"user1", "user2"};

    for (int i = 0; i < sizeof(allowed_issuers) / sizeof(char*); i++) {
        if (!strcmp(iss, allowed_issuers[i])) {
            valid = true;
            break;
        }
    }

    for (int i = 0; i < sizeof(allowed_subjects) / sizeof(char*); i++) {
        if (!strcmp(sub, allowed_subjects[i])) {
            valid = true;
            break;
        }
    }

    // Validate the expiration time
    struct tm *exp_tm = localtime(&exp);
    if (exp_tm->tm_year < 2010 || exp_tm->tm_mon < 9) {
        valid = false;
    }

    // Fill in the claims structure
    claims->sub = sub;
    claims->iss = iss;
    claims->exp = exp;
    claims->nbf = nbf;

    return valid;
}
