    foreach (string key in keys)
    {
        dataTable.Columns.Add(key, typeof(string));
    }

    // Query the database and fill the data table with the results
    using (var dbConnection = new SqlConnection("Server=myServerAddress;Database=myDataBase;User Id=myUsername;Password=myPassword"))
    {
        string query = "SELECT * FROM myTable WHERE key IN (" + String.Join(",", keys) + ")";
        using (var dbCommand = new SqlCommand(query, dbConnection))
        {
            dbConnection.Open();
            using (var reader = dbCommand.ExecuteReader())
            {
                while (reader.Read())
                {
                    dataTable.Rows.Add(reader[0]);
                }
            }
        }
    }

    // Return the data table reader
    return dataTable.CreateDataReader();
}

private List<string> ExtractKeysFromConfig(byte[] configFileBytes)
{
    // Parse the configuration file and extract the list of keys
    List<string> keys = new List<string>();
    using (var stream = new MemoryStream(configFileBytes))
    {
        using (var reader = new StreamReader(stream))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                if (line.StartsWith("key"))
                {
                    keys.Add(line.Substring(4).Trim());
                }
            }
        }
    }
    return keys;
}
