using System.Threading.Tasks;

public class FileHasher
{
    private static Dictionary<string, string> _cachedFileHashes = new Dictionary<string, string>();

    public static async Task<List<FileMetadata>> GetFileMetadataAndHashAsync(IEnumerable<string> filePaths)
    {
        var tasks = new List<Task<FileMetadata>>();
        foreach (var filePath in filePaths)
        {
            if (_cachedFileHashes.ContainsKey(filePath))
            {
                tasks.Add(Task.FromResult(_cachedFileHashes[filePath]));
            }
            else
            {
                tasks.Add(GetFileMetadataAndHashAsync(filePath));
            }
        }

        var results = await Task.WhenAll(tasks);
        return results.ToList();
    }

    private static async Task<FileMetadata> GetFileMetadataAndHashAsync(string filePath)
    {
        try
        {
            using (var stream = new FileStream(filePath, FileMode.Open))
            {
                var metadata = await GetFileMetadataAsync(stream);
                var hash = await CalculateSHA256HashAsync(stream);
                return new FileMetadata(metadata.Size, metadata.LastModifiedDate, hash);
            }
        }
        catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
        {
            // Handle exceptions gracefully and provide meaningful feedback for invalid paths
            return new FileMetadata(0, DateTime.MinValue, string.Empty);
        }
    }

    private static async Task<FileSystemInfo> GetFileMetadataAsync(Stream stream)
    {
        var fileInfo = await FileSystemInfo.FromStreamAsync(stream);
        return fileInfo;
    }

    private static async Task<string> CalculateSHA256HashAsync(Stream stream)
    {
        using (var sha256 = SHA256.Create())
        {
            var hash = await sha256.ComputeHashAsync(stream);
            return BitConverter.ToString(hash).Replace("-", string.Empty).ToLowerInvariant();
        }
    }
}

public class FileMetadata
{
    public long Size { get; set; }
    public DateTime LastModifiedDate { get; set; }
    public string Hash { get; set; }

    public FileMetadata(long size, DateTime lastModifiedDate, string hash)
    {
        this.Size = size;
        this.LastModifiedDate = lastModifiedDate;
        this.Hash = hash;
    }
}
