    TarArchiveInputStream tarIn = new TarArchiveInputStream(inputStream);

    // Initialize the map to store the extracted JSON documents
    Map<String, Object> jsonDocuments = new HashMap<>();

    try {
      TarArchiveEntry entry;
      while ((entry = tarIn.getNextTarEntry()) != null) {
        if (entry.isDirectory()) {
          continue;
        }

        // Extract the JSON document from the current entry
        String jsonDocument = IOUtils.toString(tarIn, StandardCharsets.UTF_8);

        try {
          // Parse the JSON document into a Java object using Gson's JsonParser
          JsonObject root = new JsonParser().parse(jsonDocument).getAsJsonObject();

          // Get the unique identifier of the document from the JSON structure
          String id = root.get("id").getAsString();

          // Store the parsed JSON object in the map, using the id as the key
          jsonDocuments.put(id, root);
        } catch (JsonParseException e) {
          // Log an error message if parsing fails
          log.error("Failed to parse JSON document: " + jsonDocument, e);
        }
      }
    } finally {
      tarIn.close();
    }

    return jsonDocuments;
  }

