['```rust
use std::env;
use std::time::Duration;
use tokio::runtime::Handle;
use tokio::select;
use tokio_json::JsonValue;
use reqwest::Client;
use reqwest::header::{CONTENT_TYPE, ACCEPT};
use serde_json::Value;

const CONFIG_ENDPOINT: &str = "https://example.com/config";
const CACHE_SIZE: usize = 1000;

#[derive(Debug)]
struct TaskConfig {
    url: String,
    method: String,
    headers: Vec<String>,
}

impl TaskConfig {
    fn new() -> Self {
        Self {
            url: "".to_string(),
            method: "".to_string(),
            headers: vec![],
        }
    }

    fn from_json(json: &JsonValue) -> Result<Self, &'static str> {
        let url = json["url"].as_str().ok_or("URL missing")?;
        let method = json["method"].as_str().unwrap_or("GET");
        let headers = json["headers"]
            .as_array()
            .map(|arr| arr.iter().map(|v| v.to_string()).collect())
            .unwrap_or_else(Vec::new);

        Ok(Self { url, method, headers })
    }
}

async fn fetch_config() -> Result<TaskConfig, &'static str> {
    let client = Client::builder().build().map_err(|_| "Error building client")?;
    let request = client
        .get(CONFIG_ENDPOINT)
        .header(CONTENT_TYPE, "application/json")
        .header(ACCEPT, "application/json");
    let response = request.send().await.map_err(|_| "Error sending request")?;
    let json = response.json::<Value>().await.map_err(|_| "Error parsing JSON")?;

    TaskConfig::from_json(&json)
}

async fn execute_task(config: &TaskConfig, args: Vec<String>) -> Result<(), &'static str> {
    let client = Client::builder().build().map_err(|_| "Error building client")?;
    let request = match config.method.as_str() {
        "GET" => client.get(config.url.clone()),
        "POST" => client.post(config.url.clone()),
        "PUT" => client.put(config.url.clone()),
        "DELETE" => client.delete(config.url.clone()),
        _ => return Err("Invalid HTTP method"),
    };

    if !config.headers.is_empty() {
        for header in config.headers.iter() {
            request = request.header(header.as_str(), "");
        }
    }

    let response = request
        .json(&args)
        .send()
        .await
        .map_err(|_| "Error sending request")?;

    if !response.status().is_success() {
        return Err("Response status not success");
    }

    Ok(())
}

async fn run_task(args: Vec<String>) -> Result<(), &'static str> {
    let config = fetch_config().await?;
    execute_task(&config, args).await
}

fn main() {
    Handle::current()
        .block_on(run_task(env::args().skip(1).collect()))
        .unwrap();
}
```']

