#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>

// Define the maximum number of records that can be stored in the data store
#define MAX_RECORDS 10000

// Define the range of key and offset values
#define KEY_RANGE 100
#define OFFSET_RANGE 100

// Define the maximum number of cryptographic operations that can be performed concurrently
#define MAX_CRYPTO_OPS 5

// Define the structure to store a record in the data store
struct Record {
    int key;
    int offset;
    unsigned char* value;
};

// Define the global variables for the data store and the mutex for thread-safe access
static struct Record* records = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the data store with a specified number of records
void initializeDataStore(int numRecords) {
    // Check if the number of records is within the acceptable range
    if (numRecords < 0 || numRecords > MAX_RECORDS) {
        printf("Invalid number of records. Must be between 0 and %d\n", MAX_RECORDS);
        return;
    }

    // Allocate memory for the records
    records = malloc(numRecords * sizeof(struct Record));

    // Initialize the records with random key and offset values and random byte values
    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        struct Record* record = &records[i];
        record->key = rand() % KEY_RANGE + 1;
        record->offset = rand() % OFFSET_RANGE + 1;
        record->value = malloc(record->offset);
        memset(record->value, i, record->offset);
    }
}

// Add a new record to the data store with a specified key and value
void addRecord(int key, unsigned char* value) {
    // Check if the key is within the acceptable range
    if (key < 1 || key > KEY_RANGE) {
        printf("Invalid key. Must be between 1 and %d\n", KEY_RANGE);
        return;
    }

    // Obtain a lock on the data store to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Check if the data store is full
    if (numRecords == MAX_RECORDS) {
        printf("Data store is full. Cannot add new record\n");
        return;
    }

    // Find an empty slot in the data store for the new record
    struct Record* record = NULL;
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == 0) {
            record = &records[i];
            break;
        }
    }

    // Check if an empty slot was found
    if (record == NULL) {
        printf("Data store is full. Cannot add new record\n");
        return;
    }

    // Set the key and value for the new record
    record->key = key;
    record->value = malloc(strlen(value));
    memcpy(record->value, value, strlen(value));

    // Increment the number of records in the data store
    numRecords++;

    // Release the lock on the data store
    pthread_mutex_unlock(&mutex);
}

// Retrieve a record from the data store with a specified key
struct Record* getRecord(int key) {
    // Obtain a lock on the data store to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Find the record with the specified key
    struct Record* record = NULL;
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == key) {
            record = &records[i];
            break;
        }
    }

    // Check if a matching record was found
    if (record == NULL) {
        printf("Record with key %d not found\n", key);
        return NULL;
    }

    // Return the record
    pthread_mutex_unlock(&mutex);
    return record;
}

// Update a record in the data store with a specified key and value
void updateRecord(int key, unsigned char* value) {
    // Obtain a lock on the data store to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Find the record with the specified key
    struct Record* record = NULL;
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == key) {
            record = &records[i];
            break;
        }
    }

    // Check if a matching record was found
    if (record == NULL) {
        printf("Record with key %d not found\n", key);
        return;
    }

    // Update the value for the record
    free(record->value);
    record->value = malloc(strlen(value));
    memcpy(record->value, value, strlen(value));

    // Release the lock on the data store
    pthread_mutex_unlock(&mutex);
}

// Remove a record from the data store with a specified key
void removeRecord(int key) {
    // Obtain a lock on the data store to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Find the record with the specified key
    struct Record* record = NULL;
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == key) {
            record = &records[i];
            break;
        }
    }

    // Check if a matching record was found
    if (record == NULL) {
        printf("Record with key %d not found\n", key);
        return;
    }

    // Update the number of records in the data store
    numRecords--;

    // Free the memory for the record value
    free(record->value);

    // Shift all subsequent records back by one index
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == key) {
            continue;
        } else {
            struct Record* temp = &records[i];
            memcpy(temp, temp + 1, sizeof(struct Record));
        }
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&mutex);
}

// Clean up the data store and free all memory allocated for records
void cleanupDataStore() {
    // Obtain a lock on the data store to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Free the memory for each record value
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].value);
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&mutex);

    // Free the memory for the records array
    free(records);
}
```
This code implements a dynamic collection of `Record` structures, each containing a unique integer key and an associated offset value. The function `initializeDataStore` is responsible for allocating and initializing memory for these records, ensuring efficient use of resources. It also registers the necessary cryptographic algorithms using OpenSSL's EVP functions.

The function `addRecord` adds a new record to the data store with a specified key and value. The function `getRecord` retrieves a record from the data store with a specified key, returning `NULL` if no matching record is found. The function `updateRecord` updates a record in the data store with a specified key and value, creating a new record if necessary. Finally, the function `removeRecord` removes a record from the data store with a specified key.

The data store is thread-safe, ensuring that multiple threads can access it without causing race conditions or data corruption. The function `cleanupDataStore` cleans up the data store and frees all memory allocated for records when the program finishes execution.']

