void* connectToRemote(void* args) {
    // Get the arguments passed to the function
    char* ip_address = (char*)args;

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
    if (!list) {
        printf("Error: unable to allocate memory for list\n");
        return NULL;
    }

    // Set the CRCFLAG to a randomly set value
    int crcFlag = rand() % 2 == 0 ? NFAPI_CRC_INDICATION_REL8_TAG : NFAPI_CRC_INDICATION_REL9_TAG;

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        list[i].RX_UE_INFORMATION_TAG = NFAPI_CRC_INDICATION_REL8_TAG;
        list[i].RNTI = rand() % 100000;
        list[i].CRCFLAG = crcFlag;
    }

    // Create a new socket and establish a connection to the remote address
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        printf("Error: unable to create socket\n");
        return NULL;
    }
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, ip_address, &server_addr.sin_addr);
    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        printf("Error: unable to connect to remote address\n");
        close(sock);
        return NULL;
    }

    // Set the socket to non-blocking mode
    int flags = fcntl(sock, F_GETFL, 0);
    if (flags < 0) {
        printf("Error: unable to get file descriptor flags\n");
        close(sock);
        return NULL;
    }
    if (fcntl(sock, F_SETFL, flags | O_NONBLOCK) < 0) {
        printf("Error: unable to set non-blocking mode on socket\n");
        close(sock);
        return NULL;
    }

    // Create a new thread to manage the connection
    pthread_t thread;
    if (pthread_create(&thread, NULL, manageConnection, (void*)list) != 0) {
        printf("Error: unable to create thread\n");
        close(sock);
        return NULL;
    }

    // Return the socket and list of NFAPI_CRC_INDICATION_PDU_T structures
    ConnectionInfo* connection = malloc(sizeof(ConnectionInfo));
    if (!connection) {
        printf("Error: unable to allocate memory for connection info\n");
        close(sock);
        return NULL;
    }
    connection->sock = sock;
    connection->ip_address = ip_address;
    connection->port = 0;
    connection->list = list;

    return (void*)connection;
}

// Function to manage a single connection and handle incoming data
void* manageConnection(void* args) {
    // Get the arguments passed to the function
    ConnectionInfo* connection = (ConnectionInfo*)args;

    // Set the socket to blocking mode
    int flags = fcntl(connection->sock, F_GETFL, 0);
    if (flags < 0) {
        printf("Error: unable to get file descriptor flags\n");
        close(connection->sock);
        return NULL;
    }
    if (fcntl(connection->sock, F_SETFL, flags & ~O_NONBLOCK) < 0) {
        printf("Error: unable to set blocking mode on socket\n");
        close(connection->sock);
        return NULL;
