    if (sendto(connection->sock, connection->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE, 0, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        printf("Error: unable to send data to remote address\n");
