        close(connection->sock);
        return NULL;
    }

    // Process the incoming data and update the list of NFAPI_CRC_INDICATION_PDU_T structures as necessary
    // ...

    // Close the socket and free the memory used by the connection
    close(connection->sock);
    free(connection->list);
    free(connection);

    return NULL;
}

// Function to handle errors and retry mechanisms for connection failures
void* handleConnectionErrors(void* args) {
    // Get the arguments passed to the function
    ConnectionInfo* connection = (ConnectionInfo*)args;

