            close(connection->sock);
            return NULL;
        }

        // Set a flag to indicate that the connection has succeeded
        connectionFailed = 0;
    }

    return (void*)connection;
}

// Function to handle multiple concurrent connections and ensure thread-safe data structures and synchronization mechanisms are in place
void* manageConnections(void* args) {
    // Get the arguments passed to the function
    ConnectionInfo* connection = (ConnectionInfo*)args;

    // Add the new connection to the list of connections
