int read_integers(char *server_ip, int port) {
    // Initialize variables
    char buffer[1024];
    int *integers = NULL;
    size_t integer_count = 0;
    int largest_integer = -1;

    // Connect to server and retrieve data
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, server_ip, &server_address.sin_addr);
    server_address.sin_port = htons(port);
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    connect(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address));

    // Read data from server
    while (1) {
        memset(buffer, 0, sizeof(buffer));
        int bytes_received = recv(socket_fd, buffer, sizeof(buffer), 0);
        if (bytes_received <= 0) {
            break;
        }

        // Parse received data
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            int integer = atoi(token);
            if (integer > largest_integer) {
                largest_integer = integer;
            }
            integer_count++;
            if (integers == NULL) {
                integers = malloc(sizeof(int) * integer_count);
            } else {
                integers = realloc(integers, sizeof(int) * integer_count);
            }
            integers[integer_count - 1] = integer;
            token = strtok(NULL, " ");
        }
    }

    // Close connection to server
    close(socket_fd);

    // Print largest integer in array
    printf("Largest integer: %d\n", largest_integer);

    return 0;
}']

