// Define a dynamic array of UE contexts, with locking to ensure thread safety
typedef struct {
    pthread_mutex_t mutex;
    ue_context_t* ue_contexts;
    size_t num_ue_contexts;
} ue_context_array_t;

void initialize_ue_contexts(ue_context_array_t* ue_context_arr) {
    // Initialize the mutex for the UE context array
    pthread_mutex_init(&ue_context_arr->mutex, NULL);

    // Allocate memory for the UE context array
    ue_context_arr->ue_contexts = (ue_context_t*)malloc(sizeof(ue_context_t) * INITIAL_NUM_UE_CONTEXTS);
    if (ue_context_arr->ue_contexts == NULL) {
        perror("Failed to allocate memory for UE context array");
        exit(1);
    }

    // Initialize the number of UE contexts in the array
    ue_context_arr->num_ue_contexts = INITIAL_NUM_UE_CONTEXTS;
}

void add_ue_context(ue_context_array_t* ue_context_arr, uint32_t imsi, rrc_connection_reconfiguration_msg_t* rrc_conn_reconf_msg) {
    // Acquire the lock for the UE context array
    pthread_mutex_lock(&ue_context_arr->mutex);

    // Check if the number of UE contexts in the array has reached its maximum capacity
    if (ue_context_arr->num_ue_contexts == ue_context_arr->ue_contexts->size) {
        // Resize the array to accommodate more UE contexts
        size_t new_size = ue_context_arr->ue_contexts->size * 2;
        ue_context_t* new_ue_contexts = (ue_context_t*)realloc(ue_context_arr->ue_contexts, sizeof(ue_context_t) * new_size);
        if (new_ue_contexts == NULL) {
            perror("Failed to resize UE context array");
            exit(1);
        }
        ue_context_arr->ue_contexts = new_ue_contexts;
        ue_context_arr->num_ue_contexts = new_size;
    }

    // Add the new UE context to the array
    size_t index = ue_context_arr->num_ue_contexts++;
    ue_context_arr->ue_contexts[index].imsi = imsi;
    ue_context_arr->ue_contexts[index].rrc_conn_reconf_msgs = (rrc_connection_reconfiguration_msg_t*)malloc(sizeof(rrc_connection_reconfiguration_msg_t));
    if (ue_context_arr->ue_contexts[index].rrc_conn_reconf_msgs == NULL) {
        perror("Failed to allocate memory for RRC connection reconfiguration message");
        exit(1);
    }
    ue_context_arr->ue_contexts[index].num_rrc_conn_reconf_msgs = 1;
    ue_context_arr->ue_contexts[index].rrc_conn_reconf_msgs[0] = *rrc_conn_reconf_msg;

    // Release the lock for the UE context array
    pthread_mutex_unlock(&ue_context_arr->mutex);
}

void update_ue_context(ue_context_array_t* ue_context_arr, uint32_t imsi, rrc_connection_reconfiguration_msg_t* rrc_conn_reconf_msg) {
    // Acquire the lock for the UE context array
    pthread_mutex_lock(&ue_context_arr->mutex);

    // Find the UE context corresponding to the IMSI
    size_t index = 0;
    while (index < ue_context_arr->num_ue_contexts && ue_context_arr->ue_contexts[index].imsi != imsi) {
        index++;
    }

    // If the UE context is not found, add a new one
    if (index == ue_context_arr->num_ue_contexts) {
        add_ue_context(ue_context_arr, imsi, rrc_conn_reconf_msg);
        return;
    }

    // Update the RRC connection reconfiguration message in the UE context
    ue_context_arr->ue_contexts[index].rrc_conn_reconf_msgs[0] = *rrc_conn_reconf_msg;

    // Release the lock for the UE context array
    pthread_mutex_unlock(&ue_context_arr->mutex);
}

void remove_ue_context(ue_context_array_t* ue_context_arr, uint32_t imsi) {
    // Acquire the lock for the UE context array
    pthread_mutex_lock(&ue_context_arr->mutex);

    // Find the UE context corresponding to the IMSI
    size_t index = 0;
    while (index < ue_context_arr->num_ue_contexts && ue_context_arr->ue_contexts[index].imsi != imsi) {
        index++;
    }

    // If the UE context is not found, do nothing
    if (index == ue_context_arr->num_ue_contexts) {
        return;
    }

    // Remove the UE context from the array
    ue_context_arr->ue_contexts[index] = ue_context_arr->ue_contexts[--ue_context_arr->num_ue_contexts];

    // Release the lock for the UE context array
    pthread_mutex_unlock(&ue_context_arr->mutex);
}

void clear_ue_contexts(ue_context_array_t* ue_context_arr) {
    // Acquire the lock for the UE context array
    pthread_mutex_lock(&ue_context_arr->mutex);

    // Clear all allocated resources for the UE contexts
    size_t i;
    for (i = 0; i < ue_context_arr->num_ue_contexts; i++) {
        free(ue_context_arr->ue_contexts[i].rrc_conn_reconf_msgs);
        free(ue_context_arr->ue_contexts[i].nas_messages);
    }

    // Release the lock for the UE context array
    pthread_mutex_unlock(&ue_context_arr->mutex);
}
