// Function to execute a command in the background using fork and wait system calls
int execute_command(char* cmd) {
    pid_t child_pid = fork();
    if (child_pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        return -1;
    } else if (child_pid > 0) { // Parent process
        wait(NULL);
        return 1;
    } else {
        perror("fork");
        return 0;
    }
}

// Function to allocate memory for and initialize two arrays: one for 'long' offset values and one for 'int' keys
void allocate_and_initialize_arrays(long* offsets, int* keys) {
    // Allocate memory for the offset array
    offsets = malloc(sizeof(long) * 10);
    if (offsets == NULL) {
        perror("malloc");
        return;
    }

    // Initialize the offset array with random values within a specified range
