    for (int i = 0; i < 10; i++) {
        records[i].value = rand() % 1000 + 1;
    }
}

// Function to count the number of disjoint pairs and print the number of milliseconds taken to perform the disjointness checks for each pair
void count_disjoint_pairs(struct union_find* uf, int* keys) {
    // Initialize variables
    int num_disjoint_pairs = 0;
    double start_time = clock();

    // Loop through the key array and check for disjointness among pairs of integers using the Union-Find structure
    for (int i = 0; i < 10; i++) {
        int parent_i = find(uf, keys[i]);
        for (int j = i + 1; j < 10; j++) {
            int parent_j = find(uf, keys[j]);
            if (parent_i != parent_j) {
                num_disjoint_pairs++;
                union(uf, parent_i, parent_j);
            }
        }
    }

    // Print the number of milliseconds taken to perform the disjointness checks for each pair
    double end_time = clock();
    printf("Number of disjoint pairs: %d\n", num_disjoint_pairs);
    printf("Time taken (milliseconds): %.3f\n", end_time - start_time);
}

int main() {
    // Initialize variables
    long* offsets = NULL;
    int* keys = NULL;
    struct record* records = NULL;
    struct union_find uf;

    // Allocate memory for and initialize the offset, key, and record arrays
    allocate_and_initialize_arrays(&offsets, &keys);
    allocate_and_initialize_records(&records);

    // Initialize the Union-Find structure with the key array
    uf.parents = malloc(sizeof(int) * 10);
    if (uf.parents == NULL) {
        perror("malloc");
        return 0;
    }
    for (int i = 0; i < 10; i++) {
        uf.parents[i] = i;
        uf.ranks = malloc(sizeof(int) * 10);
        if (uf.ranks == NULL) {
            perror("malloc");
            return 0;
        }
    }

    // Execute the command in the background using fork and wait system calls
    char* cmd = "sleep 2";
    int status = execute_command(cmd);
    if (status == 0) {
        printf("Error executing command\n");
        return 0;
    }

    // Count the number of disjoint pairs and print the number of milliseconds taken to perform the disjointness checks for each pair
    count_disjoint_pairs(&uf, keys);

    // Free memory allocated for the offset, key, and record arrays
    free(offsets);
    free(keys);
    free(records);
    return 1;
}
