using boost::asio::ip::tcp;

class SandeshClient {
 public:
  SandeshClient(const std::string& host, const unsigned short port) : host_(host), port_(port) {}

  void sendGetRequest() {
    auto socket = boost::make_shared<tcp::socket>(io_service_);
    tcp::resolver resolver(io_service_);
    auto endpoint_itr = resolver.resolve(host_, std::to_string(port_));

    boost::asio::connect(socket, endpoint_itr);

    boost::asio::streambuf request;
    std::ostream request_stream(&request);
    request_stream << "GET / HTTP/1.1\r\n";
    request_stream << "Host: " << host_ << "\r\n";
    request_stream << "Accept: */*\r\n";
    request_stream << "Connection: close\r\n\r\n";

    boost::asio::write(socket, request);

    boost::asio::streambuf response;
    boost::asio::read_until(socket, response, "\r\n");

    std::istream response_stream(&response);
    std::string http_version;
    response_stream >> http_version;
    unsigned int status_code;
    response_stream >> status_code;
    std::string status_message;
    std::getline(response_stream, status_message);

    if (status_code != 200) {
      std::cerr << "Invalid response: " << http_version << ' ' << status_code << ' ' << status_message << '\n';
    } else {
      // Parse the response and extract the largest integer in the list
      std::stringstream ss(std::string(response.data(), response.size()));
      std::vector<int> integers;
      int i;
      while (ss >> i) {
        integers.push_back(i);
      }
      if (!integers.empty()) {
        largest_integer_ = *std::max_element(integers.begin(), integers.end());
      } else {
        std::cout << "No integers provided\n";
      }
    }
  }

  int getLargestInteger() const { return largest_integer_; }

 private:
  boost::asio::io_service io_service_;
  std::string host_;
  unsigned short port_;
  int largest_integer_ = 0;
};

int main() {
  SandeshClient client("www.example.com", 80);
  client.sendGetRequest();
  std::cout << "Largest integer: " << client.getLargestInteger() << '\n';
}
```
