// Function to initialize a semaphore with a specified initial value
void init_sema(sem_t *sema, int val) {
    // Create the semaphore and set its initial value
    if (sem_init(sema, 0, val)) {
        perror("Error creating semaphore");
        exit(1);
    }
}

// Function to acquire a semaphore with a timeout
int acquire_sema_timeout(sem_t *sema, long timeout) {
    // Set the timeout value for the semaphore
    struct timespec ts;
    ts.tv_sec = timeout / 1000; // Convert milliseconds to seconds
    ts.tv_nsec = (timeout % 1000) * 1000000; // Convert milliseconds to nanoseconds

    // Acquire the semaphore with a timeout
    if (sem_timedwait(sema, &ts)) {
        perror("Error acquiring semaphore");
        return -1;
    }

    return 0;
}

// Function to release a semaphore
void release_sema(sem_t *sema) {
    // Release the semaphore
    if (sem_post(sema)) {
        perror("Error releasing semaphore");
        exit(1);
    }
}

// Function to process and manipulate an array of integers with a semaphore
void process_and_manipulate_sema(int *array, int size) {
    // Create a semaphore for synchronizing access to the shared resource
    sem_t sema;
    init_sema(&sema, 1);

    // Read a list of integers from standard input and store them in the array
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    // Protect critical sections with the semaphore
    while (1) {
        // Acquire the semaphore to access the shared resource
        if (acquire_sema_timeout(&sema, 500)) {
            perror("Error acquiring semaphore");
            break;
        }

        // Process and manipulate the array elements as needed
        for (int i = 0; i < size; i++) {
            array[i]++;
        }

        // Release the semaphore to allow other threads to access the shared resource
        release_sema(&sema);
    }

    // Print the largest integer from the array
    int largest = 0;
    for (int i = 0; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}
