function getUserInfo($accessToken) {
    // Set up HTTP client for making API requests
    $httpClient = new \GuzzleHttp\Client();

    // Construct API request to retrieve user information
    $request = new \GuzzleHttp\Psr7\Request('GET', 'https://www.example.com/api/users/me', [
        'Authorization' => 'Bearer ' . $accessToken,
    ]);

    // Make API request and retrieve user information
    try {
        $response = $httpClient->send($request);
        $userInfo = json_decode($response->getBody());
        return $userInfo;
    } catch (\GuzzleHttp\Exception\RequestException $e) {
        // Handle request exceptions, such as network failures or timeouts
        if ($e->hasResponse()) {
            $response = $e->getResponse();
            $statusCode = $response->getStatusCode();
            $errorMessage = $response->getReasonPhrase();
        } else {
            $statusCode = null;
            $errorMessage = 'Unknown error';
        }
        return [
            'success' => false,
            'statusCode' => $statusCode,
            'errorMessage' => $errorMessage,
        ];
    }
}

function runTest($label, $f) {
    // Set up dependency injection container for test dependencies
    $container = new \League\Container\Container();
    $container->share(\GuzzleHttp\Client::class, function () {
        return new \GuzzleHttp\Client();
