            if (!$userInfo['success']) {
                return ['success' => false, 'statusCode' => $userInfo['statusCode'], 'errorMessage' => $userInfo['errorMessage']];
            } else {
                return ['success' => true, 'message' => "Retrieved user information:\n{$userInfo}\n"];
            }
        },
        'test2' => function ($container) {
            // Test 2: Verify that access token can be refreshed using a refresh token
            $refreshToken = $_SESSION['refreshToken'];
            if (!$refreshToken) {
                return ['success' => false, 'message' => "No refresh token found in session.\n"];
            } else {
                // Refresh access token using refresh token
                $response = $container->get(\GuzzleHttp\Client::class)->post('https://www.example.com/oauth/token', [
                    'form_params' => [
                        'grant_type' => 'refresh_token',
                        'refresh_token' => $refreshToken,
                        'client_id' => CLIENT_ID,
                    ],
                ]);
                $data = json_decode($response->getBody());
                $_SESSION['accessToken'] = $data->access_token;
            }
            // Verify that new access token can be used to retrieve user information
            $userInfo = getUserInfo($_SESSION['accessToken']);
            if (!$userInfo['success']) {
                return ['success' => false, 'statusCode' => $userInfo['statusCode'], 'errorMessage' => $userInfo['errorMessage']];
            } else {
                return ['success' => true, 'message' => "Retrieved user information:\n{$userInfo}\n"];
            }
        },
    ];
    foreach ($tests as $label => $test) {
        runTest($label, $test);
    }
}
