        perror("Failed to allocate memory for PDU list");
        return;
    }

    // Initialize the semaphore initial values
    int i;
    for (i = 0; i < num_threads; i++) {
        semaphore_initial_values[i] = 1;
    }

    // Create the semaphores and initialize them to their corresponding initial values
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    semaphore = (semaphore *)malloc(sizeof(semaphore) * num_threads);
    if (semaphore == NULL) {
        // Handle memory allocation failure gracefully
        perror("Failed to allocate memory for semaphores");
        return;
    }
    for (i = 0; i < num_threads; i++) {
        if (sem_init(&semaphore[i], &attr, semaphore_initial_values[i]) != 0) {
            // Handle semaphore initialization failure gracefully
            perror("Failed to initialize semaphore");
            return;
        }
    }

    // Initialize the PDUs with random CRC values and RX UE information
