void initializeNetworkMetrics(NetworkMetric* metrics, int count) {
    // Allocate memory for the data transfer volume field, ensuring that all allocated memory is freed upon completion
    for (int i = 0; i < count; i++) {
        metrics[i].dataTransferVolume = malloc(sizeof(unsigned long long));
        if (!metrics[i].dataTransferVolume) {
            // Handle memory allocation failure gracefully by logging an error and returning early
            printf("Error: Failed to allocate memory for data transfer volume\n");
            return;
        }
    }

    // Validate the session IDs, data transfer volumes, and session durations before inclusion in the array
    for (int i = 0; i < count; i++) {
        if (!validateSessionId(metrics[i].sessionId)) {
            printf("Error: Invalid session ID found\n");
            freeNetworkMetric(&metrics[i]);
            continue;
        }
        if (!validateDataTransferVolume(metrics[i].dataTransferVolume)) {
            printf("Error: Data transfer volume out of range for session ID %d\n", metrics[i].sessionId);
            freeNetworkMetric(&metrics[i]);
            continue;
        }
        if (!validateSessionDuration(metrics[i].sessionDuration)) {
            printf("Warning: Session duration is zero or negative for session ID %d\n", metrics[i].sessionId);
            metrics[i].sessionDuration = 0; // Set a default value of 0 milliseconds for sessions with no data transfer volume
        }
    }

    // Log errors and warnings for debugging purposes, while prioritizing minimizing the performance impact of logging during high-load scenarios
    int errorCount = 0;
    int warningCount = 0;
    for (int i = 0; i < count; i++) {
        if (!metrics[i].dataTransferVolume) {
            errorCount++;
        } else {
            if (metrics[i].sessionDuration <= 0) {
                warningCount++;
            }
        }
    }
    if (errorCount > 0) {
        printf("Error: %d memory allocation errors encountered during initialization\n", errorCount);
    }
    if (warningCount > 0) {
        printf("Warning: %d session durations found to be zero or negative\n", warningCount);
    }
}

// Helper function to free a NetworkMetric structure and its associated data transfer volume field
void freeNetworkMetric(NetworkMetric* metric) {
    if (metric->dataTransferVolume) {
        free(metric->dataTransferVolume);
        metric->dataTransferVolume = NULL;
    }
}
