#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jpeglib.h>

struct Metadata {
    int resolution_x;
    int resolution_y;
    int color_space;
    char* color_profile;
};

struct JPEGImage {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
};

void processJPEG(const unsigned char* data, int length, struct Metadata* metadata) {
    struct JPEGImage image = {
        .cinfo = {
            .err = &image.jerr,
            .mem_dest = NULL
        },
        .jerr = {
            .error_exit = jpegErrorExit
        }
    };

    // Initialize the JPEG decompression object
    jpeg_create_decompress(&image.cinfo);
    image.cinfo.mem_dest = &image.jerr;

    // Set the input data source
    jpeg_mem_src(&image.cinfo, data, length);

    // Read the JPEG header and metadata
    if (jpeg_read_header(&image.cinfo, TRUE) != JPEG_HEADER_OK) {
        printf("Error reading JPEG header\n");
        return;
    }

    // Extract the resolution and color space from the JFIF marker segment
    int* jfif = (int*)jpeg_get_marker_from_markers(&image.cinfo, 0xffe1);
    if (jfif != NULL) {
        metadata->resolution_x = jfif[1];
        metadata->resolution_y = jfif[2];
        metadata->color_space = jfif[3] >> 8;
    }

    // Extract the color profile from the APP1 marker segment
    int* app1 = (int*)jpeg_get_marker_from_markers(&image.cinfo, 0xe1);
    if (app1 != NULL) {
        metadata->color_profile = malloc(16);
        memcpy(metadata->color_profile, app1 + 2, 16);
    }

    // Log non-standard markers
    int num_markers = jpeg_get_marker_count(&image.cinfo);
    for (int i = 0; i < num_markers; i++) {
        if (!jpeg_is_marker_supported(&image.cinfo, i)) {
            printf("Marker %d not supported\n", i);
        } else {
            int* marker = jpeg_get_marker_from_markers(&image.cinfo, i);
            if (marker != NULL) {
                printf("Marker %d: ", i);
                for (int j = 0; j < marker[1]; j++) {
                    printf("%02x ", marker[j + 2]);
                }
                printf("\n");
            }
        }
    }

    // Clean up the JPEG decompression object
    jpeg_destroy_decompress(&image.cinfo);
}

void jpegErrorExit(j_common_ptr cinfo) {
    struct JPEGImage* image = (struct JPEGImage*)cinfo;
    printf("JPEG error: %s\n", image->jerr.message);
}
```
This code defines a function `processJPEG` that takes an input buffer containing a JPEG image file, extracts metadata from the JFIF and APP1 marker segments, and returns a structured format suitable for downstream processing. The function also logs non-standard markers and handles various JPEG quality levels gracefully.

The `processJPEG` function first initializes a JPEG decompression object using the `jpeg_create_decompress` function from the IJG JPEG library, then sets the input data source to the given buffer using the `jpeg_mem_src` function. It reads the JPEG header and metadata using the `jpeg_read_header` function, extracts the resolution and color space from the JFIF marker segment, and allocates memory for the color profile if present.

To log non-standard markers, the function uses the `jpeg_get_marker_count` and `jpeg_is_marker_supported` functions to retrieve the total number of markers in the file and check if each marker is supported by the IJG JPEG library. If a marker is not supported, it is logged using the `printf` function. If a marker is supported, its contents are extracted using the `jpeg_get_marker_from_markers` function and printed to the console.

Finally, the function cleans up the JPEG decompression object using the `jpeg_destroy_decompress` function before returning the extracted metadata in a structured format suitable for downstream processing.']

