int rename_file(char* dir_path, char* base_name, char* desired_type) {
    int count = 0;
    struct stat st;
    while (1) {
        // Construct new filename by appending a numeric suffix to the base name
        char* new_filename = malloc(strlen(base_name) + strlen(desired_type) + 5);
        sprintf(new_filename, "%s-%d.%s", base_name, count++, desired_type);

        // Check if the new filename already exists in the directory
        if (stat(dir_path, &st) == -1) {
            perror("stat");
            return errno;
        } else if (!S_ISDIR(st.st_mode)) {
            fprintf(stderr, "Error: path is not a directory\n");
            return -1;
        }

        // Check if the new filename exceeds maximum length of 255 characters
        if (strlen(new_filename) > 255) {
            fprintf(stderr, "Error: new filename is too long\n");
            return -1;
        }

        // Check for malformed filenames and handle them gracefully
        if (strchr(base_name, '/') != NULL || strchr(desired_type, '/') != NULL) {
            fprintf(stderr, "Error: invalid filename or file type\n");
            return -1;
        }

        // Try renaming the file and check for errors
        if (rename(dir_path, new_filename)) {
            perror("rename");
            return errno;
        } else {
            // Report successful renaming to a log file or stdout
            printf("Renamed %s to %s\n", dir_path, new_filename);
            free(new_filename);
            return 0;
        }
    }
}
```
