// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int numElements) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        printf("Error: Failed to allocate memory for array of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return NULL;
    }

    // Populate the array with random RNTIs and CRCFLAG values
    int i, j;
    srand(time(NULL));
    for (i = 0; i < numElements; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        arr[i].RNTI = rand() % UINT32_MAX;
        while (true) { // Retry generating a unique RNTI until a maximum of 10 retries per attempt
            j = rand() % 10;
            if (!rnti_hash[j].occupied) {
                rnti_hash[j].key = arr[i].RNTI;
                rnti_hash[j].occupied = true;
                break;
            }
        }
        arr[i].CRCFLAG = rand() % 256; // Validate the CRCFLAG is within the specified range before setting it
    }

    return arr;
}
