int establish_connection(const char *ip, int port) {
    struct addrinfo hints;
    struct addrinfo *result, *rp;
    int s, s2;
    char host[NI_MAXHOST];
    char serv[NI_MAXSERV];

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;

    s = getaddrinfo(ip, NULL, &hints, &result);
    if (s != 0) {
        perror("getaddrinfo");
        return -1;
    }

    for (rp = result; rp != NULL; rp = rp->ai_next) {
        s2 = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (s2 == -1) {
            perror("socket");
            continue;
        }

        if (connect(s2, rp->ai_addr, rp->ai_addrlen) != -1) {
            break; // Success
        }
        close(s2);
    }

    freeaddrinfo(result);

    if (rp == NULL) { // No suitable address found
        perror("connect");
        return -1;
    }

    return s2;
}

void *connection_handler(void *args) {
    int sock = *((int *) args);
    char buffer[MESSAGE_SIZE];
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Receive data from the socket
