        // Parse received data into NFAPI_CRC_INDICATION_PDU_T structure
        pdu.RX_UE_INFORMATION_TAG = *((uint16_t *) buffer);
        pdu.RNTI = *((uint16_t *) (buffer + 2));
        pdu.CRCFLAG = *((uint8_t *) (buffer + 4));

        // Process received data
        // ...
    }

    close(sock);
    return NULL;
}

int main() {
    int sock, i;
    pthread_t thread[MAX_THREADS];

    // Initialize the list of message buffers to store incoming messages
    NFAPI_CRC_INDICATION_PDU_T *message_buffer[MESSAGE_BUFFER_SIZE];
    for (i = 0; i < MESSAGE_BUFFER_SIZE; i++) {
        message_buffer[i] = NULL;
    }

    // Initialize the list of available threads to use for handling connections
    int thread_available[MAX_THREADS];
    for (i = 0; i < MAX_THREADS; i++) {
        thread_available[i] = 1;
    }

    // Create a multicast socket using the INTERFACE and MULTICAST_TTL values
    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr("224.0.1.3");
    mreq.imr_interface.s_addr = inet_addr(INTERFACE);
    sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    // Join the multicast group and set the time-to-live value
    if (setsockopt(sock, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(struct ip_mreq)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Set the time-to-live value for outgoing multicast packets
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &MULTICAST_TTL, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Loop indefinitely to handle incoming connections and messages
    while (1) {
        int sock2 = establish_connection("224.0.1.3", 5000);
        if (sock2 < 0) {
            perror("establish_connection");
            continue;
        }

        // Find an available thread to handle the new connection
        int thread_id = -1;
        for (i = 0; i < MAX_THREADS; i++) {
            if (thread_available[i] == 1) {
                thread_id = i;
                break;
            }
        }

        // If no available threads are found, drop the new connection and continue
        if (thread_id < 0) {
            close(sock2);
            continue;
        }

        // Create a thread to handle the new connection
        thread_available[thread_id] = 0;
        pthread_create(&thread[thread_id], NULL, connection_handler, &sock2);
    }

    return 0;
}
