// Helper function to retrieve project details from the database
int getProjectDetails(sqlite3 *db, int pid, char **name, char **est_date, int **team_ids) {
    sqlite3_stmt *stmt = NULL;
    int rc = 0;

    // Prepare query to retrieve project details from the database
    const char *query = "SELECT name, est_date, team_ids FROM Projects WHERE pid = ?";

    // Bind the parameter value for the given project ID
    sqlite3_bind_int(stmt, 1, pid);

    // Execute query and retrieve results
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        *name = (char *)sqlite3_column_text(stmt, 0);
        *est_date = (char *)sqlite3_column_text(stmt, 1);
        *team_ids = (int *)sqlite3_column_int(stmt, 2);
    } else {
        printf("Error retrieving project details: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Clean up statement and database connection
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}

