    if (rc == SQLITE_ROW) {
        *names = (char **)sqlite3_column_text(stmt, 0);
        *emails = (char **)sqlite3_column_text(stmt, 1);
    } else {
        printf("Error retrieving team member details: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Clean up statement and database connection
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}

