    char* value;
};

int convertJPEGtoPDF(const char* configFilePath, const char* outputDir, const char* prefix) {
    // Open the configuration file and load its contents into memory
    FILE* configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        perror("Error opening configuration file");
        return 1;
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Read each line of the configuration file into memory
    while ((read = getline(&line, &len, configFile)) != -1) {
        if (strstr(line, "JPEG") == NULL) continue;  // Skip lines that do not contain "JPEG"

        char* key = strtok(line, "=");  // Extract the key from the line
        char* value = strtok(NULL, "\n");  // Extract the value from the line

        struct ConfigEntry entry;
        entry.key = key;
        entry.value = value;

        // Convert the JPEG file to PDF using a third-party tool
        int ret = system(entry.value);
        if (ret != 0) {
            perror("Error converting JPEG to PDF");
            return 1;
        }

        // Generate output files based on the prefix and save them in the specified directory
        char* fileName = malloc(strlen(prefix) + strlen(entry.key) + 5);
        sprintf(fileName, "%s_%s.pdf", prefix, entry.key);

        FILE* pdfFile = fopen(fileName, "w");
        if (pdfFile == NULL) {
            perror("Error creating PDF file");
            return 1;
        }

        free(fileName);
    }

    // Clean up memory and return
    free(line);
