    PDUSessionMessage *message; // Pointer to the PDUSessionMessage structure
    EPS_Bearer_Contexts *bearer; // Pointer to the EPS_Bearer_Contexts structure
} SessionManagementContext;

// Function to initialize and manage a distributed linked list of SessionManagementContext structures
void initSessionList(SessionManagementContext **head) {
    // Initialize the head pointer to NULL
    *head = NULL;
}

// Function to insert a new SessionManagementContext structure into the linked list
void insertSession(SessionManagementContext **head, PDUSessionMessage *message, EPS_Bearer_Contexts *bearer) {
    // Allocate memory for the new SessionManagementContext structure
    SessionManagementContext *newNode = (SessionManagementContext *)malloc(sizeof(SessionManagementContext));
    if (!newNode) {
        printf("Error: Failed to allocate memory for a new node in the linked list.\n");
        return;
    }

    // Set the message and bearer fields of the new SessionManagementContext structure
    newNode->message = message;
    newNode->bearer = bearer;

    // Insert the new SessionManagementContext structure into the linked list
    newNode->next = *head;
    *head = newNode;
}

// Function to remove a SessionManagementContext structure from the linked list
void deleteSession(SessionManagementContext **head, PDUSessionMessage *message) {
    // Find the node with the matching message field
    SessionManagementContext *currentNode = *head;
    while (currentNode != NULL && currentNode->message != message) {
        currentNode = currentNode->next;
    }

    // If the node was found, remove it from the linked list
    if (currentNode != NULL) {
        SessionManagementContext *previousNode = NULL;
        while (currentNode != NULL && currentNode->message == message) {
            previousNode = currentNode;
            currentNode = currentNode->next;
        }

        // Remove the node from the linked list
        if (previousNode != NULL) {
            previousNode->next = currentNode;
        } else {
            *head = currentNode;
        }
    }
}

// Function to traverse the linked list and perform some action on each SessionManagementContext structure
void traverseList(SessionManagementContext **head, void (*action)(SessionManagementContext*)) {
    // Traverse the linked list and perform the specified action on each node
    SessionManagementContext *currentNode = *head;
    while (currentNode != NULL) {
        action(currentNode);
        currentNode = currentNode->next;
    }
}
