#include <openssl/err.h>

// Define constants for memory management and data sanitization
#define MAX_RECORDS 4096
#define RESIZE_LIMIT 16384
#define CACHE_LINE_SIZE 64
#define SANITIZE_RAND_MIN 1
#define SANITIZE_RAND_MAX 100

// Define data structures for managing records and keys
typedef struct {
    int key;
    long offset;
} record;

record* records;
long* offsets;

// Define function to initialize data manager
void initialize_data_manager() {
    // Dynamically allocate memory for arrays of records and offsets
    records = (record*)malloc(sizeof(record) * MAX_RECORDS);
    offsets = (long*)malloc(sizeof(long) * MAX_RECORDS);

    // Initialize array sizes based on user input
    int num_records = 0;
    while (num_records < MAX_RECORDS && !is_full()) {
        add_record();
    }

    // Register cryptographic algorithms with OpenSSL
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_camellia_256_cbc());
    EVP_add_digest(EVP_rsa_2048_pkcs1_v1_5_encrypt());

    // Set up thread-safe operations and synchronization mechanisms
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Implement mechanism for securely erasing sensitive data from memory
    void sanitize(void* ptr, size_t size) {
        memset(ptr, 0, size);
        free(ptr);
    }
}

// Define function to add new record
void add_record() {
    // Dynamically allocate memory for new record and offset
    record* new_record = (record*)malloc(sizeof(record));
    long new_offset = 0;

    // Assign random value within specified range to integer field
    int rand_val = SANITIZE_RAND_MIN + (SANITIZE_RAND_MAX - SANITIZE_RAND_MIN) * RAND();
    new_record->key = rand_val;

    // Assign random offset value based on user input
    new_offset = rand() % 100 + 1;

    // Add record to array and update offset array
    pthread_mutex_lock(&mutex);
    records[num_records] = *new_record;
    offsets[num_records] = new_offset;
    num_records++;
    pthread_mutex_unlock(&mutex);
}

// Define function to check if array is full
bool is_full() {
    return (num_records == MAX_RECORDS) || (num_records > RESIZE_LIMIT);
}

// Define function to resize arrays when necessary
void resize_arrays(int new_size) {
    // Dynamically allocate memory for new arrays
    record* new_records = (record*)malloc(sizeof(record) * new_size);
    long* new_offsets = (long*)malloc(sizeof(long) * new_size);

    // Copy data from old arrays to new arrays
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        new_records[i] = records[i];
        new_offsets[i] = offsets[i];
    }
    pthread_mutex_unlock(&mutex);

    // Free old arrays and update variables
    free(records);
    free(offsets);
    records = new_records;
    offsets = new_offsets;
}

// Define function to erase sensitive data from memory
void sanitize_data(void* ptr, size_t size) {
    // Dynamically allocate memory for sanitized data and copy original data
    void* sanitized_ptr = malloc(size);
    memcpy(sanitized_ptr, ptr, size);

    // Clear sensitive data from original array
    memset(ptr, 0, size);

    // Sanitize data in parallel to reduce contention
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < size; i++) {
        char* byte_ptr = (char*)sanitized_ptr + i;
        *byte_ptr = 0;
    }

    // Free sanitized data and update variables
    free(sanitized_ptr);
}

// Define function to encrypt data using OpenSSL functions
void encrypt_data(void* ptr, size_t size) {
    // Create temporary buffers for data encryption
    char* encrypted_buf = malloc(size);
    char* plaintext_buf = malloc(size);

    // Copy original data to plaintext buffer
    memcpy(plaintext_buf, ptr, size);

    // Encrypt data using OpenSSL functions
    EVP_EncryptUpdate(plaintext_buf, encrypted_buf, size);

    // Free temporary buffers and update variables
    free(encrypted_buf);
    free(plaintext_buf);
}

// Define function to decrypt data using OpenSSL functions
void decrypt_data(void* ptr, size_t size) {
    // Create temporary buffers for data decryption
    char* encrypted_buf = malloc(size);
    char* plaintext_buf = malloc(size);

    // Copy original data to plaintext buffer
    memcpy(plaintext_buf, ptr, size);

    // Decrypt data using OpenSSL functions
    EVP_DecryptUpdate(encrypted_buf, plaintext_buf, size);

    // Free temporary buffers and update variables
    free(encrypted_buf);
    free(plaintext_buf);
}
```
