    float weight;
    bool validated;
};

void generate_records(int offset_min, int offset_max, int key_min, int key_max, float weight_min, float weight_max) {
    srand(time(NULL)); // seed random number generator with current time

    // allocate memory for arrays of offsets, keys, and weights
    int *offsets = malloc(sizeof(int) * offset_max);
    int *keys = malloc(sizeof(int) * key_max);
    float *weights = malloc(sizeof(float) * weight_max);

    // initialize arrays with random values within specified ranges
    for (int i = 0; i < offset_max; i++) {
        offsets[i] = rand() % (offset_max - offset_min + 1) + offset_min;
    }
    for (int j = 0; j < key_max; j++) {
        keys[j] = rand() % (key_max - key_min + 1) + key_min;
    }
    for (int k = 0; k < weight_max; k++) {
        weights[k] = (float)rand() / RAND_MAX * (weight_max - weight_min) + weight_min;
    }

    // allocate memory for array of records and initialize each record with random values
    struct record *records = malloc(sizeof(struct record) * offset_max);
    for (int l = 0; l < offset_max; l++) {
        records[l].key = keys[rand() % key_max];
        records[l].weight = weights[rand() % weight_max];
        records[l].validated = false; // initially mark all records as invalid
    }

    // validate each record against business rules defined in external configuration file
    // (implemented using an external data processing library)
    for (int m = 0; m < offset_max; m++) {
        if (validate(records[m].key, records[m].weight)) {
            records[m].validated = true;
        }
    }

    // free memory allocated for arrays of offsets, keys, and weights
    free(offsets);
    free(keys);
    free(weights);

    return records;
}
