// Context structure to store UE ID, QoS parameters, and session establishment timestamp
typedef struct {
    int ue_id;
    unsigned int qos_params;
    time_t session_establishment_timestamp;
} context_t;

// Dynamic list of contexts to store UE Contexts
typedef struct {
    context_t **contexts;
    size_t size;
    size_t capacity;
} context_list_t;

// Helper function to calculate and print the average session establishment time across all contexts
void print_average_session_establishment_time(const context_list_t *context_list) {
    // Calculate the total number of sessions and total session establishment time
    size_t num_sessions = 0;
    time_t total_session_establishment_time = 0;
    for (size_t i = 0; i < context_list->size; ++i) {
        if (context_list->contexts[i] != NULL) {
            num_sessions++;
            total_session_establishment_time += context_list->contexts[i]->session_establishment_timestamp;
        }
    }

    // Print the average session establishment time
    if (num_sessions > 0) {
        printf("Average session establishment time: %f\n",
               total_session_establishment_time / (double) num_sessions);
    } else {
        printf("No sessions available.\n");
    }
}

// Main function to manage a dynamic list of LTE UE Contexts
void mange_lte_ue_contexts(context_list_t *context_list) {
    // Initialize the context list with an initial capacity of 1000 entries
    context_list->capacity = 1000;
    context_list->size = 0;
    context_list->contexts = (context_t **) malloc(context_list->capacity * sizeof(context_t *));
    memset(context_list->contexts, 0, context_list->capacity * sizeof(context_t *));

    // Add a new context to the list
    void add_context(int ue_id, unsigned int qos_params, time_t session_establishment_timestamp) {
        if (context_list->size == context_list->capacity) {
            // Resize the list if it is full
            size_t new_capacity = context_list->capacity * 2;
            context_list->contexts = (context_t **) realloc(context_list->contexts, new_capacity * sizeof(context_t *));
            memset(context_list->contexts + context_list->capacity, 0, new_capacity - context_list->capacity);
            context_list->capacity = new_capacity;
        }

        // Allocate a new context structure and store the parameters
        context_t *new_context = (context_t *) malloc(sizeof(context_t));
        new_context->ue_id = ue_id;
        new_context->qos_params = qos_params;
        new_context->session_establishment_timestamp = session_establishment_timestamp;

        // Add the context to the list
        context_list->contexts[context_list->size++] = new_context;
    }

    // Remove a context from the list by its index
    void remove_context(size_t index) {
        if (index < 0 || index >= context_list->size) {
            return;
        }
        context_t *removed_context = context_list->contexts[index];
        for (size_t i = index + 1; i < context_list->size; ++i) {
            context_list->contexts[i - 1] = context_list->contexts[i];
        }
        context_list->size--;
        free(removed_context);
    }

    // Update the session establishment time for a given UE ID
    void update_session_establishment_time(int ue_id, time_t session_establishment_timestamp) {
        if (ue_id < 0 || context_list->size == 0) {
            return;
        }
        for (size_t i = 0; i < context_list->size; ++i) {
            if (context_list->contexts[i]->ue_id == ue_id) {
                context_list->contexts[i]->session_establishment_timestamp = session_establishment_timestamp;
                return;
            }
        }
    }

    // Print the average session establishment time across all contexts
    print_average_session_establishment_time(context_list);
}
