// Define the structure of a UEContext
typedef struct {
    int ueId;
    char* nasMessage;
} UEContext;

// Define the structure of an RRC_Connection_Reconfiguration message
typedef struct {
    int reconfigurationType;
    int numRRCConnections;
} RRC_Connection_Reconfiguration;

// Define the structure of a NAS_Message
typedef struct {
    char* nasPayload;
} NAS_Message;

// Define the dynamic array of UEContexts
UEContext* ueContexts = NULL;
size_t numUEContexts = 0;

// Function to initialize the UEContexts
void initializeUEContexts(int maxNumUEContexts) {
    // Allocate memory for the UEContexts array
    ueContexts = (UEContext*)malloc(maxNumUEContexts * sizeof(UEContext));
    if (ueContexts == NULL) {
        printf("Failed to allocate memory for UEContexts\n");
        return;
    }

    // Initialize the UEContexts array with empty structures
    memset(ueContexts, 0, maxNumUEContexts * sizeof(UEContext));

    numUEContexts = maxNumUEContexts;
}

// Function to add a new UEContext to the array
void addNewUEContext(int ueId, char* nasMessage) {
    // Check if the UEContext is already in the array
    bool found = false;
    for (size_t i = 0; i < numUEContexts; i++) {
        if (ueContexts[i].ueId == ueId) {
            found = true;
            break;
        }
    }

    // If the UEContext is not in the array, add a new structure to the end of the array
    if (!found) {
        ueContexts[numUEContexts].ueId = ueId;
        ueContexts[numUEContexts].nasMessage = nasMessage;
        numUEContexts++;
    }
}

// Function to remove an existing UEContext from the array
void removeExistingUEContext(int ueId) {
    // Find the index of the UEContext in the array
    size_t i;
    for (i = 0; i < numUEContexts; i++) {
        if (ueContexts[i].ueId == ueId) {
            break;
        }
    }

    // If the UEContext is found, remove it from the array
    if (i < numUEContexts) {
        memmove(&(ueContexts[i]), &(ueContexts[i+1]), (numUEContexts-i-1) * sizeof(UEContext));
        numUEContexts--;
    }
}

// Function to retrieve the NAS_Message for a given UEContext
char* getNASMessage(int ueId) {
    // Find the index of the UEContext in the array
    size_t i;
    for (i = 0; i < numUEContexts; i++) {
        if (ueContexts[i].ueId == ueId) {
            break;
        }
    }

    // If the UEContext is found, return the NAS_Message
    if (i < numUEContexts) {
        return ueContexts[i].nasMessage;
    } else {
        return NULL;
    }
}

// Function to free memory for the UEContexts array
void freeUEContexts() {
    // Free the memory for each UEContext in the array
    for (size_t i = 0; i < numUEContexts; i++) {
        free(ueContexts[i].nasMessage);
    }

    // Free the memory for the entire array
    free(ueContexts);
}
