// Define the record structure
typedef struct {
    int value;
    float weight;
    bool validated;
} Record;

// Define the function that generates and initializes an array of records
void generate_records(int num_records, char *config_file) {
    // Load the configuration file
    FILE *config = fopen(config_file, "r");
    if (!config) {
        printf("Error: unable to open config file\n");
        return;
    }

    // Read the number of records from the configuration file
    int record_count = 0;
    fscanf(config, "%d", &record_count);

    // Allocate memory for the array of records
    Record *records = (Record *)malloc(sizeof(Record) * record_count);
    if (!records) {
        printf("Error: unable to allocate memory\n");
        return;
    }

    // Initialize each record with a random value, weight, and validation status
    for (int i = 0; i < record_count; ++i) {
        Record *record = records + i;
        record->value = rand() % 100;
        record->weight = (float)(rand() % 100) / 100.0f;
        record->validated = true;
    }

    // Close the configuration file
    fclose(config);

    return records;
}
```
