// Thread-safe and efficient memory allocation and deallocation for list of NFAPI_CRC_INDICATION_PDU_T structures
void *allocateMemory(size_t size) {
    void *ptr = NULL;
    if (posix_memalign((void **)&ptr, 64, size)) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        return NULL;
    }
