}

// Thread-safe and efficient function to create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
int createNFAPIList(struct NFAPI_CRC_INDICATION_PDU_T *nfapi_list) {
    int i = 0;
    while (i < 100000) {
        struct NFAPI_CRC_INDICATION_PDU_T *item = allocateMemory(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!item) {
            fprintf(stderr, "Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T item\n");
