                if (png_save(&image, png_filename) != 0) {
                    fprintf(stderr, "Error saving PNG file: %s\n", png_filename);
                    free(pdu);
                    return 1;
                }
            } else {
                // Ignore non-JPEG files
                continue;
            }
        }

        // Save NFAPI_CRC_INDICATION_PDU_T structure to output file
        char outfile[256];
        snprintf(outfile, sizeof(outfile), "%s/%s.json", output_dir, prefix);
        FILE *fp = fopen(outfile, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening output file: %s\n", outfile);
            free(pdu);
            return 1;
        }
        fprintf(fp, "{\"NFAPI_CRC_INDICATION_PDU_T\":{\"RX_UE_INFORMATION_TAG\":%d,\"RNTI\":%d,\"CRC_INDICATION_REL8_TAG\":%d}}\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        fclose(fp);
    }

    // Free JSON memory and return status code
    json_decref(root);
    return 0;
}
