// Helper function to find the largest RNTI value in the list
int find_largest_rnti(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    int largest = 0;
    for (int i = 1; i < size; i++) {
        if (list[i].rnti > largest) {
            largest = list[i].rnti;
        }
    }
