}

// Main function to initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_list(const char* file_path, int num_threads) {
    // Open the compressed file for reading
    int fd = open(file_path, O_RDONLY);
    if (fd < 0) {
        printf("Error opening file %s: %s\n", file_path, strerror(errno));
        return NULL;
    }

    // Determine the size of the compressed data
    off_t fsize = lseek(fd, 0, SEEK_END);
    if (fsize < 0) {
        printf("Error seeking in file %s: %s\n", file_path, strerror(errno));
        close(fd);
        return NULL;
    }
    lseek(fd, 0, SEEK_SET);

    // Allocate memory for the decompressed data
    char* data = malloc(fsize * sizeof(char));
    if (data == NULL) {
        printf("Error allocating memory for decompressed data\n");
        close(fd);
        return NULL;
    }

    // Decompress the compressed data and validate the RNTI values
    int ret = zlib_inflate(fd, data, fsize);
    if (ret < 0) {
        printf("Error decompressing file %s: %s\n", file_path, strerror(errno));
        free(data);
        close(fd);
        return NULL;
    }

    // Parse the decompressed data to create a list of NFAPI_CRC_INDICATION_PDU_T structures
    int num_elements = ret / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error allocating memory for list of structures\n");
        free(data);
        close(fd);
        return NULL;
    }
    for (int i = 0; i < num_elements; i++) {
        memcpy(&list[i], &data[i * sizeof(NFAPI_CRC_INDICATION_PDU_T)], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Free the memory for the decompressed data and close the file
    free(data);
    close(fd);

    // Find and print the largest RNTI value in the list
    int largest = find_largest_rnti(list, num_elements);
    printf("Largest RNTI value found: %d\n", largest);

    return list;
}
