    // Use a thread pool to parallelize the encryption and decryption operations
    #pragma omp parallel for default(none) shared(num_records, chunk_size, op) schedule(dynamic)
    for (int i = 0; i < num_records; i += chunk_size) {
        // Calculate the start and end indices of the current chunk
        int start = i * chunk_size;
        int end = (i + chunk_size > num_records ? num_records : i + chunk_size);
        // Loop over the records in the current chunk and perform the requested operation
        for (int j = start; j < end; j++) {
            if (op == 0) {
                // Encryption operation
                EVP_EncryptUpdate(ctx, NULL, &records[j].offset, &records[j].key);
            } else {
                // Decryption operation
                EVP_DecryptUpdate(ctx, NULL, &records[j].offset, &records[j].key);
            }
        }
    }
}

