// Define structure to store CRC indication information
typedef struct {
    unsigned int rx_ue_information_tag;
    unsigned short rnti;
    unsigned char crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define function to initialize list of CRC indication structures
void init_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, unsigned int num_elems) {
    // Check if input is valid
    if (num_elems == 0) {
        fprintf(stderr, "Invalid input: number of elements in list must be positive\n");
        return;
    }

    // Allocate memory for list
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elems);
    if (*list == NULL) {
        fprintf(stderr, "Failed to allocate memory for CRC indication list\n");
        return;
    }

    // Initialize each element in the list with a random RNTI value and CRCFLAG set to 1
    unsigned short rand_rnti = 0;
    for (unsigned int i = 0; i < num_elems; ++i) {
        srand(time(NULL));
        rand_rnti = (unsigned short)(rand() % USHRT_MAX);
        (*list)[i].rx_ue_information_tag = 0;
        (*list)[i].rnti = rand_rnti;
        (*list)[i].crc_indication_rel8_tag = 1;
    }
}

// Define function to find and print largest RNTI value in list
void print_largest_rnti(NFAPI_CRC_INDICATION_PDU_T *list, unsigned int num_elems) {
    // Check if input is valid
    if (num_elems == 0) {
        fprintf(stderr, "Invalid input: number of elements in list must be positive\n");
        return;
    }

    // Initialize largest RNTI value to smallest possible value
    unsigned short largest_rnti = 0;

    // Iterate over each element in the list and find largest RNTI value
    for (unsigned int i = 0; i < num_elems; ++i) {
        if ((*list)[i].rnti > largest_rnti) {
            largest_rnti = (*list)[i].rnti;
        }
    }

    // Print largest RNTI value
    printf("Largest RNTI value: %hu\n", largest_rnti);
}
