void add_LTE_RRC_CU_MESSAGE_T(LTE_RRC_CU_MESSAGES_T *messages, LTE_RRC_CU_MESSAGE_T *message) {
    if (messages->num_messages >= messages->capacity) {
        // Reallocate memory to accommodate new message
        size_t new_capacity = messages->capacity * 2;
        LTE_RRC_CU_MESSAGE_T *new_messages = realloc(messages->messages, sizeof(LTE_RRC_CU_MESSAGE_T) * new_capacity);
        if (!new_messages) {
            // Handle memory allocation failure
        }
        messages->messages = new_messages;
        messages->capacity = new_capacity;
    }
    messages->messages[messages->num_messages++] = message;
}

void update_LTE_RRC_CU_MESSAGE_T(LTE_RRC_CU_MESSAGES_T *messages, size_t index, LTE_RRC_CU_MESSAGE_T *message) {
    if (index < messages->num_messages && message != NULL) {
