typedef struct {
    int key;
    long offset;
} record;

int initialize_records(const char* filename, const double factor) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    long num_records;
    record* records = NULL;
    double* offset_values = NULL;
    int* keys = NULL;

    // Read the number of records from the first line of the file
    if (fscanf(fp, "%ld", &num_records) != 1) {
        printf("Error reading number of records\n");
        fclose(fp);
        return -1;
    }

    // Allocate memory for the arrays
    offset_values = (double*)calloc(num_records, sizeof(double));
    keys = (int*)calloc(num_records, sizeof(int));
    records = (record*)calloc(num_records, sizeof(record));

    // Check for allocation failures
    if (offset_values == NULL || keys == NULL || records == NULL) {
        printf("Error allocating memory\n");
        fclose(fp);
        free(offset_values);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize the arrays with data from the file
    for (long i = 0; i < num_records; i++) {
        if (fscanf(fp, "%d,%lf", &keys[i], &offset_values[i]) != 2) {
            printf("Error reading record %ld\n", i);
            fclose(fp);
            free(offset_values);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Close the file and perform the transformation on the integer values
    fclose(fp);

    for (long i = 0; i < num_records; i++) {
        if (offset_values[i] > INT_MAX * factor) {
            printf("Overflow encountered at record %ld\n", i);
            free(offset_values);
            free(keys);
            free(records);
            return -1;
        } else {
            offset_values[i] = (int)(offset_values[i] * factor);
        }
    }

    // Initialize the record structures and deallocate memory
    for (long i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offset_values[i];
        free(keys);
        free(offset_values);
        return 0;
    }
}
