// Structure to hold UE context information
typedef struct UEContext {
    char* ue_name;
    int num_rrc_conn_reconf;
    int num_nas_msgs;
    RRC_Connection_Reconfiguration* rrc_conn_reconfs;
    NAS_Message** nas_msgs;
} UEContext;

// Function to initialize UE contexts
void initializeUEContexts(UEContext* ue_contexts, int num_ues) {
    // Initialize the number of RRC connection reconfiguration messages and NAS messages for each UE
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i].num_rrc_conn_reconf = 0;
        ue_contexts[i].num_nas_msgs = 0;
    }

    // Allocate memory for RRC connection reconfiguration messages and NAS messages for each UE
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i].rrc_conn_reconfs = my_alloc(sizeof(RRC_Connection_Reconfiguration) * MAX_NUM_RRC_CONN_RECONF);
        if (!ue_contexts[i].rrc_conn_reconfs) {
            printf("Failed to allocate memory for RRC connection reconfiguration messages\n");
            return;
        }
        ue_contexts[i].nas_msgs = my_alloc(sizeof(NAS_Message*) * MAX_NUM_NAS_MSGS);
        if (!ue_contexts[i].nas_msgs) {
            printf("Failed to allocate memory for NAS messages\n");
            return;
        }
    }
}

// Function to add a new RRC connection reconfiguration message and associate it with a NAS message
void addRRCConnReconf(UEContext* ue_contexts, int num_ues, int ue_idx, char* nas_msg) {
    // Check if there is space available for the new RRC connection reconfiguration message
    if (ue_contexts[ue_idx].num_rrc_conn_reconf >= MAX_NUM_RRC_CONN_RECONF) {
        printf("No more space available for new RRC connection reconfiguration messages\n");
        return;
    }

    // Add the new RRC connection reconfiguration message and associate it with a NAS message
    ue_contexts[ue_idx].rrc_conn_reconfs[ue_contexts[ue_idx].num_rrc_conn_reconf] = (RRC_Connection_Reconfiguration) { 0 };
    ue_contexts[ue_idx].nas_msgs[ue_contexts[ue_idx].num_nas_msgs++] = nas_msg;
    ue_contexts[ue_idx].num_rrc_conn_reconf++;
}

// Function to remove a RRC connection reconfiguration message and its associated NAS message
void removeRRCConnReconf(UEContext* ue_contexts, int num_ues, int ue_idx, int rrc_conn_reconf_idx) {
    // Check if the specified RRC connection reconfiguration message exists
    if (rrc_conn_reconf_idx >= ue_contexts[ue_idx].num_rrc_conn_reconf || rrc_conn_reconf_idx < 0) {
        printf("Specified RRC connection reconfiguration message does not exist\n");
        return;
    }

    // Remove the specified RRC connection reconfiguration message and its associated NAS message
    ue_contexts[ue_idx].num_rrc_conn_reconf--;
    for (int i = rrc_conn_reconf_idx; i < ue_contexts[ue_idx].num_rrc_conn_reconf; i++) {
        ue_contexts[ue_idx].rrc_conn_reconfs[i] = ue_contexts[ue_idx].rrc_conn_reconfs[i + 1];
    }
    for (int i = 0; i < ue_contexts[ue_idx].num_nas_msgs; i++) {
        if (ue_contexts[ue_idx].nas_msgs[i] == NULL) {
            continue;
        } else if (ue_contexts[ue_idx].nas_msgs[i]->message_number == ue_contexts[ue_idx].rrc_conn_reconfs[rrc_conn_reconf_idx].message_number) {
            free(ue_contexts[ue_idx].nas_msgs[i]);
            ue_contexts[ue_idx].nas_msgs[i] = NULL;
        }
    }
}

// Function to clear all allocated resources when the function completes
void cleanupUEContexts(UEContext* ue_contexts, int num_ues) {
    // Clear all RRC connection reconfiguration messages and NAS messages for each UE
    for (int i = 0; i < num_ues; i++) {
        for (int j = 0; j < ue_contexts[i].num_rrc_conn_reconf; j++) {
            free(ue_contexts[i].rrc_conn_reconfs[j]);
        }
        for (int j = 0; j < ue_contexts[i].num_nas_msgs; j++) {
            if (ue_contexts[i].nas_msgs[j] != NULL) {
                free(ue_contexts[i].nas_msgs[j]);
            }
        }
    }

    // Free the memory allocated for UE contexts
    free(ue_contexts);
}
