// Thread-safe linked list implementation of NFAPI_CRC_INDICATION_PDU_T structures
struct nfapi_crc_indication_list {
  struct nfapi_crc_indication_node *head;
  struct nfapi_crc_indication_node *tail;
  pthread_mutex_t mutex;
};

struct nfapi_crc_indication_node {
  struct nfapi_crc_indication_node *next;
  NFAPI_CRC_INDICATION_PDU_T pdu;
};

// Initialize the linked list with a mutex for thread-safe operations
void init_nfapi_crc_indication_list(struct nfapi_crc_indication_list *list) {
  list->head = NULL;
  list->tail = NULL;
  pthread_mutex_init(&list->mutex, NULL);
}

// Insert a new node into the linked list with a random CRCFLAG value
void insert_nfapi_crc_indication(struct nfapi_crc_indication_list *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
  struct nfapi_crc_indication_node *new_node = malloc(sizeof(struct nfapi_crc_indication_node));
  new_node->pdu = pdu;

  // Generate a random CRCFLAG value
  int flag = rand() % 2;
  if (flag) {
    new_node->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
  } else {
    new_node->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
  }

  pthread_mutex_lock(&list->mutex);
  if (list->head == NULL) {
    list->head = new_node;
    list->tail = new_node;
  } else {
    list->tail->next = new_node;
    list->tail = new_node;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Update the CRCFLAG value of an existing node in the linked list
void update_nfapi_crc_indication(struct nfapi_crc_indication_list *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
  struct nfapi_crc_indication_node *node = find_nfapi_crc_indication(list, pdu.RX_UE_INFORMATION_TAG);
  if (node != NULL) {
    node->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = pdu.CRC_INDICATION_REL8_TAG.CRCFLAG;
  }
}

// Remove a node from the linked list based on its RNTI value
void remove_nfapi_crc_indication(struct nfapi_crc_indication_list *list, uint16_t rnti) {
  struct nfapi_crc_indication_node *prev = NULL;
  struct nfapi_crc_indication_node *node = list->head;

  pthread_mutex_lock(&list->mutex);
  while (node != NULL) {
    if (node->pdu.RX_UE_INFORMATION_TAG.rnti == rnti) {
      if (prev != NULL) {
        prev->next = node->next;
      } else {
        list->head = node->next;
      }
      free(node);
      break;
    }
    prev = node;
    node = node->next;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Find a node in the linked list based on its RNTI value
struct nfapi_crc_indication_node *find_nfapi_crc_indication(struct nfapi_crc_indication_list *list, uint16_t rnti) {
  struct nfapi_crc_indication_node *node = list->head;

  pthread_mutex_lock(&list->mutex);
  while (node != NULL) {
    if (node->pdu.RX_UE_INFORMATION_TAG.rnti == rnti) {
      break;
    }
    node = node->next;
  }
  pthread_mutex_unlock(&list->mutex);

  return node;
}

// Iterate over the linked list in forward direction
void iterate_nfapi_crc_indication(struct nfapi_crc_indication_list *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
  struct nfapi_crc_indication_node *node = list->head;

  pthread_mutex_lock(&list->mutex);
  while (node != NULL) {
    callback(node->pdu);
    node = node->next;
  }
  pthread_mutex_unlock(&list->mutex);
}

// Iterate over the linked list in reverse direction
void iterate_nfapi_crc_indication_reverse(struct nfapi_crc_indication_list *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
  struct nfapi_crc_indication_node *node = list->tail;

  pthread_mutex_lock(&list->mutex);
  while (node != NULL) {
    callback(node->pdu);
    node = node->prev;
  }
  pthread_mutex_unlock(&list->mutex);
}
