Record* initializeDataStructures(int numRecords, int rangeStart, int rangeEnd, int stepSize, const char* formatString, unsigned long seed) {
    // Allocate memory for the offset and key arrays
    int* offsets = (int*)malloc(numRecords * sizeof(int));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));

    // Initialize the offset and key arrays with values derived from the specified range and step size
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rangeStart + (stepSize * i);
        keys[i] = rand_r(&seed) % (rangeEnd - rangeStart) + rangeStart;
    }

    // Allocate memory for the string buffers
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        snprintf(records[i]->string, sizeof(records[i]->string), formatString, i);
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
    }

    // Implement error handling to manage potential failures during memory allocation and ensure that all allocated memory is properly freed upon function exit
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Out of memory\n");
        free(offsets);
        free(keys);
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }
        return NULL;
    }

    // Consider performance implications and design the function to minimize memory fragmentation and maximize cache efficiency
    int* offsets_ptr = (int*)malloc(numRecords * sizeof(int));
    int* keys_ptr = (int*)malloc(numRecords * sizeof(int));
    Record** records_ptr = (Record**)malloc(numRecords * sizeof(Record*));
    memcpy(offsets_ptr, offsets, numRecords * sizeof(int));
    memcpy(keys_ptr, keys, numRecords * sizeof(int));
    memcpy(records_ptr, records, numRecords * sizeof(Record*));
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    offsets = offsets_ptr;
    keys = keys_ptr;
    records = records_ptr;

    // Ensure that the function can handle large numbers of records efficiently without compromising memory usage or performance
    if (numRecords > 1000) {
        int numChunks = numRecords / 1000;
        for (int i = 0; i < numChunks; i++) {
            initializeDataStructures(1000, rangeStart, rangeEnd, stepSize, formatString, seed + i);
        }
    }

    // Provide a mechanism for logging memory usage and performance metrics to aid in monitoring and optimization efforts
    printf("Memory used: %ld bytes\n", (long)((numRecords * sizeof(int)) + (numRecords * sizeof(Record*))));
    printf("Performance: %.2f seconds per record\n", ((double)(clock() - startTime) / CLOCKS_PER_SEC) / numRecords);

    // Return the offset, key, and record arrays
    return records;
}
