            project_tasks[i]->task_timeline->end_time = (int)time(NULL);
        } else {
            // Validate that start and end times are in chronological order
            if (project_tasks[i]->task_timeline->start_time > project_tasks[i]->task_timeline->end_time) {
                int temp = project_tasks[i]->task_timeline->start_time;
                project_tasks[i]->task_timeline->start_time = project_tasks[i]->task_timeline->end_time;
                project_tasks[i]->task_timeline->end_time = temp;
            }
        }
    }

    // Track the progress of tasks and manage deadlines efficiently
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    pthread_cond_t *cv = (pthread_cond_t *)malloc(sizeof(pthread_cond_t));

    // Monitor the array of ProjectTasks for changes and signal any waiting threads when a change is made
    void monitor_project_tasks() {
        pthread_mutex_lock(mutex);
        while (1) {
            pthread_cond_wait(cv, mutex);
            // Update the progress of each task and check if deadlines have been met
            for (int i = 0; i < task_count; i++) {
                update_task_progress(project_tasks[i]);
                check_deadline(project_tasks[i]);
            }
        }
    }

    // Update the progress of a single task and signal any waiting threads
    void update_task_progress(ProjectTask *task) {
        pthread_mutex_lock(mutex);
        if (task->task_timeline->end_time - task->task_timeline->start_time >= 0) {
            // Update the progress of the task based on the elapsed time
            int elapsed_time = task->task_timeline->end_time - task->task_timeline->start_time;
            float progress = (float)elapsed_time / task->task_details->deadline * 100;
            // Signal any waiting threads that the task's progress has changed
            pthread_cond_signal(cv);
        }
    }

    // Check if a single task's deadline has been met and signal any waiting threads
