        pthread_mutex_lock(mutex);
        if (task->task_timeline->end_time - task->task_timeline->start_time >= 0) {
            // Check if the task's deadline has been met
            bool deadline_met = (float)task->task_details->deadline / task->task_timeline->end_time * 100;
