    struct record *records = malloc(sizeof(struct record) * 1024);
    char **keys = malloc(sizeof(char *) * 1024);
    if (records == NULL || keys == NULL) {
        perror("Error allocating memory for records and keys");
        fclose(file);
        return 1;
    }

    // Read the records from the file and transform them as needed
    while (!feof(file)) {
        struct record r;
        if (fscanf(file, "%d %s", &r.offset, r.key) != 2) {
            perror("Error reading record");
            fclose(file);
            return 1;
        }
        if (predicate(&r)) {
            r.record_data = malloc(sizeof(void *) * 1024);
            memset(r.record_data, 0, sizeof(void *) * 1024);
            for (int i = 0; i < 1024; i++) {
                if (fscanf(file, "%d", &r.offset) != 1) {
                    perror("Error reading record");
                    fclose(file);
                    return 1;
                }
                r.record_data[i] = malloc(sizeof(void *) * 1024);
                memset(r.record_data[i], 0, sizeof(void *) * 1024);
            }
        }
        records[i] = r;
    }

