        data->offset[record_index] = offset;
        data->records[record_index].key = &data->key[record_index];
        data->records[record_index].offset = &data->offset[record_index];
        data->records[record_index].timestamp = get_timestamp();

        // Increment the record index and log the processed data for audit purposes
        record_index++;
        data->num_records++;
        log_data(data);
    }

    // Clean up memory allocation for the line buffer
    free(line);

    // Close the input file
    fclose(file);

    return 0;
}

// Implement function for cleaning up arrays after use
void cleanup_arrays(array_data *data) {
    if (data->records != NULL) {
        free(data->records);
    }
    if (data->key != NULL) {
        free(data->key);
    }
    if (data->offset != NULL) {
        free(data->offset);
    }
}

// Implement function for transforming integer values in the arrays
int transform_values(array_data *data, int factor) {
    // Check that the factor is valid
    if (factor <= 0 || factor > MAX_INT_VALUE) {
        handle_error("Invalid transformation factor");
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Iterate over the records and transform the integer values
    for (int i = 0; i < data->num_records; i++) {
        int new_value = data->records[i].key * factor;
        if (new_value > MAX_INT_VALUE) {
            handle_error("Overflow when applying transformation factor");
            return MEMORY_ALLOCATION_FAILURE;
        }
        data->records[i].key = new_value;
    }

    return 0;
}

