int generateAndLoadNfarb(char *filepath, struct nfapi_crc_indication_pdu **nfarb, int max_items) {
    /* Check for invalid arguments */
    if (filepath == NULL || nfarb == NULL || max_items <= 0) {
        return -1;
    }

    /* Open the file for reading */
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("fopen");
        return -2;
    }

    /* Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures */
    struct nfapi_crc_indication_pdu *nfapi_crc_indication_pdu = NULL;
    int items = 0, size = 0;

    /* Read the file line by line and parse each line as a key-value pair */
    char *line = NULL;
    size_t len = 0;
    while ((len = getline(&line, &size, fp)) != -1) {
        /* Skip empty lines and comments */
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        /* Allocate memory for the key-value pair */
        struct kv_pair *kv = malloc(sizeof(struct kv_pair));
        if (kv == NULL) {
            perror("malloc");
            break;
        }

        /* Split the line into a key and value using ':' as a delimiter */
        char *key = strtok(line, ":");
        char *value = strtok(NULL, ":");

        /* Check for invalid arguments */
        if (key == NULL || value == NULL) {
            free(kv);
            continue;
        }

        /* Store the key and value in the structure */
        kv->key = key;
        kv->value = value;

        /* Increment the number of items and allocate memory for the next item */
        ++items;
        if (items > max_items) {
            break;
        }

        /* Add the structure to the list */
        nfapi_crc_indication_pdu = realloc(nfapi_crc_indication_pdu, items * sizeof(struct nfapi_crc_indication_pdu));
        if (nfapi_crc_indication_pdu == NULL) {
            perror("realloc");
            break;
        }

        /* Initialize the structure */
        memset(&nfapi_crc_indication_pdu[items - 1], 0, sizeof(struct nfapi_crc_indication_pdu));

        /* Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG */
        if (sscanf(kv->value, "%hhu,%hhu", &nfapi_crc_indication_pdu[items - 1].rx_ue_information_tag, &nfapi_crc_indication_pdu[items - 1].crc_indication_rel8_tag) != 2) {
            free(kv);
            continue;
        }

        /* Set the RNTI and CRCFLAG */
        if (sscanf(kv->value, "%hu,%hhu", &nfapi_crc_indication_pdu[items - 1].rnti, &nfapi_crc_indication_pdu[items - 1].crcfalg) != 2) {
            free(kv);
            continue;
        }

        /* Free the key-value pair */
        free(kv);
    }

    /* Close the file */
    fclose(fp);

    /* Return the number of items in the bundle and the list of NFAPI_CRC_INDICATION_PDU_T structures */
    *nfarb = nfapi_crc_indication_pdu;
    return items;
}
