#include <pthread.h>

// Define structure for configuration record
typedef struct {
  int id;
  int value;
} ConfigRecord;

// Define structure for configuration structure
typedef struct {
  ConfigRecord *records;
  size_t numRecords;
} ConfigStruct;

// Function to manage configuration structure
ConfigStruct* configManage(size_t numRecords, int idPool[], char *dirName) {
  // Allocate memory for configuration structure and initialize it
  ConfigStruct *config = malloc(sizeof(ConfigStruct));
  if (!config) {
    printf("Error: unable to allocate memory for configuration structure\n");
    return NULL;
  }
  config->records = malloc(numRecords * sizeof(ConfigRecord));
  if (!config->records) {
    free(config);
    printf("Error: unable to allocate memory for records in configuration structure\n");
    return NULL;
  }
  config->numRecords = numRecords;

  // Initialize values of configuration records using random numbers within range
  srand(time(NULL));
  int i;
  for (i = 0; i < numRecords; ++i) {
    config->records[i].id = idPool[rand() % (sizeof(idPool) / sizeof(*idPool))];
    config->records[i].value = rand() % 100;
  }

  // Create new directory with given name and set environment variable to its path
  char *envVar = "CONFIG_DIR";
  int res = mkdir(dirName, S_IRWXU | S_IRWXG);
  if (res != 0) {
    if (errno == EEXIST) {
      // Use existing directory and set environment variable to its path
      char *path = getenv(envVar);
      if (!path) {
        printf("Error: unable to set environment variable %s\n", envVar);
        free(config->records);
        free(config);
        return NULL;
      }
      config->directoryPath = path;
    } else {
      // Failed to create directory, handle error gracefully
      printf("Error: unable to create directory %s\n", dirName);
      free(config->records);
      free(config);
      return NULL;
    }
  } else {
    // Set environment variable to path of new directory
    char *path = malloc(strlen(dirName) + strlen("/") + 1);
    if (!path) {
      printf("Error: unable to allocate memory for environment variable %s\n", envVar);
      free(config->records);
      free(config);
      return NULL;
    }
    sprintf(path, "%s/%s", dirName, "");
    res = setenv(envVar, path, 1);
    if (res != 0) {
      printf("Error: unable to set environment variable %s\n", envVar);
      free(path);
      free(config->records);
      free(config);
      return NULL;
    }
    config->directoryPath = path;
  }

  // Return configuration structure
  return config;
}
