struct EVP_CIPHER* get_cipher(const char *algorithm, const char *mode) {
    if (strcmp(algorithm, "aes-128") == 0) {
        return EVP_aes_128_cbc();
    } else if (strcmp(algorithm, "aes-192") == 0) {
        return EVP_aes_192_cbc();
    } else if (strcmp(algorithm, "aes-256") == 0) {
        return EVP_aes_256_cbc();
    } else if (strcmp(algorithm, "chacha20") == 0) {
        return EVP_chacha20();
    } else if (strcmp(algorithm, "camellia-128") == 0) {
        return EVP_camellia_128_cbc();
    } else if (strcmp(algorithm, "camellia-192") == 0) {
        return EVP_camellia_192_cbc();
    } else if (strcmp(algorithm, "camellia-256") == 0) {
        return EVP_camellia_256_cbc();
    } else {
        ERR_load_ERR_strings();
        ERR_error_string(ERR_get_error(), algorithm);
        return NULL;
    }
}

struct EVP_CIPHER* get_cipher_mode(const char *algorithm, const char *mode) {
    if (strcmp(mode, "cbc") == 0) {
        return EVP_aes_128_cbc();
    } else if (strcmp(mode, "gcm") == 0) {
        return EVP_aes_128_gcm();
    } else if (strcmp(mode, "ctr") == 0) {
        return EVP_aes_128_ctr();
    } else {
        ERR_load_ERR_strings();
        ERR_error_string(ERR_get_error(), mode);
        return NULL;
    }
}

struct EVP_CIPHER* get_cipher_and_mode(const char *algorithm, const char *mode) {
    struct EVP_CIPHER* cipher = get_cipher(algorithm, mode);
    if (cipher == NULL) {
        return NULL;
    } else {
        return get_cipher_mode(algorithm, mode);
    }
}
```
