typedef struct {
    RRC_Connection_Reconfiguration rrc_reconf;
    NAS_Message nas_msg;
} UEContext;

static UEContext ue_contexts[MAX_UE_CONTEXTS];
static int num_ue_contexts = 0;

bool initializeUEContexts(const char *rrc_reconf, const char *nas_msg) {
    // validate input parameters
    if (!rrc_reconf || !nas_msg) {
        return false;
    }

    // encode NAS message using external library
    int encoded_len = nas_encode(nas_msg, ue_contexts[num_ue_contexts].nas_message);
    if (encoded_len < 0) {
        printf("Error encoding NAS message\n");
        return false;
    }

    // validate encoded message length
    if (encoded_len > NAS_MESSAGE_LEN) {
        printf("Encoded NAS message too long, maximum length is %d\n", NAS_MESSAGE_LEN);
        return false;
    }

    // copy RRC reconfiguration message to UE context structure
    memcpy(&ue_contexts[num_ue_contexts].rrc_reconf, rrc_reconf, sizeof(RRC_Connection_Reconfiguration));

    num_ue_contexts++;
    return true;
}

void finalizeUEContexts() {
    // free any allocated memory for UE context structures
    for (int i = 0; i < num_ue_contexts; i++) {
        free(ue_contexts[i].nas_msg.nas_message);
    }
}

void printUEContexts() {
    // print each UE context structure to stdout
    for (int i = 0; i < num_ue_contexts; i++) {
        printf("UE Context %d: RRC reconfiguration message is ", i + 1);
        print_rrc_reconf(&ue_contexts[i].rrc_reconf);
        printf("NAS message is ");
        for (int j = 0; j < encoded_len; j++) {
            printf("%c", ue_contexts[i].nas_msg.nas_message[j]);
        }
        printf("\n");
    }
}
