// Define a structure to hold the records
typedef struct record {
    int key;
} Record;

// Define the maximum memory usage limit in bytes
const size_t MAX_MEMORY_LIMIT = 10 * 1024 * 1024; // 10 MB

// Define the range for the random integer values
const int RANDOM_INT_RANGE = 100;

// Function to manage memory for two dynamically allocated arrays: one for long offset values and another for int keys.
void manageMemory(int *keys, long *offsets, size_t numRecords) {
    // Calculate the total memory usage in bytes
    size_t totalMemUsage = sizeof(Record) * numRecords;

    // Check if the total memory usage exceeds the maximum limit
    if (totalMemUsage > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Error: Total memory usage exceeds maximum limit of %zu bytes\n", MAX_MEMORY_LIMIT);
        exit(1);
    }

    // Allocate memory for the arrays
    keys = (int *)malloc(numRecords * sizeof(int));
    offsets = (long *)malloc(numRecords * sizeof(long));

    if (!keys || !offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for the arrays\n");
        exit(1);
    }

    // Initialize the arrays with random values within the range
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = rand() % RANDOM_INT_RANGE + 1;
        offsets[i] = (long)(rand() % RANDOM_INT_RANGE + 1);
    }

    // Sort the records based on their associated key values using a custom comparator function
    qsort(keys, numRecords, sizeof(int), compareKeys);

    // Free the allocated memory
    free(keys);
    free(offsets);
}

// Custom comparator function for sorting the records based on their associated key values
int compareKeys(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
