#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

#define BUFFER_SIZE 4096
#define MEMORY_CHUNK_SIZE 1024
#define FILE_NAME "example.txt"

typedef struct {
    char *key;
    char *value;
} KeyValuePair;

// Dynamically allocate memory for the bundle and its items using malloc, calloc, or realloc
KeyValuePair **loadNfarbResourceBundle(const char *file_path) {
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    // Get the file size and allocate memory for the bundle and its items
    struct stat sb;
    fstat(fd, &sb);
    long file_size = sb.st_size;
    int num_items = file_size / BUFFER_SIZE;
    KeyValuePair **bundle = (KeyValuePair **)calloc(num_items, sizeof(KeyValuePair *));
    if (!bundle) {
        perror("calloc");
        close(fd);
        return NULL;
    }

    // Read the file and load the items into the bundle
    char *buffer = (char *)malloc(BUFFER_SIZE);
    if (!buffer) {
        perror("malloc");
        free(bundle);
        close(fd);
        return NULL;
    }

    int i, j;
    for (i = 0; i < num_items; i++) {
        // Read a line from the file into the buffer
        ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read == -1) {
            perror("read");
            free(buffer);
            close(fd);
            return NULL;
        }

        // Split the line into key and value
        char *key = strtok(buffer, ":");
        if (!key) {
            fprintf(stderr, "Invalid format: missing colon in item %d\n", i + 1);
            free(buffer);
            close(fd);
            return NULL;
        }
        char *value = strtok(NULL, "\n");
        if (!value) {
            fprintf(stderr, "Invalid format: missing value in item %d\n", i + 1);
            free(buffer);
            close(fd);
            return NULL;
        }

        // Allocate memory for the key and value
        bundle[i] = (KeyValuePair *)malloc(sizeof(KeyValuePair));
        if (!bundle[i]) {
            perror("malloc");
            free(buffer);
            close(fd);
            return NULL;
        }

        // Copy the key and value into the bundle
        strcpy(bundle[i]->key, key);
        strcpy(bundle[i]->value, value);
    }

    // Clean up
    free(buffer);
    close(fd);

    return bundle;
}

// Process the loaded items and print them to the console
void processNfarbResourceBundle(KeyValuePair **bundle) {
    int i, j;
    for (i = 0; i < num_items; i++) {
        // Print the key and value
        printf("Item %d: %s => %s\n", i + 1, bundle[i]->key, bundle[i]->value);

        // Free the memory for the item
        free(bundle[i]);
    }

    // Clean up
    free(bundle);
}
