#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for UE context
typedef struct {
    RRC_Connection_Reconfiguration rrc_reconf;
    NAS_Message nas_msg;
} UEContext;

// Define a custom memory pool for efficient allocation and deallocation of NAS messages
struct MemoryPool {
    void* free_list;  // List of free blocks
    int block_size;   // Size of each block in bytes
};

// Initialize the memory pool with a given number of blocks and block size
void mempool_init(struct MemoryPool* pool, int num_blocks, int block_size) {
    pool->free_list = NULL;
    pool->block_size = block_size;
}

// Allocate a new block from the memory pool
void* mempool_alloc(struct MemoryPool* pool) {
    void* block = malloc(pool->block_size);
    if (block == NULL) return NULL;
    // Add the new block to the free list
    *((void**)block) = pool->free_list;
    pool->free_list = block;
    return block;
}

// Deallocate a block from the memory pool
void mempool_dealloc(struct MemoryPool* pool, void* block) {
    // Remove the block from the free list
    *((void**)block) = pool->free_list;
    pool->free_list = block;
}

// Initialize and populate an array of UEContext structures with valid RRC_Connection_Reconfiguration messages and NAS_Message fields
void init_uecontext(UEContext* uecontext, int num_uests) {
    // Allocate memory for the UEContext array
    uecontext = malloc(sizeof(UEContext) * num_uests);
    if (uecontext == NULL) {
        printf("Failed to allocate memory for UEContext array\n");
        return;
    }

    // Initialize the RRC_Connection_Reconfiguration messages and NAS_Message fields
    int i;
    for (i = 0; i < num_uests; i++) {
        // Allocate a new block from the memory pool for the NAS message
        void* nas_msg_block = mempool_alloc(&nas_msg_pool);
        if (nas_msg_block == NULL) {
            printf("Failed to allocate memory for NAS message\n");
            return;
        }

        // Initialize the RRC_Connection_Reconfiguration message and encode it
        uecontext[i].rrc_reconf.msg_type = 1;
        uecontext[i].rrc_reconf.length = 32;
        memset(uecontext[i].rrc_reconf.data, 0, 32);

        // Initialize the NAS message and encode it
        uecontext[i].nas_msg.msg_type = 2;
        uecontext[i].nas_msg.length = 64;
        memset(uecontext[i].nas_msg.data, 0, 64);

        // Deallocate the memory block for the NAS message if it is not used anymore
        if (mempool_dealloc(&nas_msg_pool, nas_msg_block) != 0) {
            printf("Failed to deallocate memory for NAS message\n");
            return;
        }
    }
}

// Free the memory allocated for the UEContext array and the custom memory pool
void free_uecontext(UEContext* uecontext, int num_uests) {
    // Free the memory allocated for the UEContext array
    if (uecontext != NULL) {
        free(uecontext);
    }

    // Deallocate all blocks from the custom memory pool
    while (nas_msg_pool.free_list != NULL) {
        void* block = nas_msg_pool.free_list;
        nas_msg_pool.free_list = *((void**)block);
        free(block);
    }
}

// Serialization mechanism to store the populated UEContext array to disk in a binary format
int serialize_uecontext(UEContext* uecontext, int num_uests, const char* filename) {
    // Open the file for writing and check for errors
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Failed to open file %s for writing\n", filename);
        return -1;
    }

    // Write the UEContext array to the file
    int i;
    for (i = 0; i < num_uests; i++) {
        fwrite(&uecontext[i], sizeof(UEContext), 1, fp);
    }

    // Close the file and check for errors
    if (fclose(fp) != 0) {
        printf("Failed to close file %s\n", filename);
        return -1;
    }

    return 0;
}

// Deserialization mechanism to read the populated UEContext array from disk in a binary format
int deserialize_uecontext(UEContext* uecontext, int num_uests, const char* filename) {
    // Open the file for reading and check for errors
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Failed to open file %s for reading\n", filename);
        return -1;
    }

    // Read the UEContext array from the file
    int i;
    for (i = 0; i < num_uests; i++) {
        fread(&uecontext[i], sizeof(UEContext), 1, fp);
    }

    // Close the file and check for errors
    if (fclose(fp) != 0) {
        printf("Failed to close file %s\n", filename);
        return -1;
    }

    return 0;
}
