// Define a dynamic array to store the LTE_DL_CCCH_Message data
static LTE_DL_CCCH_Message *messages = NULL;
static size_t num_messages = 0;

// Function to add a new message to the array
int add_message(NAS_MESSAGE *nas_message, LOGICAL_CHANNEL_GROUP *logical_channel_group) {
    // Allocate memory for the new message
    LTE_DL_CCCH_Message *new_message = malloc(sizeof(LTE_DL_CCCH_Message));
    if (new_message == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        return -1;
    }

    // Initialize the new message with the given data
    new_message->nas_message = nas_message;
    new_message->logical_channel_group = logical_channel_group;

    // Add the new message to the array
    messages = realloc(messages, (num_messages + 1) * sizeof(LTE_DL_CCCH_Message));
    if (messages == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        free(new_message);
        return -1;
    }
    messages[num_messages] = new_message;
    num_messages++;

    return 0;
}

// Function to remove a message from the array by identifier
int remove_message(LOGICAL_CHANNEL_GROUP *logical_channel_group) {
    // Find the index of the message with the given identifier
    size_t i = 0;
    for (i = 0; i < num_messages; i++) {
        if (messages[i]->logical_channel_group == logical_channel_group) {
            break;
        }
    }

    // If the message was not found, return an error
    if (i >= num_messages) {
        fprintf(stderr, "Error: Message with given identifier not found\n");
        return -1;
    }

    // Remove the message from the array
    messages[i] = messages[num_messages - 1];
    num_messages--;

    free(messages[i]);

    return 0;
}

// Function to iterate over all messages in the array and process their content
int process_messages() {
    // Iterate over all messages in the array
    for (size_t i = 0; i < num_messages; i++) {
        LTE_DL_CCCH_Message *message = messages[i];

        // Process the message content using the third-party library
        int ret = process_nas_message(message->nas_message);
        if (ret != 0) {
            fprintf(stderr, "Error: Failed to process NAS message\n");
            return -1;
        }
    }

    return 0;
}

// Function to free the memory allocated for the dynamic array and reset the counter
void cleanup() {
    // Free the memory allocated for the messages
    for (size_t i = 0; i < num_messages; i++) {
        free(messages[i]);
    }
    free(messages);
    messages = NULL;
    num_messages = 0;
}
```
This implementation uses a dynamic array to store the `LTE_DL_CCCH_Message` structures, which allows for efficient addition and removal of messages. The function `add_message()` allocates memory for the new message and initializes it with the given data. If the allocation fails, the function returns an error code. The function `remove_message()` finds the index of the message with the given identifier and removes it from the array by swapping it with the last element. If the message is not found, the function returns an error code. The function `process_messages()` iterates over all messages in the array and processes their content using the third-party library for NAS messaging. The function `cleanup()` frees the memory allocated for the dynamic array and resets the counter to 0.

