// Hash table for tracking unique CELL_ID values
typedef struct {
    int size;
    int num_elements;
    LTE_DL_CCCH_Message **table;
} CellIdHashTable;

// Lock for synchronizing access to the hash table and the array of structures
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

void init_hash_table(CellIdHashTable *ht) {
    ht->size = 1000;
    ht->num_elements = 0;
    ht->table = (LTE_DL_CCCH_Message **)malloc(ht->size * sizeof(LTE_DL_CCCH_Message *));
    memset(ht->table, 0, ht->size * sizeof(LTE_DL_CCCH_Message *));
}

void destroy_hash_table(CellIdHashTable *ht) {
    free(ht->table);
}

int hash(int cell_id) {
    return cell_id % ht.size;
}

int add_message(LTE_DL_CCCH_Message *msg, CellIdHashTable *ht) {
    pthread_rwlock_wrlock(&lock);
    int index = hash(msg->cell_id);
    if (index < 0 || index >= ht.size || ht->table[index] != NULL) {
        pthread_rwlock_unlock(&lock);
        return -1;
    }
    ht->table[index] = msg;
    ht->num_elements++;
    pthread_rwlock_unlock(&lock);
    return 0;
}

int remove_message(LTE_DL_CCCH_Message *msg, CellIdHashTable *ht) {
    pthread_rwlock_wrlock(&lock);
    int index = hash(msg->cell_id);
    if (index < 0 || index >= ht.size || ht->table[index] == NULL) {
        pthread_rwlock_unlock(&lock);
        return -1;
    }
    ht->table[index] = NULL;
    ht->num_elements--;
    pthread_rwlock_unlock(&lock);
    return 0;
}

int get_message(LTE_DL_CCCH_Message *msg, CellIdHashTable *ht) {
    pthread_rwlock_rdlock(&lock);
    int index = hash(msg->cell_id);
    if (index < 0 || index >= ht.size || ht->table[index] == NULL) {
        pthread_rwlock_unlock(&lock);
        return -1;
    }
    memcpy(msg, ht->table[index], sizeof(LTE_DL_CCCH_Message));
    pthread_rwlock_unlock(&lock);
    return 0;
}

int iterate_messages(CellIdHashTable *ht, void (*callback)(LTE_DL_CCCH_Message *)) {
    pthread_rwlock_rdlock(&lock);
    for (int i = 0; i < ht.size; i++) {
        if (ht->table[i] != NULL) {
            callback(ht->table[i]);
        }
    }
    pthread_rwlock_unlock(&lock);
}
```

