    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the custom Union-Find data structure
typedef struct {
    uint32_t rank;
    uint32_t parent;
} UnionFindSet;

void createAndPopulateList(int N) {
    // Declare a list to store the populated structures
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    // Generate random values for RX_UE_INFORMATION_TAG and RNTI
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        list[i].RNTI = rand() % 100000000;
    }

    // Set the CRCFLAG to a random value for each structure
    for (int i = 0; i < N; i++) {
        list[i].CRCFLAG = rand() % 2;
    }

    // Use the custom Union-Find data structure to efficiently determine disjoint sets of RNTI values
    UnionFindSet* ufs = (UnionFindSet*)malloc(sizeof(UnionFindSet) * N);
    for (int i = 0; i < N; i++) {
        ufs[i].rank = 1;
        ufs[i].parent = i;
    }

    // Iterate over the list and update the Union-Find data structure accordingly
    for (int i = 0; i < N; i++) {
        int currentRNTI = list[i].RNTI;
        int currentParent = findSet(ufs, currentRNTI);

        // Iterate over the remaining structures and update the Union-Find data structure if necessary
        for (int j = i + 1; j < N; j++) {
            int otherRNTI = list[j].RNTI;
            int otherParent = findSet(ufs, otherRNTI);

            // If the RNTI values are equal, merge the sets and update the rank of the parent set
            if (currentRNTI == otherRNTI) {
                UnionFindSet* parentSet = ufs + currentParent;
                parentSet->rank++;

                int otherRank = ufs[otherParent].rank;
                for (int k = 0; k < otherRank; k++) {
                    ufs[otherParent * N].parent = currentParent;
                }
            }
        }
    }

    // Print the number of milliseconds taken to perform the disjointness checks for each RNTI pair
    clock_t startTime = clock();
    for (int i = 0; i < N; i++) {
        int currentRNTI = list[i].RNTI;
        int currentParent = findSet(ufs, currentRNTI);

        // Iterate over the remaining structures and check if the RNTI values form disjoint sets
        for (int j = i + 1; j < N; j++) {
            int otherRNTI = list[j].RNTI;
            int otherParent = findSet(ufs, otherRNTI);

            // If the RNTI values are not equal, print the number of milliseconds taken to perform the disjointness checks for each RNTI pair
            if (currentRNTI != otherRNTI) {
                int rank = ufs[otherParent].rank;
                for (int k = 0; k < rank; k++) {
                    printf("%d, %d\n", currentRNTI, otherRNTI);
                }
            }
        }
    }
    clock_t endTime = clock();

    // Free the memory allocated for the list and Union-Find data structure
    free(list);
    free(ufs);

    // Print the number of milliseconds taken to perform the disjointness checks for each RNTI pair
    printf("Number of milliseconds: %f\n", (endTime - startTime) * 1000.0 / CLOCKS_PER_SEC);
}

// Find the root node of a Union-Find set and update the parent pointers accordingly
int findSet(UnionFindSet* ufs, int rnti) {
    if (ufs[rnti].rank == 1) return rnti;

    // Iterate until the rank is 1 or the parent pointer points to itself
    while (ufs[rnti].parent != rnti) {
        ufs[rnti].parent = ufs[ufs[rnti].parent].parent;
        rnti = ufs[rnti].parent;
    }

    return rnti;
}
```']

