    while (1) {
        // Lock the cells array to prevent race conditions when adding or removing cells
        pthread_mutex_lock(&cells_lock);

        // Iterate over all cells in the cells array and update their configuration parameters
        int i;
        for (i = 0; i < sizeof(cells) / sizeof(CellInfo*); i++) {
            CellInfo* cell = cells[i];
            updateNetworkPerformanceMetrics(cell->base_station_id, cell->config);
        }

        // Unlock the cells array and sleep for a short period of time before checking again
        pthread_mutex_unlock(&cells_lock);
        usleep(1000);
    }
}
