#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/modes.h>
#include <openssl/rand.h>
#include <openssl/err.h>

/* Macros for error handling */
#define BUF_SIZE 4096
#define KEY_SIZE 16
#define IV_SIZE 16

typedef enum { ENC, DEC } MODE;

struct config {
    char* algorithm;
    char* key;
    char* iv;
};

static struct config* getConfig(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return NULL;
    }

    int len = 0;
    char* line = NULL;
    size_t n = 0;
    while ((n = getline(&line, &len, fp)) != -1) {
        if (strncmp(line, "algorithm=", 9) == 0) {
            config->algorithm = strdup(line + 9);
        } else if (strncmp(line, "key=", 4) == 0) {
            config->key = strdup(line + 4);
        } else if (strncmp(line, "iv=", 3) == 0) {
            config->iv = strdup(line + 3);
        }
    }

    fclose(fp);
    return config;
}

static void freeConfig(struct config* config) {
    if (config != NULL) {
        free(config->algorithm);
        free(config->key);
        free(config->iv);
        free(config);
    }
}

static int getAlgorithm(const char* algorithm) {
    if (strcmp(algorithm, "AES-128") == 0) {
        return AES_128;
    } else if (strcmp(algorithm, "AES-192") == 0) {
        return AES_192;
    } else if (strcmp(algorithm, "AES-256") == 0) {
        return AES_256;
    } else {
        printf("Unsupported algorithm: %s\n", algorithm);
        return -1;
    }
}

static int getKey(const char* key, unsigned char** out) {
    if (strlen(key) != KEY_SIZE * 2) {
        printf("Invalid key length: %lu\n", strlen(key));
        return -1;
    }

    EVP_BytesToKey(getAlgorithm(), EVP_aes_cbc(), NULL, (unsigned char*)key, strlen(key), 1, out, NULL);
    return 0;
}

static int getIV(const char* iv, unsigned char** out) {
    if (strlen(iv) != IV_SIZE * 2) {
        printf("Invalid IV length: %lu\n", strlen(iv));
        return -1;
    }

    sscanf(iv, "%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx%hhx", out);
    return 0;
}

static int encrypt(int fd, struct config* config) {
    unsigned char* key = NULL;
    unsigned char* iv = NULL;
    if (getKey(config->key, &key) != 0 || getIV(config->iv, &iv) != 0) {
        return -1;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, getAlgorithm(), NULL, key, iv) != 1) {
        printf("Failed to initialize encryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return -1;
    }

    unsigned char inbuf[BUF_SIZE];
    int inlen = 0;
    while ((inlen = read(fd, inbuf, BUF_SIZE)) > 0) {
        unsigned char outbuf[BUF_SIZE];
        int outlen = 0;
        if (EVP_EncryptUpdate(ctx, outbuf, &outlen, inbuf, inlen) != 1) {
            printf("Failed to encrypt data\n");
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            free(iv);
            return -1;
        }
        write(fd, outbuf, outlen);
    }

    unsigned char* final = NULL;
    int outlen = 0;
    if (EVP_EncryptFinal_ex(ctx, final, &outlen) != 1) {
        printf("Failed to encrypt data\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(iv);
    return 0;
}

static int decrypt(int fd, struct config* config) {
    unsigned char* key = NULL;
    unsigned char* iv = NULL;
    if (getKey(config->key, &key) != 0 || getIV(config->iv, &iv) != 0) {
        return -1;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (EVP_DecryptInit_ex(ctx, getAlgorithm(), NULL, key, iv) != 1) {
        printf("Failed to initialize decryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return -1;
    }

    unsigned char inbuf[BUF_SIZE];
    int inlen = 0;
    while ((inlen = read(fd, inbuf, BUF_SIZE)) > 0) {
        unsigned char outbuf[BUF_SIZE];
        int outlen = 0;
        if (EVP_DecryptUpdate(ctx, outbuf, &outlen, inbuf, inlen) != 1) {
            printf("Failed to decrypt data\n");
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            free(iv);
            return -1;
        }
        write(fd, outbuf, outlen);
    }

    unsigned char* final = NULL;
    int outlen = 0;
    if (EVP_DecryptFinal_ex(ctx, final, &outlen) != 1) {
        printf("Failed to decrypt data\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(iv);
    return 0;
}

static int processData(int fd, struct config* config) {
    if (config->mode == ENC) {
        return encrypt(fd, config);
    } else if (config->mode == DEC) {
        return decrypt(fd, config);
    } else {
        printf("Invalid mode\n");
        return -1;
    }
}

static void handleError(const char* message) {
    perror(message);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        printf("Usage: %s [enc/dec] [config file]\n", argv[0]);
        return -1;
    }

    struct config* config = getConfig(argv[2]);
    if (config == NULL) {
        handleError("Failed to load configuration");
        return -1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) {
        handleError("Failed to open input file");
        freeConfig(config);
        return -1;
    }

    int ret = processData(fd, config);
    close(fd);
    freeConfig(config);
    return ret;
}
