#include <string.h>
#include <openssl/evp.h>

typedef struct {
  int key;
} record;

EVP_CIPHER *init_cipher(int mode, int keysize, int datasize) {
  EVP_CIPHER *cipher = NULL;
  int ivsize, blocksize;
  switch (mode) {
    case EDE:
      cipher = EVP_des_ede();
      break;
    case EDE3:
      cipher = EVP_des_ede3();
      break;
    case CFB:
      cipher = EVP_des_cfb();
      break;
    default:
      break;
  }

  if (cipher) {
    ivsize = EVP_CIPHER_iv_length(cipher);
    blocksize = EVP_CIPHER_block_size(cipher);
    long *offsets = malloc((datasize / blocksize + 1) * sizeof(*offsets));
    int *keys = malloc((datasize / keysize + 1) * sizeof(*keys));
    record *records = malloc(datasize * sizeof(*records));
    for (int i = 0; i < datasize / blocksize; ++i) {
      offsets[i] = rand() % keysize;
      keys[i] = rand();
      records[i].key = rand();
    }
    EVP_CIPHER_CTX *ctx = EVP_CIPER_CTX_new();
    EVP_EncryptInit(ctx, cipher, NULL, NULL);
    int inl = 0;
    for (int i = 0; i < datasize / blocksize; ++i) {
      if (inl >= blocksize) {
        break;
      }
      EVP_EncryptUpdate(ctx, records[i].key, &keys[i], ivsize);
    }
    EVP_CIPHER_CTX_free(ctx);
  }
}
