        if (rntis->count == 0) {
            // Allocate memory for the first element in the dynamic array
            rntis->elements = (int*)malloc(sizeof(int));
            rntis->elements[0] = rnti;
            rntis->count++;
        } else {
            // Double the size of the dynamic array if it is full
            if (rntis->count == rntis->elements) {
                int* newElements = (int*)realloc(rntis->elements, sizeof(int) * 2 * rntis->count);
                if (newElements == NULL) {
                    // Handle memory allocation failure
                    return NULL;
                } else {
                    rntis->elements = newElements;
                    rntis->elements[rntis->count++] = rnti;
                }
            } else {
                rntis->elements[rntis->count++] = rnti;
            }
        }
    }

    return rntis;
}

// Function to identify and print the largest RNTI value present in a dynamically allocated array of integers
int findMaxRNTI(IntArray* rntis) {
    if (rntis == NULL || rntis->count == 0) {
        return -1;
    }

    int maxRNTI = rntis->elements[0];

    for (int i = 1; i < rntis->count; i++) {
        if (rntis->elements[i] > maxRNTI) {
            maxRNTI = rntis->elements[i];
        }
    }

    return maxRNTI;
}
