#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Structure to hold an integer value between -100 and 100, along with pointers to the next and previous nodes
typedef struct node {
    int value;
    struct node *next;
    struct node *prev;
} Node;

// Function to allocate memory for a new node
Node* new_node(int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Error: failed to allocate memory for new node\n");
        return NULL;
    }
    node->value = value;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to insert a new node into the doubly linked list
bool insert_node(Node* list, int value) {
    Node* node = new_node(value);
    if (!node) {
        fprintf(stderr, "Error: failed to allocate memory for new node\n");
        return false;
    }
    // If the list is empty, set the new node as both the head and tail
    if (list == NULL) {
        list = node;
        list->next = node;
        list->prev = node;
        return true;
    }
    // Set the new node's next pointer to point to the current head
    node->next = list->head;
    // Set the current head's prev pointer to point to the new node
    list->head->prev = node;
    // Set the new node as the new head
    list->head = node;
    return true;
}

// Function to delete a node from the doubly linked list
bool delete_node(Node* list, int value) {
    Node* node = find_node(list, value);
    if (!node) {
        fprintf(stderr, "Error: failed to find node with value %d\n", value);
        return false;
    }
    // If the node is the head or tail, set its next or prev pointer to NULL
    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
    }
    // Set the previous and next pointers of adjacent nodes to point to each other
    node->prev->next = node->next;
    node->next->prev = node->prev;
    free(node);
    return true;
}

// Function to find a node in the doubly linked list with a given value
Node* find_node(Node* list, int value) {
    Node* node = list;
    while (node != NULL && node->value != value) {
        node = node->next;
    }
    return node;
}

// Function to traverse the doubly linked list and print all values
void traverse_list(Node* list) {
    Node* node = list->head;
    while (node != NULL) {
        printf("%d ", node->value);
        node = node->next;
    }
    printf("\n");
}
