typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    // Set the CRCFLAG based on a hash of the RX_UE_INFORMATION_TAG and RNTI
    pdu->crcflag = calculate_crc_flag(rx_ue_information, rnti);

    // Add the new PDU to the list
    pdu->next = NULL;
    if (pdu_list == NULL) {
        pdu_list = pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *curr = pdu_list;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = pdu;
    }
}

void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu == pdu_list) {
        pdu_list = pdu->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *prev = pdu_list;
        while (prev != NULL && prev->next != pdu) {
            prev = prev->next;
        }
        if (prev != NULL) {
            prev->next = pdu->next;
        }
    }
}

void update_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    // Set the CRCFLAG based on a hash of the RX_UE_INFORMATION_TAG and RNTI
    pdu->crcflag = calculate_crc_flag(rx_ue_information, rnti);
}

CRCFLAG calculate_crc_flag(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    // Calculate a hash of the RX_UE_INFORMATION_TAG and RNTI
    unsigned long hash = 0;
    for (int i = 0; i < sizeof(rx_ue_information); ++i) {
        hash = (hash << 8) ^ rx_ue_information[i];
    }
    for (int i = 0; i < sizeof(rnti); ++i) {
        hash = (hash << 8) ^ rnti[i];
    }
    // Return the CRCFLAG based on the hash
    return hash % NUM_CRC_FLAG_VALUES;
}

void handle_crc_indications() {
    // Handle incoming CRC indications
    NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_list;
    while (pdu != NULL) {
        // Process the PDU
        process_crc_indication(pdu);
        // Move to the next PDU in the list
        pdu = pdu->next;
    }
}
