} NFAPI_CRC_INDICATION_PDU_T;

// List of structures to store the CRC indications in memory
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;

// Mutex used for thread-safe operations on the list
static pthread_mutex_t crc_indication_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random CRC flag value
bool generate_random_crcflag() {
    return (rand() % 2) == 0 ? true : false;
}

// Function to populate the list of structures with new CRC indications
void populate_crc_indication_list(uint32_t num_structures) {
    // Acquire mutex for thread-safe operations on the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if the list has reached its maximum capacity and dynamically allocate more memory if necessary
    if (num_structures >= MAX_STRUCTURES && crc_indication_list == NULL) {
        uint32_t new_max = num_structures + MEMORY_THRESHOLD;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_max);

        // Initialize the newly allocated memory and copy the existing data from the old list
        memcpy(new_list, crc_indication_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
        free(crc_indication_list);

        // Update the maximum capacity of the list and point the old list to the new one
        crc_indication_list = new_list;
    }

    // Generate random RX UE information tag, RNTI, and CRC indication REL8 tags for each structure
    for (uint32_t i = 0; i < num_structures; i++) {
        crc_indication_list[i].rx_ue_information_tag = rand() % 1000000;
        crc_indication_list[i].rnti = rand() % 65535;
        crc_indication_list[i].crc_indication_rel8_tag = rand() % 256;
        crc_indication_list[i].crcflag = generate_random_crcflag();
    }

    // Release mutex and return the populated list
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Function to update the rate limit for generating new structures
void set_rate_limit(uint32_t new_rate) {
    // Acquire mutex for thread-safe operations on the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Update the rate limit value
    RATE_LIMIT = new_rate;

    // Release mutex and return
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Function to retrieve the current number of structures in the list
uint32_t get_num_structures() {
    // Acquire mutex for thread-safe operations on the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Return the current number of structures in the list
    uint32_t num_structures = (crc_indication_list == NULL) ? 0 : crc_indication_list->rx_ue_information_tag;

    // Release mutex and return
    pthread_mutex_unlock(&crc_indication_list_mutex);

    return num_structures;
}

// Function to retrieve the next structure in the list and increment the index
NFAPI_CRC_INDICATION_PDU_T *get_next_structure() {
    // Acquire mutex for thread-safe operations on the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if there are any structures left in the list
    if (crc_indication_list == NULL || crc_indication_list->rx_ue_information_tag == 0) {
        pthread_mutex_unlock(&crc_indication_list_mutex);
        return NULL;
    }

    // Get the next structure in the list and increment the index
    NFAPI_CRC_INDICATION_PDU_T *structure = &crc_indication_list[0];
    crc_indication_list->rx_ue_information_tag--;

    // Release mutex and return the structure
    pthread_mutex_unlock(&crc_indication_list_mutex);

    return structure;
}

// Function to free the memory allocated for the list of structures
void free_crc_indication_list() {
    // Acquire mutex for thread-safe operations on the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if there are any structures in the list
    if (crc_indication_list != NULL) {
        free(crc_indication_list);
        crc_indication_list = NULL;
    }

    // Release mutex and return
    pthread_mutex_unlock(&crc_indication_list_mutex);
}
