```
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} record_t;

// Function to dynamically allocate memory for two arrays: one for 'long' offset values and another for 'int' keys
void init_arrays(size_t num_offset, size_t num_keys) {
    // Allocate memory for the offset array
    long* offsets = malloc(num_offset * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_offset; i++) {
        offsets[i] = rand() % 1000;
    }

    // Allocate memory for the key array
    int* keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the key array with random values within a specified range
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000;
    }

    // Allocate memory for the record structure array
    size_t total_records = num_offset * num_keys;
    record_t* records = malloc(total_records * sizeof(record_t));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for record structure array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the records with random values within a specified range
    srand(time(NULL));
    size_t i = 0;
    for (size_t j = 0; j < num_offset; j++) {
        for (size_t k = 0; k < num_keys; k++) {
            records[i].value = rand() % 1000;
            i++;
        }
    }
}
