#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
#include <time.h>

// Define the data structure for performance counters
typedef struct {
    uint16_t id;           // Unique identifier for each counter
    char *name;            // Name of the counter (for display purposes)
    uint32_t value;        // Current value of the counter
    double time_stamp;     // Timestamp for the last update
} performance_counter_t;

// Define the data structure for the performance monitor
typedef struct {
    performance_counter_t *counters;   // Array of performance counters
    size_t num_counters;              // Number of counters in the array
    size_t capacity;                  // Capacity of the data structure (in number of counters)
} performance_monitor_t;

// Initialize a new performance monitor with the specified capacity
performance_monitor_t *init_performance_monitor(size_t capacity) {
    performance_monitor_t *monitor = malloc(sizeof(performance_monitor_t));
    if (monitor == NULL) {
        return NULL;
    }

    monitor->counters = calloc(capacity, sizeof(performance_counter_t));
    if (monitor->counters == NULL) {
        free(monitor);
        return NULL;
    }

    monitor->num_counters = 0;
    monitor->capacity = capacity;

    return monitor;
}

// Add a new performance counter to the monitor
int add_counter(performance_monitor_t *monitor, char *name) {
    if (monitor == NULL || name == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < monitor->num_counters && strcmp(monitor->counters[i].name, name) != 0) {
        i++;
    }

    if (i == monitor->num_counters) {
        // Create a new counter with the specified name
        performance_counter_t *counter = malloc(sizeof(performance_counter_t));
        if (counter == NULL) {
            return -1;
        }

        counter->id = monitor->num_counters++;
        counter->name = name;
        counter->value = 0;
        counter->time_stamp = time(NULL);

        // Add the new counter to the array of counters
        if (monitor->num_counters == monitor->capacity) {
            // Resize the array of counters if necessary
            performance_counter_t *new_counters = realloc(monitor->counters, 2 * monitor->capacity * sizeof(performance_counter_t));
            if (new_counters == NULL) {
                free(counter);
                return -1;
            }
            monitor->counters = new_counters;
            monitor->capacity *= 2;
        }

        monitor->counters[i] = *counter;
        free(counter);
    }

    return 0;
}

// Update the value of a performance counter
int update_counter(performance_monitor_t *monitor, char *name, uint32_t value) {
    if (monitor == NULL || name == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < monitor->num_counters && strcmp(monitor->counters[i].name, name) != 0) {
        i++;
    }

    if (i == monitor->num_counters) {
        return -1;
    }

    monitor->counters[i].value = value;
    monitor->counters[i].time_stamp = time(NULL);

    return 0;
}

// Read the value of a performance counter
int read_counter(performance_monitor_t *monitor, char *name, uint32_t *value) {
    if (monitor == NULL || name == NULL || value == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < monitor->num_counters && strcmp(monitor->counters[i].name, name) != 0) {
        i++;
    }

    if (i == monitor->num_counters) {
        return -1;
    }

    *value = monitor->counters[i].value;

    return 0;
}

// Update all performance counters with the latest values from the external monitoring library
int update_all_counters(performance_monitor_t *monitor) {
    if (monitor == NULL) {
        return -1;
    }

    // Get the latest values for each counter from the external monitoring library
    uint32_t *values = malloc(sizeof(uint32_t) * monitor->num_counters);
    if (values == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < monitor->num_counters) {
        values[i] = get_counter_value(monitor->counters[i].name);
        if (values[i] == UINT32_MAX) {
            free(values);
            return -1;
        }
        i++;
    }

    // Update the values of each counter in the performance monitor
    i = 0;
    while (i < monitor->num_counters) {
        update_counter(monitor, monitor->counters[i].name, values[i]);
        if (monitor->counters[i].value == UINT32_MAX) {
            free(values);
            return -1;
        }
        i++;
    }

    // Update the timestamp of each counter in the performance monitor
    time_t now = time(NULL);
    i = 0;
    while (i < monitor->num_counters) {
        monitor->counters[i].time_stamp = now;
        i++;
    }

    free(values);

    return 0;
}

// Get the latest values of all performance counters in the performance monitor
int get_all_counter_values(performance_monitor_t *monitor, uint32_t **values) {
    if (monitor == NULL || values == NULL) {
        return -1;
    }

    // Allocate memory for the array of counter values
    size_t num_counters = monitor->num_counters;
    *values = malloc(sizeof(uint32_t) * num_counters);
    if (*values == NULL) {
        return -1;
    }

    // Get the latest values of each counter from the performance monitor
    size_t i = 0;
    while (i < num_counters) {
        read_counter(monitor, monitor->counters[i].name, &(*values)[i]);
        if ((*values)[i] == UINT32_MAX) {
            free(*values);
            return -1;
        }
        i++;
    }

    return 0;
}

// Real-time alerting functionality for the performance monitor
int add_alert(performance_monitor_t *monitor, char *name, uint32_t threshold, void (*callback)(void)) {
    if (monitor == NULL || name == NULL || callback == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < monitor->num_counters && strcmp(monitor->counters[i].name, name) != 0) {
        i++;
    }

    if (i == monitor->num_counters) {
        return -1;
    }

    // Add the alert to the counter's alert list
    performance_counter_t *counter = &monitor->counters[i];
    size_t num_alerts = counter->num_alerts + 1;
    counter->alerts = realloc(counter->alerts, sizeof(performance_counter_alert_t) * num_alerts);
    if (counter->alerts == NULL) {
        return -1;
    }

    counter->alerts[num_alerts].threshold = threshold;
    counter->alerts[num_alerts].callback = callback;
    counter->num_alerts = num_alerts;

    return 0;
}

// Customizable metric aggregation functions for the performance monitor
int aggregate_counters(performance_monitor_t *monitor, char *aggregate_function) {
    if (monitor == NULL || aggregate_function == NULL) {
        return -1;
    }

    // Calculate the aggregated value of each counter using the specified function
    size_t num_counters = monitor->num_counters;
    uint32_t *values = malloc(sizeof(uint32_t) * num_counters);
    if (values == NULL) {
        return -1;
    }

    size_t i = 0;
    while (i < num_counters) {
        read_counter(monitor, monitor->counters[i].name, &values[i]);
        if (values[i] == UINT32_MAX) {
            free(values);
            return -1;
        }
        i++;
    }

    // Aggregate the values using the specified function
    uint32_t aggregated_value = 0;
    if (strcmp(aggregate_function, "sum") == 0) {
        for (i = 0; i < num_counters; i++) {
            aggregated_value += values[i];
        }
    } else if (strcmp(aggregate_function, "mean") == 0) {
        aggregated_value = values[0] / num_counters;
    } else if (strcmp(aggregate_function, "median") == 0) {
        // Sort the array of counter values in ascending order
        size_t j = 0;
        for (i = 1; i < num_counters; i++) {
            if (values[j] > values[i]) {
                j++;
                uint32_t tmp = values[j];
                values[j] = values[i];
                values[i] = tmp;
            }
        }
        // Calculate the median value as the middle element of the sorted array
        aggregated_value = values[(num_counters - 1) / 2];
    } else {
        free(values);
        return -1;
    }

    // Update the aggregated value for each counter in the performance monitor
    i = 0;
    while (i < num_counters) {
        update_counter(monitor, monitor->counters[i].name, aggregated_value);
        if (monitor->counters[i].value == UINT32_MAX) {
            free(values);
            return -1;
        }
        i++;
    }

    free(values);

    return 0;
}
```
This code defines a `performance_monitor` data structure that stores information about performance counters and allows for efficient updating, reading, and aggregation of these counters. The monitor can be initialized with a specified capacity for the number of counters it can store, and new counters can be added to the monitor using the `add_counter` function. Each counter has a unique identifier, name, current value, and timestamp. The `update_counter` function updates the value of a specific counter in the monitor, while the `read_counter` function retrieves the latest value of a particular counter.

The `update_all_counters` function updates all counters with the latest values from an external monitoring library, and the `get_all_counter_values` function retrieves the latest values of all counters in the monitor. The monitor also supports real-time alerting functionality through the `add_alert` function, which adds a callback function that will be triggered when a threshold is exceeded for a particular counter. Customizable metric aggregation functions are available through the `aggregate_counters` function, which allows users to calculate the sum, mean, or median of all counters in the monitor using a specified function.

This code also demonstrates how to integrate with an external monitoring library and provide extended features such as real-time alerting, historical trend analysis, and customizable metric aggregation functions.']

