using namespace std;

class RESTClient {
public:
    RESTClient(const string& url, const string& user_agent) : url_(url), user_agent_(user_agent) {}

    void fetch() {
        // Create a socket
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) {
            cout << "Error creating socket" << endl;
            return;
        }

        // Get the IP address and port number of the URL
        struct addrinfo* result;
        struct addrinfo hints;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(url_.c_str(), NULL, &hints, &result) != 0) {
            cout << "Error resolving URL" << endl;
            close(sock);
            return;
        }

        // Connect to the server
        struct addrinfo* rp = result;
        while (connect(sock, rp->ai_addr, rp->ai_addrlen) < 0) {
            close(sock);
            freeaddrinfo(result);
            cout << "Error connecting to server" << endl;
            return;
        }

        // Send the GET request
        char* get_request = "GET / HTTP/1.1\r\nHost: localhost\r\nUser-Agent: ";
        strcat(get_request, user_agent_.c_str());
        strcat(get_request, "\r\nConnection: close\r\n");
        if (send(sock, get_request, strlen(get_request), 0) < 0) {
            cout << "Error sending request" << endl;
            close(sock);
            freeaddrinfo(result);
            return;
        }

        // Receive the response
        char buffer[4096];
        int bytes_received = recv(sock, buffer, 4096, 0);
        if (bytes_received < 0) {
            cout << "Error receiving response" << endl;
            close(sock);
            freeaddrinfo(result);
            return;
        }

        // Close the socket and free the memory
        close(sock);
        freeaddrinfo(result);

        // Parse the response
        stringstream ss(buffer);
        string line;
        getline(ss, line);
        if (line == "HTTP/1.1 200 OK") {
            cout << "Request successful" << endl;
        } else {
            cout << "Request failed with status code: " << line << endl;
        }
    }

private:
    string url_;
    string user_agent_;
};

