// Custom memory allocator configuration
#define BLOCK_SIZE 16 // Block size for memory allocation (in bytes)
#define OVERHEAD 4 // Overhead for memory allocation (in bytes)
#define POOL_MAX_CAPACITY 1024 // Maximum capacity of the pool (in number of records)

// Record structure
typedef struct {
    long offset;
    char status;
} Record;

// Memory pool structure
typedef struct {
    int size; // Current capacity of the pool (in number of records)
    int count; // Current number of records in the pool
    Record *records; // Array of records in the pool
} Pool;

// Function to initialize and allocate memory for the record system
Pool* init_pool(int max_capacity) {
    if (max_capacity > POOL_MAX_CAPACITY) {
        printf("Error: Maximum capacity exceeded\n");
        return NULL;
    }

    Pool *pool = malloc(sizeof(Pool));
    if (!pool) {
        printf("Error: Failed to allocate memory for pool\n");
        return NULL;
    }

    // Initialize the pool size and capacity
    pool->size = max_capacity;
    pool->count = 0;

    // Allocate memory for the record array
    pool->records = malloc(sizeof(Record) * max_capacity);
    if (!pool->records) {
        printf("Error: Failed to allocate memory for records\n");
        free(pool);
        return NULL;
    }

    // Initialize the records with random values
    srand(time(NULL));
    for (int i = 0; i < max_capacity; i++) {
        pool->records[i].offset = rand() % 100 + 1;
        pool->records[i].status = rand() % 26 + 'A';
    }

    return pool;
}

// Function to add a new record to the record system
void add_record(Pool *pool, long offset, char status) {
    if (pool->count == pool->size) {
        printf("Error: Pool capacity exceeded\n");
        return;
    }

    // Add the new record to the end of the pool
    pool->records[pool->count].offset = offset;
    pool->records[pool->count++].status = status;
}

// Function to remove a record from the record system
void remove_record(Pool *pool, long offset) {
    // Find the index of the record with the specified offset
    int i = 0;
    while (i < pool->count && pool->records[i].offset != offset) {
        i++;
    }

    // If the record was found, remove it from the pool and adjust the count
    if (i < pool->count) {
        pool->count--;
        for (int j = i; j < pool->count; j++) {
            pool->records[j] = pool->records[j + 1];
        }
    } else {
        printf("Error: Record not found\n");
    }
}

// Function to resize the record system based on memory utilization
void resize_pool(Pool *pool) {
    // Calculate the current memory usage and determine if a resize is needed
    int size = pool->count * sizeof(Record);
    int max_size = pool->size * sizeof(Record);
    if (size > 0.8 * max_size) {
        printf("Resizing pool from %d to %d\n", pool->size, 2 * pool->size);

        // Reallocate memory for the record array with a new size
        Record *new_records = realloc(pool->records, 2 * max_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: Failed to resize pool\n");
            return;
        }

        // Update the pool size and records pointer
        pool->size = 2 * pool->size;
        pool->records = new_records;
    }
}

// Function to monitor memory utilization and trigger a resize operation
void check_memory(Pool *pool) {
    // Calculate the current memory usage and determine if a resize is needed
    int size = pool->count * sizeof(Record);
    int max_size = pool->size * sizeof(Record);
    if (size > 0.8 * max_size) {
        printf("Memory utilization exceeded, resizing pool\n");
        resize_pool(pool);
    }
}

// Function to free all allocated memory for the record system
void destroy_pool(Pool *pool) {
    // Free the record array and pool structure
    free(pool->records);
    free(pool);
