// Define structure to hold record data and metadata
struct record {
    long value;
    char status;
    void *metadata;
};

// Define callback function type for handling metadata operations
typedef void (*metadata_callback)(const struct record *record, void *metadata);

// Function to dynamically manage memory for records and initialize arrays
void manage_records(size_t max_records, long seed, metadata_callback cb) {
    // Allocate memory for the arrays of 'long' offsets, 'int' keys, and record structures
    size_t *offset_array = malloc(max_records * sizeof(size_t));
    int *key_array = malloc(max_records * sizeof(int));
    struct record *record_array = malloc(max_records * sizeof(struct record));

    // Initialize arrays with random 'long' values within a specified range, and randomly generated 'char' status indicators
    srand(seed);
    for (size_t i = 0; i < max_records; ++i) {
        offset_array[i] = rand() % 10000;
        key_array[i] = rand() % 26 + 'a';
        record_array[i].value = rand() % 10000;
        record_array[i].status = (rand() % 2) ? 'A' : 'D';
    }

    // Allocate additional metadata pointers for each record and register callback function for handling metadata operations
    for (size_t i = 0; i < max_records; ++i) {
        record_array[i].metadata = malloc(sizeof(struct metadata));
        if (cb != NULL) {
            cb(&record_array[i], record_array[i].metadata);
        }
    }

    // Validate that all allocated memory is correctly initialized and deallocate resources appropriately
    for (size_t i = 0; i < max_records; ++i) {
        if (offset_array[i] == NULL || key_array[i] == NULL || record_array[i].metadata == NULL) {
            printf("Error: Unable to allocate memory for record %zu\n", i);
            exit(1);
        }
    }

    // Maintain a running count of the actual number of records allocated, which should not exceed the maximum specified
    size_t num_records = 0;
    for (size_t i = 0; i < max_records; ++i) {
        if (offset_array[i] != NULL && key_array[i] != NULL && record_array[i].metadata != NULL) {
            num_records++;
        }
    }

    // Log error message and terminate gracefully without crashing if the limit is exceeded
    if (num_records > max_records) {
        printf("Error: Exceeded maximum number of records allowed (%zu)\n", max_records);
        exit(1);
    }

    // Release memory for arrays and free resources appropriately
    free(offset_array);
    free(key_array);
    for (size_t i = 0; i < max_records; ++i) {
        if (record_array[i].metadata != NULL) {
            free(record_array[i].metadata);
        }
    }
    free(record_array);
}
```
