// Function to initialize and populate an array of UEContext structures
int initUEContexts(struct UEContextTable *ueCtxTbl, int numContexts) {
    // Check for valid input parameters
    if (numContexts <= 0 || ueCtxTbl == NULL) {
        return -1;
    }

    // Allocate memory for the array of UEContext structures
    ueCtxTbl->contexts = malloc(sizeof(struct UEContext *) * numContexts);
    if (ueCtxTbl->contexts == NULL) {
        return -2;
    }

    // Initialize each UEContext structure with a RRC_Connection_Reconfiguration message and NAS_Message field
    for (int i = 0; i < numContexts; i++) {
        ueCtxTbl->contexts[i] = malloc(sizeof(struct UEContext));
        if (ueCtxTbl->contexts[i] == NULL) {
            return -3;
        }
        ueCtxTbl->contexts[i]->reconf = (RRC_Connection_Reconfiguration *)malloc(sizeof(RRC_Connection_Reconfiguration));
        if (ueCtxTbl->contexts[i]->reconf == NULL) {
            return -4;
        }
        ueCtxTbl->contexts[i]->nasMsg = (NAS_Message *)malloc(sizeof(NAS_Message));
        if (ueCtxTbl->contexts[i]->nasMsg == NULL) {
            return -5;
