    }

    // Set the maximum number of UE contexts and allocate memory for the NAS message buffers
    ueCtxTbl->maxNumContexts = numContexts;
    ueCtxTbl->nasBufSize = sizeof(NAS_Message) * numContexts;
    ueCtxTbl->nasMsgBufs = malloc(ueCtxTbl->nasBufSize);
    if (ueCtxTbl->nasMsgBufs == NULL) {
        return -6;
    }

    // Set the number of active UE contexts to 0
    ueCtxTbl->numActiveContexts = 0;

    return 0;
}

// Function to add a new UE context to the array
int addUEContext(struct UEContextTable *ueCtxTbl, RRC_Connection_Reconfiguration *reconf, NAS_Message *nasMsg) {
