    if (reconf == NULL || nasMsg == NULL || ueCtxTbl == NULL) {
        return -1;
    }

    // Acquire a lock on the UE context table to prevent concurrent modification
    pthread_mutex_lock(&ueCtxTbl->mtx);

    // Check if there is space for another UE context in the array
    if (ueCtxTbl->numActiveContexts >= ueCtxTbl->maxNumContexts) {
        pthread_mutex_unlock(&ueCtxTbl->mtx);
        return -2;
    }

    // Allocate memory for the new UE context and copy the RRC_Connection_Reconfiguration message and NAS_Message field
    struct UEContext *newUECtx = malloc(sizeof(struct UEContext));
    if (newUECtx == NULL) {
