    Record* records[MAX_RECORDS];
} RecordSystem;

// Initialize a record system with a specified maximum number of records
void initialize_record_system(RecordSystem* rs, int max_records) {
    // Set the total number of records and pool size to the specified values
    rs->num_records = 0;
    rs->pool_size = max_records * sizeof(Record);

    // Allocate memory for the record system using a pool-based approach
    void* ptr = malloc_pool(rs->pool_size);
    rs->records = (Record*)ptr;
}

// Add a new record to the dynamic record system with a specified offset, status, and data field
void add_record(RecordSystem* rs, long offset, char status, const char* data) {
    // Check if the total number of records exceeds the maximum allowed
    if (rs->num_records >= MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded\n");
        return;
    }

    // Allocate memory for the new record using a custom allocator
    Record* rec = malloc_record(sizeof(Record));
    if (!rec) {
        printf("Error: Out of memory\n");
        return;
    }

    // Initialize the new record with the specified offset, status, and data field
    rec->offset = offset;
    rec->status = status;
    rec->data = strdup(data);

    // Add the new record to the record system
    rs->records[rs->num_records] = rec;
    rs->num_records++;
}

// Remove a record from the dynamic record system with a specified offset and status
void remove_record(RecordSystem* rs, long offset, char status) {
    // Find the index of the record to be removed
    int i = 0;
    while (i < rs->num_records && rs->records[i]->offset != offset || rs->records[i]->status != status) {
        i++;
    }

    // Check if the record exists in the system
    if (i >= rs->num_records) {
        printf("Error: Record not found\n");
        return;
    }

    // Remove the record from the record system and free its memory
    Record* rec = rs->records[i];
    free(rec->data);
    free(rec);
    rs->num_records--;
}

// Update a record in the dynamic record system with a specified offset, status, and data field
void update_record(RecordSystem* rs, long offset, char status, const char* data) {
    // Find the index of the record to be updated
    int i = 0;
    while (i < rs->num_records && rs->records[i]->offset != offset || rs->records[i]->status != status) {
        i++;
    }

    // Check if the record exists in the system
    if (i >= rs->num_records) {
        printf("Error: Record not found\n");
        return;
    }

    // Update the record with the specified offset, status, and data field
    Record* rec = rs->records[i];
    free(rec->data);
    rec->data = strdup(data);
}

// Filter records in the dynamic record system based on a specified criteria
void filter_records(RecordSystem* rs, int (*criteria)(const Record*)) {
    // Create an array to store filtered records
    int num_filtered = 0;
    Record** filtered = malloc(rs->num_records * sizeof(Record*));
    if (!filtered) {
        printf("Error: Out of memory\n");
        return;
    }

    // Iterate over all records in the system and filter based on the criteria function
    for (int i = 0; i < rs->num_records; i++) {
        if (criteria(rs->records[i])) {
            filtered[num_filtered++] = rs->records[i];
        }
    }

    // Update the record system with the filtered records
    rs->num_records = num_filtered;
    for (int i = 0; i < num_filtered; i++) {
        rs->records[i] = filtered[i];
    }
}

// Serialize a record system to a binary file
void serialize_record_system(RecordSystem* rs, const char* filename) {
    // Open the output file in binary mode for writing
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        printf("Error: Failed to open file\n");
        return;
    }

    // Write the number of records in the system to the output file
    int num_records = rs->num_records;
    fwrite(&num_records, sizeof(int), 1, fp);

    // Iterate over all records in the system and write them to the output file
    for (int i = 0; i < num_records; i++) {
        Record* rec = rs->records[i];
        fwrite(&rec->offset, sizeof(long), 1, fp);
        fwrite(&rec->status, sizeof(char), 1, fp);
        fwrite(rec->data, strlen(rec->data), 1, fp);
    }

    // Close the output file
    fclose(fp);
}

// Deserialize a record system from a binary file
void deserialize_record_system(RecordSystem* rs, const char* filename) {
    // Open the input file in binary mode for reading
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error: Failed to open file\n");
        return;
    }

    // Read the number of records from the input file
    int num_records;
    fread(&num_records, sizeof(int), 1, fp);

    // Initialize the record system with the specified number of records
    initialize_record_system(rs, num_records);

    // Iterate over all records in the input file and deserialize them into the record system
    for (int i = 0; i < num_records; i++) {
        Record* rec = malloc_record(sizeof(Record));
        fread(&rec->offset, sizeof(long), 1, fp);
        fread(&rec->status, sizeof(char), 1, fp);
        rec->data = strdup(fread(NULL, 0, 1, fp));
        rs->records[i] = rec;
    }

    // Close the input file
    fclose(fp);
}

