// Structure to store CRC indication information
typedef struct {
    RX_UE_INFORMATION_TAG rxInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndRel8;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool to optimize memory usage
static NFAPI_CRC_INDICATION_PDU_T* memoryPool[100000];

// Maximum size of the list
#define MAX_SIZE 100000

// Function to add a new structure to the list
void addStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if memory pool is full
    if (memoryPool[MAX_SIZE] == NULL) {
        printf("Memory pool is full, cannot add new structure\n");
        return;
    }

    // Check if RNTI value falls within valid range for the specified UE
    if (structure->rnti < 0 || structure->rnti > MAX_RNTI) {
        printf("Invalid RNTI value: %d\n", structure->rnti);
        return;
    }

    // Add new structure to memory pool
    memoryPool[MAX_SIZE] = structure;
}

// Function to update an existing structure in the list
void updateStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if RNTI value falls within valid range for the specified UE
    if (structure->rnti < 0 || structure->rnti > MAX_RNTI) {
        printf("Invalid RNTI value: %d\n", structure->rnti);
        return;
    }

    // Update existing structure in memory pool
    NFAPI_CRC_INDICATION_PDU_T* oldStructure = NULL;
    for (int i = 0; i < MAX_SIZE; i++) {
        if (memoryPool[i]->rnti == structure->rnti) {
            oldStructure = memoryPool[i];
            break;
        }
    }

    // Check if the structure was found in the list
    if (oldStructure == NULL) {
        printf("Structure with RNTI %d not found\n", structure->rnti);
        return;
    }

    // Update structure with new values
    oldStructure->rxInfoTag = structure->rxInfoTag;
    oldStructure->crcIndRel8.crflag = structure->crcIndRel8.crflag;
    oldStructure->timestamp = time(NULL);
}

// Function to delete a structure from the list
void deleteStructure(RNTI rnti) {
    // Check if RNTI value falls within valid range for the specified UE
    if (rnti < 0 || rnti > MAX_RNTI) {
        printf("Invalid RNTI value: %d\n", rnti);
        return;
    }

    // Delete structure from memory pool
    NFAPI_CRC_INDICATION_PDU_T* oldStructure = NULL;
    for (int i = 0; i < MAX_SIZE; i++) {
        if (memoryPool[i]->rnti == rnti) {
            oldStructure = memoryPool[i];
            break;
        }
    }

    // Check if the structure was found in the list
    if (oldStructure == NULL) {
        printf("Structure with RNTI %d not found\n", rnti);
        return;
    }

    // Delete structure from memory pool
    for (int i = 0; i < MAX_SIZE; i++) {
        if (memoryPool[i] == oldStructure) {
            memoryPool[i] = NULL;
            break;
        }
    }
}

// Function to retrieve a structure from the list
NFAPI_CRC_INDICATION_PDU_T* getStructure(RNTI rnti) {
    // Check if RNTI value falls within valid range for the specified UE
    if (rnti < 0 || rnti > MAX_RNTI) {
        printf("Invalid RNTI value: %d\n", rnti);
        return NULL;
    }

    // Retrieve structure from memory pool
    for (int i = 0; i < MAX_SIZE; i++) {
        if (memoryPool[i]->rnti == rnti) {
            return memoryPool[i];
        }
    }

    // Return NULL if the structure was not found in the list
    return NULL;
}
