// Struct to represent a record in the collection
typedef struct {
    long offset;
    int key;
    float data_value;
} Record;

// Function to create a new record and add it to the collection
Record* create_record(int max_memory, int key) {
    // Check if the maximum memory threshold has been reached
    if (max_memory <= 0) {
        fprintf(stderr, "Maximum memory threshold reached. Unable to create new record.\n");
        return NULL;
    }

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record. Out of memory.\n");
        return NULL;
    }

    // Generate random values for the offset and data value
    new_record->offset = rand() % max_memory;
    new_record->data_value = ((float)rand()) / RAND_MAX;

    // Check if a key collision occurred
    if (find_key(new_record->key)) {
        fprintf(stderr, "Key collision detected. Retrying allocation process...\n");
        free(new_record);
        return create_record(max_memory - 1, key);
    }

    // Add the new record to the collection
    add_record(new_record);

    return new_record;
}

// Function to find a specific record in the collection by key
Record* find_record(int key) {
    // Iterate through the records in the collection
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            return records[i];
        }
    }
    return NULL;
}

// Function to add a new record to the collection
void add_record(Record* new_record) {
    // Check if the maximum memory threshold has been reached
    if (max_memory <= 0) {
        fprintf(stderr, "Maximum memory threshold reached. Unable to add new record.\n");
        return;
    }

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record. Out of memory.\n");
        return;
    }

    // Copy the values from the passed-in record to the new record
    new_record->offset = new_record->offset;
    new_record->key = new_record->key;
    new_record->data_value = new_record->data_value;

    // Add the new record to the collection
    records[num_records++] = new_record;
}

// Function to remove a specific record from the collection by key
void remove_record(int key) {
    // Find the index of the record in the collection
    int index = find_key(key);
    if (index < 0) {
        fprintf(stderr, "Record with key %d not found. Unable to remove.\n", key);
        return;
    }

    // Remove the record from the collection
    free(records[index]);
    records[index] = NULL;

    // Update the number of records in the collection
    num_records--;
}
