#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>

#define LOG_LEVELS 4
#define LOG_BUFFER_SIZE 1024

typedef enum {
    LOG_DEBUG = 0,
    LOG_INFO = 1,
    LOG_WARN = 2,
    LOG_ERROR = 3
} log_level;

typedef struct {
    char *buffer;
    size_t buffer_size;
    size_t pos;
    bool async;
    pthread_mutex_t mutex;
} log_buffer;

typedef struct {
    log_level level;
    const char *format;
} log_message;

typedef struct {
    const char *name;
    log_level min_level;
    log_message messages[LOG_LEVELS];
} log_config;

typedef struct {
    log_config config;
    log_buffer buffer;
    pthread_t thread;
    bool running;
    int fd;
} log_handler;

log_handler *log_init(const char *name, log_level min_level, bool async) {
    // Initialize a new log handler structure
    log_handler *handler = malloc(sizeof(log_handler));
    if (handler == NULL) {
        return NULL;
    }

    // Set the configuration for the log handler
    strcpy(handler->config.name, name);
    handler->config.min_level = min_level;
    handler->async = async;

    // Initialize the buffer for logging messages
    handler->buffer.buffer = malloc(LOG_BUFFER_SIZE);
    if (handler->buffer.buffer == NULL) {
        free(handler);
        return NULL;
    }
    handler->buffer.buffer_size = LOG_BUFFER_SIZE;
    handler->buffer.pos = 0;

    // Initialize the mutex for thread-safe access to the buffer
    pthread_mutex_init(&(handler->buffer.mutex), NULL);

    // Create a new thread for handling log messages asynchronously
    if (async) {
        handler->thread = malloc(sizeof(pthread_t));
        if (handler->thread == NULL) {
            free(handler->buffer.buffer);
            pthread_mutex_destroy(&(handler->buffer.mutex));
            free(handler);
            return NULL;
        }
    }

    // Set the log level and format for each message type
    strcpy(handler->config.messages[LOG_DEBUG].format, "%s: DEBUG: %s\n");
    strcpy(handler->config.messages[LOG_INFO].format, "%s: INFO: %s\n");
    strcpy(handler->config.messages[LOG_WARN].format, "%s: WARNING: %s\n");
    strcpy(handler->config.messages[LOG_ERROR].format, "%s: ERROR: %s\n");

    // Set the file descriptor for writing log messages to syslog
    handler->fd = openlog(name, LOG_CONS | LOG_NDELAY | LOG_PID, LOG_USER);
    if (handler->fd < 0) {
        perror("openlog");
        free(handler->buffer.buffer);
        pthread_mutex_destroy(&(handler->buffer.mutex));
        free(handler->thread);
        free(handler);
        return NULL;
    }

    // Set the running flag to indicate that the log handler is ready for use
    handler->running = true;

    return handler;
}

void log_destroy(log_handler *handler) {
    // Free any allocated memory and close the file descriptor
    if (handler->async) {
        pthread_cancel(handler->thread);
        free(handler->thread);
    }
    closelog();
    free(handler->buffer.buffer);
    pthread_mutex_destroy(&(handler->buffer.mutex));
    free(handler);
}

void log_write(log_handler *handler, log_level level, const char *message) {
    // Check if the log message is at a high enough level to be logged
    if (level >= handler->config.min_level) {
        // Acquire the mutex for thread-safe access to the buffer
        pthread_mutex_lock(&(handler->buffer.mutex));

        // Copy the log message into the buffer
        size_t len = strlen(message);
        if (handler->buffer.pos + len >= handler->buffer.buffer_size) {
            flush_log_buffer(handler);
        }
        memcpy(handler->buffer.buffer + handler->buffer.pos, message, len);
        handler->buffer.pos += len;

        // Release the mutex and return
        pthread_mutex_unlock(&(handler->buffer.mutex));
    }
}

void flush_log_buffer(log_handler *handler) {
    // Acquire the mutex for thread-safe access to the buffer
    pthread_mutex_lock(&(handler->buffer.mutex));

    // Write the log message to the file descriptor or syslog
    if (handler->async) {
        int rc = pthread_create(&handler->thread, NULL, async_write_log, handler);
        if (rc != 0) {
            fprintf(stderr, "Error creating log thread: %s\n", strerror(errno));
        }
    } else {
        write_log(handler);
    }

    // Reset the position in the buffer and release the mutex
    handler->buffer.pos = 0;
    pthread_mutex_unlock(&(handler->buffer.mutex));
}

void *async_write_log(void *args) {
    log_handler *handler = (log_handler *) args;
    write_log(handler);
    return NULL;
}

void write_log(log_handler *handler) {
    // Write the log message to the file descriptor or syslog
    if (handler->fd >= 0) {
        syslog(LOG_INFO, "%s", handler->buffer.buffer);
    } else {
        fprintf(stderr, "%s\n", handler->buffer.buffer);
    }
}']

