// Structure definition for an item
struct item {
    char identifier;
    double value;
    char *description;
};

void initialize_items(int num_items, struct item items[]) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Initialize each item in the array
    for (int i = 0; i < num_items; i++) {
        // Generate a random identifier and value for the item
        items[i].identifier = rand() % ('z' - 'a') + 'a';
        items[i].value = (double)rand() / RAND_MAX;

        // Allocate memory for the description string
        size_t desc_len = 10 + (rand() % 40);
        items[i].description = malloc(desc_len * sizeof(char));
        if (!items[i].description) {
            printf("Error: Failed to allocate memory for item %d\n", i);
            return;
        }

        // Generate a random description string
        for (size_t j = 0; j < desc_len - 1; j++) {
            items[i].description[j] = rand() % ('z' - 'a') + 'a';
        }
        items[i].description[desc_len - 1] = '\0';
    }
}

void free_items(int num_items, struct item items[]) {
    // Free each item in the array
    for (int i = 0; i < num_items; i++) {
        free(items[i].description);
    }
}
