    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array of NFAPI_CRC_INDICATION_PDU_T structures to manage the list of elements
typedef struct {
