// Function to add a new element to the dynamic array, ensuring that memory allocation succeeds
int nfapi_crc_indication_add(NFAPI_CRC_INDICATION_PDU_T_LIST *list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti) {
