// Memory pool size in bytes
#define POOL_SIZE (1 << 20) // 1 MB

// Records structure
typedef struct {
    long offset;
    int key;
    float data;
} record;

// Hash table to store unique keys
static record** hashTable = NULL;

// Memory pool for storing records
static char* memoryPool = NULL;

// Current size of the memory pool in bytes
static size_t poolSize = 0;

// Current number of records stored in the memory pool
static size_t numRecords = 0;

// Flag to indicate if the memory pool is full
static bool poolFull = false;

// Function to allocate a new record from the memory pool
record* allocateRecord(int key, float data) {
    // Check if the memory pool is full
    if (poolFull) {
        // Reallocate the memory pool with a larger size
        reallocatePool();
    }

    // Create a new record in the memory pool
    record* newRecord = (record*) memoryPool;
    newRecord->key = key;
    newRecord->data = data;

    // Increment the number of records stored in the memory pool
    numRecords++;

    return newRecord;
}

// Function to deallocate a record from the memory pool
void deallocateRecord(record* rec) {
    // Decrement the number of records stored in the memory pool
    numRecords--;

    // Deallocate the record from the memory pool
    free(rec);
}

// Function to reallocate the memory pool with a larger size
void reallocatePool() {
    // Check if the memory pool is already full
    if (poolFull) {
        return;
    }

    // Reallocate the memory pool with a larger size
    char* newPool = realloc(memoryPool, POOL_SIZE * 2);
    if (newPool == NULL) {
        printf("Error: Failed to allocate memory for record\n");
        exit(1);
    }

    // Update the memory pool and its size
    memoryPool = newPool;
    poolSize += POOL_SIZE * 2;

    // Set the flag to indicate that the memory pool is now full
    poolFull = true;
}

// Function to insert a record into the hash table
void insertRecord(record* rec) {
    // Check if the hash table is already full
    if (hashTable == NULL) {
        // Allocate a new hash table with a size equal to twice the number of records
        int tableSize = 2 * numRecords;
        hashTable = malloc(tableSize * sizeof(record*));
        if (hashTable == NULL) {
            printf("Error: Failed to allocate memory for hash table\n");
            exit(1);
        }
    }

    // Calculate the index of the hash table based on the record's key
    int index = rec->key % numRecords;

    // Check if a record with the same key already exists in the hash table
    while (hashTable[index] != NULL && hashTable[index]->key == rec->key) {
        // Increment the index and try again if a record with the same key already exists
        index = (index + 1) % numRecords;
    }

    // Insert the record into the hash table
    hashTable[index] = rec;
}

// Function to search for a record in the hash table
record* searchRecord(int key) {
    // Calculate the index of the hash table based on the key
    int index = key % numRecords;

    // Check if a record with the given key exists in the hash table
    while (hashTable[index] != NULL && hashTable[index]->key != key) {
        // Increment the index and try again if a record with the given key does not exist
        index = (index + 1) % numRecords;
    }

    return hashTable[index];
}

// Function to delete a record from the hash table
void deleteRecord(int key) {
    // Calculate the index of the hash table based on the key
    int index = key % numRecords;

    // Check if a record with the given key exists in the hash table
    while (hashTable[index] != NULL && hashTable[index]->key != key) {
        // Increment the index and try again if a record with the given key does not exist
        index = (index + 1) % numRecords;
    }

    // Delete the record from the hash table
    hashTable[index] = NULL;
}

// Function to retrieve a record by its offset in the memory pool
record* getRecord(long offset) {
    // Check if the offset is within the bounds of the memory pool
    if (offset < 0 || offset >= POOL_SIZE) {
        return NULL;
    }

    // Calculate the index of the record in the memory pool based on its offset
    int index = offset / sizeof(record);

    // Return the record at the calculated index
    return (record*) &memoryPool[index * sizeof(record)];
}

// Function to update a record's data value
void updateRecord(int key, float data) {
    // Search for the record in the hash table
    record* rec = searchRecord(key);
    if (rec == NULL) {
        return;
    }

    // Update the record's data value
    rec->data = data;
}

// Function to delete a record by its offset in the memory pool
void deleteRecordByOffset(long offset) {
    // Check if the offset is within the bounds of the memory pool
    if (offset < 0 || offset >= POOL_SIZE) {
        return;
    }

    // Calculate the index of the record in the memory pool based on its offset
    int index = offset / sizeof(record);

    // Delete the record from the hash table
    deleteRecord(hashTable[index]->key);

    // Deallocate the record from the memory pool
    deallocateRecord(hashTable[index]);
}

// Function to log detailed metrics about the memory pool and hash table
void logMetrics() {
    printf("Memory pool size: %zu bytes\n", poolSize);
    printf("Number of records in the memory pool: %zu\n", numRecords);
    printf("Hash table size: %d\n", numRecords * sizeof(record*));
}
```
