#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for records
typedef struct record {
    long offset;
    int key;
    float data_value;
} record_t;

// Define the collection type
typedef struct collection {
    record_t* records; // Array of records
    size_t capacity; // Current capacity of the collection
    size_t count; // Number of records in the collection
    pthread_mutex_t mutex; // Mutex for concurrent access
} collection_t;

// Initialize a new record with random values within predefined ranges
void init_record(record_t* record) {
    // Randomly generate an offset between 0 and 1000
    record->offset = (long)(rand() % 1000);

    // Randomly generate a key between 1 and 100
    record->key = rand() % 100 + 1;

    // Randomly generate a data value between 0.0 and 100.0
    record->data_value = (float)(rand() % 1000) / 100.0f;
}

// Insert a new record into the collection, returning 0 on success or a negative error code on failure
int insert_record(collection_t* collection, record_t* record) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&(collection->mutex));

    // Check if the collection is full and needs to be resized
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record_t* new_records = realloc(collection->records, sizeof(record_t) * new_capacity);
        if (new_records == NULL) {
            pthread_mutex_unlock(&(collection->mutex));
            return -1; // Error: failed to resize the collection
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // Copy the record into the collection
    memcpy(&(collection->records[collection->count]), record, sizeof(record_t));
    collection->count++;

    // Release the mutex
    pthread_mutex_unlock(&(collection->mutex));

    return 0; // Success: inserted the record into the collection
}

// Remove a record from the collection, returning 0 on success or a negative error code on failure
int remove_record(collection_t* collection, int key) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&(collection->mutex));

    // Find the record with the matching key and return an error if it's not found
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            break;
        }
    }
    if (i == collection->count) {
        pthread_mutex_unlock(&(collection->mutex));
        return -2; // Error: record not found
    }

    // Copy the last record to the vacated position and reduce the count by 1
    memcpy(&(collection->records[i]), &(collection->records[collection->count - 1]), sizeof(record_t));
    collection->count--;

    // Release the mutex
    pthread_mutex_unlock(&(collection->mutex));

    return 0; // Success: removed the record from the collection
}

// Get a record from the collection, returning a pointer to the record on success or NULL on failure
record_t* get_record(collection_t* collection, int key) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&(collection->mutex));

    // Find the record with the matching key and return NULL if it's not found
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            break;
        }
    }
    if (i == collection->count) {
        pthread_mutex_unlock(&(collection->mutex));
        return NULL; // Error: record not found
    }

    // Return a pointer to the record
    record_t* result = &(collection->records[i]);

    // Release the mutex
    pthread_mutex_unlock(&(collection->mutex));

    return result; // Success: returned a pointer to the record
}

// Update a record in the collection, returning 0 on success or a negative error code on failure
int update_record(collection_t* collection, int key, float data_value) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&(collection->mutex));

    // Find the record with the matching key and return an error if it's not found
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            break;
        }
    }
    if (i == collection->count) {
        pthread_mutex_unlock(&(collection->mutex));
        return -2; // Error: record not found
    }

    // Update the data value of the record
    collection->records[i].data_value = data_value;

    // Release the mutex
    pthread_mutex_unlock(&(collection->mutex));

    return 0; // Success: updated the record in the collection
}

// Iterate over all records in the collection, invoking a callback function for each one
void iterate_records(collection_t* collection, void (*callback)(record_t*)) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&(collection->mutex));

    // Iterate over all records in the collection and invoke the callback function for each one
    size_t i;
    for (i = 0; i < collection->count; i++) {
        callback(&(collection->records[i]));
    }

    // Release the mutex
    pthread_mutex_unlock(&(collection->mutex));
}

int main() {
    srand(time(NULL));

    collection_t* collection = malloc(sizeof(collection_t));
    if (collection == NULL) {
        return -1; // Error: failed to allocate memory for the collection
    }
    collection->capacity = 16;
    collection->count = 0;
    collection->records = malloc(sizeof(record_t) * collection->capacity);
    if (collection->records == NULL) {
        free(collection);
        return -2; // Error: failed to allocate memory for the records array
    }

    // Initialize a record with random values and insert it into the collection
    record_t record;
    init_record(&record);
    if (insert_record(collection, &record) < 0) {
        free(collection->records);
        free(collection);
        return -3; // Error: failed to insert the record into the collection
    }

    // Get a record from the collection and update its data value
    record_t* retrieved_record = get_record(collection, 1);
    if (retrieved_record == NULL) {
        free(collection->records);
        free(collection);
        return -4; // Error: failed to retrieve the record from the collection
    }
    update_record(collection, retrieved_record->key, 10.0f);

    // Remove a record from the collection and iterate over all records in the collection
    if (remove_record(collection, 2) < 0) {
        free(collection->records);
        free(collection);
        return -5; // Error: failed to remove the record from the collection
    }
    iterate_records(collection, print_record);

    free(collection->records);
    free(collection);

    return 0; // Success: all operations completed successfully
}

// Define a callback function for printing records
void print_record(record_t* record) {
