import json
from datetime import datetime
from typing import Optional
from collections import defaultdict

class Event:
    def __init__(self, id: str, title: str, description: str, start_time: datetime, end_time: datetime, location: str):
        self.id = id
        self.title = title
        self.description = description
        self.start_time = start_time
        self.end_time = end_time
        self.location = location

    def to_dict(self) -> dict:
        return {
            'id': self.id,
            'title': self.title,
            'description': self.description,
            'start_time': self.start_time,
            'end_time': self.end_time,
            'location': self.location
        }

class EventManager:
    def __init__(self):
        self.events = defaultdict(list)

    def handle_request(self, request: dict) -> Optional[Event]:
        action = request['action']
        if action == 'create':
            return self.create_event(request)
        elif action == 'update':
            return self.update_event(request)
        elif action == 'delete':
            return self.delete_event(request)
        elif action == 'fetch':
            return self.fetch_events(request)
        else:
            raise ValueError('Invalid action')

    def create_event(self, request: dict) -> Event:
        id = request['id'] if 'id' in request else str(uuid4())
        title = request['title']
        description = request['description']
        start_time = request['start_time']
        end_time = request['end_time']
        location = request['location']
        event = Event(id, title, description, start_time, end_time, location)
        self.events[id].append(event)
        return event

    def update_event(self, request: dict) -> Optional[Event]:
        id = request['id']
        if not self.events[id]:
            raise ValueError('Event does not exist')
        for event in self.events[id]:
            event.title = request['title'] if 'title' in request else event.title
            event.description = request['description'] if 'description' in request else event.description
            event.start_time = request['start_time'] if 'start_time' in request else event.start_time
            event.end_time = request['end_time'] if 'end_time' in request else event.end_time
            event.location = request['location'] if 'location' in request else event.location
        return self.events[id]

    def delete_event(self, request: dict) -> Optional[Event]:
        id = request['id']
        if not self.events[id]:
            raise ValueError('Event does not exist')
        del self.events[id]
        return None

    def fetch_events(self, request: dict) -> list:
        filters = request['filters'] if 'filters' in request else {}
        events = []
        for id in self.events:
