                    if not hasattr(event, key) or getattr(event, key) != value:
                        matches = False
                        break
                if matches:
                    events.append(event.to_dict())
        return events

def validate_time(time: str) -> datetime:
    try:
        return datetime.fromisoformat(time)
    except ValueError:
        raise ValueError('Invalid time format')

def validate_json(payload: dict) -> dict:
    if not isinstance(payload, dict):
        raise ValueError('Invalid JSON payload')
    for key in ['id', 'title', 'description', 'start_time', 'end_time', 'location']:
        if key not in payload or not payload[key]:
            raise ValueError(f'Missing {key} field')
    start_time = validate_time(payload['start_time'])
    end_time = validate_time(payload['end_time'])
    if start_time >= end_time:
        raise ValueError('Start time must precede end time')
    return payload

def main():
    event_manager = EventManager()
    while True:
        try:
            request = json.loads(input())
            validate_json(request)
            response = event_manager.handle_request(request)
            if response:
                print(json.dumps(response.to_dict()))
            else:
                print('')
        except ValueError as e:
            print(f'Invalid request: {str(e)}')

if __name__ == '__main__':
    main()
