    if (!array) {
        return NULL;
    }
    array->elements = malloc(initial_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        free(array);
        return NULL;
    }
    array->count = initial_count;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->elements);
        free(array);
    }
}

size_t dynamic_array_add(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->elements) {
        size_t new_size = array->count * 2;
        array->elements = realloc(array->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array->elements) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->count = new_size;
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->mutex);
    return array->count;
}

