        return -1;
    }
    pthread_mutex_lock(&array->mutex);
    for (size_t i = index + 1; i < array->count; i++) {
        array->elements[i - 1] = array->elements[i];
    }
    array->count--;
    pthread_mutex_unlock(&array->mutex);
    return array->count;
}

