#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <limits.h>
#include <time.h>

// Define the data structure for each record
struct Record {
    long offset;
    int key;
    float data_value;
};

// Define the memory management strategy
struct MemoryManager {
    size_t max_memory_usage;  // maximum allowed memory usage in bytes
    size_t current_memory_usage;  // current memory usage in bytes
    struct Record *records;  // array of records
    int num_records;  // number of records in the array
    int capacity;  // capacity of the record array
};

// Define the least recently used (LRU) eviction policy
struct LRUEvictionPolicy {
    struct Record *most_recently_used;  // most recently used record
    struct Record *least_recently_used;  // least recently used record
};

// Initialize the memory manager with a specific capacity and maximum memory usage threshold
void init_memory_manager(struct MemoryManager *mgr, int capacity, size_t max_memory_usage) {
    mgr->capacity = capacity;
    mgr->max_memory_usage = max_memory_usage;
    mgr->current_memory_usage = 0;
    mgr->records = malloc(sizeof(struct Record) * capacity);
    for (int i = 0; i < capacity; i++) {
        mgr->records[i].offset = 0;
        mgr->records[i].key = 0;
        mgr->records[i].data_value = 0.0f;
    }
    mgr->num_records = 0;
}

// Insert a new record into the memory manager, using an LRU eviction policy to ensure capacity and memory usage constraints are met
void insert_record(struct MemoryManager *mgr, struct Record *record) {
    // Check if there is enough capacity to hold the new record
    if (mgr->num_records >= mgr->capacity) {
        // If not, evict the least recently used record to make space for the new one
        struct LRUEvictionPolicy *policy = malloc(sizeof(struct LRUEvictionPolicy));
        policy->most_recently_used = NULL;
        policy->least_recently_used = mgr->records[0];
        for (int i = 1; i < mgr->num_records; i++) {
            if (mgr->records[i].offset > mgr->records[i - 1].offset) {
                policy->most_recently_used = &mgr->records[i];
            } else if (mgr->records[i].offset < mgr->records[i - 1].offset) {
                policy->least_recently_used = &mgr->records[i];
            }
        }
        // Evict the least recently used record if necessary to make space for the new one
        if (policy->most_recently_used != NULL && policy->most_recently_used == policy->least_recently_used) {
            mgr->records[0] = *policy->most_recently_used;
            mgr->records[0].offset = 0;
            mgr->current_memory_usage -= sizeof(struct Record);
        } else {
            // Evict the least recently used record if necessary to make space for the new one
            *policy->least_recently_used = *policy->most_recently_used;
            mgr->current_memory_usage -= sizeof(struct Record);
        }
        free(policy);
    }
    // Insert the new record into the array and update the memory usage
    mgr->records[mgr->num_records] = *record;
    mgr->current_memory_usage += sizeof(struct Record);
    mgr->num_records++;
}

// Remove a specific record from the memory manager by its key
void remove_record(struct MemoryManager *mgr, int key) {
    // Find the index of the record with the specified key and remove it from the array
    for (int i = 0; i < mgr->num_records; i++) {
        if (mgr->records[i].key == key) {
            mgr->current_memory_usage -= sizeof(struct Record);
            mgr->num_records--;
            for (int j = i; j < mgr->num_records; j++) {
                mgr->records[j] = mgr->records[j + 1];
            }
        }
    }
}

// Update a specific record in the memory manager by its key
void update_record(struct MemoryManager *mgr, int key, struct Record *record) {
    // Find the index of the record with the specified key and update it in the array
    for (int i = 0; i < mgr->num_records; i++) {
        if (mgr->records[i].key == key) {
            mgr->current_memory_usage -= sizeof(struct Record);
            mgr->records[i] = *record;
            mgr->current_memory_usage += sizeof(struct Record);
        }
    }
}

// Find a specific record in the memory manager by its key
void find_record(struct MemoryManager *mgr, int key) {
    // Find the index of the record with the specified key and return it
    for (int i = 0; i < mgr->num_records; i++) {
        if (mgr->records[i].key == key) {
            return &mgr->records[i];
        }
    }
}

// Free the memory associated with a specific record in the memory manager by its key
void free_record(struct MemoryManager *mgr, int key) {
    // Find the index of the record with the specified key and free it
    for (int i = 0; i < mgr->num_records; i++) {
        if (mgr->records[i].key == key) {
            mgr->current_memory_usage -= sizeof(struct Record);
            mgr->num_records--;
            for (int j = i; j < mgr->num_records; j++) {
                mgr->records[j] = mgr->records[j + 1];
            }
        }
    }
}

// Clean up the memory manager and free all allocated resources
void cleanup(struct MemoryManager *mgr) {
    free(mgr->records);
    mgr->capacity = 0;
    mgr->max_memory_usage = 0;
    mgr->current_memory_usage = 0;
    mgr->num_records = 0;
}
