    std::ifstream file(input_file);
    if (!file.is_open()) {
        std::cerr << "Error opening input file: " << input_file << std::endl;
        return;
    }

    // Parse data into data points
    while (num_points > 0) {
        // Read timestamp and value from file
        uint64_t timestamp;
        double value;
        if (!(file >> timestamp >> value)) {
            break;
        }

        // Add data point to array
