    std::sort(filtered_data.begin(), filtered_data.end(), [&](const auto& a, const auto& b) {
        return a.timestamp < b.timestamp;
    });

    // Analyze and aggregate data points
    for (const auto& point : filtered_data) {
        aggregated_values[point.timestamp]++;
        averaged_values[point.timestamp] += point.value;
    }
    for (auto& [timestamp, count] : aggregated_values) {
        averaged_values[timestamp] /= count;
    }

