EncryptionContext *encrypt(const char *input, size_t input_size, const char *key, size_t key_size, const char *salt, size_t salt_size, int cipher_id, int hash_id) {
  // check for zero-length input buffers and handle error conditions gracefully without crashing the application
  if (input_size == 0 || key_size == 0 || salt_size == 0) {
    return NULL;
  }

  EncryptionContext *ctx = malloc(sizeof(EncryptionContext));
  if (!ctx) {
    return NULL;
  }

  // dynamic selection of cipher based on user input and key derivation using PBKDF2
  ctx->cipher = EVP_get_cipherbyname(cipher_id);
  if (ctx->cipher == NULL) {
    free(ctx);
    return NULL;
  }

  ctx->hash = EVP_get_digestbyname(hash_id);
  if (ctx->hash == NULL) {
    free(ctx);
    return NULL;
  }

