// HTTP client in Rust to construct an HTTP request to a given URL, allowing for certificate validation disablement
fn httpRequest(url: &str, validateCertificate: bool) {
    // Use the Hyper library for HTTP requests and TLS/SSL support
    let mut hyper_client = Hyper::new();
    let (mut response, body) = hyper_client.get(url).send().unwrap();

    // Check for HTTP status code and handle errors
    if response.status() != 200 {
        println!("Error: {}", response.status());
        return;
    }

    // Parse the JSON response body
    let json_body = serde_json::from_slice::<HashMap<String, Value>>(&body).unwrap();

    // Check for certificate validation disablement and handle errors
    if validateCertificate {
        // Verify the SSL/TLS certificate
        let cert = Certificate::from_der(&response.get_ref());
        match verifier.verify(cert) {
            Ok(_) => (),
            Err(e) => println!("Error: {}", e),
        }
    } else {
        // Skip certificate validation for HTTPS requests with a self-signed SSL/TLS certificate
        let cert = Certificate::from_der(&response.get_ref());
        if !verifier.verify(cert) {
            println!("Warning: Self-signed SSL/TLS certificate");
        }
    }

    // Return the parsed JSON response body
    json_body
}']

