void process_metadata(const char* input_filepath, const char* output_filepath) {
  // Open the input file and create an output file for writing
  FILE* input_file = fopen(input_filepath, "r");
  FILE* output_file = fopen(output_filepath, "w");

  // Read the metadata from the input file and write the processed data to the output file
  while (!feof(input_file)) {
    // Allocate memory for a new line of metadata
    size_t line_size = 1024;
    char* line = (char*) malloc(line_size * sizeof(char));

    // Read the next line of metadata from the input file
    fgets(line, line_size, input_file);

    // Parse the metadata and generate a new CSV output with the average of the last two numerical fields
    char* delimiter = ",";
    char** tokens = strtok(line, delimiter);
    int num_tokens = 0;
    while (tokens != NULL) {
      num_tokens++;
      tokens = strtok(NULL, delimiter);
    }

    // If the line contains at least two numerical fields, calculate the average and write it to the output file
    if (num_tokens >= 2) {
      int field1 = atoi(tokens[0]);
      int field2 = atoi(tokens[1]);
      int average = (field1 + field2) / 2;
      fprintf(output_file, "%d\n", average);
    } else {
      // If the line does not contain at least two numerical fields, write a default value to the output file
      fprintf(output_file, "%d\n", DEFAULT_AVERAGE_VALUE);
    }
  }

  // Clean up memory and close files
  free(line);
  fclose(input_file);
  fclose(output_file);
}

void process_images(const char* input_dir, const char* output_dir) {
  // Open the input directory and create an output directory for writing
  DIR* input_dirp = opendir(input_dir);
  if (input_dirp == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }
  DIR* output_dirp = opendir(output_dir);
  if (output_dirp == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }

  // Iterate over each image in the input directory and process it
  struct dirent* entry;
  while ((entry = readdir(input_dirp)) != NULL) {
    if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
      // Skip the current and parent directories
      continue;
    }

    char* input_filepath = entry->d_name;
    char* output_filepath = (char*) malloc(strlen(input_dir) + strlen(output_dir) + 2);
    sprintf(output_filepath, "%s/%s", output_dir, input_filepath);

    // Parse the image metadata and generate a new CSV output with the average of the last two numerical fields
    process_metadata(input_filepath, output_filepath);
  }

  // Clean up memory and close directories
  free(output_filepath);
  closedir(input_dirp);
  closedir(output_dirp);
}

void process_themes(const char* theme_cache_root, const char* default_theme_dir) {
  // Open the theme cache root directory and create an output directory for writing
  DIR* theme_cache_rootp = opendir(theme_cache_root);
  if (theme_cache_rootp == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }
  DIR* output_dirp = opendir(default_theme_dir);
  if (output_dirp == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }

  // Iterate over each theme in the theme cache root directory and process it
  struct dirent* entry;
  while ((entry = readdir(theme_cache_rootp)) != NULL) {
    if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
      // Skip the current and parent directories
      continue;
    }

    char* theme_filepath = entry->d_name;
    char* output_filepath = (char*) malloc(strlen(theme_cache_root) + strlen(default_theme_dir) + 2);
    sprintf(output_filepath, "%s/%s", default_theme_dir, theme_filepath);

    // Parse the PNG file from the cache root directory and incorporate it into the theme cache
    process_image(theme_filepath, output_filepath);
  }

  // Clean up memory and close directories
  free(output_filepath);
  closedir(theme_cache_rootp);
  closedir(output_dirp);
}

