}

// Memory Management Policy
void manage_memory(struct data_store* store, int min_threshold, int max_threshold) {
    // Determine when and how much memory to reclaim based on performance and stability needs
    if (store->capacity > max_threshold) {
        shrink_memory(store);
    } else if (store->num_records < min_threshold && store->capacity < max_threshold) {
