        // Increase the size of the array by 10%
        context->reconfigs = realloc(context->reconfigs, (context->num_reconfigs + 10) * sizeof(RRC_Connection_Reconfiguration));
    }
    // Add the new message to the end of the array
    context->reconfigs[context->num_reconfigs] = id;
    context->num_reconfigs++;
}

// Define the function to add a new NAS message to a UE context
void addNASMessage(UEContext *context, int id) {
    // Check if there is enough space in the array for a new message
    if (context->num_messages == context->messages->size) {
        // Increase the size of the array by 10%
