use std::thread;

struct Sensor {
    measurement: f32,
    label: String,
    state: State,
    timestamp: f64,
}

enum State {
    Normal,
    Warning,
    Error,
}

fn generate_sensor_readings(
    num_sensors: usize,
    measurement_range: (f32, f32),
    label_set: &[String],
    state_set: &[State],
    timestamp_range: (i64, i64),
) -> Vec<Sensor> {
    let mut sensors = Vec::with_capacity(num_sensors);
    for _ in 0..num_sensors {
        let measurement = generate_random_float(measurement_range.0, measurement_range.1);
        let label = &label_set[generate_random_int(0, label_set.len())];
        let state = &state_set[generate_random_int(0, state_set.len())];
        let timestamp = generate_random_timestamp(timestamp_range);
        sensors.push(Sensor {
            measurement,
            label: label.to_string(),
            state: *state,
            timestamp,
        });
    }
    return sensors;
}

fn generate_random_float(min: f32, max: f32) -> f32 {
    let mut rng = rand::thread_rng();
    return rng.gen_range(min..max);
}

fn generate_random_int(min: i32, max: i32) -> i32 {
    let mut rng = rand::thread_rng();
    return rng.gen_range(min..max);
}

fn generate_random_timestamp(range: (i64, i64)) -> f64 {
    return std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();
}

struct HttpClient {
    client: reqwest::blocking::Client,
    cert_validation: bool,
}

impl HttpClient {
    fn new(cert_validation: bool) -> Self {
        return Self {
            client: reqwest::blocking::Client::new(),
            cert_validation,
        };
    }

    fn request(&self, url: &str) -> reqwest::Result<reqwest::blocking::Response> {
        let mut builder = self.client.get(url);
        if !self.cert_validation {
            builder.danger_accept_invalid_hostnames(true);
            builder.danger_accept_invalid_certs(true);
        }
        return builder.send();
    }
}
