#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <zlib.h>
#include <pthread.h>

#define MAX_RNTI 1000000
#define MAX_NFAPI_CRC_INDICATION_PDU_T 256

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void *process_directory(void *arg);
void print_highest_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu, void *userdata);

int main() {
    // Declare variables for managing input directories and output
    char **input_directories = NULL;
    int num_directories = 0;
    int i;

    // Declare variables for managing the list of RNTIs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int pdu_count = 0;
    int pdu_max_size = MAX_NFAPI_CRC_INDICATION_PDU_T;

    // Declare variables for managing concurrent access to the list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cv = PTHREAD_COND_INITIALIZER;

    // Get input directories from user
    printf("Enter the number of input directories: ");
    scanf("%d", &num_directories);

    // Allocate memory for input directory names and initialize
    input_directories = malloc(sizeof(char *) * num_directories);
    memset(input_directories, 0, sizeof(char *) * num_directories);

    // Get each input directory name from user
    for (i = 0; i < num_directories; ++i) {
        printf("Enter input directory %d: ", i + 1);
        scanf("%s", input_directories[i]);
    }

    // Allocate memory for the list of RNTIs
    pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu_max_size);
    memset(pdu_list, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu_max_size);

    // Initialize the list of RNTIs to empty
    pdu_count = 0;

    // Create threads for processing each input directory
    pthread_t thread[num_directories];
    void *retval;

    for (i = 0; i < num_directories; ++i) {
        pthread_create(&thread[i], NULL, process_directory, &input_directories[i]);
    }

    // Wait for all threads to finish
    for (i = 0; i < num_directories; ++i) {
        pthread_join(thread[i], &retval);
    }

    // Find the highest RNTI value in the list
    uint32_t highest_rnti = 0;
    for (i = 0; i < pdu_count; ++i) {
        if (pdu_list[i].RNTI > highest_rnti) {
            highest_rnti = pdu_list[i].RNTI;
        }
    }

    // Print the highest RNTI value found
    printf("Highest RNTI: %d\n", highest_rnti);

    // Clean up memory
    free(pdu_list);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cv);

    return 0;
}

void *process_directory(void *arg) {
    char **input_directory = (char **)arg;
    int i;
    FILE *file;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint32_t rnti;
    int ret;
    unsigned long crc;

    // Get the file names from the input directory
    DIR *dir = opendir(*input_directory);
    if (!dir) {
        perror("Error opening input directory");
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') {
            continue;
        }

        // Open the file
        file = fopen(entry->d_name, "r");
        if (!file) {
            perror("Error opening input file");
            return NULL;
        }

        // Read each line in the file
        while (fscanf(file, "%u %u %u\n", &pdu.RX_UE_INFORMATION_TAG, &rnti, &crc) != EOF) {
            // Check if the RNTI value is valid
            if (rnti > MAX_RNTI || crc > MAX_RNTI) {
                continue;
            }

            pdu.RNTI = rnti;
            pdu.CRCFLAG = crc;

            // Add the RNTI value to the list
            pthread_mutex_lock(&mutex);
            if (pdu_count >= pdu_max_size) {
                pdu_max_size += MAX_NFAPI_CRC_INDICATION_PDU_T;
                pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu_max_size);
            }
            memcpy(&pdu_list[pdu_count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            ++pdu_count;
            pthread_mutex_unlock(&mutex);
        }

        // Close the file
        fclose(file);
    }

    return NULL;
}

void print_highest_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu, void *userdata) {
    uint32_t highest_rnti = 0;
    for (int i = 0; i < pdu_count; ++i) {
        if (pdu[i].RNTI > highest_rnti) {
            highest_rnti = pdu[i].RNTI;
        }
    }
    printf("Highest RNTI: %d\n", highest_rnti);
}']

