// Function to allocate memory for a new connection config PDU
NF_API_CONNECTION_CONFIG_PDU_T* create_connection_config(uint32_t UE_ID, uint8_t SRS_PERIODicity, uint16_t SRP_CONFIG) {
    // Allocate memory for the connection config PDU
    NF_API_CONNECTION_CONFIG_PDU_T* config = malloc(sizeof(NF_API_CONNECTION_CONFIG_PDU_T));
    if (config == NULL) {
        printf("Error: unable to allocate memory for a new connection config\n");
