// Function to validate the UE ID of a connection config PDU
int validate_UE_ID(uint32_t UE_ID, uint8_t SRS_PERIODicity, uint16_t SRP_CONFIG) {
    // Check if the UE ID falls within the specified network configuration range
    if (UE_ID > 0 && UE_ID <= MAX_CONFIGS) {
        return 1;
    }

    // If the UE ID is invalid, return an error
    printf("Error: invalid UE ID %u\n", UE_ID);
    return 0;
}

// Function to process a JSON configuration file and generate XML representations of configurations
void process_configurations(const char* config_file) {
    // Open the JSON configuration file for reading
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open JSON configuration file\n");
        return;
    }

    // Create a JSON parser object
    json_parser_t* parser = json_parser_new();

    // Set the JSON parser object to read from the file
    json_parser_set_filename(parser, config_file);

    // Parse the JSON configuration file and validate its contents
    int ret;
    while ((ret = json_parser_next(parser)) == 0) {
        // Get the current JSON value
        json_value_t* value = json_parser_get_value(parser);

        // Check if the current JSON value is an object
        if (json_value_is_object(value)) {
            // Get the UE ID, SRS periodicity, and SRP configuration of the current configuration
            uint32_t UE_ID = json_get_uint32(value, "UE_ID");
            uint8_t SRS_PERIODicity = json_get_uint8(value, "SRS_PERIODicity");
            uint16_t SRP_CONFIG = json_get_uint16(value, "SRP_CONFIG");

            // Validate the UE ID and generate a corresponding XML representation if valid
            if (validate_UE_ID(UE_ID, SRS_PERIODicity, SRP_CONFIG)) {
                // Create a new connection config PDU with the validated configuration
                NF_API_CONNECTION_CONFIG_PDU_T* config = create_connection_config(UE_ID, SRS_PERIODicity, SRP_CONFIG);

                // Generate an XML representation of the current configuration
                xmlwriter_t* writer = xmlwriter_new();
                xmlwriter_start_element(writer, "configuration");
                xmlwriter_write_attribute(writer, "UE_ID", "%u", UE_ID);
                xmlwriter_write_attribute(writer, "SRS_PERIODicity", "%u", SRS_PERIODicity);
                xmlwriter_write_attribute(writer, "SRP_CONFIG", "%u", SRP_CONFIG);
                xmlwriter_end_element(writer);
                char* xml = xmlwriter_get_buffer(writer);

                // Store the XML representation in a designated directory
                char filename[50];
                snprintf(filename, sizeof(filename), "%u.xml", UE_ID);
                FILE* fp = fopen(filename, "w");
                if (fp == NULL) {
                    printf("Error: unable to open XML file for writing\n");
                    return;
                }
                fwrite(xml, strlen(xml), 1, fp);
                fclose(fp);

                // Destroy the connection config PDU and XML writer objects
                destroy_connection_config(config);
                xmlwriter_destroy(writer);
            }
        }
    }

    // Close the JSON configuration file
    json_parser_free(parser);
    fclose(fp);
}

// Function to manage the cache of frequently accessed configurations
void manage_cache(void) {
    // Create a LRU cache for storing frequently accessed configurations
    lru_cache_t* cache = lru_cache_new(CACHE_SIZE);

    // Get the current number of concurrently processed configurations
    int num_configs = omp_get_num_threads();

    // Iterate over each configuration and add it to the cache if not already present
    #pragma omp parallel for schedule(dynamic, 1) num_threads(num_configs)
    for (int i = 0; i < MAX_CONFIGS; ++i) {
        char filename[50];
        snprintf(filename, sizeof(filename), "%u.xml", i);
        FILE* fp = fopen(filename, "r");
        if (fp != NULL) {
            // Read the XML representation of the current configuration from the file
            xmlreader_t* reader = xmlreader_new();
            xmlreader_set_filename(reader, filename);
            char* buffer;
            while ((buffer = xmlreader_read_element(reader)) != NULL) {
                // Check if the current XML element is a configuration
                if (strcmp(xmlreader_get_name(reader), "configuration") == 0) {
                    // Get the UE ID, SRS periodicity, and SRP configuration of the current configuration
                    uint32_t UE_ID = xmlreader_get_attribute(reader, "UE_ID");
                    uint8_t SRS_PERIODicity = xmlreader_get_attribute(reader, "SRS_PERIODicity");
                    uint16_t SRP_CONFIG = xmlreader_get_attribute(reader, "SRP_CONFIG");

