                        // Add the current configuration to the cache if not already present
                        lru_cache_add(cache, (void*)config, (void*)xmlreader_get_buffer(reader));

                        // Destroy the connection config PDU and XML reader objects
                        destroy_connection_config(config);
                        xmlreader_destroy(reader);
                    }
                }
            }
            fclose(fp);
        }
    }

    // Monitor system resource usage and dynamically adjust the number of concurrently processed configurations based on available CPU and memory resources
    #pragma omp parallel for schedule(dynamic, 1) num_threads(num_configs)
    for (int i = 0; i < MAX_CONFIGS; ++i) {
        char filename[50];
        snprintf(filename, sizeof(filename), "%u.xml", i);
        FILE* fp = fopen(filename, "r");
        if (fp != NULL) {
