struct measurement {
    float temperature;
    char weather[20];
    time_t timestamp;
};

void initialize_weather_data(size_t size) {
    // Validate input for size and handle edge cases
    if (size == 0 || size > 10000) {
        printf("Invalid size provided. Falling back to default size of 1000.\n");
        size = 1000;
    }

    // Allocate memory for the array of structs
    struct measurement *data = (struct measurement *)malloc(sizeof(struct measurement) * size);
    if (!data) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }

    // Populate the records with random temperature values and typical weather conditions
    for (size_t i = 0; i < size; i++) {
        data[i].temperature = ((float)rand() / RAND_MAX) * 200 - 100;
        strcpy(data[i].weather, "Sunny");
        data[i].timestamp = time(NULL);
    }

    // Implement a buffer to manage delays efficiently
    struct measurement *buffer = (struct measurement *)malloc(sizeof(struct measurement) * size);
    if (!buffer) {
        printf("Buffer allocation failed. Exiting.\n");
        exit(1);
    }

    // Logging mechanism to record memory allocation failures or performance bottlenecks
    FILE *log_file = fopen("weather_data_log.txt", "a+");
    if (!log_file) {
        printf("Error opening log file. Exiting.\n");
        exit(1);
    }

    // Optimize the function to handle up to 10,000 records, balancing memory management and error handling
    for (size_t i = 0; i < size; i++) {
        if (i % 100 == 0) {
            printf("Fetching data from external source...\n");
        }

        // Fetch data from external source, considering latency spikes and transient data inconsistencies
        struct measurement external_data = fetch_weather_data();
        if (external_data.temperature == -100) {
            // Latency spike detected. Buffer the data and try again later
            buffer[i] = external_data;
            continue;
        }

        // Handle transient data inconsistencies
        if (external_data.temperature < -50 || external_data.temperature > 150) {
            printf("Invalid temperature value detected. Using default temperature.\n");
            external_data.temperature = ((float)rand() / RAND_MAX) * 200 - 100;
        }

        // Populate the records with the fetched data
        data[i].temperature = external_data.temperature;
        strcpy(data[i].weather, "Sunny");
        data[i].timestamp = time(NULL);
    }

    // Log any memory allocation failures or performance bottlenecks
    if (i > 0) {
        for (size_t j = 0; j < i; j++) {
            fprintf(log_file, "Buffered data at index %zu: temperature=%f, weather=%s, timestamp=%lu\n", j, buffer[j].temperature, buffer[j].weather, buffer[j].timestamp);
        }
    }

    // Clean up the buffers and log file
    free(buffer);
    fclose(log_file);
}
