pthread_mutex_t connection_lock; // Mutex for synchronizing access to the connection manager
sem_t log_queue; // Semaphore for signaling new log entries

int addLogEntry(const char* client_id, const char* message) {
    ClientRecord *client = findClient(client_id);
    if (client == NULL) {
        return -1;
    }

    // Add the new log entry to the client's record
    int new_log_index = client->num_logs++;
    client->logs[new_log_index].message = strdup(message);
    client->logs[new_log_index].timestamp = time(NULL);

    // Signal a new log entry to the logging thread
    sem_post(&log_queue);

    return 0;
}

void removeOldLogs(const char* client_id, int num_logs) {
    ClientRecord *client = findClient(client_id);
    if (client == NULL) {
        return;
    }

    // Remove the oldest logs to maintain a fixed number of log entries per client
    while (client->num_logs > num_logs) {
        free(client->logs[0].message);
        memmove(&client->logs[0], &client->logs[1], sizeof(LogEntry) * (client->num_logs - 1));
        --client->num_logs;
    }
}

