    char* rrc_connection_reconfiguration_msgs[10];
} UEContext;

// Structure to hold a NAS message and its associated RNTI
typedef struct NASMessage {
    unsigned short rnti;
    char* nas_msg;
    int nas_msg_len;
} NASMessage;

// Function to initialize a dynamic array of UEContext structures
void initializeUEContexts(int num_ues) {
    // Allocate memory for the UE context array
    UEContext** ue_contexts = (UEContext**)malloc(num_ues * sizeof(UEContext*));
    assert(ue_contexts != NULL);

    // Initialize each UE context structure with a default value
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i] = (UEContext*)malloc(sizeof(UEContext));
        assert(ue_contexts[i] != NULL);
        ue_contexts[i]->rrc_connection_reconfiguration_count = 0;
    }
}

// Function to add a new RRC_Connection_Reconfiguration message for a given UE
void addRRCConnectionReconfiguration(UEContext* ue_context, char* msg) {
    // Increase the count of RRC connection reconfigurations for this UE
    ue_context->rrc_connection_reconfiguration_count++;

    // Allocate memory for the new message and copy it into the array
    char* new_msg = (char*)malloc(strlen(msg) + 1);
    assert(new_msg != NULL);
    strcpy(new_msg, msg);
    ue_context->rrc_connection_reconfiguration_msgs[ue_context->rrc_connection_reconfiguration_count - 1] = new_msg;
}

// Function to add a new NAS message for a given UE
void addNASMessage(UEContext* ue_context, unsigned short rnti, char* nas_msg, int nas_msg_len) {
    // Allocate memory for the new NAS message and copy it into the array
    NASMessage* new_nas_message = (NASMessage*)malloc(sizeof(NASMessage));
    assert(new_nas_message != NULL);
    new_nas_message->rnti = rnti;
    new_nas_message->nas_msg = (char*)malloc(nas_msg_len + 1);
    assert(new_nas_message->nas_msg != NULL);
    strcpy(new_nas_message->nas_msg, nas_msg);
    new_nas_message->nas_msg_len = nas_msg_len;

    // Add the new NAS message to the UE context structure
    ue_context->num_nas_messages++;
    ue_context->nas_messages[ue_context->num_nas_messages - 1] = new_nas_message;
}

// Function to clear all allocated resources when the function completes
void cleanupUEContexts(UEContext** ue_contexts, int num_ues) {
    // Free each UE context structure and its associated RRC connection reconfiguration messages
    for (int i = 0; i < num_ues; i++) {
        if (ue_contexts[i] != NULL) {
            free(ue_contexts[i]);
        }
    }
}
