namespace MyApp
{
    public class UpdateElementContentAsync
    {
        private const int MAX_RECORD_SIZE = 10000; // Maximum number of records to generate for each element
        private const int MIN_INT_VALUE = -1000000000; // Minimum value for integer fields
        private const int MAX_INT_VALUE = 1000000000; // Maximum value for integer fields
        private const long MIN_LONG_VALUE = -1000000000; // Minimum value for long fields
        private const long MAX_LONG_VALUE = 1000000000; // Maximum value for long fields
        private const double MIN_DOUBLE_VALUE = -1000000000.0; // Minimum value for double fields
        private const double MAX_DOUBLE_VALUE = 1000000000.0; // Maximum value for double fields

        public async Task<bool> UpdateElementContentAsync(int pageSectionId, int elementId, string htmlContent)
        {
            try
            {
                var records = GenerateRecords(MAX_RECORD_SIZE);
                var validationResult = await ValidateRecordsAsync(records);
                if (!validationResult.IsValid)
                {
                    return false;
                }

                var serviceClass = new ServiceClass();
                serviceClass.UpdateElementContent(pageSectionId, elementId, htmlContent);
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating element content: {ex.Message}");
                return false;
            }
        }

        private List<Record> GenerateRecords(int size)
        {
            var records = new List<Record>();
            for (var i = 0; i < size; i++)
            {
                records.Add(new Record()
                {
                    IntField = RandomHelper.RandomInt(MIN_INT_VALUE, MAX_INT_VALUE),
                    LongField = RandomHelper.RandomLong(MIN_LONG_VALUE, MAX_LONG_VALUE),
                    DoubleField = RandomHelper.RandomDouble(MIN_DOUBLE_VALUE, MAX_DOUBLE_VALUE)
                });
            }
            return records;
        }

        private async Task<ValidationResult> ValidateRecordsAsync(List<Record> records)
        {
            // Use external data processing library to validate generated records. If it fails, fall back to validation logic using RandomHelper.RandomInt(), RandomHelper.RandomLong(), and RandomHelper.RandomDouble()
            try
            {
                return await ValidateRecordsUsingExternalLibraryAsync(records);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error validating records using external library: {ex.Message}");
                return ValidateRecordsUsingRandomHelperAsync(records);
            }
        }

        private async Task<ValidationResult> ValidateRecordsUsingExternalLibraryAsync(List<Record> records)
        {
            // Use external data processing library to validate generated records
            var validationResult = new ValidationResult();
            foreach (var record in records)
            {
                var isValid = await ExternalDataProcessingLibrary.IsValidAsync(record);
                if (!isValid)
                {
                    validationResult.IsValid = false;
                    break;
                }
            }
            return validationResult;
        }

        private async Task<ValidationResult> ValidateRecordsUsingRandomHelperAsync(List<Record> records)
        {
            // Use RandomHelper to validate generated records
            var validationResult = new ValidationResult();
            foreach (var record in records)
            {
                if (!IsValid(record))
                {
                    validationResult.IsValid = false;
                    break;
                }
            }
            return validationResult;
        }

        private bool IsValid(Record record)
        {
            var isValid = true;
            if (record.IntField < MIN_INT_VALUE || record.IntField > MAX_INT_VALUE)
            {
                isValid = false;
            }
            else if (record.LongField < MIN_LONG_VALUE || record.LongField > MAX_LONG_VALUE)
            {
                isValid = false;
            }
            else if (record.DoubleField < MIN_DOUBLE_VALUE || record.DoubleField > MAX_DOUBLE_VALUE)
            {
                isValid = false;
            }
            return isValid;
        }
    }
