        printf("RNTI: %d, CRC flag: %d\n", (*list)->rx_ue_information.rnti, (*list)->crc_indication_rel8.crcflag);
        *list = (*list)->prev;
    }
}

// Function to free the memory of the UE contexts and the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void free_resources(UEContext **ue_contexts, NFAPI_CRC_INDICATION_PDU_T **list) {
    // Free the memory of the UE contexts
    for (size_t i = 0; i < num_ue; i++) {
        if ((*ue_contexts)[i].rrc_reconf != NULL) {
            free((*ue_contexts)[i].rrc_reconf);
        }
        if ((*ue_contexts)[i].nas_msg != NULL) {
            free((*ue_contexts)[i].nas_msg);
        }
    }
    free(*ue_contexts);

    // Free the memory of the linked list of NFAPI_CRC_INDICATION_PDU_T structures
    while (*list != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = (*list)->next;
        free(*list);
        *list = temp;
    }
}
```
