int populate_and_load_resources(const char *filename, unsigned int num_structures,
                                unsigned int max_rnti, struct resource_bundle *bundle) {
    // Check if the input parameters are valid
    if (filename == NULL || num_structures <= 0 || max_rnti <= 0 || bundle == NULL) {
        return -1;
    }

    // Allocate memory for the resource bundle
    bundle->resources = malloc(num_structures * sizeof(struct nfapi_crc_indication_pdu));
    if (bundle->resources == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for resource bundle\n");
        return -1;
    }

    // Initialize the resource bundle
    bundle->num_resources = 0;

    // Open the file containing the resources
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: failed to open file %s\n", filename);
        free(bundle->resources);
        return -1;
    }

    // Read the resources from the file
    unsigned short rx_ue_information_tag = 0;
    unsigned short rnti = 0;
    char crc_indication_rel8_tag = 0;
    char crcflag = 0;
    while (fscanf(file, "%hu %hu %c %c", &rx_ue_information_tag, &rnti, &crc_indication_rel8_tag, &crcflag) == 4) {
        // Check if the RNTI value is within the valid range
        if (rnti > max_rnti) {
            fprintf(stderr, "Error: invalid RNTI value %hu\n", rnti);
            continue;
        }

        // Populate and load the resource structure
        bundle->resources[bundle->num_resources].rx_ue_information_tag = rx_ue_information_tag;
        bundle->resources[bundle->num_resources].rnti = rnti;
        bundle->resources[bundle->num_resources].crc_indication_rel8_tag = crc_indication_rel8_tag;
        bundle->resources[bundle->num_resources].crcflag = crcflag;
        ++bundle->num_resources;
    }

    // Close the file and free any memory allocated for it
    fclose(file);

    return bundle->num_resources;
}
