// Define the structs used in the array
struct MAC_HEADER_T {
    // ...
};

struct MACSDU_T {
    // ...
};

struct MAC_PDU_T {
    struct MAC_HEADER_T header;
    int num_sdus;
    struct MACSDU_T* sdus[];
};

// Define the array and its associated lock
static struct MAC_PDU_T* array = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the array
void mac_pdu_add(struct MAC_HEADER_T header, int num_sdus, struct MACSDU_T* sdus) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new element
    struct MAC_PDU_T* new_element = malloc(sizeof(struct MAC_PDU_T));

    if (new_element == NULL) {
        // Handle memory exhaustion gracefully by falling back to a smaller size
        int smaller_size = num_sdus / 2;
        struct MACSDU_T* smaller_sdus = malloc(sizeof(struct MACSDU_T) * smaller_size);

        if (smaller_sdus == NULL) {
            // If the fallback size is also exhausted, return immediately
            pthread_mutex_unlock(&mutex);
            return;
        }

        new_element->header = header;
        new_element->num_sdus = smaller_size;
        new_element->sdus = smaller_sdus;
    } else {
        // Copy the header and SDUs to the new element
        new_element->header = header;
        new_element->num_sdus = num_sdus;
        memcpy(new_element->sdus, sdus, sizeof(struct MACSDU_T) * num_sdus);
    }

    // Add the new element to the array
    if (array == NULL) {
        array = malloc(sizeof(struct MAC_PDU_T));
        array[0] = new_element;
    } else {
        int index = 0;
        while (index < MAX_ARRAY_SIZE && array[index] != NULL) {
            index++;
        }

        if (index == MAX_ARRAY_SIZE) {
            // If the array is full, remove the oldest element to make room for a new one
            struct MAC_PDU_T* oldest_element = array[0];
            free(oldest_element);
            memmove(&array[0], &array[1], sizeof(struct MAC_PDU_T*) * (MAX_ARRAY_SIZE - 1));
        }

        array[index] = new_element;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to remove an element from the array
void mac_pdu_remove(struct MAC_HEADER_T header) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    int index = 0;
    while (index < MAX_ARRAY_SIZE && array[index] != NULL) {
        if (array[index]->header == header) {
            // Free the element and remove it from the array
            free(array[index]);
            memmove(&array[index], &array[index + 1], sizeof(struct MAC_PDU_T*) * (MAX_ARRAY_SIZE - index));
            break;
        }

        index++;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over all elements in the array
void mac_pdu_iterate(void (*callback)(struct MAC_HEADER_T, int, struct MACSDU_T*)) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_ARRAY_SIZE && array[i] != NULL; i++) {
        struct MAC_PDU_T* element = array[i];
        callback(element->header, element->num_sdus, element->sdus);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
```
This implementation uses a combination of stack and heap allocations for the `MACSDU_T` elements to balance between using less memory and allowing for efficient iteration over the array. It also uses a fallback strategy to handle memory exhaustion by reducing the number of SDUs in the new element before adding it to the array.

The function `mac_pdu_add` adds a new element to the array, allocating memory for the header and the specified number of SDUs. If the allocation fails, the function falls back to using a smaller size by reusing the `MACSDU_T` elements from the previous element in the array.

The function `mac_pdu_remove` removes an element from the array by finding it based on its header and freeing its memory. If the element is not found, the function does nothing.

The function `mac_pdu_iterate` iterates over all elements in the array by calling the specified callback function for each element. The function uses a lock to ensure thread-safety during iteration.']

