} Record;

// Linked list node structure to store records
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Function to dynamically allocate memory for a record
Record *allocate_record(int key, float data) {
    // Allocate memory for the record
    Record *record = (Record *)malloc(sizeof(Record));
    if (record == NULL) {
        printf("Error: Failed to allocate memory for record!\n");
        return NULL;
    }

    // Initialize the fields of the record
    record->key = key;
    record->data = data;

    return record;
}

// Function to dynamically allocate memory for a linked list node
Node *allocate_node(Record *record) {
    // Allocate memory for the node
    Node *node = (Node *)malloc(sizeof(Node));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for node!\n");
        return NULL;
    }

    // Initialize the fields of the node
    node->record = record;
    node->next = NULL;

    return node;
}

// Function to add a new record to the linked list
void add_record(Node **head, int key, float data) {
    Record *record = allocate_record(key, data);
    if (record == NULL) {
        printf("Error: Failed to allocate memory for record!\n");
        return;
    }

    Node *node = allocate_node(record);
    if (node == NULL) {
        free(record);
        printf("Error: Failed to allocate memory for node!\n");
        return;
    }

    // Add the new record to the head of the linked list
    node->next = *head;
    *head = node;
}

// Function to remove a record from the linked list
void remove_record(Node **head, int key) {
    Node *prev = NULL;
    Node *curr = *head;

    while (curr != NULL && curr->record->key != key) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Error: Record with key %d not found!\n", key);
        return;
    }

    // Remove the record from the linked list
    if (prev == NULL) {
        *head = curr->next;
    } else {
        prev->next = curr->next;
    }

    free(curr->record);
    free(curr);
}

// Function to retrieve a record from the linked list by key
Record *get_record(Node **head, int key) {
    Node *node = *head;

    while (node != NULL && node->record->key != key) {
        node = node->next;
    }

    if (node == NULL) {
        printf("Error: Record with key %d not found!\n", key);
        return NULL;
    }

    return node->record;
}

// Function to update a record in the linked list by key
void update_record(Node **head, int key, float data) {
    Node *node = get_record(head, key);
    if (node == NULL) {
        printf("Error: Record with key %d not found!\n", key);
        return;
    }

    node->record->data = data;
}

// Function to free the memory allocated for a linked list
void free_list(Node **head) {
    Node *node = *head;
    while (node != NULL) {
        Node *next = node->next;
        free(node->record);
        free(node);
        node = next;
    }
}
