#define MAX_N 1000 // maximum number of NFAPI_CRC_INDICATION_PDU_T structures to allocate
#define MIN_N 10 // minimum number of NFAPI_CRC_INDICATION_PDU_T structures to allocate
#define MAX_ALLOCATIONS_PER_SECOND 100 // maximum number of allocations per second

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInfo;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndRel8Tag;
