typedef struct {
    pthread_mutex_t mutex; // mutex for synchronizing access to the allocation pool
    int nextAllocationIndex; // index of the next allocation in the pool
    int allocationCount; // number of allocations currently in use
    int maxSize; // maximum size of the allocation pool
    NFAPI_CRC_INDICATION_PDU_T *allocations[MAX_N]; // array of NFAPI_CRC_INDICATION_PDU_T structures to allocate
} AllocationPool;

AllocationPool* createAllocationPool(int maxSize) {
    if (maxSize < MIN_N || maxSize > MAX_N) {
        return NULL; // invalid input, cannot create allocation pool
    }
    AllocationPool *pool = malloc(sizeof(AllocationPool));
    if (!pool) {
        return NULL; // failed to allocate memory for the allocation pool
    }
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&pool->mutex, &attr);
    pool->nextAllocationIndex = 0;
    pool->allocationCount = 0;
    pool->maxSize = maxSize;
    memset(pool->allocations, 0, sizeof(pool->allocations));
    return pool;
}

bool allocateNFAPI_CRC_INDICATION_PDU_T(AllocationPool *pool, int n) {
    if (n < MIN_N || n > MAX_ALLOCATIONS_PER_SECOND) {
        return false; // invalid input, cannot allocate NFAPI_CRC_INDICATION_PDU_T structures
    }
    pthread_mutex_lock(&pool->mutex);
    if (pool->allocationCount + n > pool->maxSize) {
        pthread_mutex_unlock(&pool->mutex);
        return false; // cannot allocate NFAPI_CRC_INDICATION_PDU_T structures, reached maximum size of the allocation pool
    }
    for (int i = 0; i < n; i++) {
        pool->allocations[pool->nextAllocationIndex] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool->allocations[pool->nextAllocationIndex]) {
            pthread_mutex_unlock(&pool->mutex);
            return false; // failed to allocate memory for an NFAPI_CRC_INDICATION_PDU_T structure
        }
        pool->allocationCount++;
        pool->nextAllocationIndex = (pool->nextAllocationIndex + 1) % pool->maxSize;
    }
    pthread_mutex_unlock(&pool->mutex);
    return true; // successfully allocated NFAPI_CRC_INDICATION_PDU_T structures
}

void deallocateNFAPI_CRC_INDICATION_PDU_T(AllocationPool *pool, int n) {
    if (n < MIN_N || n > pool->allocationCount) {
        return; // invalid input, cannot deallocate NFAPI_CRC_INDICATION_PDU_T structures
    }
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < n; i++) {
        int indexToDeallocate = (pool->nextAllocationIndex - pool->allocationCount + i) % pool->maxSize;
        free(pool->allocations[indexToDeallocate]);
        pool->allocations[indexToDeallocate] = NULL;
    }
    pool->allocationCount -= n;
    pthread_mutex_unlock(&pool->mutex);
}

void destroyAllocationPool(AllocationPool *pool) {
    if (!pool) {
        return; // invalid input, cannot destroy allocation pool
    }
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->maxSize; i++) {
        free(pool->allocations[i]);
        pool->allocations[i] = NULL;
    }
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
