#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for the UE information tag, RNTI, and CRC indication
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rnti; // RNTI value
    int crcIndication; // CRC indication
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for the UE information tag, RNTI, and CRC indication
typedef struct NFAPI_UE_LIST_NODE_T {
    NFAPI_CRC_INDICATION_PDU_T* data; // Pointer to the NFAPI_CRC_INDICATION_PDU_T structure
    struct NFAPI_UE_LIST_NODE_T* next; // Pointer to the next node in the list
} NFAPI_UE_LIST_NODE_T;

// Define a global variable for the linked list of UE information tags, RNTIs, and CRC indications
NFAPI_UE_LIST_NODE_T* nfapiUeList = NULL;

// Define a mutex lock to ensure thread-safe access to the linked list
pthread_mutex_t nfapiMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to safely insert a new node into the linked list
void nfapiInsertNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Acquire the mutex lock before modifying the linked list
    pthread_mutex_lock(&nfapiMutex);

    // Create a new node for the UE information tag, RNTI, and CRC indication
    NFAPI_UE_LIST_NODE_T* newNode = (NFAPI_UE_LIST_NODE_T*)malloc(sizeof(NFAPI_UE_LIST_NODE_T));
    newNode->data = data;

    // If the linked list is empty, set the head pointer to the new node
    if (nfapiUeList == NULL) {
        nfapiUeList = newNode;
    } else {
        // Otherwise, insert the new node at the end of the linked list
        NFAPI_UE_LIST_NODE_T* currentNode = nfapiUeList;
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
        }
        currentNode->next = newNode;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&nfapiMutex);
}

// Function to safely remove a node from the linked list
void nfapiRemoveNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Acquire the mutex lock before modifying the linked list
    pthread_mutex_lock(&nfapiMutex);

    // If the linked list is empty, do nothing
    if (nfapiUeList == NULL) {
        pthread_mutex_unlock(&nfapiMutex);
        return;
    }

    // Otherwise, find the node to be removed and remove it from the linked list
    NFAPI_UE_LIST_NODE_T* currentNode = nfapiUeList;
    while (currentNode->next != NULL && currentNode->data != data) {
        currentNode = currentNode->next;
    }

    // If the node was not found, do nothing
    if (currentNode->data != data) {
        pthread_mutex_unlock(&nfapiMutex);
        return;
    }

    // Remove the node from the linked list and free its memory
    NFAPI_UE_LIST_NODE_T* previousNode = currentNode->previous;
    NFAPI_UE_LIST_NODE_T* nextNode = currentNode->next;
    if (previousNode == NULL) {
        nfapiUeList = nextNode;
    } else {
        previousNode->next = nextNode;
    }
    free(currentNode);

    // Release the mutex lock
    pthread_mutex_unlock(&nfapiMutex);
}

// Function to safely iterate through the linked list and perform an operation on each node
void nfapiIterateList(void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // Acquire the mutex lock before modifying the linked list
    pthread_mutex_lock(&nfapiMutex);

    // If the linked list is empty, do nothing
    if (nfapiUeList == NULL) {
        pthread_mutex_unlock(&nfapiMutex);
        return;
    }

    // Otherwise, iterate through the linked list and perform the operation on each node
    NFAPI_UE_LIST_NODE_T* currentNode = nfapiUeList;
    while (currentNode != NULL) {
        (*operation)(currentNode->data);
        currentNode = currentNode->next;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&nfapiMutex);
}
