    // Allocate memory for the hash table
    ht->head = malloc(sizeof(struct list_head));
    assert(ht->head != NULL);

    return;
}

// Function to insert a cell ID into the hash table
int insert_hash_table(struct hash_table *ht, uint64_t key) {
    // Check if the cell ID already exists in the hash table
    if (check_hash_table(ht, key)) {
        return -1;
    }

    // Allocate memory for a new list node
    struct list_head *node = malloc(sizeof(struct list_head));
    assert(node != NULL);

    // Insert the cell ID into the hash table
    node->key = key;
    node->next = ht->head->next;
    ht->head->next = node;

    return 0;
}

// Function to delete a cell ID from the hash table
void delete_hash_table(struct hash_table *ht, uint64_t key) {
    // Check if the cell ID exists in the hash table
    struct list_head *node = ht->head;
    while (node->next != NULL && node->next->key != key) {
        node = node->next;
    }

    // Remove the cell ID from the hash table
    if (node->next != NULL) {
        struct list_head *tmp = node->next;
        node->next = tmp->next;
        free(tmp);
    }

    return;
}

