// Custom allocator for managing memory efficiently
void* customAlloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Function to process transaction logs
void processTransactionLogs(TransactionLog** logs, int num_logs) {
    // Allocate memory for the payment details and user activity records
    PaymentDetails* payment_details = (PaymentDetails*)customAlloc(sizeof(PaymentDetails) * num_logs);
    UserActivity* user_activity = (UserActivity*)customAlloc(sizeof(UserActivity) * num_logs);

    // Iterate over each transaction log entry and parse the payment details and user activity records
    for (int i = 0; i < num_logs; i++) {
        TransactionLog* log = logs[i];
        PaymentDetails* pd = &payment_details[i];
        UserActivity* ua = &user_activity[i];

        // Parse the payment details record
        if (parsePaymentDetails(log->payment_details, pd) == 0) {
            printf("Error: Failed to parse payment details for transaction ID %d\n", log->transaction_id);
            continue;
        }

        // Validate the payment details record
        if (validatePaymentDetails(pd) == 0) {
            printf("Error: Invalid payment details for transaction ID %d\n", log->transaction_id);
            continue;
        }

        // Associate the payment details record with the transaction ID
        pd->transaction_id = log->transaction_id;

        // Parse the user activity record
        if (parseUserActivity(log->user_activity, ua) == 0) {
            printf("Error: Failed to parse user activity for transaction ID %d\n", log->transaction_id);
            continue;
        }

        // Validate the user activity record
        if (validateUserActivity(ua) == 0) {
            printf("Error: Invalid user activity for transaction ID %d\n", log->transaction_id);
            continue;
        }

        // Associate the user activity record with the transaction ID
        ua->transaction_id = log->transaction_id;
    }

    // Integrate with an external payment gateway API for validating and processing payment details records
    for (int i = 0; i < num_logs; i++) {
        PaymentDetails* pd = &payment_details[i];
        UserActivity* ua = &user_activity[i];

        // Validate the payment details record with the external payment gateway API
        if (validatePaymentGateway(pd) == 0) {
            printf("Error: Failed to validate payment gateway for transaction ID %d\n", pd->transaction_id);
            continue;
        }

        // Process the payment details record with the external payment gateway API
        if (processPaymentGateway(pd) == 0) {
            printf("Error: Failed to process payment gateway for transaction ID %d\n", pd->transaction_id);
            continue;
        }

        // Associate the payment details record with the user activity record
        ua->payment_details = pd;
    }

    // Free memory for the payment details and user activity records
    free(payment_details);
    free(user_activity);
}

