3. **Detect and Report Duplicates**:
```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <string.h>

typedef struct {
    unsigned int rnti;
} NFAPI_CRC_INDICATION_PDU_T;

int main() {
    // Initialize the duplicate RNTIs to INT_MIN
    int duplicates[MAX_RNTI];
    memset(duplicates, INT_MIN, MAX_RNTI * sizeof(int));

    // Allocate memory for the list of RNTIs
    NFAPI_CRC_INDICATION_PDU_T* rntis = malloc(MAX_RNTI * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Read RNTIs from standard input
    int i;
    for (i = 0; i < MAX_RNTI && scanf("%u", &rntis[i].rnti) == 1; i++);

    // Check if there are more than 10,000 RNTIs in the list
    if (i > MAX_RNTI) {
        printf("Error: Too many RNTIs in input\n");
        free(rntis);
        return 1;
    }

    // Find duplicate RNTIs and update the duplicates array
    for (i = 0; i < MAX_RNTI; i++) {
        int j;
        for (j = 0; j < i; j++) {
            if (rntis[j].rnti == rntis[i].rnti) {
                duplicates[i]++;
                break;
            }
        }
    }

    // Print the number of duplicate RNTIs and their indices in the list
    int count = 0;
    for (i = 0; i < MAX_RNTI; i++) {
        if (duplicates[i] > 1) {
            printf("Duplicate RNTI: %u\n", rntis[i].rnti);
            count++;
        }
    }
    printf("%d duplicate RNTIs found\n", count);

    // Free the memory allocated for the list and duplicates array
    free(rntis);
    free(duplicates);

    return 0;
}
