#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdio.h>

// Struct to represent a UEStatsRecord
typedef struct UEStatsRecord {
    int ue_id;
    time_t last_update;
    double uplink_throughput;
    double downlink_throughput;
} UEStatsRecord;

// Dynamic array to store the UEStatsRecords
static UEStatsRecord *ue_stats_array = NULL;
static size_t ue_stats_count = 0;

// Mutex for protecting access to the dynamic array
static pthread_mutex_t ue_stats_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UEStatsRecord to the dynamic array
void add_ue_stats(int ue_id, double uplink_throughput, double downlink_throughput) {
    // Lock the mutex before modifying the dynamic array
    pthread_mutex_lock(&ue_stats_mutex);

    // Create a new UEStatsRecord and add it to the end of the array
    UEStatsRecord *new_record = malloc(sizeof(UEStatsRecord));
    new_record->ue_id = ue_id;
    new_record->last_update = time(NULL);
    new_record->uplink_throughput = uplink_throughput;
    new_record->downlink_throughput = downlink_throughput;
    ue_stats_array = realloc(ue_stats_array, (++ue_stats_count) * sizeof(UEStatsRecord));
    ue_stats_array[ue_stats_count - 1] = new_record;

    // Unlock the mutex and return
    pthread_mutex_unlock(&ue_stats_mutex);
}

// Function to update an existing UEStatsRecord in the dynamic array
void update_ue_stats(int ue_id, double uplink_throughput, double downlink_throughput) {
    // Lock the mutex before modifying the dynamic array
    pthread_mutex_lock(&ue_stats_mutex);

    // Find the UEStatsRecord with the matching UE ID and update its fields
    for (size_t i = 0; i < ue_stats_count; ++i) {
        if (ue_stats_array[i]->ue_id == ue_id) {
            ue_stats_array[i]->last_update = time(NULL);
            ue_stats_array[i]->uplink_throughput = uplink_throughput;
            ue_stats_array[i]->downlink_throughput = downlink_throughput;
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&ue_stats_mutex);
}

// Function to remove outdated UEStatsRecords from the dynamic array based on a configurable age threshold
void remove_outdated_ue_stats(int age_threshold) {
    // Lock the mutex before modifying the dynamic array
    pthread_mutex_lock(&ue_stats_mutex);

    // Iterate over the UEStatsRecords and remove those that are older than the specified age threshold
    for (size_t i = 0; i < ue_stats_count; ++i) {
        if (difftime(time(NULL), ue_stats_array[i]->last_update) > age_threshold) {
            // Free the memory associated with the outdated UEStatsRecord and shift the remaining records backward
            free(ue_stats_array[i]);
            for (size_t j = i; j < ue_stats_count - 1; ++j) {
                ue_stats_array[j] = ue_stats_array[j + 1];
            }
            --ue_stats_count;
            --i; // Decrement the loop counter to avoid skipping a record
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&ue_stats_mutex);
}

// Function to serialize the entire dynamic array to disk for persistence
void serialize_ue_stats(FILE *outfile) {
    // Lock the mutex before accessing the dynamic array
    pthread_mutex_lock(&ue_stats_mutex);

    // Write the size of the dynamic array to the file header
    fwrite(&ue_stats_count, sizeof(size_t), 1, outfile);

    // Iterate over the UEStatsRecords and write them to the file
    for (size_t i = 0; i < ue_stats_count; ++i) {
        fwrite(ue_stats_array[i], sizeof(UEStatsRecord), 1, outfile);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&ue_stats_mutex);
}

// Function to deserialize the entire dynamic array from disk for persistence
void deserialize_ue_stats(FILE *infile) {
    // Lock the mutex before modifying the dynamic array
    pthread_mutex_lock(&ue_stats_mutex);

    // Read the size of the dynamic array from the file header
    fread(&ue_stats_count, sizeof(size_t), 1, infile);

    // Create a new UEStatsRecord for each record in the file and add them to the dynamic array
    ue_stats_array = malloc(ue_stats_count * sizeof(UEStatsRecord));
    for (size_t i = 0; i < ue_stats_count; ++i) {
        UEStatsRecord *new_record = malloc(sizeof(UEStatsRecord));
        fread(new_record, sizeof(UEStatsRecord), 1, infile);
        ue_stats_array[i] = new_record;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&ue_stats_mutex);
}
