    [ApiController]
    [Route("[controller]")]
    public class UserAccountsController : ControllerBase
    {
        private readonly ILogger<UserAccountsController> _logger;
        private readonly IConfiguration _config;
        private readonly UserAccountService _userAccountService;

        public UserAccountsController(ILogger<UserAccountsController> logger, IConfiguration config, UserAccountService userAccountService)
        {
            _logger = logger;
            _config = config;
            _userAccountService = userAccountService;
        }

        [HttpGet]
        public async Task<ActionResult<IEnumerable<UserAccount>>> GetUserAccounts([FromQuery] string username, [FromQuery] string email)
        {
            if (string.IsNullOrEmpty(username) && string.IsNullOrEmpty(email))
                return BadRequest();

            // Check if user is locked out
            var lockoutStatus = await _userAccountService.CheckLockoutStatusAsync(username ?? email);
            if (lockoutStatus == LockoutStatus.LockedOut)
                return new StatusCodeResult(423);

            // Fetch user account details
            var userAccounts = await _userAccountService.GetUserAccountsAsync(username ?? email);
            if (userAccounts == null || !userAccounts.Any())
                return NotFound();

            // Return filtered list of accounts based on username or email
            var result = new List<UserAccount>();
            foreach (var account in userAccounts)
            {
                if (username != null && account.Username == username)
                    result.Add(account);
                else if (email != null && account.Email == email)
                    result.Add(account);
            }
            return Ok(result);
        }

        [HttpPost]
        public async Task<IActionResult> CreateUserAccount([FromBody] UserAccount userAccount)
        {
            // Validate user account input
            if (userAccount == null || string.IsNullOrEmpty(userAccount.Username) || string.IsNullOrEmpty(userAccount.Password))
                return BadRequest();

            // Check username availability and password strength
            var usernameAvailable = await _userAccountService.CheckUsernameAvailabilityAsync(userAccount.Username);
            if (!usernameAvailable)
                return Conflict();
            var passwordStrength = await _userAccountService.CheckPasswordStrengthAsync(userAccount.Password);
            if (passwordStrength < PasswordStrength.Medium)
                return BadRequest("Invalid password");

            // Create user account
            var createdUserAccount = await _userAccountService.CreateUserAccountAsync(userAccount);
            if (createdUserAccount == null)
                return StatusCode(500, "Failed to create user account");

            // Return newly created account
            return Ok(createdUserAccount);
        }

        [HttpPut("{id}")]
        public async Task<IActionResult> UpdateUserAccount([FromRoute] int id, [FromBody] UserAccount updatedUserAccount)
        {
            // Validate user account input
            if (updatedUserAccount == null || string.IsNullOrEmpty(updatedUserAccount.Username))
                return BadRequest();

            // Check username availability and password strength
            var usernameAvailable = await _userAccountService.CheckUsernameAvailabilityAsync(updatedUserAccount.Username);
            if (!usernameAvailable)
                return Conflict();
            var passwordStrength = await _userAccountService.CheckPasswordStrengthAsync(updatedUserAccount.Password);
            if (passwordStrength < PasswordStrength.Medium)
                return BadRequest("Invalid password");

            // Update user account
            var updatedUserAccounts = await _userAccountService.UpdateUserAccountAsync(id, updatedUserAccount);
            if (updatedUserAccounts == null || !updatedUserAccounts.Any())
                return NotFound();

            // Return updated account
            return Ok(updatedUserAccounts.First());
        }

        [HttpDelete("{id}")]
        public async Task<IActionResult> DeleteUserAccount([FromRoute] int id)
        {
            // Validate user account ID
            if (id < 0)
                return BadRequest();

            // Check if user account exists
            var deletedUserAccounts = await _userAccountService.DeleteUserAccountAsync(id);
            if (deletedUserAccounts == null || !deletedUserAccounts.Any())
                return NotFound();

            // Return deleted account
            return Ok(deletedUserAccounts.First());
        }
    }
}
