#include <stdbool.h>

typedef struct {
    int value;
    char* string;
    bool valid;
} Record;

Record* allocate_records(int num_records, size_t max_length) {
    // Calculate the required memory for the records and buffers
    size_t record_size = sizeof(Record);
    size_t buffer_size = max_length + 1; // +1 for null terminator
    size_t total_memory = num_records * (record_size + buffer_size);

    // Allocate the memory using a fixed-size pool allocator
    void* memory = malloc(total_memory);
    if (!memory) {
        return NULL;
    }

    // Initialize the records and buffers in the allocated memory
    Record* records = (Record*)memory;
    char* buffers = (char*)((uint8_t*)records + num_records * record_size);
    for (int i = 0; i < num_records; i++) {
        // Initialize the record value and valid flag
        records[i].value = 0;
        records[i].valid = false;

        // Allocate a buffer for the string representation of the integer value
        char* buffer = buffers + (buffer_size * i);
        size_t length = snprintf(buffer, max_length, "%d", records[i].value);
        if (length < max_length) {
            // Update the buffer length and set the valid flag to true
            records[i].string = buffer;
            records[i].valid = true;
        } else {
            // Set the valid flag to false and free the buffer
            records[i].string = NULL;
            free(buffer);
        }
    }

    return records;
}

void validate_record(Record* record) {
    // Check if the record's integer value is within a valid range
    if (record->value < 0 || record->value > 10000) {
        record->valid = false;
    } else {
        // Check if the string representation of the integer value matches the actual value
        int actual_value = atoi(record->string);
        if (actual_value != record->value) {
            record->valid = false;
        }
    }
}

Record* insert_record(Record* records, size_t num_records, Record new_record) {
    // Validate the new record's integrity before inserting it
    validate_record(&new_record);
    if (!new_record.valid) {
        return NULL;
    }

    // Find an empty slot in the array for the new record
    int index = 0;
    while (index < num_records && records[index].valid) {
        index++;
    }

    if (index == num_records) {
        return NULL;
    }

    // Copy the new record into the array and update its string representation
    records[index] = new_record;
    size_t length = snprintf(records[index].string, max_length, "%d", records[index].value);
    if (length < max_length) {
        // Update the buffer length and set the valid flag to true
        records[index].valid = true;
    } else {
        // Set the valid flag to false and free the buffer
        records[index].string = NULL;
        free(records[index].string);
        records[index].valid = false;
    }

    return &records[index];
}
