["Here is an example C function that dynamically allocates memory for a variable number of 'record' structures, each containing an 'int' value, a 'char' buffer of a fixed size, and a pointer to an external data source for dynamic content:
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>

// Define the structure for the record
typedef struct {
    int value;
    char buffer[10];
    void *external_data;
} Record;

// Define a hash table to store the records
struct HashTable {
    int size;
    int count;
    Record **records;
};

// Function to generate a random integer value within a specified range
int rand_range(int min, int max) {
    return min + (rand() % (max - min));
}

// Function to initialize the hash table with a certain number of records
void init_hash_table(struct HashTable *ht, int num_records) {
    ht->size = num_records;
    ht->count = 0;
    ht->records = malloc(num_records * sizeof(Record));
}

// Function to add a new record to the hash table
void add_record(struct HashTable *ht, int value, char *buffer, void *external_data) {
    // Generate a random integer value within the specified range
    int rand_val = rand_range(value - 50, value + 50);

    // Create a new record with the random integer value and buffer
    Record *new_record = malloc(sizeof(Record));
    new_record->value = rand_val;
    strncpy(new_record->buffer, buffer, sizeof(new_record->buffer) - 1);
    new_record->external_data = external_data;

    // Add the record to the hash table
    ht->records[ht->count++] = new_record;
}

// Function to retrieve a record from the hash table based on its integer value
Record *get_record(struct HashTable *ht, int value) {
    for (int i = 0; i < ht->count; i++) {
        if (ht->records[i]->value == value) {
            return ht->records[i];
        }
    }

    // If no record with the specified integer value is found, return NULL
    return NULL;
}

// Function to update a record in the hash table based on its integer value
void update_record(struct HashTable *ht, int value, char *buffer) {
    Record *record = get_record(ht, value);

    // If no record with the specified integer value is found, return
    if (record == NULL) {
        return;
    }

    // Update the record's buffer with the new data
    strncpy(record->buffer, buffer, sizeof(record->buffer) - 1);
}

// Function to free the memory used by the hash table and its records
void free_hash_table(struct HashTable *ht) {
    for (int i = 0; i < ht->count; i++) {
        free(ht->records[i]);
    }
    free(ht->records);
}
```
This function uses a hash table to store the records, which allows for efficient lookups and updates. The `add_record` function generates a random integer value within a specified range and creates a new record with that value. It also copies the buffer and external data pointer into the record. The `get_record` function retrieves a record from the hash table based on its integer value. The `update_record` function updates a record in the hash table by copying the new data into the record's buffer. Finally, the `free_hash_table` function frees the memory used by the hash table and its records.

Note that this is just an example implementation and may need to be modified based on specific requirements. For instance, it is not necessary to use a hash table for storage, but it can provide good performance for lookups and updates. It is also important to handle potential out-of-memory conditions and other resource management issues appropriately."]

