/* C function for initializing and populating an array of UEContext structures */
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "ue_context.h"

/* Define a custom synchronization mechanism to handle contention during bulk updates to the context array */
void* ue_context_lock = NULL;
int ue_context_size = 0; /* Size of the UEContext array */
UEContext** ue_contexts = NULL; /* Array of UEContext structures */

/* Define a custom logging system that allows for different logging levels and destinations, including file-based logs, console output, and remote logging services */
#define LOG_LEVEL_ERROR 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_INFO 3
#define LOG_LEVEL_DEBUG 4
#define LOG_DESTINATION_FILE 1
#define LOG_DESTINATION_CONSOLE 2
#define LOG_DESTINATION_REMOTE 3
int log_level = LOG_LEVEL_ERROR; /* Current logging level */
int log_destination = LOG_DESTINATION_FILE; /* Current logging destination */
char* log_filepath = NULL; /* File path for file-based logs */

/* Define a performance monitoring system that tracks the number of successful and failed message encodings per second, along with average encoding times */
#define MESSAGE_ENCODING_SUCCESS 1
#define MESSAGE_ENCODING_FAILURE 2
struct perf_monitor {
    unsigned int num_encodings; /* Total number of message encodings */
    unsigned long long total_encoding_time; /* Total encoding time in nanoseconds */
    struct timespec start_time; /* Start time for measuring encoding duration */
};
struct perf_monitor* perf_monitor = NULL; /* Performance monitor structure */

/* Initialize the UEContext array with a given size and populate it with valid RRC_Connection_Reconfiguration messages and NAS_Messages */
int ue_context_init(int size, int msg_size) {
    if (ue_context_lock == NULL) {
        /* Create a lock for synchronizing access to the UEContext array */
        pthread_mutexattr_t attr;
        pthread_mutexattr_init(&attr);
        pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
        pthread_mutex_init(&ue_context_lock, &attr);
    }

    if (size <= 0) {
        /* Set the default UEContext size if not specified */
        size = 16;
    }

    ue_context_size = size;
    ue_contexts = calloc(ue_context_size, sizeof(UEContext*));
    if (ue_contexts == NULL) {
        log_error("Failed to allocate memory for UEContext array");
        return -1;
    }

    /* Initialize each UEContext structure with a valid RRC_Connection_Reconfiguration message and NAS_Message */
    int i;
    for (i = 0; i < ue_context_size; i++) {
        UEContext* context = calloc(1, sizeof(UEContext));
        if (context == NULL) {
            log_error("Failed to allocate memory for UEContext structure");
            return -1;
        }
        /* Populate the RRC_Connection_Reconfiguration message and NAS_Message fields */
        context->rrc_reconf = calloc(1, sizeof(RRC_Connection_Reconfiguration));
        if (context->rrc_reconf == NULL) {
            log_error("Failed to allocate memory for RRC_Connection_Reconfiguration message");
            return -1;
        }
        context->nas_msg = calloc(1, msg_size);
        if (context->nas_msg == NULL) {
            log_error("Failed to allocate memory for NAS_Message buffer");
            return -1;
        }
        /* Validate the NAS_Message against a predefined schema and store it in a dynamically allocated buffer */
        int nas_msg_size = encode_nas_message(context->nas_msg, msg_size);
        if (nas_msg_size < 0) {
            log_error("Failed to validate NAS_Message against schema");
            return -1;
        }
        /* Update the UEContext structure with the validated NAS_Message */
        context->nas_msg_size = nas_msg_size;
        ue_contexts[i] = context;
    }

    return 0;
}

/* Destroy the UEContext array and release all allocated memory */
void ue_context_destroy() {
    if (ue_contexts != NULL) {
        int i;
        for (i = 0; i < ue_context_size; i++) {
            free(ue_contexts[i]);
        }
        free(ue_contexts);
    }
}

/* Add a new UEContext structure to the array and return its index */
int ue_context_add() {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    /* If the maximum number of contexts has been reached, return -1 */
    if (ue_context_size == MAX_UE_CONTEXT_SIZE) {
        log_warning("Maximum number of UEContext structures reached");
        pthread_mutex_unlock(&ue_context_lock);
        return -1;
    }

    /* Allocate a new UEContext structure and initialize its fields */
    int index = ue_context_size++;
    UEContext* context = calloc(1, sizeof(UEContext));
    if (context == NULL) {
        log_error("Failed to allocate memory for new UEContext structure");
        return -1;
    }
    /* Initialize the RRC_Connection_Reconfiguration message and NAS_Message fields */
    context->rrc_reconf = calloc(1, sizeof(RRC_Connection_Reconfiguration));
    if (context->rrc_reconf == NULL) {
        log_error("Failed to allocate memory for new RRC_Connection_Reconfiguration message");
        return -1;
    }
    context->nas_msg = calloc(1, NAS_MESSAGE_SIZE);
    if (context->nas_msg == NULL) {
        log_error("Failed to allocate memory for new NAS_Message buffer");
        return -1;
    }
    /* Validate the NAS_Message against a predefined schema and store it in a dynamically allocated buffer */
    int nas_msg_size = encode_nas_message(context->nas_msg, NAS_MESSAGE_SIZE);
    if (nas_msg_size < 0) {
        log_error("Failed to validate new NAS_Message against schema");
        return -1;
    }
    /* Update the UEContext structure with the validated NAS_Message */
    context->nas_msg_size = nas_msg_size;
    ue_contexts[index] = context;

    pthread_mutex_unlock(&ue_context_lock);
    return index;
}

/* Remove a UEContext structure from the array by its index */
void ue_context_remove(int index) {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    if (index >= 0 && index < ue_context_size) {
        free(ue_contexts[index]);
        memmove(&ue_contexts[index], &ue_contexts[index + 1], sizeof(UEContext*) * (ue_context_size - index - 1));
        ue_context_size--;
    } else {
        log_error("Invalid UEContext index");
    }

    pthread_mutex_unlock(&ue_context_lock);
}

/* Update the NAS_Message field of a given UEContext structure and validate it against a predefined schema */
int ue_context_update(int index, char* nas_msg, int msg_size) {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    if (index >= 0 && index < ue_context_size) {
        /* Free the existing NAS_Message buffer and allocate a new one with the updated size */
        free(ue_contexts[index]->nas_msg);
        int nas_msg_size = encode_nas_message(nas_msg, msg_size);
        if (nas_msg_size < 0) {
            log_error("Failed to validate updated NAS_Message against schema");
            return -1;
        }
        ue_contexts[index]->nas_msg = calloc(1, nas_msg_size);
        if (ue_contexts[index]->nas_msg == NULL) {
            log_error("Failed to allocate memory for updated NAS_Message buffer");
            return -1;
        }
        memcpy(ue_contexts[index]->nas_msg, nas_msg, nas_msg_size);
    } else {
        log_error("Invalid UEContext index");
        return -1;
    }

    pthread_mutex_unlock(&ue_context_lock);
    return 0;
}

/* Monitor the health of the data structure and report on various metrics, such as number of active contexts, average size of NAS_Message buffers, and peak memory usage over the last 10 seconds */
void ue_context_monitor() {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    int num_active_contexts = 0;
    int avg_nas_msg_size = 0;
    unsigned long peak_memory_usage = 0;
    /* Iterate over each UEContext structure and calculate metrics */
    for (int i = 0; i < ue_context_size; i++) {
        if (ue_contexts[i] != NULL) {
            num_active_contexts++;
            avg_nas_msg_size += ue_contexts[i]->nas_msg_size;
            unsigned long memory_usage = (unsigned long)(sizeof(UEContext*) + sizeof(RRC_Connection_Reconfiguration) + ue_contexts[i]->nas_msg_size);
            peak_memory_usage = max(peak_memory_usage, memory_usage);
        }
    }
    /* Report on the various metrics */
    log_info("Num active contexts: %d", num_active_contexts);
    log_info("Avg NAS Message size: %.2f KiB", (float)avg_nas_msg_size / 1024.0f);
    log_info("Peak memory usage: %.2f KiB", (float)peak_memory_usage / 1024.0f);

    pthread_mutex_unlock(&ue_context_lock);
}

/* Gracefully shut down the data structure and release all allocated resources */
void ue_context_shutdown() {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    /* Free all allocated memory for the UEContext structures */
    if (ue_contexts != NULL) {
        int i;
        for (i = 0; i < ue_context_size; i++) {
            free(ue_contexts[i]);
        }
        free(ue_contexts);
    }
    /* Release the lock */
    pthread_mutex_unlock(&ue_context_lock);
}

/* Scale the size of the UEContext array based on real-time traffic patterns, adjusting up to a maximum limit specified at compile-time and configurable at runtime */
void ue_context_scale(int new_size) {
    /* Acquire the lock for synchronizing access to the UEContext array */
    pthread_mutex_lock(&ue_context_lock);

    if (new_size > MAX_UE_CONTEXT_SIZE) {
        log_warning("Maximum number of UEContext structures reached");
        pthread_mutex_unlock(&ue_context_lock);
        return;
    }

    /* Reallocate the array with a new size */
    int i;
    for (i = 0; i < ue_context_size; i++) {
        UEContext* context = ue_contexts[i];
        if (context != NULL) {
            free(context->rrc_reconf);
            free(context->nas_msg);
            free(context);
        }
    }
    free(ue_contexts);
    ue_context_size = new_size;
    ue_contexts = calloc(ue_context_size, sizeof(UEContext*));
    if (ue_contexts == NULL) {
        log_error("Failed to allocate memory for UEContext array with new size");
        return;
    }

    /* Initialize each new UEContext structure with a valid RRC_Connection_Reconfiguration message and NAS_Message */
    for (i = 0; i < ue_context_size; i++) {
