// Define the structure of a UE Context
typedef struct {
    int ue_id;
    struct rrc_ue_s1ap_ids *rrc_ue_s1ap_ids;
    struct traffic_channel_status_report_list *traffic_channel_status_reports;
} ue_context;

// Define a dynamic array of UE Context structures
typedef struct {
    int capacity;
    int size;
    ue_context **array;
} ue_context_array;

// Initialize the dynamic array with a given capacity
void ue_context_array_init(ue_context_array *ua, int capacity) {
    ua->capacity = capacity;
    ua->size = 0;
    ua->array = (ue_context **)malloc(sizeof(ue_context *) * capacity);
}

// Add a new UE Context to the dynamic array
void ue_context_array_add(ue_context_array *ua, int ue_id, struct rrc_ue_s1ap_ids *rrc_ue_s1ap_ids, struct traffic_channel_status_report_list *traffic_channel_status_reports) {
    if (ua->size == ua->capacity) {
        int new_capacity = ua->capacity * 2;
        ua->array = realloc(ua->array, sizeof(ue_context *) * new_capacity);
        ua->capacity = new_capacity;
    }
    ue_context *uc = (ue_context *)malloc(sizeof(ue_context));
    uc->ue_id = ue_id;
    uc->rrc_ue_s1ap_ids = rrc_ue_s1ap_ids;
    uc->traffic_channel_status_reports = traffic_channel_status_reports;
    ua->array[ua->size] = uc;
    ua->size++;
}

// Find a UE Context in the dynamic array by its unique ID
ue_context *ue_context_array_find(ue_context_array *ua, int ue_id) {
    for (int i = 0; i < ua->size; i++) {
        if (ua->array[i]->ue_id == ue_id) {
            return ua->array[i];
        }
    }
    return NULL;
}

// Remove a UE Context from the dynamic array by its unique ID
void ue_context_array_remove(ue_context_array *ua, int ue_id) {
    for (int i = 0; i < ua->size; i++) {
        if (ua->array[i]->ue_id == ue_id) {
            free(ua->array[i]);
            ua->size--;
            break;
        }
    }
}

// Update a UE Context in the dynamic array with new radio resources and traffic channel status reports
void ue_context_array_update(ue_context_array *ua, int ue_id, struct rrc_ue_s1ap_ids *rrc_ue_s1ap_ids, struct traffic_channel_status_report_list *traffic_channel_status_reports) {
    ue_context *uc = ue_context_array_find(ua, ue_id);
    if (uc != NULL) {
        uc->rrc_ue_s1ap_ids = rrc_ue_s1ap_ids;
        uc->traffic_channel_status_reports = traffic_channel_status_reports;
    } else {
        printf("Error: Could not find UE context with ID %d\n", ue_id);
    }
}

// Thread-safe access to the dynamic array using semaphores and mutex locks
semaphore g_mutex;
int g_lock_count = 0;
void ue_context_array_lock(ue_context_array *ua) {
    if (g_lock_count++ == 0) {
        semaphore_wait(&g_mutex);
    }
}

void ue_context_array_unlock(ue_context_array *ua) {
    if (--g_lock_count == 0) {
        semaphore_post(&g_mutex);
    }
}
