void modifyAndInitializeRecords(const char* filename, int minValue, size_t recordsCount) {
    // Determine the number of digits in the current extension and file type
    int numDigits = strlen(filename) - 1;
    while (numDigits > 0 && !isdigit(filename[numDigits])) {
        --numDigits;
    }

    // Modify the filename by appending a new extension that includes a specified number of digits and a new file type
    char newFilename[strlen(filename) + numDigits + 5];
    sprintf(newFilename, "%s.%0*d.txt", filename, numDigits, recordsCount);

    // Allocate memory for the array of record structures and initialize each record's value to a random integer within the range defined by minValue and maxValue
    struct record* records = malloc(recordsCount * sizeof(struct record));
    int long offsets[recordsCount];
    int keys[recordsCount];
    for (size_t i = 0; i < recordsCount; ++i) {
        // Generate a random integer within the range defined by minValue and maxValue using a modulo operation and an addition
        int randomValue = (int)(minValue + (double)(rand() % (maxValue - minValue)));
        records[i].value = randomValue;
        offsets[i] = i * sizeof(int);
        keys[i] = randomValue;
    }

    // Free allocated memory when no longer needed
    free(records);
    free(offsets);
    free(keys);
}
