    for (int i = 0; i < nfapiPDUStructs.size(); i++) {
        nfapiPDUStructs[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_dist(gen);
        nfapiPDUStructs[i].RNTI = RNTI_dist(gen);
        nfapiPDUStructs[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG_dist(gen);
        nfapiPDUStructs[i].CRCFLAG = CRCFLAG_dist(gen);
    }

    // Check for consecutive selections within the cooldown period
    uint16_t lastAttack = 0;
    for (int i = 0; i < nfapiPDUStructs.size(); i++) {
        if (lastAttack == nfapiPDUStructs[i].RX_UE_INFORMATION_TAG) {
            // Cooldown period has been reached, select a new attack
            lastAttack = 0;
            cout << "New attack selected: " << i + 1 << endl;
        } else {
            // Update the last attack selection
            lastAttack = nfapiPDUStructs[i].RX_UE_INFORMATION_TAG;
        }
    }

    return nfapiPDUStructs;
}
