            return;
        }
    }
}

// Function to handle concurrent access to shared resources safely, minimizing contention and ensuring thread safety
void handle_concurrent_access(Record *records, int num_records) {
    // Use a mutex to synchronize access to the shared record array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_records; i++) {
        if (!pthread_mutex_lock(&mutex)) {
            // Critical section: access the shared record array
            records[i].status = 'V'; // Validated status
