    if (!head) {
        printf("Error: Unable to allocate memory for MAC RX list\n");
        exit(1);
    }
}

void add_mac_rx_context(uint32_t layer2_id, void* rrc_conversion_context, uint32_t mac_rx_data) {
    // Allocate memory for the new MAC RX context structure
    MAC_RX_CONTEXT* new_context = (MAC_RX_CONTEXT*) malloc(sizeof(MAC_RX_CONTEXT));
    if (!new_context) {
        printf("Error: Unable to allocate memory for new MAC RX context\n");
        exit(1);
    }

    // Initialize the new MAC RX context structure
    new_context->layer2_id = layer2_id;
    new_context->rrc_conversion_context = rrc_conversion_context;
    new_context->mac_rx_data[0] = mac_rx_data;

    // Add the new MAC RX context structure to the linked list
    ListNode* current_node = head;
    while (current_node->next) {
        if (current_node->context->layer2_id == layer2_id) {
            printf("Error: Duplicate MAC RX context detected for Layer 2 ID %d\n", layer2_id);
            exit(1);
        }
        current_node = current_node->next;
    }
    current_node->next = (ListNode*) malloc(sizeof(ListNode));
    if (!current_node->next) {
        printf("Error: Unable to allocate memory for new MAC RX list node\n");
        exit(1);
    }
    current_node->next->context = new_context;
}

void remove_mac_rx_context(uint32_t layer2_id) {
    // Find the MAC RX context structure with the specified Layer 2 ID
    ListNode* current_node = head;
    while (current_node->next && current_node->next->context->layer2_id != layer2_id) {
        current_node = current_node->next;
    }
    if (!current_node->next) {
        printf("Error: Unable to find MAC RX context for Layer 2 ID %d\n", layer2_id);
        exit(1);
    }

    // Remove the MAC RX context structure from the linked list
    ListNode* node_to_remove = current_node->next;
    current_node->next = current_node->next->next;
    free(node_to_remove);
}

void clear_mac_rx_list() {
    // Free all nodes in the linked list
    while (head) {
        ListNode* node_to_free = head;
        head = head->next;
        free(node_to_free);
    }
}
