#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

// Define structure for holding CRC indication information
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array for holding the CRC indication structures
typedef struct {
    int size; // current number of elements in the array
    int capacity; // total number of elements that can be stored in the array
    NFAPI_CRC_INDICATION_PDU_T* elements; // pointer to the first element in the array
} DYNAMIC_ARRAY;

// Define a semaphore for controlling access to the dynamic array
sem_t mutex;

void init_dynamic_array(DYNAMIC_ARRAY* arr) {
    // Initialize the capacity and size of the dynamic array to zero
    arr->capacity = 0;
    arr->size = 0;
    // Allocate memory for the first element in the array
    arr->elements = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_dynamic_array(DYNAMIC_ARRAY* arr) {
    // Free the memory allocated for the elements in the array
    free(arr->elements);
    // Reset the capacity and size of the dynamic array to zero
    arr->capacity = 0;
    arr->size = 0;
}

void add_element_to_dynamic_array(DYNAMIC_ARRAY* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    // Check if the array is full
    if (arr->capacity == arr->size) {
        // Double the capacity of the array if it is full
        arr->capacity *= 2;
        // Reallocate memory for the elements in the array
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(arr->elements, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Check if memory allocation failed
        if (!new_elements) {
            perror("Memory allocation failed");
            exit(1);
        } else {
            // Update the pointer to the first element in the array
            arr->elements = new_elements;
        }
    }
    // Add the new element to the end of the array
    arr->elements[arr->size++] = element;
}

void remove_element_from_dynamic_array(DYNAMIC_ARRAY* arr, int index) {
    // Check if the index is valid
    if (index < 0 || index >= arr->size) {
        printf("Invalid index specified");
        return;
    }
    // Shift all elements after the specified index one position to the left
    for (int i = index + 1; i < arr->size; i++) {
        arr->elements[i - 1] = arr->elements[i];
    }
    // Decrement the size of the array by one
    arr->size--;
}

void check_duplicate_rnti(DYNAMIC_ARRAY* arr, int rnti) {
    // Check if the specified RNTI already exists in the array
    for (int i = 0; i < arr->size; i++) {
        if (arr->elements[i].rnti == rnti) {
            printf("Duplicate RNTI detected");
            return;
        }
    }
}

void manage_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu) {
    // Initialize a dynamic array for holding the CRC indication structures
    DYNAMIC_ARRAY arr;
    init_dynamic_array(&arr);

