// Define data structure for dynamic array of UE stats records
struct UEStatsArray {
  struct UEStatsRecord *records;
  size_t capacity;
  size_t count;
};

// Define configuration parameters for the function
#define AGE_THRESHOLD (60 * 60) // 1 hour in seconds
#define MAX_UE_COUNT 1000
#define MIN_MEMORY_ALLOCATION 256 // MB
#define CPU_UTILIZATION 80 // % of available CPU

// Function to manage dynamic array of UE stats records
void manageUEStats(struct UEStatsArray *array) {
  // Define and initialize mutex for thread safety
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

  // Define and initialize condition variable for waiting on data availability
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

  // Define and initialize thread attributes for handling external data sources
  pthread_attr_t attr;
  pthread_attr_init(&attr);
  pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

  // Define and initialize thread array for concurrent data processing
  pthread_t threads[MAX_UE_COUNT];

  // Define and initialize semaphore for limiting memory usage
  sem_t sem;
  sem_init(&sem, 0, MAX_MEMORY_ALLOCATION);

  // Loop indefinitely to manage UE stats records
  while (1) {
    // Acquire mutex to synchronize access to array
    pthread_mutex_lock(&mutex);

    // Check if there are any outdated entries and remove them if necessary
    for (size_t i = 0; i < array->count; ++i) {
      long age = time(NULL) - array->records[i].timestamp;
      if (age > AGE_THRESHOLD) {
        // Remove outdated entry and adjust count accordingly
        free(&array->records[i]);
        --array->count;
        break;
      }
    }

    // Check if there is enough memory available to add a new record
    size_t memory_usage = sem_getvalue(&sem);
    if (memory_usage > MIN_MEMORY_ALLOCATION) {
      // Add new record to array and adjust count accordingly
      ++array->count;
      struct UEStatsRecord *record = malloc(sizeof(*record));
      memset(record, 0, sizeof(*record));
      array->records[array->count - 1] = record;
    }

    // Release mutex to release access to array
    pthread_mutex_unlock(&mutex);

    // Wait on condition variable until new data is available
    pthread_cond_wait(&cond, &mutex);

    // Process new data and update existing records accordingly
    for (size_t i = 0; i < array->count; ++i) {
      struct UEStatsRecord *record = &array->records[i];
      if (record->timestamp == 0) {
        continue;
      }
      long age = time(NULL) - record->timestamp;
      if (age <= AGE_THRESHOLD) {
        // Update uplink and downlink throughput metrics
        double uplink_throughput = calculateUplinkThroughput(record);
        double downlink_throughput = calculateDownlinkThroughput(record);
        record->uplink_throughput = uplink_throughput;
        record->downlink_throughput = downlink_throughput;
      } else {
        // Remove outdated entry and adjust count accordingly
        free(&array->records[i]);
        --array->count;
      }
    }

    // Signal condition variable to wake up any waiting threads
    pthread_cond_signal(&cond);
  }
