    EVP_add_digest(EVP_sha1());
    EVP_add_digest_alias("SHA-1", "SHA");
    EVP_add_digest_alias("RSA-3072", "RSA");

    // Implement a mechanism to securely erase sensitive data from memory
    memset(records, 0, num_records * sizeof(record));

    // Ensure thread safety and consistent behavior across multiple invocations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int max_threads = 4; // adjust as needed
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        while (num_threads > max_threads) {
            pthread_cond_wait(&cond, &mutex);
        }
        // Perform cryptographic operations on the records
        pthread_mutex_unlock(&mutex);
    }

    // Free allocated memory and return
    free(offset_array);
    free(key_array);
    free(records);
}
