// Cache entry structure to store packet metadata and data
typedef struct {
    uint32_t PCI; // Physical Cell ID
    uint16_t PUCCH_INFO; // Uplink Control Channel Information
    uint8_t PHY_RXINFO; // Receive Information
    uint8_t* data; // Packet data
} NFAPI_L1_ENB_PDU_T;

// Cache structure to store cache entries
typedef struct {
    NFAPI_L1_ENB_PDU_T** entries;
    size_t capacity; // Maximum number of cache entries
    size_t count; // Current number of cache entries
} NFAPI_L1_CACHE_T;

// Initialize a new cache with a given capacity
NFAPI_L1_CACHE_T* nfapi_l1_cache_init(size_t capacity) {
    // Allocate memory for the cache entries
    NFAPI_L1_CACHE_T* cache = malloc(sizeof(NFAPI_L1_CACHE_T));
    if (!cache) {
        return NULL;
    }
    cache->entries = calloc(capacity, sizeof(NFAPI_L1_ENB_PDU_T*));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }
    cache->count = 0;
    cache->capacity = capacity;
    return cache;
}

// Add a new cache entry for a given packet
int nfapi_l1_cache_add(NFAPI_L1_CACHE_T* cache, uint32_t PCI, uint16_t PUCCH_INFO, uint8_t PHY_RXINFO, uint8_t* data) {
    if (cache->count == cache->capacity) {
        return -1; // Cache is full
    }
    NFAPI_L1_ENB_PDU_T* entry = malloc(sizeof(NFAPI_L1_ENB_PDU_T));
    if (!entry) {
        return -2; // Memory allocation failed
    }
    entry->PCI = PCI;
    entry->PUCCH_INFO = PUCCH_INFO;
    entry->PHY_RXINFO = PHY_RXINFO;
    entry->data = data;
    cache->entries[cache->count++] = entry;
    return 0; // Success
}

// Update an existing cache entry for a given packet
int nfapi_l1_cache_update(NFAPI_L1_CACHE_T* cache, uint32_t PCI, uint16_t PUCCH_INFO, uint8_t PHY_RXINFO) {
    for (size_t i = 0; i < cache->count; i++) {
        NFAPI_L1_ENB_PDU_T* entry = cache->entries[i];
        if (entry->PCI == PCI && entry->PUCCH_INFO == PUCCH_INFO && entry->PHY_RXINFO == PHY_RXINFO) {
            // Update the cache entry with new data
            return 0;
        }
    }
    return -1; // Cache entry not found
}

// Retrieve a cache entry for a given packet
NFAPI_L1_ENB_PDU_T* nfapi_l1_cache_get(NFAPI_L1_CACHE_T* cache, uint32_t PCI, uint16_t PUCCH_INFO, uint8_t PHY_RXINFO) {
    for (size_t i = 0; i < cache->count; i++) {
        NFAPI_L1_ENB_PDU_T* entry = cache->entries[i];
        if (entry->PCI == PCI && entry->PUCCH_INFO == PUCCH_INFO && entry->PHY_RXINFO == PHY_RXINFO) {
            return entry;
        }
    }
    return NULL; // Cache entry not found
}

// Clear the cache entries
void nfapi_l1_cache_clear(NFAPI_L1_CACHE_T* cache) {
    for (size_t i = 0; i < cache->count; i++) {
        NFAPI_L1_ENB_PDU_T* entry = cache->entries[i];
        free(entry);
    }
    free(cache->entries);
}
