// C function for dynamically reading a list of integers from standard input
int read_integers(char *filename, int **array) {
    // Open file for reading
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    // Allocate memory for the integer array
    int size = 10; // initial size of the array
    *array = (int *)malloc(size * sizeof(int));
    if (!*array) {
        fclose(file);
        return 0;
    }

    // Read integers from file and store in array
    int i = 0;
    while (fscanf(file, "%d", &(*array)[i]) == 1) {
        if (i >= size - 1) {
            size *= 2; // double the size of the array
            *array = (int *)realloc(*array, size * sizeof(int));
            if (!*array) {
                fclose(file);
                return 0;
            }
        }
        i++;
    }

    // Close file and return number of integers read
    fclose(file);
    return i;
}

