    pthread_mutex_lock(&ue_contexts_mutex);

    // Allocate memory for NAS message content
    int nas_message_length = strlen(NAS_Message);
    char *nas_message_content = (char *)malloc(nas_message_length + 1);
    if (!nas_message_content) {
