struct record* create_records(int num_records, long offset_min, long offset_max, int key_min, int key_max, float data_min, float data_max) {
    // Allocate memory for the array of records
    struct record** records = malloc(num_records * sizeof(struct record*));
    if (records == NULL) {
        perror("malloc");
        return NULL;
    }

    // Initialize each record with a random offset, key, and data value within specified ranges
    for (int i = 0; i < num_records; i++) {
        struct record* record = malloc(sizeof(struct record));
        if (record == NULL) {
            perror("malloc");
            free(records);
            return NULL;
        }

        // Generate a random offset within the specified range
        long offset = (long)(offset_min + ((double)rand() / RAND_MAX) * (offset_max - offset_min));
        record->offset = offset;

        // Generate a random key within the specified range
        int key = (int)(key_min + ((double)rand() / RAND_MAX) * (key_max - key_min));
        record->key = key;

        // Generate a random data value within the specified range
        float data = (float)(data_min + ((double)rand() / RAND_MAX) * (data_max - data_min));
        record->data = data;

        records[i] = record;
    }

    return records;
}
