    }

    // Allocate memory for the string buffer for each record, ensuring that the allocation size is sufficient for the string plus the null terminator
    char** string_buffers = (char**)malloc(num_records * sizeof(char*));
    for (int i = 0; i < num_records; i++) {
        string_buffers[i] = (char*)malloc((100 + 1) * sizeof(char)); // +1 for the null terminator
