function resizeArray(array, initialCapacity) {
  // Calculate the current capacity of the array
  let capacity = Math.max(initialCapacity, array.length);

  // Create a new array with double the current capacity
  const newArray = new Array(capacity * 2);

  // Copy the elements from the old array to the new one
