// Define the structure for storing RRC_Connection_Reconfiguration messages and NAS_Messages
typedef struct UEContext {
    RRC_Connection_Reconfiguration *rrc;
    NAS_Message *nas;
} UEContext;

// Define a dynamic array of UEContext structures
UEContext* ue_contexts = NULL;
size_t num_ue_contexts = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // mutex for synchronizing access to the array

// Initialize the UE contexts with a given capacity
void initialize_ue_contexts(size_t capacity) {
    // Allocate memory for the dynamic array
    ue_contexts = (UEContext*) malloc(sizeof(UEContext) * capacity);
    if (!ue_contexts) {
        perror("malloc");
        exit(1);
    }
    num_ue_contexts = 0;
}

// Add a new UE context to the array, allocating memory for its RRC and NAS messages
void add_ue_context(RRC_Connection_Reconfiguration *rrc, NAS_Message *nas) {
    // Acquire the lock before modifying the array
    pthread_mutex_lock(&lock);
    // Check if we need to resize the array
    if (num_ue_contexts == capacity) {
        // Resize the array by 50%
        size_t new_capacity = capacity * 1.5;
        UEContext* new_array = (UEContext*) realloc(ue_contexts, sizeof(UEContext) * new_capacity);
        if (!new_array) {
            perror("realloc");
            exit(1);
        }
        ue_contexts = new_array;
        capacity = new_capacity;
    }
    // Add the new UE context to the array
    UEContext *ue_context = &ue_contexts[num_ue_contexts++];
    ue_context->rrc = rrc;
    ue_context->nas = nas;
    pthread_mutex_unlock(&lock); // release the lock
}

// Clear all allocated resources when the function completes
void clear_ue_contexts() {
    // Acquire the lock before modifying the array
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_ue_contexts; ++i) {
        UEContext *ue_context = &ue_contexts[i];
        free(ue_context->rrc);
        free(ue_context->nas);
    }
    free(ue_contexts);
    pthread_mutex_unlock(&lock); // release the lock
}
