// Define the data structure for holding the record information
typedef struct {
    int offset;
    char* key;
    char* string_buffer;
    int integer_value;
} Record;

// Define the function that will initialize the data structures
void initializeDataStructures(int num_records, int offset_range, int step_size, char** format_strings, int seed) {
    // Allocate memory for the offset and key arrays
    int* offsets = (int*)malloc(num_records * sizeof(int));
    char** keys = (char**)malloc(num_records * sizeof(char*));

    // Initialize the offsets and keys with values derived from the specified range and step size
    for (int i = 0; i < num_records; i++) {
        offsets[i] = offset_range + (step_size * i);
        keys[i] = (char*)malloc(100);
    }

    // Allocate memory for the string buffers to store null-terminated strings with a maximum length of 100 characters
    char** string_buffers = (char**)malloc(num_records * sizeof(char*));
    for (int i = 0; i < num_records; i++) {
        string_buffers[i] = (char*)malloc(100);
    }

    // Populate each string buffer with a unique string generated based on the record index and the provided format strings, using the provided seed for consistent randomness across runs
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        int random_index = rand() % (sizeof(format_strings) / sizeof(*format_strings));
        char* format_string = format_strings[random_index];

        snprintf(string_buffers[i], 100, format_string, i);
    }

    // Assign a random integer value within the specified range to each record
    int rand_max = offset_range + (step_size * num_records) - 1;
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % rand_max;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Populate the record array with the initialized data structures
    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].string_buffer = string_buffers[i];
        records[i].integer_value = rand() % (rand_max - offsets[i]) + 1;
    }

    // Free the allocated memory for the offset and key arrays
    free(offsets);
    free(keys);

    // Return the record array
    return records;
}
```
