    int *keys = malloc(num_records * sizeof(int));
    struct record *values = malloc(num_records * sizeof(struct record));

    if (!offsets || !keys || !values) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Exiting.\n");
        return -1;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the arrays in parallel using multiple threads, ensuring thread safety
    size_t num_threads = 4; // Number of threads to use for initialization
    size_t chunk_size = num_records / num_threads;
    pthread_t threads[num_threads];
    struct init_args {
        size_t start, end;
        long *offsets;
        int *keys;
        struct record *values;
        pthread_mutex_t *mutex;
    } args[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        args[i].start = chunk_size * i;
        args[i].end = (i == num_threads - 1) ? num_records : (chunk_size * (i + 1));
        args[i].offsets = offsets;
        args[i].keys = keys;
        args[i].values = values;
        args[i].mutex = &mutex;
    }

    // Initialize the arrays in parallel using multiple threads, ensuring thread safety
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, init_record, &args[i]);
    }

    // Wait for all threads to complete initialization
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Validate the generated records against predefined criteria using an external library
    if (!validate_records(num_records, offsets, keys, values)) {
        // Handle record validation failure gracefully
        printf("Record validation failed. Exiting.\n");
        return -1;
    }

    // Integrate the validated records with an external data processing library
    if (!process_records(num_records, offsets, keys, values)) {
        // Handle record processing failure gracefully
        printf("Record processing failed. Exiting.\n");
        return -1;
    }

    // Clean up allocated memory and return
    free(offsets);
    free(keys);
    free(values);
    pthread_mutex_destroy(&mutex);
    return 0;
}

