        return malloc(size);
    }
    void deallocate(void* ptr) {
        free(ptr);
    }
};

// Define a function to process transaction logs and handle errors gracefully
void processTransactionLogs(struct TransactionLog** logArray, size_t numTransactions) {
    // Allocate memory for the payment details arrays in each transaction log entry
    for (size_t i = 0; i < numTransactions; i++) {
        struct TransactionLog* log = logArray[i];
        log->paymentDetails = CustomAllocator.allocate(log->numPaymentDetails * sizeof(struct PaymentDetails));
        if (!log->paymentDetails) {
            perror("Failed to allocate memory for payment details");
            exit(EXIT_FAILURE);
        }
    }

    // Validate and parse the payment details for each transaction log entry
    for (size_t i = 0; i < numTransactions; i++) {
        struct TransactionLog* log = logArray[i];
        for (size_t j = 0; j < log->numPaymentDetails; j++) {
            // Validate the payment method and amount
            if (!validatePaymentMethod(log->paymentDetails[j].paymentMethod)) {
