                exit(EXIT_FAILURE);
            } else if (log->paymentDetails[j].amount <= 0) {
                fprintf(stderr, "Invalid amount for payment details %zu\n", j);
                log->paymentDetails[j].status = FAILED;
            } else {
                log->paymentDetails[j].status = SUCCESS;
            }
        }
    }

    // Optimize memory usage and performance by minimizing allocations and reallocations
    struct TransactionLog* optimizedLogArray = (struct TransactionLog*)malloc(numTransactions * sizeof(struct TransactionLog));
    size_t numOptimizedTransactions = 0;
    for (size_t i = 0; i < numTransactions; i++) {
        struct TransactionLog* log = logArray[i];
        if (log->paymentDetails) {
            // Copy the transaction log entry and payment details arrays to the optimized array
            memcpy(&optimizedLogArray[numOptimizedTransactions], log, sizeof(struct TransactionLog));
            numOptimizedTransactions++;
        }
    }

    // Support concurrent access to the array from multiple threads without unnecessary locking mechanisms
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < numOptimizedTransactions; i++) {
        struct TransactionLog* log = &optimizedLogArray[i];
        // Acquire the lock before accessing the payment details array
        pthread_mutex_lock(&mutex);
        for (size_t j = 0; j < log->numPaymentDetails; j++) {
            // Modify the payment details array without holding a lock
            if (log->paymentDetails[j].status == SUCCESS) {
                // Perform any necessary modifications to the payment details here
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Allow for the dynamic resizing of the array as new transaction log entries are added
    size_t maxSize = numOptimizedTransactions * 2;
    while (numOptimizedTransactions < maxSize) {
        struct TransactionLog* newLogEntry = (struct TransactionLog*)malloc(sizeof(struct TransactionLog));
        // Initialize the new log entry and add it to the optimized array
        memcpy(&optimizedLogArray[numOptimizedTransactions], newLogEntry, sizeof(struct TransactionLog));
        numOptimizedTransactions++;
    }

    // Ensure that the function is robust against race conditions and deadlocks when accessed by multiple threads simultaneously
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < numOptimizedTransactions; i++) {
        struct TransactionLog* log = &optimizedLogArray[i];
        // Acquire the lock before accessing the payment details array
        pthread_mutex_lock(&mutex);
        for (size_t j = 0; j < log->numPaymentDetails; j++) {
            // Modify the payment details array without holding a lock
            if (log->paymentDetails[j].status == SUCCESS) {
                // Perform any necessary modifications to the payment details here
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Provide a mechanism to clear all allocated resources when the function completes, including both the payment details content and the transaction log structures themselves
    for (size_t i = 0; i < numOptimizedTransactions; i++) {
        struct TransactionLog* log = &optimizedLogArray[i];
        if (log->paymentDetails) {
            CustomAllocator.deallocate(log->paymentDetails);
        }
    }
    free(optimizedLogArray);
}

// Define a function to validate the payment method for a single transaction log entry
bool validatePaymentMethod(char* paymentMethod) {
    // Check if the payment method is supported (e.g. credit card, PayPal)
    return strcmp(paymentMethod, "credit_card") == 0 || strcmp(paymentMethod, "paypal") == 0;
}
