#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

typedef struct {
    long offset;
    int key;
} Record;

struct RecordCollection {
    int capacity;
    int size;
    Record* records;
};

RecordCollection* create_collection(int capacity) {
    // Allocate memory for the collection structure and initialize its fields
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    assert(collection != NULL);
    collection->capacity = capacity;
    collection->size = 0;
    collection->records = calloc(capacity, sizeof(Record));
    assert(collection->records != NULL);
    return collection;
}

void initialize_collection(RecordCollection* collection, int range_start, int range_end) {
    // Generate random offsets within the specified range for each record
    srand(time(NULL));
    for (int i = 0; i < collection->capacity; ++i) {
        collection->records[i].offset = rand() % (range_end - range_start + 1) + range_start;
    }
}

void update_record(RecordCollection* collection, int index, int key) {
    // Update the record at the specified index with the given key
    assert(index >= 0 && index < collection->capacity);
    collection->records[index].key = key;
}

int resize_collection(RecordCollection* collection) {
    // Resize the collection if its capacity is exceeded
    int new_capacity = collection->capacity * 2;
    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
    assert(new_records != NULL);
    collection->capacity = new_capacity;
    collection->records = new_records;
}

void serialize_collection(const RecordCollection* collection) {
    // Serialize the collection to a file, one record per line
    FILE* fp = fopen("record_collection.txt", "w");
    assert(fp != NULL);
    for (int i = 0; i < collection->size; ++i) {
        fprintf(fp, "%d %ld\n", collection->records[i].key, collection->records[i].offset);
    }
}

void deserialize_collection(RecordCollection* collection, const char* filename) {
    // Deserialize the collection from a file, one record per line
    FILE* fp = fopen(filename, "r");
    assert(fp != NULL);
    while (!feof(fp)) {
        int key;
        long offset;
        if (fscanf(fp, "%d %ld\n", &key, &offset) == 2) {
            insert_record(collection, key, offset);
        }
    }
}

void destroy_collection(RecordCollection* collection) {
    // Free the memory allocated for the collection
    free(collection->records);
    free(collection);
}

int main() {
    // Test the functions by creating a collection, initializing it, and updating records
    RecordCollection* collection = create_collection(10);
    initialize_collection(collection, 1, 100);
    update_record(collection, 2, 1234);
    serialize_collection(collection);
    destroy_collection(collection);
    return 0;
}']

