    *list = malloc(sizeof(LTE_UESRVCC_MOrvinecation_PDU_T) * 1000);
    if (*list == NULL) {
        printf("Error allocating memory: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    // Read the file and populate the list of UE's S1AP messages
