// Function to validate the source file's integrity before processing to avoid corrupted data
void validate_source_file(const char *file_path) {
    // Open file for reading
    FILE *file = fopen(file_path, "r");

    // Check if file could not be opened
    if (file == NULL) {
        printf("ERROR: Could not open file %s\n", file_path);
        return;
    }

    // Read file line by line and check for validity of each line
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
