        crc_indication_pdus[i].crcflag = rand() % 2;
    }
}

void destroyRecordsWithCRC(int num_records) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        printf("Invalid number of records\n");
        return;
    }

    // Destroy the semaphore for concurrent access to shared resources
    sem_destroy(&semaphore);

    // Free the memory allocated for the arrays
    free(records);
    free(rx_ue_info);
    free(crc_indication_pdus);
}
