    int num_records = 0;
    int offset_min = 0;
    int offset_max = 0;
    int step_size = 0;
    const char* format_string = NULL;
    unsigned seed = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [--help | -c | -o output_file]\n", argv[0]);
            return 1;
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            input_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
            i++;
        }
    }

    // Initialize and store records
    struct records* records = NULL;
    if (input_file != NULL) {
        FILE* file = fopen(input_file, "r");
        if (file == NULL) {
            printf("Error opening input file\n");
            return 1;
        }
        while (!feof(file)) {
            char line[256];
            fgets(line, sizeof(line), file);
            num_records++;
        }
        records = (struct records*)malloc(sizeof(struct records));
        if (records == NULL) {
            printf("Error allocating memory for records\n");
            return 1;
        }
        records->num_records = num_records;
        initializeAndStoreRecords(records, num_records, offset_min, offset_max, step_size, format_string, seed);
    } else {
        // Handle partial data availability by implementing a caching mechanism
        printf("Please provide an input file\n");
        return 1;
    }

    // Print the number of lines in the input file
    printf("Number of lines in input file: %d\n", records->num_records);

    // Clean up and exit
    if (input_file != NULL) {
        fclose(file);
    }
    free(records);
    return 0;
}
