entry_t* init_entries(size_t num_floats, size_t num_idents) {
    // Calculate the total number of nodes needed
    size_t total_nodes = num_floats * num_idents;

    // Allocate memory for the entries array
    entry_t *entries = malloc(total_nodes * sizeof(entry_t));
    if (!entries) {
        perror("Failed to allocate memory for entries");
        exit(EXIT_FAILURE);
    }

    // Initialize each node in the entries array
    for (size_t i = 0; i < total_nodes; ++i) {
        // Allocate memory for the node structure
        entry_t *entry = malloc(sizeof(node_t));
        if (!entry) {
            perror("Failed to allocate memory for node");
            exit(EXIT_FAILURE);
        }

        // Initialize the node fields
        entry->node = malloc(sizeof(node_t));
        entry->node->value = 0.0;
        entry->node->index = 0;

        // Add the node to the entries array
        entries[i] = *entry;
    }

    return entries;
}

// Function to manage memory allocations and deallocations for the entries array
void free_entries(entry_t *entries) {
    if (entries) {
        for (size_t i = 0; i < total_nodes; ++i) {
            // Free the node structure
            free(entries[i].node);

            // Free the entry structure
            free(entries[i]);
        }

        // Free the entries array
        free(entries);
    }
}
