// C function to dynamically allocate an array of sensor structures
sensor* createSensors(int numSensors, int minMeasurement, int maxMeasurement, char** labels, enum states* states) {
    // Allocate memory for the sensor array
    sensor* sensors = (sensor*)malloc(sizeof(sensor) * numSensors);
    if (!sensors) {
        return NULL;
    }

    // Populate the sensor array with random values
    for (int i = 0; i < numSensors; i++) {
        sensors[i].measurement = minMeasurement + rand() % (maxMeasurement - minMeasurement);
        sensors[i].label = labels[rand() % NUM_LABELS]; // randomly select a label from the predefined set
        sensors[i].state = states[rand() % NUM_STATES]; // randomly choose a state
    }

    // Integrate with external data processing library to validate sensor readings against predefined criteria
    validateSensors(sensors, numSensors);

    return sensors;
}

