// Define the memory pool to optimize allocation and reduce fragmentation
typedef struct {
    void *memory;
    size_t size;
} memory_pool_t;

static bool mempool_init(memory_pool_t *mempool, size_t size) {
    mempool->memory = malloc(size);
    if (!mempool->memory) {
        return false;
    }
    mempool->size = size;
    return true;
}

static void mempool_deinit(memory_pool_t *mempool) {
    free(mempool->memory);
}

static bool mempool_alloc(memory_pool_t *mempool, size_t size) {
    if (size > mempool->size) {
        return false;
    }
    void *new_memory = malloc(size);
    if (!new_memory) {
        return false;
    }
    memcpy(new_memory, mempool->memory, size);
    free(mempool->memory);
    mempool->memory = new_memory;
    mempool->size -= size;
    return true;
}

