// Initialize and populate an array of UEContext structures with valid RRC_Connection_Reconfiguration messages and NAS_Message fields. The function should dynamically allocate memory for the NAS_Message content and ensure that all allocated memory is freed upon completion of the function execution.
int initUEContext(UEContext **ue_context, int num_entries) {
    // Check input parameters
    if (ue_context == NULL || num_entries <= 0) {
        return -1;
    }

    // Allocate memory for the UEContext array and set its size to the given number of entries
    *ue_context = (UEContext *)malloc(num_entries * sizeof(**ue_context));
    if (*ue_context == NULL) {
        return -2;
    }
    memset(*ue_context, 0, num_entries * sizeof(**ue_context));
    int i;
    for (i = 0; i < num_entries; ++i) {
        (*ue_context)[i].rrc.message = (char *)malloc(RRC_MESSAGE_SIZE);
        if ((*ue_context)[i].rrc.message == NULL) {
            break;
        }
    }

    // Check for allocation failures and free all allocated memory if any
    if (i < num_entries) {
        while (i >= 0) {
            free((*ue_context)[i].rrc.message);
            --i;
        }
        free(*ue_context);
        *ue_context = NULL;
        return -3;
    }

    // Populate the RRC_Connection_Reconfiguration messages and NAS_Message fields
    for (i = 0; i < num_entries; ++i) {
        (*ue_context)[i].rrc.message[RRC_MESSAGE_SIZE - 1] = '\0';
        (*ue_context)[i].nas.message = (char *)malloc(NAS_MESSAGE_SIZE);
        if ((*ue_context)[i].nas.message == NULL) {
            break;
        }
    }

    // Check for allocation failures and free all allocated memory if any
    if (i < num_entries) {
        while (i >= 0) {
            free((*ue_context)[i].nas.message);
            --i;
        }
        free(*ue_context);
        *ue_context = NULL;
        return -3;
    }

    // Set the number of entries in the array
    (*ue_context)->num_entries = num_entries;

    // Log successful initialization and return the initialized UEContext array
    logInfo("Successfully initialized %d UEContext structures", num_entries);
    return 0;
}
