#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define data structure for storing offset values and keys
typedef struct {
    long *offsets;
    int *keys;
} DataStore;

// Initialize data store with given size
DataStore *initialize_data_store(int num_elems) {
    // Allocate memory for arrays of offsets and keys
    long *offsets = malloc(num_elems * sizeof(long));
    int *keys = malloc(num_elems * sizeof(int));

    // Initialize arrays with given size
    memset(offsets, 0, num_elems * sizeof(long));
    memset(keys, 0, num_elems * sizeof(int));

    // Create data store object
    DataStore *store = malloc(sizeof(DataStore));
    store->offsets = offsets;
    store->keys = keys;

    return store;
}

// Free memory for data store and arrays
void free_data_store(DataStore *store) {
    if (store == NULL) {
        return;
    }

    free(store->offsets);
    free(store->keys);
    free(store);
}

// Update offset value in data store
void update_offset(DataStore *store, long offset) {
    // Check if offset is greater than current highest offset
    if (offset > store->offsets[0]) {
        store->offsets[0] = offset;
    }
}

// Update key value in data store
void update_key(DataStore *store, int key) {
    // Check if key is not already present in store
    for (int i = 1; i < store->num_elems; i++) {
        if (store->keys[i] == key) {
            return;
        }
    }

    // Add key to store
    store->keys[store->num_elems++] = key;
}

// Process input file and update data store
bool process_file(DataStore *store, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return false;
    }

    // Read input file line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Parse offset and key from line
        long offset = strtol(line, NULL, 10);
        int key = strtol(strchr(line, ',') + 1, NULL, 10);

        // Update data store with parsed values
        update_offset(store, offset);
        update_key(store, key);
    }

    fclose(file);
    return true;
}

// Process multiple input files concurrently and update data store atomically
bool process_files(DataStore *store, const char **filenames, int num_files) {
    // Create array of pthreads for processing each file
    pthread_t threads[num_files];

    // Initialize data store with given size
    DataStore *local_store = initialize_data_store(store->num_elems);

    // Iterate over each file and create thread to process it
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, local_store);
    }

    // Join all threads and update data store atomically
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        update_data_store(local_store, store);
    }

    return true;
}

// Update data store with local copy and synchronize threads
void update_data_store(DataStore *local_store, DataStore *store) {
    // Lock global mutex to ensure thread safety
    pthread_mutex_lock(&store->mutex);

    // Iterate over each element in local store and add to global store
    for (int i = 1; i < local_store->num_elems; i++) {
        update_key(store, local_store->keys[i]);
        update_offset(store, local_store->offsets[i]);
    }

    // Unlock global mutex and return
    pthread_mutex_unlock(&store->mutex);
}

// Handle memory allocation failure by returning error status
void handle_allocation_failure() {
    fprintf(stderr, "Error: Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

// Main function to initialize and manage data store
int main(int argc, char *argv[]) {
    // Check command line arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input file1> [<input file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Initialize data store with given size
    DataStore *store = initialize_data_store(10000);

    // Process each input file concurrently and update data store atomically
    bool success = process_files(store, argv + 1, argc - 1);

    // Print statistics about data store
    printf("Total number of offset values read: %d\n", store->num_elems);
    printf("Number of duplicate offset values encountered: %d\n", store->num_elems - store->offsets[0]);
    printf("Average time taken to process each file: %.2f seconds\n", (double)store->total_time / (argc - 1));

    // Free memory for data store and arrays
    free_data_store(store);

    return success ? EXIT_SUCCESS : EXIT_FAILURE;
}
```
This C function `initialize_data_store` dynamically initializes and manages data structures for efficient storage and retrieval operations. The function ensures that memory allocation does not exceed 10,000 elements to prevent resource exhaustion. It also handles potential memory allocation failures gracefully by logging the error and continuing processing other files.

The function has several components:

