#include <stdlib.h> // for malloc(), free()
#include <stdio.h>  // for printf()
#include <time.h>   // for random()
#include <string.h> // for strcmp()

// Define the record structure
typedef struct {
    double temperature;
    char measurement_unit;
} record;

// Define the lookup table to map measurement units to conversion factors
const char *measurement_units[] = {"C", "F"};
double conversion_factors[] = {1.8, 33.8};
int num_measurement_units = sizeof(measurement_units) / sizeof(*measurement_units);

// Define the logging function to write temperature conversions to a file
void log_temperature_conversion(record *rec) {
    FILE *fp;
    if ((fp = fopen("temperature_log.txt", "a")) == NULL) {
        // error opening file
        return;
    }
    char conversion[32];
    snprintf(conversion, 32, "%f %c -> %f F", rec->temperature, measurement_units[rec->measurement_unit - 'A'], rec->temperature * conversion_factors[rec->measurement_unit - 'A']);
    fprintf(fp, "%s\n", conversion);
    fclose(fp);
}

// Initialize an array of records with random temperature readings within a specified range
record *init_records(int num_records, double min_temp, double max_temp) {
    // Allocate memory for the record array
    record *records = malloc(num_records * sizeof(*records));
    if (records == NULL) {
        // error allocating memory
        return NULL;
    }
    // Initialize temperature readings with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].temperature = min_temp + ((max_temp - min_temp) * random()) / RAND_MAX;
        // Set measurement unit to Celsius by default
        records[i].measurement_unit = 'C';
    }
    return records;
}

// Convert temperature readings from Celsius to Fahrenheit using the lookup table
void convert_temperatures(record *records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        // Check if the measurement unit is 'C' or 'F', and convert accordingly
        if (records[i].measurement_unit == 'C') {
            records[i].temperature *= conversion_factors['C'];
            records[i].measurement_unit = 'F';
        } else if (records[i].measurement_unit == 'F') {
            records[i].temperature /= conversion_factors['F'];
            records[i].measurement_unit = 'C';
        }
    }
}

// Main function to manage memory allocation for an array of records
record *manage_records(int num_records, double min_temp, double max_temp, int log_to_file) {
    // Allocate memory for the record array and initialize temperature readings with random values within the specified range
    record *records = init_records(num_records, min_temp, max_temp);
    if (records == NULL) {
        // error allocating memory
        return NULL;
    }
    // Convert temperature readings from Celsius to Fahrenheit using the lookup table
    convert_temperatures(records, num_records);
    // Log temperature conversions to a file if requested
    if (log_to_file) {
        for (int i = 0; i < num_records; i++) {
            log_temperature_conversion(&records[i]);
        }
    }
    return records;
}
```
