        offsets[i] = rand() % max_offset - min_offset;
        keys[i] = rand() % (max_key - min_key) + min_key;
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
