    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Allocate memory for the context structure
    Context *ctx = (Context *)malloc(sizeof(Context));
    if (ctx == NULL) {
        printf("Error: Failed to allocate memory for context\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize the context structure with the number of records and a pointer to the record array
    ctx->num_records = num_records;
    ctx->records = records;

    // Track memory usage over time
    printf("Memory usage at initialization: %lu bytes\n", getMemoryUsage());
}

void freeMemory(Context *ctx) {
    if (ctx == NULL) return;

    // Free the memory allocated for the record array and the context structure
    free(ctx->records);
    free(ctx);

    // Track memory usage over time
    printf("Memory usage at deallocation: %lu bytes\n", getMemoryUsage());
}

void updateRecords(Context *ctx, size_t num_records) {
    if (ctx == NULL || ctx->records == NULL) return;

    // Allocate memory for the new record array and initialize it with random values within the specified range
    Record *new_records = (Record *)malloc(sizeof(Record) * num_records);
    if (new_records == NULL) {
        printf("Error: Failed to allocate memory for new records\n");
        return;
    }

    // Update the record array and the context structure with the new values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        new_records[i].offset = rand() % ctx->max_offset - ctx->min_offset;
        new_records[i].key = rand() % (ctx->max_key - ctx->min_key) + ctx->min_key;
    }

    // Free the old record array and update the context structure with the new values
    free(ctx->records);
    ctx->num_records = num_records;
    ctx->records = new_records;
}

size_t getMemoryUsage() {
    return (sizeof(long) * 10000 + sizeof(int) * 10000 + sizeof(Record) * 10000);
}
