// Customizable initial values for semaphores
const int SEM_INITIAL_VALUES[] = {1, 2, 3};

// Timeout values for semaphore operations (milliseconds)
const int SEM_TIMEOUTS[] = {500, 1000, 2000};

// Logging levels for semaphore operations
enum LOGGING_LEVELS {DEBUG, INFO, WARNING, ERROR};

// Function to initialize semaphores with customizable initial values
void init_semaphores(sem_t *semaphores[], const int num_semaphores) {
  for (int i = 0; i < num_semaphores; i++) {
    if (sem_init(semaphores[i], SEM_INITIAL_VALUES[i]) == -1) {
      perror("Error initializing semaphore");
      exit(EXIT_FAILURE);
    }
  }
}

// Function to perform atomic increment on a semaphore with timeout
int sem_increment(sem_t *sem, const int timeout) {
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec += timeout / 1000;
  ts.tv_nsec += (timeout % 1000) * 1000000;

  if (sem_timedwait(sem, &ts) == -1) {
    perror("Error waiting for semaphore");
    exit(EXIT_FAILURE);
  }

  return sem_getvalue(sem, NULL);
}

// Function to perform atomic decrement on a semaphore with timeout
int sem_decrement(sem_t *sem, const int timeout) {
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec += timeout / 1000;
  ts.tv_nsec += (timeout % 1000) * 1000000;

  if (sem_timedwait(sem, &ts) == -1) {
    perror("Error waiting for semaphore");
    exit(EXIT_FAILURE);
  }

  return sem_getvalue(sem, NULL);
}

// Function to perform cleanup on a semaphore
void sem_cleanup(sem_t *sem) {
  if (sem_destroy(sem) == -1) {
    perror("Error destroying semaphore");
    exit(EXIT_FAILURE);
  }
}

// Function to perform DNS resolution and handle errors gracefully
int resolve_hostname(const char *hostname, struct in_addr *ip_address) {
  struct hostent *host = gethostbyname(hostname);
  if (host == NULL) {
    perror("Error resolving hostname");
    return -1;
  }

  memcpy(ip_address, host->h_addr_list[0], sizeof(struct in_addr));
  return 0;
}

// Function to log semaphore operations with configurable logging levels
void log_semaphore_operation(const char *operation, const int value) {
  switch (log_level) {
    case DEBUG:
      printf("DEBUG: %s - %d\n", operation, value);
      break;
    case INFO:
      printf("INFO: %s - %d\n", operation, value);
      break;
    case WARNING:
      printf("WARNING: %s - %d\n", operation, value);
      break;
    case ERROR:
      printf("ERROR: %s - %d\n", operation, value);
      break;
  }
}

// Function to limit the capabilities of a process with configurable resource usage and network bandwidth limits
void limit_process_capabilities(const int cpu_limit, const int memory_limit, const int bandwidth_limit) {
  // Set CPU affinity for process
  cpu_set_t cpuset;
  CPU_ZERO(&cpuset);
  CPU_SET(cpu_limit, &cpuset);
  if (sched_setaffinity(0, sizeof(cpu_set_t), &cpuset) == -1) {
    perror("Error setting process CPU affinity");
    exit(EXIT_FAILURE);
  }

  // Set memory limit for process
  struct rlimit mem_lim;
  mem_lim.rlim_cur = memory_limit * 1024 * 1024;
  mem_lim.rlim_max = mem_lim.rlim_cur;
  if (setrlimit(RLIMIT_AS, &mem_lim) == -1) {
    perror("Error setting memory limit");
    exit(EXIT_FAILURE);
  }

  // Set network bandwidth limit for process
  struct rlimit net_lim;
  net_lim.rlim_cur = bandwidth_limit * 1024 * 1024;
  net_lim.rlim_max = net_lim.rlim_cur;
  if (setrlimit(RLIMIT_NET_BANDWIDTH, &net_lim) == -1) {
    perror("Error setting network bandwidth limit");
    exit(EXIT_FAILURE);
  }
}

// Function to handle unexpected interruptions and ensure graceful cleanup of resources
void handle_interruption() {
  // Handle signal interrupts
  if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
    perror("Error ignoring SIGINT");
    exit(EXIT_FAILURE);
  }

  // Clean up semaphores and other resources before exiting
  for (int i = 0; i < num_semaphores; i++) {
    if (sem_destroy(semaphores[i]) == -1) {
      perror("Error destroying semaphore");
      exit(EXIT_FAILURE);
    }
  }
}

