    if (numRecords <= 0 || numRecords > INT_MAX) {
        return NULL;
    }

    // Allocate memory for the array of Records
    Record* records = malloc(sizeof(Record) * numRecords);
    if (!records) {
        return NULL;
    }

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = rand() % 10000;
        records[i].key = rand() % 1000;
        records[i].value = rand() % 1000;
    }

    return records;
}

