int* readRNTIs(int numRNTIs) {
    // Check if the number of RNTIs is valid
    if (numRNTIs <= 0 || numRNTIs > INT_MAX) {
        return NULL;
    }

    // Allocate memory for the array of RNTIs
    int* rntis = malloc(sizeof(int) * numRNTIs);
    if (!rntis) {
        return NULL;
    }

    // Read each RNTI value from standard input and store it in the array
