    if (numRecords <= 0 || numRecords > INT_MAX) {
        return;
    }

    // Initialize variables to keep track of the largest RNTI value and its indices
    int largestRNTI = -1;
    int* indices = NULL;
    int indexCount = 0;

    // Iterate through the records and find the largest RNTI value
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].rnti > largestRNTI) {
            largestRNTI = records[i].rnti;
            indices = realloc(indices, sizeof(int) * (indexCount + 1));
            indices[indexCount++] = i;
        } else if (records[i].rnti == largestRNTI) {
            indices = realloc(indices, sizeof(int) * (indexCount + 1));
            indices[indexCount++] = i;
        }
    }

    // Print the largest RNTI value and its indices
    if (largestRNTI != -1) {
        printf("Largest RNTI: %d\n", largestRNTI);
        for (int i = 0; i < indexCount; ++i) {
