#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <forward_list>
#include <chrono>
#include <random>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>

using namespace std;

struct Record {
    string str;
    int i;
    time_t timestamp;
};

class EfficientDataManager {
public:
    EfficientDataManager() : records(), mutex(), condVar(), numThreads(0) {}

    void insertRecord(const string& searchStr, const Record& newRecord);

    void randomizeIntegers(int minVal, int maxVal);

    vector<Record> getRecords();

    void eraseSensitiveFields();

    ~EfficientDataManager() { records.clear(); }

private:
    forward_list<Record> records;
    mutex mutex;
    condition_variable condVar;
    int numThreads;

    void insertRecordHelper(const string& searchStr, const Record& newRecord);

    bool insertRecordWorker(const string& searchStr, const Record& newRecord);

    vector<Record> getRecordsHelper();

    bool getRecordsWorker(vector<Record>& records);

    void eraseSensitiveFieldsHelper();

    bool eraseSensitiveFieldsWorker(int minVal, int maxVal);
};

void EfficientDataManager::insertRecord(const string& searchStr, const Record& newRecord) {
    // Insert a new record into the list after the first occurrence of a specified search string. If the search string is not found, append the new record to the end of the list.
    unique_lock<mutex> lock(mutex);
    auto iter = find_if(records.begin(), records.end(), [&](const Record& r) { return r.str == searchStr; });
    if (iter != records.end()) {
        insertRecordHelper(searchStr, newRecord);
    } else {
        records.push_back(newRecord);
    }
}

void EfficientDataManager::insertRecordHelper(const string& searchStr, const Record& newRecord) {
    // Insert a new record after the first occurrence of a specified search string.
    auto iter = find_if(records.begin(), records.end(), [&](const Record& r) { return r.str == searchStr; });
    if (iter != records.end()) {
        ++iter; // Advance to the next record after the search string.
        records.insert_after(iter, newRecord);
    } else {
        cerr << "Failed to insert record: Search string not found." << endl;
    }
}

bool EfficientDataManager::insertRecordWorker(const string& searchStr, const Record& newRecord) {
    // Insert a new record into the list after the first occurrence of a specified search string. If the search string is not found, append the new record to the end of the list.
    unique_lock<mutex> lock(mutex);
    auto iter = find_if(records.begin(), records.end(), [&](const Record& r) { return r.str == searchStr; });
    if (iter != records.end()) {
        ++iter; // Advance to the next record after the search string.
        records.insert_after(iter, newRecord);
        return true;
    } else {
        cerr << "Failed to insert record: Search string not found." << endl;
        return false;
    }
}

void EfficientDataManager::randomizeIntegers(int minVal, int maxVal) {
    // Assign a random integer value within a specified range [min_value, max_value] to each record.
    unique_lock<mutex> lock(mutex);
    uniform_int_distribution<int> dist(minVal, maxVal);
    for (auto& record : records) {
        record.i = dist(default_random_engine());
    }
}

void EfficientDataManager::eraseSensitiveFields() {
    // Erase sensitive fields from memory to prevent accidental exposure.
    unique_lock<mutex> lock(mutex);
    for (auto& record : records) {
        memset(&record.str, 0, sizeof(string));
        memset(&record.i, 0, sizeof(int));
        memset(&record.timestamp, 0, sizeof(time_t));
    }
}

vector<Record> EfficientDataManager::getRecords() {
    // Get all records from the list.
    unique_lock<mutex> lock(mutex);
    return getRecordsHelper();
}

vector<Record> EfficientDataManager::getRecordsHelper() {
    // Get all records from the list.
    vector<Record> result;
    for (auto& record : records) {
        result.push_back(record);
    }
    return result;
}

bool EfficientDataManager::getRecordsWorker(vector<Record>& records) {
    // Get all records from the list.
    unique_lock<mutex> lock(mutex);
    for (auto& record : records) {
        record = this->records.front();
        this->records.pop_front();
    }
    return true;
}

void EfficientDataManager::eraseSensitiveFieldsHelper() {
    // Erase sensitive fields from memory to prevent accidental exposure.
    unique_lock<mutex> lock(mutex);
    for (auto& record : records) {
        memset(&record.str, 0, sizeof(string));
        memset(&record.i, 0, sizeof(int));
        memset(&record.timestamp, 0, sizeof(time_t));
    }
}

bool EfficientDataManager::eraseSensitiveFieldsWorker(int minVal, int maxVal) {
    // Erase sensitive fields from memory to prevent accidental exposure.
    unique_lock<mutex> lock(mutex);
    uniform_int_distribution<int> dist(minVal, maxVal);
    for (auto& record : records) {
        record.i = dist(default_random_engine());
    }
    return true;
}
