    // If the key was found, return the corresponding value
    if (i < keys->size) {
        return values[offsets->offsets[i]];
    } else {
        return NULL;
    }
}

// Serialize the collection to persistent storage
void serialize(OffsetArray *offsets, KeyArray *keys) {
    // Write the offset and key arrays to a file
    FILE *f = fopen("data.bin", "wb");
    if (f == NULL) {
        // Handle error by returning an error code
        return -1;
    }
    fwrite(offsets->offsets, sizeof(long), offsets->size, f);
    fwrite(keys->keys, sizeof(int), keys->size, f);
    fclose(f);
}

// Deserialize the collection from persistent storage
void deserialize(OffsetArray *offsets, KeyArray *keys) {
    // Read the offset and key arrays from a file
    FILE *f = fopen("data.bin", "rb");
    if (f == NULL) {
        // Handle error by returning an error code
        return -1;
    }
    offsets->size = fread(offsets->offsets, sizeof(long), offsets->capacity, f);
    keys->size = fread(keys->keys, sizeof(int), keys->capacity, f);
    fclose(f);
}
