entry* manage_memory(int* capacity, int* size, entry* arr) {
    // Check if the user has specified an initial capacity
    if (*capacity == 0) {
        *capacity = 1;
    }

    // If the user wants to resize the array, double its capacity
    if (*size >= *capacity) {
        *capacity *= 2;
    }

