        if (!ue_context->nas_message) {
            printf("Error: unable to allocate memory for NAS message\n");
            return;
        }
        ue_context->ue_id = i + 1;
    }

    // Set thread-local storage for the UE context array
    pthread_key_create(&ue_contexts, free);

    // Return the initialized UE contexts
    return ue_contexts;
}

// Define function to add a new NAS message to an existing UE context
void addNASMessage(UEContext *ue_context) {
