        return;
    }

    // Copy the new NAS message into the existing UE context
    memcpy(ue_context->nas_message, new_nas_message, 1024);

    // Free the allocated memory for the new NAS message
    free(new_nas_message);
}

// Define function to clear all allocated resources when the function completes
void clearResources() {
    UEContext **ue_contexts = pthread_getspecific(&ue_contexts);
    if (!ue_contexts) {
        printf("Error: unable to retrieve thread-local storage for UE contexts\n");
        return;
    }

    // Free the memory allocated for each UE context
    for (int i = 0; i < num_ue; i++) {
        UEContext *ue_context = ue_contexts[i];
        if (!ue_context) {
            printf("Error: unable to retrieve UE context\n");
            return;
        }
        free(ue_context->nas_message);
    }

    // Free the memory allocated for the UE context array
    free(ue_contexts);
}
