#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Define a record structure to store 'int' keys and 'long' offsets
typedef struct {
  int key;
  long offset;
} record_t;

// Define a memory pool structure to store records
typedef struct {
  size_t capacity; // total number of records in the pool
  size_t count; // number of records currently allocated
  size_t used; // total amount of memory used by the pool
  record_t* records; // pointer to array of records
} mempool_t;

// Function to initialize a new memory pool with a given capacity
mempool_t* mempool_init(size_t capacity) {
  mempool_t* mp = malloc(sizeof(mempool_t));
  if (mp == NULL) {
    return NULL; // allocation failure, handle as appropriate
  }
  mp->capacity = capacity;
  mp->count = 0;
  mp->used = 0;
  mp->records = malloc(capacity * sizeof(record_t));
  if (mp->records == NULL) {
    free(mp); // release partially allocated memory
    return NULL; // allocation failure, handle as appropriate
  }
  for (size_t i = 0; i < capacity; i++) {
    mp->records[i].key = -1; // initialize record keys to invalid values
    mp->records[i].offset = -1L; // initialize record offsets to invalid values
  }
  return mp;
}

// Function to allocate a new record in the memory pool, with key and offset values
record_t* mempool_alloc(mempool_t* mp) {
  if (mp == NULL || mp->count >= mp->capacity) { // check for overflow or null pointer
    return NULL; // allocation failure, handle as appropriate
  }
  size_t index = mp->count++; // increment record count and retrieve new index
  record_t* rec = &mp->records[index]; // retrieve record structure at the given index
  rec->key = rand() % (INT_MAX - INT_MIN) + INT_MIN; // generate random key value within range
  rec->offset = rand() % (LONG_MAX - LONG_MIN) + LONG_MIN; // generate random offset value within range
  mp->used += sizeof(record_t); // update memory usage
  return rec; // return pointer to the allocated record
}

// Function to deallocate a single record in the memory pool, by key
bool mempool_dealloc(mempool_t* mp, int key) {
  if (mp == NULL || mp->count <= 0) { // check for underflow or null pointer
    return false; // deallocation failure, handle as appropriate
  }
  size_t index = -1; // initialize index to invalid value
  for (size_t i = 0; i < mp->capacity; i++) {
    if (mp->records[i].key == key) { // check for matching key value
      index = i; // save index of the matching record
      break; // exit early to avoid unnecessary comparisons
    }
  }
  if (index == -1) { // handle failure to find a matching record
    return false; // deallocation failure, handle as appropriate
  }
  mp->count--; // decrement record count
  memmove(mp->records + index, mp->records + index + 1, sizeof(record_t) * (mp->capacity - index - 1)); // shift records to fill gap
  mp->used -= sizeof(record_t); // update memory usage
  return true; // deallocation successful
}

// Function to release all allocated memory in the memory pool, restoring it to its original state
void mempool_free(mempool_t* mp) {
  if (mp == NULL || mp->count <= 0) { // check for underflow or null pointer
    return; // no-op, handle as appropriate
  }
  free(mp->records); // release memory pool array of records
  free(mp); // release memory pool structure
}
```
This code implements a flexible record storage system within a given memory pool, with dynamically allocated memory and efficient memory management. The `mempool_init` function initializes a new memory pool with a given capacity, allocating memory for the record structures and initializing their key and offset fields to invalid values. The `mempool_alloc` function allocates a new record in the memory pool, generating random key and offset values within specified ranges and incrementing the record count. The `mempool_dealloc` function deallocates a single record by its key value, decrementing the record count and shifting records to fill any gap left by the deleted record. The `mempool_free` function releases all allocated memory in the memory pool, restoring it to its original state.

Performance considerations:
- This implementation uses a fixed-size array of record structures within the memory pool, which can lead to performance issues if the number of records exceeds the capacity of the available memory pool.
- To optimize memory usage and reduce overhead, the `mempool_dealloc` function could use a more sophisticated algorithm for shifting records, such as a linked list or a dynamic array of record pointers.
- Evaluating the impact of varying `max_mem` settings on system responsiveness and resource utilization requires testing under various scenarios and conditions."]

