int create_records(int num_records, long **offsets, int **keys, float **precision_values, char **status_flags) {
    if (num_records <= 0) {
        return -1;
    }

    // Allocate memory for each record
    *offsets = (long *)malloc(sizeof(long) * num_records);
    *keys = (int *)malloc(sizeof(int) * num_records);
    *precision_values = (float *)malloc(sizeof(float) * num_records);
    *status_flags = (char *)malloc(sizeof(char) * num_records);

    // Initialize each record with default values
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = 0;
        (*keys)[i] = 0;
        (*precision_values)[i] = 0.0f;
        (*status_flags)[i] = ' ';
    }

    return 0;
}

// Function to update a record
int update_record(long offset, int key, float precision_value, char status_flag) {
    if (offset < 0 || key < 0 || precision_value < 0.0f) {
        return -1;
    }

    // Update the corresponding record with the new values
    (*offsets)[offset] = offset;
    (*keys)[offset] = key;
    (*precision_values)[offset] = precision_value;
    (*status_flags)[offset] = status_flag;

    return 0;
}

// Function to delete a record
int delete_record(long offset) {
    if (offset < 0) {
        return -1;
    }

    // Delete the corresponding record by shifting all subsequent records backwards
    for (int i = offset; i < num_records - 1; i++) {
        (*offsets)[i] = (*offsets)[i + 1];
        (*keys)[i] = (*keys)[i + 1];
        (*precision_values)[i] = (*precision_values)[i + 1];
        (*status_flags)[i] = (*status_flags)[i + 1];
    }

    num_records--;

    return 0;
}

// Function to search for a record by key
int find_record(int key) {
    if (key < 0) {
        return -1;
    }

    // Search the corresponding record by iterating through all records
    for (int i = 0; i < num_records; i++) {
        if ((*keys)[i] == key) {
            return i;
        }
    }

    return -1;
}

// Function to iterate over all records
void foreach_record(void (*callback)(void *, int)) {
    for (int i = 0; i < num_records; i++) {
        callback((*offsets)[i], (*keys)[i]);
        callback((*precision_values)[i], (*status_flags)[i]);
    }
}
