void initializeAndManageRequests() {
    // Allocate memory for the arrays
    requests = (DataTransferRequest*)malloc(5 * sizeof(DataTransferRequest));
    chars = (char(*)[26])malloc(5 * 26 * sizeof(char));
    nodes = (Node**)malloc(5 * sizeof(Node*));
