        strLengths[i] = 0;
        strData[i] = (char*)malloc(strLengths[i] * sizeof(char));
    }
}

// Add a new request to the array
void addNewRequest(int requestId, char* destinationAddress, size_t payloadSize) {
    // Check if the request ID is valid
    if (requestId < 1 || requestId > 5) {
        return;
    }

    // Allocate memory for the new request
    DataTransferRequest* newRequest = (DataTransferRequest*)malloc(sizeof(DataTransferRequest));
    newRequest->requestId = requestId;
    newRequest->destinationAddress = destinationAddress;
    newRequest->payloadSize = payloadSize;

    // Add the new request to the array
    requests[requestId - 1] = *newRequest;
}

// Update an existing request in the array
void updateRequest(int requestId, char* destinationAddress, size_t payloadSize) {
    // Check if the request ID is valid
    if (requestId < 1 || requestId > 5) {
        return;
    }

    // Update the existing request
    requests[requestId - 1].destinationAddress = destinationAddress;
    requests[requestId - 1].payloadSize = payloadSize;
}

// Retrieve the total size of all payloads combined for a given request ID
size_t getPayloadSize(int requestId) {
    // Check if the request ID is valid
    if (requestId < 1 || requestId > 5) {
        return -1;
    }

    // Return the payload size of the existing request
    return requests[requestId - 1].payloadSize;
}

// Insert a new node into the linked list at the end
void insertNode(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = NULL;

    if (nodes[0] == NULL) {
        nodes[0] = newNode;
        return;
    }

    Node* curr = nodes[0];
    while (curr->next != NULL) {
        curr = curr->next;
    }

    curr->next = newNode;
}

// Traverse the linked list and add the values to an array
void traverseList() {
    Node* curr = nodes[0];
    while (curr != NULL) {
        int value = curr->value;
        // Add the value to the array
        strLengths[0]++;
        strData[0] = (char*)realloc(strData[0], strLengths[0] * sizeof(char));
        strData[0][strLengths[0] - 1] = value;
        curr = curr->next;
    }
}

// Free the memory allocated for the linked list and arrays
void freeMemory() {
    // Free the nodes in the linked list
    Node* curr = nodes[0];
    while (curr != NULL) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }

    // Free the arrays
    for (int i = 0; i < 5; ++i) {
        free(requests[i].destinationAddress);
        free(strData[i]);
    }
}
