// Define structure for DataTransferRequest
typedef struct {
    int requestId;
    char* destinationAddress;
    size_t payloadSize;
} DataTransferRequest;

// Define a hashtable for storing requests by ID
#define REQUESTS_HASHTABLE_SIZE 1024 // arbitrary size, adjust as needed
static DataTransferRequest* requestHashtable[REQUESTS_HASHTABLE_SIZE];

// Function to add/update a request in the hashtable
int updateRequest(DataTransferRequest* newRequest) {
    int index = newRequest->requestId % REQUESTS_HASHTABLE_SIZE;
    DataTransferRequest* currentRequest = requestHashtable[index];

    // Check if a request with the same ID already exists
    while (currentRequest != NULL && currentRequest->requestId != newRequest->requestId) {
        currentRequest = currentRequest->next;
    }

    if (currentRequest == NULL) {
        // No request with this ID found, add a new one
        currentRequest = malloc(sizeof(DataTransferRequest));
        assert(currentRequest != NULL);
        memcpy(currentRequest, newRequest, sizeof(DataTransferRequest));
        currentRequest->next = requestHashtable[index];
        requestHashtable[index] = currentRequest;
    } else {
        // Update an existing request with the same ID
        memcpy(currentRequest, newRequest, sizeof(DataTransferRequest));
    }

    return 0;
}

// Function to retrieve a request from the hashtable by ID
DataTransferRequest* getRequestById(int requestId) {
    int index = requestId % REQUESTS_HASHTABLE_SIZE;
    DataTransferRequest* currentRequest = requestHashtable[index];

    while (currentRequest != NULL && currentRequest->requestId != requestId) {
        currentRequest = currentRequest->next;
    }

    return currentRequest;
}

// Function to calculate the total payload size of all requests
size_t getTotalPayloadSize() {
    size_t totalPayloadSize = 0;
    for (int i = 0; i < REQUESTS_HASHTABLE_SIZE; i++) {
        DataTransferRequest* currentRequest = requestHashtable[i];
        while (currentRequest != NULL) {
            totalPayloadSize += currentRequest->payloadSize;
            currentRequest = currentRequest->next;
        }
    }
    return totalPayloadSize;
}
