#include <string.h>
#include <pthread.h>
#include "LTE_PHY_RX_FRAME.h"
#include "LTE_DL_CCCH_MESSAGE.h"
#include "LTE_RNTI.h"
#include "LTE_RX_CQI_RECORD.h"

typedef struct LTE_PHY_RX_FRAME_Node {
    LTE_PHY_RX_FRAME *frame;
    struct LTE_PHY_RX_FRAME_Node *next;
} LTE_PHY_RX_FRAME_Node;

LTE_PHY_RX_FRAME_Node *init_LTE_PHY_RX_FRAME(size_t num_frames) {
    // Allocate memory for the linked list of frames
    LTE_PHY_RX_FRAME_Node *head = malloc(sizeof(LTE_PHY_RX_FRAME_Node));
    head->frame = malloc(num_frames * sizeof(LTE_PHY_RX_FRAME));
    head->next = NULL;

    // Initialize the frames in the linked list
    for (size_t i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME *frame = &head->frame[i];
        frame->LTE_DL_CCCH_MESSAGE = malloc(sizeof(LTE_DL_CCCH_MESSAGE));
        frame->LTE_RNTI = malloc(sizeof(LTE_RNTI));
        frame->LTE_RX_CQI_RECORD = malloc(sizeof(LTE_RX_CQI_RECORD));
    }

    // Initialize the linked list of frames
    LTE_PHY_RX_FRAME_Node *curr = head;
    for (size_t i = 0; i < num_frames - 1; i++) {
        curr->next = malloc(sizeof(LTE_PHY_RX_FRAME_Node));
        curr = curr->next;
    }

    return head;
}

void destroy_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_Node *head) {
    // Free the memory for the linked list of frames
    LTE_PHY_RX_FRAME_Node *curr = head;
    while (curr != NULL) {
        free(curr->frame);
        curr = curr->next;
    }
    free(head);
}

void add_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_Node *head, LTE_PHY_RX_FRAME *frame) {
    // Acquire a lock to prevent race conditions
    pthread_mutex_lock(&add_lock);

    // Add the frame to the linked list
    LTE_PHY_RX_FRAME_Node *curr = head;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    curr->next = malloc(sizeof(LTE_PHY_RX_FRAME_Node));
    curr->next->frame = frame;

    // Release the lock and return
    pthread_mutex_unlock(&add_lock);
}

bool validate_LTE_RX_CQI_RECORD(LTE_PHY_RX_FRAME *frame) {
    // Check if the record is valid
    if (frame->LTE_RX_CQI_RECORD.valid == false) {
        return false;
    }

    // Check if the record has a sufficient number of samples
    if (frame->LTE_RX_CQI_RECORD.num_samples < MINIMUM_NUM_SAMPLES) {
        return false;
    }

    // Check if the record has a sufficient signal strength
    if (frame->LTE_RX_CQI_RECORD.signal_strength < MINIMUM_SIGNAL_STRENGTH) {
        return false;
    }

    // Return true if all checks pass
    return true;
}
