} dataUnit;

// Define the predefined set of operation modes
enum type {
    OPERATION_MODE_1,
    OPERATION_MODE_2,
    OPERATION_MODE_3,
};

process* create_process(size_t num_floats, size_t num_chars, size_t num_data_units) {
    // Allocate memory for the process structure
    process *p = malloc(sizeof(process));

    // Allocate memory for the float array
    p->float_array = malloc(num_floats * sizeof(double));

    // Allocate memory for the char array
    p->char_array = malloc(num_chars * sizeof(char*));

    // Allocate memory for the data unit array
    p->data_unit_array = malloc(num_data_units * sizeof(dataUnit*));

    // Initialize the float array with random values within a specified range
    for (size_t i = 0; i < num_floats; i++) {
        double value = (double)rand() / RAND_MAX;
        p->float_array[i] = value;
    }

    // Initialize the char array with random values within a specified range
    for (size_t i = 0; i < num_chars; i++) {
        char *value = malloc(10 * sizeof(char));
        sprintf(value, "%d", rand() % 10);
        p->char_array[i] = value;
    }

    // Initialize the data unit array with random values within a specified range
    for (size_t i = 0; i < num_data_units; i++) {
        dataUnit *d = malloc(sizeof(dataUnit));
        d->value = (double)rand() / RAND_MAX;
        enum type operation_mode = rand() % OPERATION_MODE_3 + 1; // Enum value between 1 and 3
        d->operation_mode = operation_mode;
        p->data_unit_array[i] = d;
    }

    return p;
}

void destroy_process(process *p) {
    free(p->float_array);
    free(p->char_array);
    for (size_t i = 0; i < p->num_data_units; i++) {
        dataUnit *d = p->data_unit_array[i];
        free(d);
    }
    free(p->data_unit_array);
}

int main() {
    // Create a process with random sizes for the float, char, and data unit arrays
    size_t num_floats = rand() % 10 + 5;
    size_t num_chars = rand() % 20 + 10;
    size_t num_data_units = rand() % 30 + 20;
    process *p = create_process(num_floats, num_chars, num_data_units);

    // Validate the integrity of the generated processes against predefined criteria
    if (validate_process(p)) {
        printf("Process is valid\n");
    } else {
        printf("Process is invalid\n");
    }

    // Destroy the process and free its memory
    destroy_process(p);

    return 0;
}
