// Function to initialize records
Record* initialize_records(int num_records, int min_range, int max_range, unsigned seed) {
    // Check available memory and predefined limits
    if (num_records < 0 || num_records > MAX_NUM_RECORDS) {
        printf("Invalid number of records: %d\n", num_records);
        return NULL;
    }

    // Allocate memory for the records array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the random number generator
    srand(seed);

    // Generate random values for the offset field
    int i;
    for (i = 0; i < num_records; i++) {
        records[i].offset = rand() % (max_range - min_range + 1) + min_range;
    }

    // Generate random values for the key field
    for (i = 0; i < num_records; i++) {
        records[i].key = rand() % MAX_KEY_VALUE + MIN_KEY_VALUE;
    }

    // Initialize error logging mechanism
    strcpy(records->error, "");

    // Check for any allocation failures or invalid operations
    if (check_errors()) {
        printf("Error initializing records\n");
        free(records);
        return NULL;
    }

    // Return pointer to initialized records array
    return records;
}

// Custom error logging mechanism
void log_error(char* message) {
    strcpy(records->error, message);
}

// Thread-safe version of the random number generator
int rand_thread_safe() {
    int val = 0;
    #pragma omp critical
    {
        val = rand();
    }
    return val;
}

// Function to free memory allocated by initialize_records
void free_records(Record* records) {
    // Free the memory allocated for the records array
    free(records);
}
