void initializeNetworkTrafficManager(int* flow_ids, int num_flows) {
    // Allocate memory for the TrafficFlow structures and initialize them
    TrafficFlow* traffic_flows = malloc(num_flows * sizeof(TrafficFlow));
    if (traffic_flows == NULL) {
        printf("Error: Could not allocate memory for TrafficFlow structures\n");
        return;
    }

    // Initialize the TrafficFlow structures with default values
    for (int i = 0; i < num_flows; i++) {
        traffic_flows[i].flow_id = flow_ids[i];
        traffic_flows[i].pdu_data = NULL;
        traffic_flows[i].pdu_len = 0;
        traffic_flows[i].priority = 0;
    }

    // Allocate memory for the PDU data segments and initialize them with default values
    char* pdu_data = malloc(num_flows * sizeof(char));
    if (pdu_data == NULL) {
        printf("Error: Could not allocate memory for PDU data segments\n");
        return;
    }
    memset(pdu_data, 0, num_flows * sizeof(char));

    // Initialize the priority of each PDU segment to a default value
    uint8_t priority = 1;

    // Create a mutex to protect the TrafficFlow structures and PDU data segments from concurrent access
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        printf("Error: Could not allocate memory for mutex\n");
        return;
    }
    pthread_mutex_init(mutex, NULL);

    // Initialize the number of successful and failed operations for debugging purposes
    int num_successful_operations = 0;
    int num_failed_operations = 0;

    // Create a logging mechanism to track the number of successful and failed operations
    FILE* logfile = fopen("traffic_manager.log", "w");
    if (logfile == NULL) {
        printf("Error: Could not open log file\n");
        return;
    }

    // Implement a mechanism to clear all allocated resources when the function completes
    atexit(cleanup);

    // Return the TrafficFlow structures and PDU data segments, along with the mutex and logging mechanism
    return traffic_flows, pdu_data, mutex, logfile;
}
