// Function to read N FlowIDs from standard input and store them in a dynamically allocated array of integers, handling up to 10,000 unique elements efficiently
int* readFlowIDs(int num_flows) {
    // Allocate memory for the flow IDs and initialize them with default values
    int* flow_ids = malloc(num_flows * sizeof(int));
    if (flow_ids == NULL) {
        printf("Error: Could not allocate memory for flow IDs\n");
        return NULL;
    }
    memset(flow_ids, 0, num_flows * sizeof(int));

    // Read the flow IDs from standard input and store them in the flow ID array
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, stdin)) != -1) {
        // Parse the flow ID from the input line and store it in the flow IDs array
        char* token = strtok(line, " ");
        int flow_id = atoi(token);
        flow_ids[flow_id] = 1;
    }

    // Return the flow IDs array
    return flow_ids;
