    // Allocate memory for the record
    record_t* record = (record_t*) malloc(sizeof(record_t));
    if (!record) {
        return NULL;
    }

    // Initialize the record with the given key and offset
    record->key = key;
    record->offset = offset;
    record->data = data;

    // Add the record to the LRU cache
    lru_cache_t* cache = get_lru_cache();
    size_t index = hash(key) % cache->size;
    cache->records[index] = record;
    cache->num_records++;

    return record;
}

// Function to deallocate memory efficiently, minimizing leaks and optimizing performance
void free_record(record_t* record) {
    lru_cache_t* cache = get_lru_cache();
    size_t index = hash(record->key) % cache->size;

    // Remove the record from the LRU cache
    if (cache->records[index] == record) {
        cache->records[index] = NULL;
        cache->num_records--;
    }

    // Free the record
    free(record);
}

