void resize_lru_cache(int size) {
    lru_cache_t* cache = get_lru_cache();

    // Reallocate the cache with the new size
    cache->size = size;
    cache->records = realloc(cache->records, sizeof(record_t*) * size);
}

// Function to manage memory usage effectively with an LRU eviction policy when necessary
void lru_evict() {
    lru_cache_t* cache = get_lru_cache();

    // Evict the least recently used record from the cache
