#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <sys/time.h>
#include <math.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 4096
#define MIN_BUFFERS 2
#define MAX_BUFFERS 8

typedef struct {
    char *data;
    size_t length;
} data_buffer_t;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cv;
    int head, tail;
    data_buffer_t *buffers[MAX_BUFFERS];
    size_t buffer_sizes[MAX_BUFFERS];
} data_queue_t;

void init_data_queue(data_queue_t *queue) {
    queue->head = 0;
    queue->tail = 0;
    memset(&queue->buffers, NULL, sizeof(queue->buffers));
    for (int i = 0; i < MAX_BUFFERS; i++) {
        queue->buffer_sizes[i] = BUFFER_SIZE;
        queue->buffers[i] = malloc(sizeof(data_buffer_t) * BUFFER_SIZE);
    }
}

void destroy_data_queue(data_queue_t *queue) {
    for (int i = 0; i < MAX_BUFFERS; i++) {
        free(queue->buffers[i]);
    }
}

void enqueue(data_queue_t *queue, data_buffer_t *buffer) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->tail + 1 == queue->head) {
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }
    queue->buffers[queue->tail] = buffer;
    queue->tail = (queue->tail + 1) % MAX_BUFFERS;
    pthread_cond_signal(&queue->cv);
    pthread_mutex_unlock(&queue->mutex);
}

data_buffer_t *dequeue(data_queue_t *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }
    data_buffer_t *buffer = queue->buffers[queue->head];
    queue->head = (queue->head + 1) % MAX_BUFFERS;
    pthread_cond_signal(&queue->cv);
    pthread_mutex_unlock(&queue->mutex);
    return buffer;
}

void process_streamed_data(int data_fd, int error_fd, void *user_data) {
    // Initialize the queue for storing the incoming data
    data_queue_t queue;
    init_data_queue(&queue);

    // Start the thread pool for processing the data
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_data, &queue);
    }

    // Read the data from the file descriptor and enqueue it in the queue
    char buffer[BUFFER_SIZE];
    while (1) {
        ssize_t n = read(data_fd, buffer, BUFFER_SIZE);
        if (n == 0) {
            break;
        } else if (n < 0) {
            perror("Error reading from file descriptor");
            exit(1);
        }
        data_buffer_t *data = malloc(sizeof(data_buffer_t));
        data->data = buffer;
        data->length = n;
        enqueue(&queue, data);
    }

    // Wait for all the threads to finish processing the data
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy the queue and free up the resources
    destroy_data_queue(&queue);
}

void *process_data(void *user_data) {
    data_queue_t *queue = user_data;

    // Process the data in the queue
    while (1) {
        data_buffer_t *buffer = dequeue(queue);
        if (!buffer) {
            break;
        }

        // Do some processing on the buffer here...

        free(buffer->data);
        free(buffer);
    }

    pthread_exit(NULL);
}
```
