// Define the event structure
typedef struct {
    uint64_t timestamp;
    uint32_t id;
} Event;

// Define the linked list node for the event structures
typedef struct Node {
    Event event;
    struct Node* next;
} Node;

// Define the hash table for efficient lookup by ID
typedef struct {
    uint32_t id;
    Event* event;
} HashTable;

// Define the system module for managing events
typedef struct {
    int idRange;
    int eventCount;
    float durationDistribution;
    Node* head;
    HashTable* hashTable;
} EventSystem;

// Initialize the event system with default parameters
EventSystem initEventSystem() {
    // Set default values for the parameters
    int idRange = 10000;
    int eventCount = 1000;
    float durationDistribution = 1.0f;

    // Allocate memory for the event system struct
    EventSystem* sys = (EventSystem*)malloc(sizeof(EventSystem));

    // Initialize the linked list and hash table
    sys->head = NULL;
    sys->hashTable = (HashTable*)malloc(idRange * sizeof(HashTable));
    for (int i = 0; i < idRange; i++) {
        sys->hashTable[i].id = -1;
        sys->hashTable[i].event = NULL;
    }

    // Initialize the event count and duration distribution
    sys->eventCount = eventCount;
    sys->durationDistribution = durationDistribution;

    return *sys;
}

// Register a new event with the system
void registerEvent(EventSystem* sys, uint32_t id, uint64_t timestamp) {
    // Check if the ID is within the valid range
    if (id >= 0 && id < sys->idRange) {
        // Allocate memory for the new event structure
        Event* event = (Event*)malloc(sizeof(Event));
        event->timestamp = timestamp;
        event->id = id;

        // Add the event to the linked list
        Node* node = (Node*)malloc(sizeof(Node));
        node->event = event;
        node->next = sys->head;
        sys->head = node;

        // Update the hash table with the new ID and event pointer
        sys->hashTable[id].id = id;
        sys->hashTable[id].event = event;
    }
}

// Retrieve an event by its ID from the system
Event* getEvent(EventSystem* sys, uint32_t id) {
    // Check if the ID is within the valid range
    if (id >= 0 && id < sys->idRange) {
        return sys->hashTable[id].event;
    }

    return NULL;
}

// Log an error message with a descriptive message
