```rust
use std::collections::HashMap;
use std::net::TcpStream;
use std::thread;

// Define the data structure for each record
struct Record {
    integer: i32,
    floating_point: f64,
    string: String,
}

// Function to send an HTTP request and receive a response
fn send_http_request(url: &str, headers: HashMap<String, String>) -> Result<TcpStream, String> {
    // Create the TCP stream for the connection
    let mut stream = TcpStream::connect(url).map_err(|e| e.to_string())?;

    // Set the request headers
    for (header, value) in headers.iter() {
        stream.write_all(format!("{}: {}", header, value).as_bytes()).map_err(|e| e.to_string())?;
    }

    // Send the request body
    stream.write_all(b"").map_err(|e| e.to_string())?;

    // Read the response headers and status code
    let mut headers = vec![];
    loop {
        match read_line(&mut stream) {
            Ok(line) => {
                if line.is_empty() { break; }
                headers.push(line);
            },
            Err(e) => return Err(format!("Failed to read response header: {}", e)),
        }
    }
    let status_code = get_status_code(&headers);
    if !is_success_status_code(status_code) {
        return Err(format!("Response status code is not 2xx: {}", status_code));
    }

    // Read the response body
    let mut body = vec![];
    stream.read_to_end(&mut body).map_err(|e| e.to_string())?;

    Ok(body)
}
