// Custom Memory Allocator
#include <stdlib.h>
#include <string.h>

typedef struct {
    void *buffer;
    size_t capacity;
} Buffer;

void initBuffer(Buffer *buf, size_t initialCapacity) {
    buf->buffer = malloc(initialCapacity);
    buf->capacity = initialCapacity;
}

void resizeBuffer(Buffer *buf, size_t newCapacity) {
    if (newCapacity > buf->capacity) {
        buf->buffer = realloc(buf->buffer, newCapacity);
        buf->capacity = newCapacity;
    }
}

void freeBuffer(Buffer *buf) {
    free(buf->buffer);
}

// Custom Memory Manager
#include <stdlib.h>
#include <string.h>

#define MEMORY_ALLOCATION_GRANULARITY 64 // bytes

typedef struct {
    Buffer buffers[1024]; // max number of buffers is 1024
} MemoryManager;

MemoryManager *initMemoryManager() {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    for (int i = 0; i < 1024; i++) {
        initBuffer(&manager->buffers[i], MEMORY_ALLOCATION_GRANULARITY);
    }
    return manager;
}

void *allocate(MemoryManager *manager, size_t bytes) {
    for (int i = 0; i < 1024; i++) {
        Buffer *buf = &manager->buffers[i];
        if (buf->capacity - buf->size >= bytes) {
            return buf->buffer + buf->size;
        }
    }
    return NULL;
}

void deallocate(MemoryManager *manager, void *ptr, size_t bytes) {
    for (int i = 0; i < 1024; i++) {
        Buffer *buf = &manager->buffers[i];
        if (buf->buffer == ptr && buf->size - bytes >= 0) {
            buf->size -= bytes;
            return;
        }
    }
}

void freeMemoryManager(MemoryManager *manager) {
    for (int i = 0; i < 1024; i++) {
        Buffer *buf = &manager->buffers[i];
        freeBuffer(buf);
    }
    free(manager);
}

// Logging System
