#include <stdarg.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

void log(LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    switch (level) {
        case DEBUG:
            vprintf("[DEBUG] ", args);
            break;
        case INFO:
            vprintf("[INFO] ", args);
            break;
        case WARNING:
            vprintf("[WARNING] ", args);
            break;
