// Define function to initialize traffic flow statistics
void initializeTrafficStatistics(struct TrafficFlow** traffic_flows, int num_traffic_flows) {
  // Allocate memory for the traffic flows
  *traffic_flows = (struct TrafficFlow*) malloc(num_traffic_flows * sizeof(struct TrafficFlow));

