    (*traffic_flows)[i].traffic_name = malloc(sizeof(char) * 32);
    sprintf((*traffic_flows)[i].traffic_name, "Traffic Flow %d", i + 1);
    (*traffic_flows)[i].data_packets = NULL;
  }
}

// Define function to add a data packet to the traffic flow statistics
void addDataPacket(struct TrafficFlow* traffic_flow, struct DataPacket* data_packet) {
  // Allocate memory for the data packet
  data_packet = (struct DataPacket*) malloc(sizeof(struct DataPacket));

  // Initialize the data packet with the appropriate ID and size
  data_packet->traffic_flow = traffic_flow;
  data_packet->packet_size = sizeof(int) + sizeof(char) * 32;
  data_packet->packet_data = malloc(sizeof(unsigned char) * data_packet->packet_size);

  // Serialize the data packet and compute its CRC
  json_object* packet_json = json_object_new();
  json_object_object_add(packet_json, "traffic_id", json_object_new_int(traffic_flow->traffic_id));
  json_object_object_add(packet_json, "traffic_name", json_object_new_string(traffic_flow->traffic_name));
  json_object_object_add(packet_json, "data_size", json_object_new_int(data_packet->packet_size));
  json_object* data_json = json_object_new();
  for (int i = 0; i < data_packet->packet_size; i++) {
    char* data_char = malloc(sizeof(char) * 2);
    sprintf(data_char, "%d", data_packet->packet_data[i]);
    json_object_array_add(data_json, json_object_new_string(data_char));
    free(data_char);
  }
  json_object_object_add(packet_json, "data", data_json);
  char* packet_str = json_serialize_to_string(packet_json);
  unsigned long crc = computeCrc32(packet_str);
  free(packet_str);
  json_object_put(packet_json);

  // Add the data packet to the traffic flow statistics
  traffic_flow->data_packets = (struct DataPacket*) realloc(traffic_flow->data_packets, sizeof(struct DataPacket) * (traffic_flow->num_data_packets + 1));
  traffic_flow->data_packets[traffic_flow->num_data_packets].traffic_flow = traffic_flow;
  traffic_flow->data_packets[traffic_flow->num_data_packets].packet_size = data_packet->packet_size;
  traffic_flow->data_packets[traffic_flow->num_data_packets].packet_data = data_packet->packet_data;
  traffic_flow->data_packets[traffic_flow->num_data_packets].crc = crc;
  traffic_flow->num_data_packets++;
}

// Define function to compute the CRC-32 of a string
unsigned long computeCrc32(char* str) {
  unsigned long crc = 0xFFFFFFFFUL;
  for (int i = 0; i < strlen(str); i++) {
    crc = (crc >> 8) ^ (crc_table[(unsigned char)(str[i])] ^ (crc << 24));
  }
  return ~crc;
}

// Define function to clear all allocated resources when the function completes
void clearResources() {
  // Free memory for the traffic flows
  for (int i = 0; i < num_traffic_flows; i++) {
    free((*traffic_flows)[i].traffic_name);
    free((*traffic_flows)[i].data_packets);
  }
  free(*traffic_flows);

  // Free memory for the data packets
  for (int i = 0; i < num_data_packets; i++) {
    free(data_packets[i].traffic_flow->data_packets[i].packet_data);
  }
  free(data_packets);
}
