// Define the function to handle concurrent access to shared resources safely, ensuring thread safety without significantly impacting performance
void* thread_safe_access(void* ptr, size_t size) {
  // Use a mutex to ensure that only one thread can access the shared resource at a time
  pthread_mutex_lock(&mutex);

