// Function to initialize network configuration structure
void initializeNetworkConfig(struct NetworkConfig* config) {
    // Allocate memory for the integer configuration flags array
    config->flags = (int*)malloc(sizeof(int)*MAX_CONFIG_FLAGS);
    if (!config->flags) {
        perror("Error allocating memory for network configuration flags");
        exit(EXIT_FAILURE);
    }
    // Initialize all elements of the integer configuration flags array to 0
    memset(config->flags, 0, sizeof(int)*MAX_CONFIG_FLAGS);

    // Allocate memory for the long offset values array
    config->offsets = (long*)malloc(sizeof(long)*MAX_OFFSET_VALUES);
    if (!config->offsets) {
        perror("Error allocating memory for network configuration offsets");
        exit(EXIT_FAILURE);
    }
    // Initialize all elements of the long offset values array to 0
    memset(config->offsets, 0, sizeof(long)*MAX_OFFSET_VALUES);

    // Allocate memory for the float weights array
    config->weights = (float*)malloc(sizeof(float)*MAX_WEIGHTS);
    if (!config->weights) {
        perror("Error allocating memory for network configuration weights");
        exit(EXIT_FAILURE);
    }
    // Initialize all elements of the float weights array to 0.0
    memset(config->weights, 0, sizeof(float)*MAX_WEIGHTS);

    // Allocate memory for the network connection structure array
    config->connections = (struct NetworkConnection*)malloc(sizeof(struct NetworkConnection)*MAX_CONNECTIONS);
    if (!config->connections) {
        perror("Error allocating memory for network configuration connections");
        exit(EXIT_FAILURE);
    }

    // Initialize all elements of the network connection structure array to 0
    memset(config->connections, 0, sizeof(struct NetworkConnection)*MAX_CONNECTIONS);
}

// Function to deinitialize network configuration structure
