        return -1;
    }

    // Read and store the contents of the resource bundle file in the struct ResourceBundle
    while ((fgets(bundle->contents, MAX_BUNDLE_SIZE, fp)) != NULL) {
        // Parse the current line from the resource bundle file
        parseResourceLine(bundle);
    }

    // Close the file pointer to the resource bundle file
