    for (int i = 0; i < MAX_ELEMENTS; i++) {
        struct Element* element = config->elements[i];
        if (element->type == element_type) {
            // Test the current element's class or ID against the user-provided function
            bool match = checkElementMatch(element, element_type);

            if (match) {
                // Add the current element to the list of matching elements
                addToList(matching_elements, element);
            }
        }
    }

    return matching_elements;
}

