        printf("Error: Failed to allocate memory for dynamically allocated path\n");
        return NULL;
    }

    // Use the realpath() function from <stdlib.h> to resolve the file path
    char* resolved_path = realpath(path, NULL);
    if (!resolved_path) {
        printf("Error: Failed to resolve dynamically allocated path\n");
        free(path);
        return NULL;
    }

    // Use the stat() function from <sys/stat.h> to validate the existence and accessibility of the file
    struct stat st;
    if (stat(resolved_path, &st) == -1) {
        printf("Error: Failed to validate dynamically allocated path\n");
        free(resolved_path);
        return NULL;
    }

    // Return the validated path as a char*
    return resolved_path;
}

// Function to validate the existence and accessibility of the dynamically allocated file paths
void validate_paths(data_entry* entries, size_t size) {
    for (size_t i = 0; i < size; i++) {
        data_entry* entry = &entries[i];
        if (entry->path != NULL) {
            // Use the realpath() function from <stdlib.h> to resolve the file path
            char* resolved_path = realpath(entry->path, NULL);
            if (!resolved_path) {
                printf("Error: Failed to validate dynamically allocated path\n");
                free(entry->path);
                entry->path = NULL;
            } else {
                // Use the stat() function from <sys/stat.h> to validate the existence and accessibility of the file
                struct stat st;
                if (stat(resolved_path, &st) == -1) {
                    printf("Error: Failed to validate dynamically allocated path\n");
                    free(resolved_path);
                    entry->path = NULL;
                }
            }
        }
    }
}

int main() {
