#include <pthread.h>

// Define a structure to hold the UE context and RRC connection reconfiguration messages
typedef struct {
    int ue_id; // Unique identifier for each UE context
    int num_rrc_msg; // Number of RRC connection reconfiguration messages stored
    RRC_Connection_Reconfiguration *rrc_msgs[]; // Array to hold the RRC connection reconfiguration messages
    NAS_Message nas_msg; // NAS message associated with this UE context
} UEContext;

// Define a structure to hold the list of UE contexts and their corresponding RRC connection reconfiguration messages
typedef struct {
    int num_ue_contexts; // Number of UE contexts in the list
    UEContext *ue_contexts[]; // Array to hold the UE contexts and their corresponding RRC connection reconfiguration messages
} UEContextList;

// Define a function to initialize the UE context list and allocate memory for the NAS message content
void initializeUEContexts(UEContextList *list) {
    // Allocate memory for the UE context list
    list = (UEContextList *)malloc(sizeof(UEContextList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for UE context list\n");
        exit(1);
    }
    // Initialize the number of UE contexts in the list to 0
    list->num_ue_contexts = 0;
    // Allocate memory for the array of UE contexts
    list->ue_contexts = (UEContext *)malloc(sizeof(UEContext) * INITIAL_NUM_UE_CONTEXTS);
    if (!list->ue_contexts) {
        fprintf(stderr, "Failed to allocate memory for array of UE contexts\n");
        exit(1);
    }
}

// Define a function to add a new UE context to the list and allocate memory for the NAS message content
void addUEContext(UEContextList *list, int ue_id) {
    // Check if the list has enough capacity to hold the new UE context
    if (list->num_ue_contexts >= MAX_NUM_UE_CONTEXTS) {
        fprintf(stderr, "Failed to add new UE context: list is full\n");
        return;
    }
    // Allocate memory for the new UE context
    UEContext *new_ue_context = (UEContext *)malloc(sizeof(UEContext));
    if (!new_ue_context) {
        fprintf(stderr, "Failed to allocate memory for new UE context\n");
        return;
    }
    // Initialize the new UE context and its corresponding RRC connection reconfiguration messages
    new_ue_context->ue_id = ue_id;
    new_ue_context->num_rrc_msg = 0;
    new_ue_context->rrc_msgs = (RRC_Connection_Reconfiguration *)malloc(sizeof(RRC_Connection_Reconfiguration) * INITIAL_NUM_RRC_MSGS);
    if (!new_ue_context->rrc_msgs) {
        fprintf(stderr, "Failed to allocate memory for new UE context's RRC connection reconfiguration messages\n");
        return;
    }
    // Add the new UE context to the list and increment the number of UE contexts
    list->ue_contexts[list->num_ue_contexts++] = new_ue_context;
}

// Define a function to remove an existing UE context from the list and free its memory
void removeUEContext(UEContextList *list, int ue_id) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to remove UE context: not found\n");
        return;
    }
    // Free the memory for the UE context and its corresponding RRC connection reconfiguration messages
    free(list->ue_contexts[index]);
    list->ue_contexts[index] = NULL;
    // Decrement the number of UE contexts in the list
    list->num_ue_contexts--;
}

// Define a function to find the index of an existing UE context in the list by its unique identifier
int findUEContextIndex(UEContextList *list, int ue_id) {
    for (int i = 0; i < list->num_ue_contexts; i++) {
        if (list->ue_contexts[i]->ue_id == ue_id) {
            return i;
        }
    }
    // UE context not found
    return -1;
}

// Define a function to add a new RRC connection reconfiguration message for an existing UE context in the list
void addRRCMessage(UEContextList *list, int ue_id, RRC_Connection_Reconfiguration *msg) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to add RRC message: UE context not found\n");
        return;
    }
    // Check if the UE context has enough capacity to hold the new RRC connection reconfiguration message
    if (list->ue_contexts[index]->num_rrc_msg >= MAX_NUM_RRC_MSGS) {
        fprintf(stderr, "Failed to add RRC message: list is full\n");
        return;
    }
    // Allocate memory for the new RRC connection reconfiguration message
    list->ue_contexts[index]->rrc_msgs[list->ue_contexts[index]->num_rrc_msg++] = msg;
}

// Define a function to remove an existing RRC connection reconfiguration message from an existing UE context in the list and free its memory
void removeRRCMessage(UEContextList *list, int ue_id, int msg_index) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to remove RRC message: UE context not found\n");
        return;
    }
    // Check if the specified RRC connection reconfiguration message exists in the UE context
    if (msg_index >= list->ue_contexts[index]->num_rrc_msg) {
        fprintf(stderr, "Failed to remove RRC message: index out of range\n");
        return;
    }
    // Free the memory for the RRC connection reconfiguration message
    free(list->ue_contexts[index]->rrc_msgs[msg_index]);
    list->ue_contexts[index]->rrc_msgs[msg_index] = NULL;
    // Decrement the number of RRC connection reconfiguration messages in the UE context
    list->ue_contexts[index]->num_rrc_msg--;
}

// Define a function to encode the NAS message associated with an existing UE context in the list
bool encodeNASMessage(UEContextList *list, int ue_id, char **encoded) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to encode NAS message: UE context not found\n");
        return false;
    }
    // Check if the UE context has a NAS message associated with it
    if (!list->ue_contexts[index]->nas_msg.is_set) {
        fprintf(stderr, "Failed to encode NAS message: NAS message not found\n");
        return false;
    }
    // Allocate memory for the encoded NAS message content
    *encoded = (char *)malloc(sizeof(char) * list->ue_contexts[index]->nas_msg.len);
    if (!*encoded) {
        fprintf(stderr, "Failed to allocate memory for encoded NAS message\n");
        return false;
    }
    // Encode the NAS message content and store it in the encoded buffer
    memcpy(*encoded, list->ue_contexts[index]->nas_msg.content, list->ue_contexts[index]->nas_msg.len);
    return true;
}

// Define a function to validate the NAS message associated with an existing UE context in the list
bool validateNASMessage(UEContextList *list, int ue_id) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to validate NAS message: UE context not found\n");
        return false;
    }
    // Check if the UE context has a NAS message associated with it
    if (!list->ue_contexts[index]->nas_msg.is_set) {
        fprintf(stderr, "Failed to validate NAS message: NAS message not found\n");
        return false;
    }
    // Validate the NAS message content and return the result
    return nas_validate_message(list->ue_contexts[index]->nas_msg.content);
}

// Define a function to associate a unique identifier with an existing NAS message in the list
void setNASMessageIdentifier(UEContextList *list, int ue_id) {
    // Find the index of the UE context in the list
    int index = findUEContextIndex(list, ue_id);
    if (index < 0) {
        fprintf(stderr, "Failed to set NAS message identifier: UE context not found\n");
        return;
    }
    // Check if the UE context has a NAS message associated with it
    if (!list->ue_contexts[index]->nas_msg.is_set) {
        fprintf(stderr, "Failed to set NAS message identifier: NAS message not found\n");
        return;
    }
    // Generate a unique identifier for the NAS message and store it in the UE context
    list->ue_contexts[index]->nas_msg.identifier = generate_unique_identifier();
}

// Define a function to free all memory allocated by the UE context list and its elements
void destroyUEContextList(UEContextList *list) {
    // Iterate over the array of UE contexts in the list
    for (int i = 0; i < list->num_ue_contexts; i++) {
        if (!list->ue_contexts[i]) {
            continue;
        }
        // Free the memory for each UE context's RRC connection reconfiguration messages and NAS message content
        free(list->ue_contexts[i]->rrc_msgs);
        list->ue_contexts[i]->rrc_msgs = NULL;
        if (list->ue_contexts[i]->nas_msg.is_set) {
            free(list->ue_contexts[i]->nas_msg.content);
            list->ue_contexts[i]->nas_msg.content = NULL;
        }
    }
    // Free the memory for the UE context list and its elements
    free(list->ue_contexts);
    list->ue_contexts = NULL;
}
