struct record {
    long offset;
    int key;
    float value;
    char status_message[10];
    double timestamp;
};

// Function to generate random values within specified ranges for each field of a record
void generate_random_values(struct record* rec) {
    // Generate long offset between 0 and 1000000
    rec->offset = (long)(rand() % 1000000);

    // Generate int key between 0 and 500
    rec->key = rand() % 500;

    // Generate float value between 0 and 1000
    rec->value = (float)(rand() % 1000) / 100;

    // Generate status message
    strcpy(rec->status_message, "OK");

    // Generate timestamp in milliseconds
    rec->timestamp = (double)time(NULL) * 1000;
}

// Function to validate generated records against predefined criteria
int validate_record(struct record* rec) {
    // Check if the offset is within a valid range
    if (rec->offset < 0 || rec->offset > 1000000) {
        return 0;
    }

    // Check if the key is within a valid range
    if (rec->key < 0 || rec->key > 500) {
        return 0;
    }

    // Check if the value is within a valid range
    if (rec->value < 0 || rec->value > 1000) {
        return 0;
    }

    // Check if the status message is valid
    if (strcmp(rec->status_message, "OK") != 0 && strcmp(rec->status_message, "ERROR") != 0) {
        return 0;
    }

    // Check if the timestamp is within a valid range
    if (rec->timestamp < 0 || rec->timestamp > 1000000) {
        return 0;
    }

    // If all validation checks pass, return 1
    return 1;
}

// Function to dynamically allocate memory for and initialize multiple arrays and structures to store various types of data
void* allocate_and_initialize_data() {
    // Define array to store pointers to records
    struct record** records = (struct record**)malloc(sizeof(struct record*) * 10);

    // Initialize each record with random values within specified ranges
    for (int i = 0; i < 10; i++) {
        records[i] = malloc(sizeof(struct record));
        generate_random_values(records[i]);
    }

    // Validate each record against predefined criteria
    int valid_records = 0;
    for (int i = 0; i < 10; i++) {
        if (validate_record(records[i])) {
            valid_records++;
        }
    }

    // If all records are valid, return pointer to array of pointers to valid records
    if (valid_records == 10) {
        return records;
    } else {
        // Otherwise, free memory for invalid records and return NULL
        for (int i = 0; i < 10; i++) {
            if (!validate_record(records[i])) {
                free(records[i]);
            }
        }
        return NULL;
    }
}
