        int found = hash_table_find(messages[i].chq_tag.hash_table, cell_id);
        pthread_rwlock_unlock(&messages[i].chq_tag.rwlock);
        if (found) {
            // retry with a new cell ID if the current one is already in use
            i--;
            continue;
