// Define the maximum number of connections to be managed by the function
#define MAX_CONNECTIONS 100

// Define the structure for storing NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

