// Define the function to establish and manage a persistent connection
void* connect(void *arg) {
    // Cast the argument to a string
    char *connection_string = (char*) arg;

    // Initialize the semaphore for synchronizing access to the shared data structures
    sem_t *sem = sem_open("connect", O_CREAT, 0644, MAX_CONNECTIONS);

    // Loop until a connection is established or an error occurs
    while (1) {
        // Acquire the semaphore to synchronize access to the shared data structures
        if (sem_wait(sem) == -1) {
            printf("Error acquiring semaphore: %s\n", strerror(errno));
            break;
        }

        // Create a new NFAPI_CRC_INDICATION_PDU_T structure and populate it with random data
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu->CRCFLAG = (unsigned short) rand() % 65536;

        // Create a new array for long offset values and initialize it with random data
        long_t *offset_values = (long_t*) malloc(sizeof(long_t) * MAX_CONNECTIONS);
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            offset_values[i].value = rand() % 100000;
        }

        // Create a new array for int keys and initialize it with random data
        int_t *key_values = (int_t*) malloc(sizeof(int_t) * MAX_CONNECTIONS);
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            key_values[i].key = rand() % 100000;
