        // Create a new array of record structures and initialize it with random data
        record_t *record_data = (record_t*) malloc(sizeof(record_t) * MAX_CONNECTIONS);
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            record_data[i].value = rand() % 100000;
        }

        // Release the semaphore to release the shared data structures
        if (sem_post(sem) == -1) {
            printf("Error releasing semaphore: %s\n", strerror(errno));
            break;
        }
    }

    // Close the semaphore and return
    sem_close(sem);
    return NULL;
}

int main() {
    // Create a thread for each connection to be managed
    pthread_t threads[MAX_CONNECTIONS];

    // Loop through each thread and start it
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pthread_create(&threads[i], NULL, connect, (void*) "connection string") != 0) {
            printf("Error creating thread: %s\n", strerror(errno));
            break;
        }
    }

    // Join each thread to ensure they have completed
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            printf("Error joining thread: %s\n", strerror(errno));
            break;
        }
    }

    return 0;
}
