    int *key_array = malloc(sizeof(int) * array_size);

    if (offset_array == NULL || key_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset and key arrays\n");
        return 0;
    }

    // Populate the offset and key arrays with values within their respective ranges
    srand(time(NULL));
    for (int i = 0; i < array_size; i++) {
