        key_array[i] = rand() % (key_max - key_min + 1) + key_min;
    }

    // Allocate and initialize the record array with a size equal to array_size
    Record *record_array = malloc(sizeof(Record) * array_size);

    if (record_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return 0;
    }

