// Structure to hold UE context information
typedef struct UEContext {
    char *ueId;
    size_t numRRCConnections;
    RRCConnectionReconfiguration **rrcConnections;
} UEContext;

// Structure to hold RRC connection reconfiguration message
typedef struct RRCConnectionReconfiguration {
    NASMessage *nasMsg;
    char *ueId;
} RRCConnectionReconfiguration;

// Structure to hold NAS message information
typedef struct NASMessage {
    size_t length;
    uint8_t *content;
} NASMessage;

// Structure to hold encryption configuration options
typedef struct EncryptionConfig {
    bool useSymmetricEncryption;
    bool useAsymmetricEncryption;
    bool usePBKDF2;
    bool useCBCMode;
    bool useGCMMode;
    char *symmetricEncryptionAlgorithm;
    char *hashFunction;
