// Structure to hold encryption context information
typedef struct EncryptionContext {
    size_t numUEContexts;
    UEContext **ueContexts;
    NASMessage **nasMessages;
} EncryptionContext;

// Function to initialize the UE contexts and NAS messages
void initializeUEContexts(EncryptionConfig *config, int numUEs) {
    // Allocate memory for the UE contexts
    UEContext *ueContexts = (UEContext *)malloc(sizeof(UEContext) * numUEs);
    if (!ueContexts) {
        printf("Error: failed to allocate memory for UE contexts\n");
        return;
    }

    // Initialize the UE contexts
    for (int i = 0; i < numUEs; i++) {
        ueContexts[i].ueId = NULL;
        ueContexts[i].numRRCConnections = 0;
        ueContexts[i].rrcConnections = NULL;
    }

    // Allocate memory for the NAS messages
    NASMessage *nasMessages = (NASMessage *)malloc(sizeof(NASMessage) * numUEs);
    if (!nasMessages) {
        printf("Error: failed to allocate memory for NAS messages\n");
        free(ueContexts);
        return;
    }

    // Initialize the NAS messages
    for (int i = 0; i < numUEs; i++) {
        nasMessages[i].length = 0;
        nasMessages[i].content = NULL;
    }

    // Create the encryption context
    EncryptionContext *encryptionContext = (EncryptionContext *)malloc(sizeof(EncryptionContext));
    if (!encryptionContext) {
        printf("Error: failed to create encryption context\n");
        free(ueContexts);
        free(nasMessages);
        return;
    }

    // Initialize the encryption context
    encryptionContext->numUEContexts = numUEs;
    encryptionContext->ueContexts = ueContexts;
    encryptionContext->nasMessages = nasMessages;

    // Return the encryption context
    return encryptionContext;
}

// Function to add a new RRC connection reconfiguration message to the UE context
void addRRCConnectionReconfiguration(EncryptionContext *encryptionContext, char *ueId, RRCConnectionReconfiguration *rrcConnection) {
    // Find the UE context with the given ID
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, create a new one
    if (ueIndex == encryptionContext->numUEContexts) {
        UEContext *newUEContext = (UEContext *)malloc(sizeof(UEContext));
        newUEContext->ueId = ueId;
        newUEContext->numRRCConnections = 1;
        newUEContext->rrcConnections = (RRCConnectionReconfiguration **)malloc(sizeof(RRCConnectionReconfiguration *));
        if (!newUEContext->rrcConnections) {
            printf("Error: failed to allocate memory for RRC connection reconfigurations\n");
            return;
        }
        newUEContext->rrcConnections[0] = rrcConnection;
        encryptionContext->numUEContexts++;
        encryptionContext->ueContexts = (UEContext *)realloc(encryptionContext->ueContexts, sizeof(UEContext) * encryptionContext->numUEContexts);
        encryptionContext->ueContexts[ueIndex] = newUEContext;
    } else {
        // If the UE context was found, add the RRC connection reconfiguration message to it
        UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
        ueContext->numRRCConnections++;
        ueContext->rrcConnections = (RRCConnectionReconfiguration **)realloc(ueContext->rrcConnections, sizeof(RRCConnectionReconfiguration *) * ueContext->numRRCConnections);
        if (!ueContext->rrcConnections) {
            printf("Error: failed to allocate memory for RRC connection reconfigurations\n");
            return;
        }
        ueContext->rrcConnections[ueContext->numRRCConnections - 1] = rrcConnection;
    }
}

// Function to remove a RRC connection reconfiguration message from the UE context
void removeRRCConnectionReconfiguration(EncryptionContext *encryptionContext, char *ueId, int index) {
    // Find the UE context with the given ID and index
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, return
    if (ueIndex == encryptionContext->numUEContexts) {
        printf("Error: UE context not found\n");
        return;
    }

    // Remove the RRC connection reconfiguration message from the UE context
    UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
    if (index >= ueContext->numRRCConnections) {
        printf("Error: index out of bounds\n");
        return;
    }
    for (int i = index; i < ueContext->numRRCConnections - 1; i++) {
        ueContext->rrcConnections[i] = ueContext->rrcConnections[i + 1];
    }
    ueContext->numRRCConnections--;

    // If there are no more RRC connection reconfiguration messages for the UE context, remove it
    if (ueContext->numRRCConnections == 0) {
        free(ueContext);
        encryptionContext->numUEContexts--;
        encryptionContext->ueContexts = (UEContext *)realloc(encryptionContext->ueContexts, sizeof(UEContext) * encryptionContext->numUEContexts);
    }
}

// Function to add a new NAS message to the UE context
void addNASMessage(EncryptionContext *encryptionContext, char *ueId, NASMessage *nasMsg) {
    // Find the UE context with the given ID
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

