        newUEContext->ueId = ueId;
        newUEContext->numRRCConnections = 0;
        newUEContext->rrcConnections = NULL;
        encryptionContext->numUEContexts++;
        encryptionContext->ueContexts = (UEContext *)realloc(encryptionContext->ueContexts, sizeof(UEContext) * encryptionContext->numUEContexts);
        encryptionContext->ueContexts[ueIndex] = newUEContext;
    }

    // Add the NAS message to the UE context
    UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
    ueContext->numNASMessages++;
    ueContext->nasMessages = (NASMessage *)realloc(ueContext->nasMessages, sizeof(NASMessage) * ueContext->numNASMessages);
    if (!ueContext->nasMessages) {
        printf("Error: failed to allocate memory for NAS messages\n");
