// Function to encrypt the NAS message for a specific UE context
bool encryptNASMessage(EncryptionContext *encryptionContext, char *ueId) {
    // Find the UE context with the given ID
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, return false
    if (ueIndex == encryptionContext->numUEContexts) {
        printf("Error: UE context not found\n");
        return false;
    }

    // Encrypt the NAS message for the UE context
    UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
    NASMessage *nasMsg = ueContext->nasMessages[0];
    size_t length = nasMsg->length;
    uint8_t *content = (uint8_t *)malloc(sizeof(uint8_t) * length);
    if (!content) {
        printf("Error: failed to allocate memory for NAS message content\n");
        return false;
    }
    memcpy(content, nasMsg->content, length);
    bool success = encryptContent(encryptionContext, ueId, content, length);
    if (!success) {
        printf("Error: failed to encrypt NAS message content\n");
        free(content);
        return false;
    }
    nasMsg->length = length;
    nasMsg->content = content;
    return true;
}

// Function to decrypt the NAS message for a specific UE context
bool decryptNASMessage(EncryptionContext *encryptionContext, char *ueId) {
    // Find the UE context with the given ID
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, return false
