        printf("Error: UE context not found\n");
        return false;
    }

    // Decrypt the NAS message for the UE context
    UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
    NASMessage *nasMsg = ueContext->nasMessages[0];
    size_t length = nasMsg->length;
    uint8_t *content = (uint8_t *)malloc(sizeof(uint8_t) * length);
    if (!content) {
        printf("Error: failed to allocate memory for NAS message content\n");
        return false;
    }
    bool success = decryptContent(encryptionContext, ueId, content, length);
    if (!success) {
        printf("Error: failed to decrypt NAS message content\n");
        free(content);
        return false;
    }
    nasMsg->length = length;
    nasMsg->content = content;
    return true;
}

// Function to encrypt the content for a specific UE context using the given encryption configuration
bool encryptContent(EncryptionContext *encryptionContext, char *ueId, uint8_t *content, size_t length) {
    // Find the UE context with the given ID and encryption configuration
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, return false
    if (ueIndex == encryptionContext->numUEContexts) {
        printf("Error: UE context not found\n");
        return false;
    }

    // Encrypt the content for the UE context using the given encryption configuration
    UEContext *ueContext = encryptionContext->ueContexts[ueIndex];
    EncryptionConfig *encryptionConfig = &ueContext->encryptionConfig;
    switch (encryptionConfig->algorithm) {
        case AES_CBC: {
            size_t keyLength = encryptionConfig->key.length;
            uint8_t *iv = encryptionConfig->iv;
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            bool success = EVP_EncryptInit(ctx, EVP_aes_128_cbc(), encryptionConfig->key.content, iv) &&
                           EVP_EncryptUpdate(ctx, content, &length, content, length);
            if (!success) {
                printf("Error: failed to encrypt NAS message content\n");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            EVP_EncryptFinal(ctx, content + length, &length);
            EVP_CIPHER_CTX_free(ctx);
            break;
        }
        case AES_GCM: {
            size_t keyLength = encryptionConfig->key.length;
            uint8_t *iv = encryptionConfig->iv;
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            bool success = EVP_EncryptInit(ctx, EVP_aes_128_gcm(), encryptionConfig->key.content, iv) &&
                           EVP_EncryptUpdate(ctx, content, &length, content, length);
            if (!success) {
                printf("Error: failed to encrypt NAS message content\n");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            EVP_EncryptFinal(ctx, content + length, &length);
            EVP_CIPHER_CTX_free(ctx);
            break;
        }
    }
    return true;
}

// Function to decrypt the content for a specific UE context using the given encryption configuration
bool decryptContent(EncryptionContext *encryptionContext, char *ueId, uint8_t *content, size_t length) {
    // Find the UE context with the given ID and encryption configuration
    int ueIndex = 0;
    while (ueIndex < encryptionContext->numUEContexts && strcmp(encryptionContext->ueContexts[ueIndex].ueId, ueId)) {
        ueIndex++;
    }

    // If the UE context was not found, return false
    if (ueIndex == encryptionContext->numUEContexts) {
