    EncryptionConfig *encryptionConfig = &ueContext->encryptionConfig;
    switch (encryptionConfig->algorithm) {
        case AES_CBC: {
            size_t keyLength = encryptionConfig->key.length;
            uint8_t *iv = encryptionConfig->iv;
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            bool success = EVP_DecryptInit(ctx, EVP_aes_128_cbc(), encryptionConfig->key.content, iv) &&
                           EVP_DecryptUpdate(ctx, content, &length, content, length);
            if (!success) {
                printf("Error: failed to decrypt NAS message content\n");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            EVP_DecryptFinal(ctx, content + length, &length);
            EVP_CIPHER_CTX_free(ctx);
