            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            bool success = EVP_DecryptInit(ctx, EVP_aes_128_gcm(), encryptionConfig->key.content, iv) &&
                           EVP_DecryptUpdate(ctx, content, &length, content, length);
            if (!success) {
                printf("Error: failed to decrypt NAS message content\n");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            EVP_DecryptFinal(ctx, content + length, &length);
            EVP_CIPHER_CTX_free(ctx);
            break;
        }
    }
    return true;
}

// Function to free the memory allocated by the encryption context
void freeEncryptionContext(EncryptionContext *encryptionContext) {
    for (int i = 0; i < encryptionContext->numUEContexts; i++) {
        UEContext *ueContext = encryptionContext->ueContexts[i];
        if (ueContext->nasMessages != NULL) {
            free(ueContext->nasMessages);
        }
        if (ueContext->encryptionConfig.key.content != NULL) {
            free(ueContext->encryptionConfig.key.content);
        }
        if (ueContext->encryptionConfig.iv != NULL) {
            free(ueContext->encryptionConfig.iv);
