#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Structure to represent a record in the dataset
typedef struct {
    long timestamp;
    int key_index;
    double value;
} record;

// Function to dynamically allocate memory for and initialize multiple data structures
int init_dataset(int num_records) {
    // Allocate memory for the arrays of offsets, keys, and records
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    // Check for memory allocation failure
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: failed to allocate memory\n");
        return -1;
    }

    // Initialize the arrays of offsets, keys, and records
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
        keys[i] = i;
        records[i].timestamp = rand() % 100000; // randomize the timestamp
        records[i].key_index = i;
        records[i].value = drand48(); // initialize the value to a random floating-point number between 0.0 and 1.0
    }

    // Create a custom hash table for quick lookups based on the integer key
    struct ht *ht = malloc(sizeof(struct ht));
    if (ht == NULL) {
        printf("Error: failed to allocate memory\n");
        return -1;
    }
    ht->num_buckets = num_records;
    ht->bucket = malloc(num_records * sizeof(struct bucket));
    if (ht->bucket == NULL) {
        printf("Error: failed to allocate memory\n");
        return -1;
    }
    for (int i = 0; i < num_records; i++) {
        ht->bucket[i].key = keys[i];
        ht->bucket[i].record = records[i];
    }

    // Sort the array of records based on their timestamps in ascending order
    qsort(records, num_records, sizeof(record), compare_records);

    // Free any memory that was allocated but not used
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (ht->bucket != NULL) {
        free(ht->bucket);
    }

    return num_records;
}

// Custom hash table for quick lookups based on the integer key
struct ht {
    int num_buckets;
    struct bucket *bucket;
};

// Structure to represent a bucket in the custom hash table
struct bucket {
    int key;
    record record;
};

// Comparator function for sorting the array of records based on their timestamps
int compare_records(const void *a, const void *b) {
    return ((record *) a)->timestamp - ((record *) b)->timestamp;
}
