// Define the data structures for the NFAPI_CRC_INDICATION_PDU_T and RX_UE_INFORMATION_TAG
typedef struct {
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG *rx_ue_information_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the data structure for the record and the arrays of long and int
typedef struct {
    int value;
} record;

long *offset_array = NULL;
int *key_array = NULL;
record **records = NULL;

// Function to process a single line of the log file
void process_line(char *line) {
    // Split the line into fields based on spaces
    char *field[10];
    int num_fields = 0;
    field[num_fields++] = strtok(line, " ");
    while ((field[num_fields++] = strtok(NULL, " ")) != NULL) {}

    // Calculate the sum of all numeric fields and store the result
    long sum = 0;
    for (int i = 0; i < num_fields; i++) {
        char *endptr;
        long value = strtol(field[i], &endptr, 10);
        if (*endptr == '\0') {
            sum += value;
        }
    }

    // Identify the last two numeric fields in the line and compute their average
    int num_numerics = num_fields - 1;
    long avg = 0;
    if (num_numerics >= 2) {
        long sum_last_two = 0;
        for (int i = num_fields - 2; i < num_fields; i++) {
            char *endptr;
            long value = strtol(field[i], &endptr, 10);
            if (*endptr == '\0') {
                sum_last_two += value;
            } else {
                break;
            }
        }
        avg = sum_last_two / (num_numerics - 1);
    }

    // Replace the last field with the computed average
    if (avg > 0) {
        char buf[256];
        sprintf(buf, "%ld", avg);
        strcpy(field[num_fields - 1], buf);
    }

    // Store the modified line in a dynamically allocated array of strings
    int index = records[0].value;
    char **lines = malloc(sizeof(char *) * (index + 1));
    if (lines != NULL) {
        for (int i = 0; i < index; i++) {
            lines[i] = strdup(records[i].value);
        }
        free(records);
        records = malloc(sizeof(record *) * (index + 1));
        if (records != NULL) {
            records[index++] = malloc(sizeof(record) * (index + 1));
        }
    }
    lines[index - 1] = strdup(field);
}

// Function to handle a single connection to the remote address
void *handle_connection(void *arg) {
    // Create a socket and connect to the remote address
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return NULL;
    }
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(80);
    if (inet_pton(AF_INET, "127.0.0.1", &server.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return NULL;
    }
    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("connect");
        close(sock);
        return NULL;
    }

    // Read the data from the socket and process each line
    char *buffer = malloc(1024);
    while (read(sock, buffer, 1024) > 0) {
        char *line = strtok(buffer, "\n");
        while (line != NULL) {
            process_line(line);
            line = strtok(NULL, "\n");
        }
    }
    free(buffer);

    // Close the socket and return
    close(sock);
    pthread_exit(NULL);
}

// Function to handle multiple connections to the remote address in parallel
void handle_connections(int num_threads) {
    int i;
    for (i = 0; i < num_threads; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, handle_connection, NULL) != 0) {
            perror("pthread_create");
            return;
        }
    }
}

// Main function to process the log file and establish connections to the remote address
int main(int argc, char **argv) {
    // Check the number of arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s filename\n", argv[0]);
        return 1;
    }

    // Allocate and initialize the arrays for NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, crcflag, long offset values, int keys, and records
    NFAPI_CRC_INDICATION_PDU_T *nfapi_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024);
    RX_UE_INFORMATION_TAG *rx_ue_information_tag = malloc(sizeof(RX_UE_INFORMATION_TAG) * 1024);
    int *crcflag = malloc(sizeof(int) * 1024);
    offset_array = malloc(sizeof(long) * 1024);
    key_array = malloc(sizeof(int) * 1024);
    records = malloc(sizeof(record *) * 1024);

    // Open the log file and read each line
    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        perror("fopen");
        return 1;
    }
    char *line = malloc(1024);
    while (fgets(line, 1024, file) != NULL) {
        process_line(line);
    }
    free(line);

    // Close the log file and return
    fclose(file);
    return 0;
}
