int processAndFilterTransactions(struct Transaction** transactions, int* num_transactions) {
    // Dynamic memory allocation for the transaction array
    *transactions = (struct Transaction*)malloc(*num_transactions * sizeof(struct Transaction));
    if (*transactions == NULL) {
        return -1;  // Out of memory error
    }

    // Initialize the transactions array
    for (int i = 0; i < *num_transactions; i++) {
