    int largest_index = 0;
    for (int i = 0; i < *num_transactions; i++) {
        if (fscanf(stdin, "%ms%ms", &((*transactions)[i].tls_handshake), &((*transactions)[i].application_data)) != 2) {
            return -1;  // Error reading input
        }
        // Dynamic memory allocation for the application data
        if ((*transactions)[i].application_data == NULL) {
            (*transactions)[i].application_data = malloc(sizeof(char));
            if ((*transactions)[i].application_data == NULL) {
                return -1;  // Out of memory error
            }
        }
    }

    // Filter the transactions based on age, number of transactions in the past 3 seconds, and weighted sum
    int max_weighted_sum = INT_MIN;
    for (int i = 0; i < *num_transactions; i++) {
        if ((*transactions)[i].tls_handshake == NULL || (*transactions)[i].application_data == NULL) {
            continue;  // Skip invalid transactions
        }
        int age = calculateAge((*transactions)[i].tls_handshake);
        if (age > 3) {
            continue;  // Skip transactions older than 3 seconds
        }
        int num_past_transactions = countPastTransactions((*transactions), i, 3);
        if (num_past_transactions >= 10) {
            continue;  // Skip transactions with more than 10 past transactions
        }
        int weighted_sum = calculateWeightedSum((*transactions)[i].application_data);
        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            largest_index = i;
        }
    }

    // Log the metrics and return the maximum weighted sum
    printf("Maximum weighted sum: %d\n", max_weighted_sum);
    printf("Largest transaction ID: %d\n", (*transactions)[largest_index].tls_handshake);
    free((*transactions)[largest_index].application_data);
    free(*transactions);
    *num_transactions = 0;
    return max_weighted_sum;
}

int calculateAge(char* tls_handshake) {
    // Calculate the age of the transaction based on the TLS handshake message
    int age = 0;
    for (int i = 0; i < strlen(tls_handshake); i++) {
        if (tls_handshake[i] == ' ') {
            age++;
        }
    }
    return age;
}

int countPastTransactions(struct Transaction* transactions, int current_index, int past_seconds) {
    // Count the number of transactions in the past `past_seconds` seconds
    int count = 0;
    for (int i = 0; i < current_index; i++) {
        if (calculateAge(transactions[i].tls_handshake) <= past_seconds) {
            count++;
        }
    }
    return count;
}

int calculateWeightedSum(char* application_data) {
    // Calculate the weighted sum of the transaction based on the application data
    int weighted_sum = 0;
    for (int i = 0; i < strlen(application_data); i++) {
        if (application_data[i] == ' ') {
            weighted_sum++;
        }
    }
    return weighted_sum;
}

// Helper function to find the largest integer in an array of integers
int getLargestInteger(int* numbers, int size) {
    if (size == 0) {
        return -1;  // No input provided
    }
    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }
    return largest;
}
