// Structure to store an entry in the hash table
typedef struct {
    char* str;
    int key;
} entry_t;

// Hash table data structure
typedef struct {
    // Array of entries in the hash table
    entry_t** entries;

    // Number of slots in the hash table
    size_t num_slots;

    // Number of entries in the hash table
    size_t num_entries;

    // Mutex for synchronizing access to the hash table
    pthread_mutex_t mutex;
} hash_table_t;

// Function to initialize a new hash table
hash_table_t* init_hash_table(size_t num_slots) {
    // Allocate memory for the hash table structure
    hash_table_t* table = malloc(sizeof(hash_table_t));

    // Initialize the number of slots and entries to 0
    table->num_slots = num_slots;
    table->num_entries = 0;

    // Allocate memory for the array of entry pointers
    table->entries = malloc(sizeof(entry_t*) * num_slots);

    // Initialize each entry pointer to NULL
    for (size_t i = 0; i < num_slots; i++) {
        table->entries[i] = NULL;
    }

    // Initialize the mutex for synchronizing access to the hash table
    pthread_mutex_init(&table->mutex, NULL);

    return table;
}

// Function to insert a new entry into the hash table
void insert(hash_table_t* table, const char* str, int key) {
    // Acquire the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    // Compute the hash code for the given string and key
    size_t hash = strhash(str, key);

    // Find the first empty slot in the hash table
    size_t i;
    for (i = 0; i < table->num_slots && table->entries[i] != NULL; i++) {
        if (table->entries[i]->key == key) {
            break;
        }
    }

    // If no empty slot is found, resize the hash table and retry
    if (i == table->num_slots) {
        // Double the number of slots in the hash table
        size_t new_num_slots = table->num_slots * 2;

        // Allocate memory for the new array of entry pointers
        entry_t** new_entries = malloc(sizeof(entry_t*) * new_num_slots);

        // Copy over the old entries and initialize any new slots to NULL
        for (size_t j = 0; j < table->num_slots; j++) {
            if (table->entries[j] != NULL) {
                new_entries[j] = table->entries[j];
            } else {
                new_entries[j] = NULL;
            }
        }

        // Free the old array of entry pointers
        free(table->entries);

        // Update the hash table structure with the new array and number of slots
        table->num_slots = new_num_slots;
        table->entries = new_entries;

        // Retry the insertion process
        i = strhash(str, key) % new_num_slots;
    }

    // Allocate memory for the new entry and assign its fields
    entry_t* new_entry = malloc(sizeof(entry_t));
    new_entry->str = strdup(str);
    new_entry->key = key;

    // Insert the new entry into the hash table
    table->entries[i] = new_entry;

    // Increment the number of entries in the hash table
    table->num_entries++;

    // Release the mutex for synchronizing access to the hash table
    pthread_mutex_unlock(&table->mutex);
}

// Function to retrieve an entry from the hash table by its key
entry_t* get(hash_table_t* table, int key) {
    // Acquire the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    // Find the entry with the given key
    size_t i;
    for (i = 0; i < table->num_slots && table->entries[i] != NULL; i++) {
        if (table->entries[i]->key == key) {
            break;
        }
    }

    // Return NULL if the entry was not found
    if (i == table->num_slots) {
        pthread_mutex_unlock(&table->mutex);
        return NULL;
    }

    // Return a copy of the entry's string and release the mutex
    char* str = strdup(table->entries[i]->str);
    pthread_mutex_unlock(&table->mutex);
    return (entry_t*) {.str = str, .key = key};
}

// Function to delete an entry from the hash table by its key
void delete(hash_table_t* table, int key) {
    // Acquire the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    // Find the entry with the given key
    size_t i;
    for (i = 0; i < table->num_slots && table->entries[i] != NULL; i++) {
        if (table->entries[i]->key == key) {
            break;
        }
    }

    // Return if the entry was not found
    if (i == table->num_slots) {
        pthread_mutex_unlock(&table->mutex);
        return;
    }

    // Delete the entry from the hash table and free its memory
    entry_t* entry = table->entries[i];
    table->entries[i] = NULL;
    free(entry->str);
    free(entry);

    // Decrement the number of entries in the hash table
    table->num_entries--;

    // Release the mutex for synchronizing access to the hash table
    pthread_mutex_unlock(&table->mutex);
}

// Function to destroy a hash table
void destroy(hash_table_t* table) {
    // Acquire the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    // Free the memory allocated for the array of entry pointers
    free(table->entries);

    // Destroy the mutex for synchronizing access to the hash table
    pthread_mutex_destroy(&table->mutex);

    // Release the mutex for synchronizing access to the hash table
    pthread_mutex_unlock(&table->mutex);
}
