// Define hash table data structure and operations
typedef struct {
    int size;
    int capacity;
    record **buckets;
} hash_table;

void create_hash_table(hash_table *ht) {
    ht->size = 0;
    ht->capacity = 16; // initial capacity
    ht->buckets = (record**)malloc(sizeof(record*) * ht->capacity);
}

void add_to_hash_table(hash_table *ht, record *r) {
    int index = r->key_index % ht->capacity;
    if (ht->buckets[index] == NULL) {
        ht->size++;
    }
    ht->buckets[index] = r;
}

record* get_from_hash_table(hash_table *ht, int key_index) {
    int index = key_index % ht->capacity;
    return ht->buckets[index];
}

// Define memory management functions
void free_records(record **recs, int count) {
    for (int i = 0; i < count; i++) {
        free(recs[i]);
    }
    free(recs);
}

void free_hash_table(hash_table *ht) {
    free_records(ht->buckets, ht->size);
}

// Define error handling functions
int handle_error(const char* msg, int line_no) {
    fprintf(stderr, "%s (line %d): %s\n", __FILE__, line_no, msg);
    return -1;
}

// Implement memory management and error handling in a thread-safe manner
void* memory_thread_func(void *args) {
    hash_table *ht = (hash_table*)args;
    while (true) {
        // Acquire lock before accessing shared data structures
        pthread_mutex_lock(&ht->lock);
        if (ht->size > 0) {
            record *r = ht->buckets[ht->size - 1];
            free(r);
            ht->size--;
            // Release lock after updating shared data structures
            pthread_mutex_unlock(&ht->lock);
        } else {
            pthread_cond_wait(&ht->cv, &ht->lock);
        }
    }
}

int main(int argc, char **argv) {
    // Declare and initialize data structures
    hash_table ht;
    create_hash_table(&ht);
    pthread_mutex_init(&ht.lock, NULL);
    pthread_cond_init(&ht.cv, NULL);
    pthread_t memory_thread;
    pthread_create(&memory_thread, NULL, memory_thread_func, &ht);

    // Declare and initialize input sources
