    int (*sorting_func)(void*, size_t, size_t, compare_records) = NULL;
    if (strcmp(argv[3], "quick") == 0) {
        sorting_func = quicksort;
    } else if (strcmp(argv[3], "merge") == 0) {
        sorting_func = mergesort;
    }

    // Declare and initialize input data processing loop
    while (true) {
        char *buffer = malloc(BUFFER_SIZE);
        ssize_t read_bytes = read(file_descriptor, buffer, BUFFER_SIZE);
        if (read_bytes < 0) {
            handle_error("failed to read from input file", __LINE__);
        } else if (read_bytes == 0) {
            break;
        }
        // Declare and initialize output data structure
        record *records = (record*)malloc(sizeof(record) * read_bytes);
        int count = 0;
        for (int i = 0; i < read_bytes; i++) {
            char* encryption_key = buffer[i];
            // Decrypt input data using encryption algorithm if applicable
