            long timestamp = 0;
            int key_index = 0;
            double value = 0.0;
            // Insert record into hash table for quick lookup
            add_to_hash_table(&ht, &records[count]);
            count++;
        }
        // Sort output data structure using sorting algorithm if applicable
        if (sorting_func != NULL) {
            qsort(records, count, sizeof(record), compare_records);
        }
        // Print output data structure to standard output
        for (int i = 0; i < count; i++) {
