  printf("%s\n", message);

// Struct for records
typedef struct record {
  int key;
  long timestamp;
  char* value;
} Record;

// Function to create a new record
Record* create_record(int key, long timestamp, char* value) {
  Record* record = malloc(sizeof(Record));
  CHECK_ERROR(record == NULL, "Failed to allocate memory for new record");

  record->key = key;
  record->timestamp = timestamp;
  record->value = strdup(value);

  return record;
}

// Function to free a record
void free_record(Record* record) {
  free(record->value);
  free(record);
}

// Function to add a new record to the dataset
void add_record(int key, long timestamp, char* value) {
  Record* record = create_record(key, timestamp, value);
  pthread_mutex_lock(&mutex);

  // Check if we need to resize the array
  if (num_records == capacity) {
    // Resize the array by 50%
    capacity *= 1.5;
    Record** new_records = realloc(records, sizeof(Record*) * capacity);
    CHECK_ERROR(new_records == NULL, "Failed to resize dataset");
    records = new_records;
  }

  // Add the record to the end of the array
  records[num_records++] = record;
  pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the dataset
void remove_record(int key) {
  pthread_mutex_lock(&mutex);

  // Find the index of the record with the given key
  int i;
  for (i = 0; i < num_records; i++) {
    if (records[i]->key == key) {
      break;
    }
  }

  // If the record was not found, return
  if (i == num_records) {
    pthread_mutex_unlock(&mutex);
    return;
  }

  // Remove the record from the array by swapping it with the last element and decreasing the size
  Record* tmp = records[--num_records];
  records[i] = records[num_records];
  free(tmp);

  pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record from the dataset
Record* get_record(int key) {
  pthread_mutex_lock(&mutex);

  // Find the index of the record with the given key
  int i;
  for (i = 0; i < num_records; i++) {
    if (records[i]->key == key) {
      break;
    }
  }

  // If the record was not found, return NULL
  Record* record = records[i];
  pthread_mutex_unlock(&mutex);
  return record;
}

// Function to sort the dataset by timestamp
void sort_records() {
  // Create a copy of the array to avoid concurrent modifications
  Record** sorted_records = malloc(sizeof(Record*) * num_records);
  memcpy(sorted_records, records, sizeof(Record*) * num_records);

  // Sort the array using quicksort and insertion sort
  int i;
  for (i = 0; i < num_records - 1; i++) {
    if (sorted_records[i]->timestamp > sorted_records[i + 1]->timestamp) {
      Record* tmp = sorted_records[i];
      sorted_records[i] = sorted_records[i + 1];
      sorted_records[i + 1] = tmp;
    } else if (sorted_records[i]->timestamp == sorted_records[i + 1]->timestamp) {
      int j;
      for (j = i + 2; j < num_records; j++) {
        if (sorted_records[j - 1]->timestamp > sorted_records[j]->timestamp) {
          Record* tmp = sorted_records[j - 1];
          sorted_records[j - 1] = sorted_records[j];
          sorted_records[j] = tmp;
        } else {
          break;
        }
      }
    }
  }

  // Swap the original array with the sorted one
  pthread_mutex_lock(&mutex);
  memcpy(records, sorted_records, sizeof(Record*) * num_records);
  pthread_mutex_unlock(&mutex);
}

// Function to retrieve the size of the dataset
int get_size() {
  int size;
  pthread_mutex_lock(&mutex);
  size = num_records;
  pthread_mutex_unlock(&mutex);
  return size;
}

// Function to retrieve the timestamp of the oldest record in the dataset
long get_oldest_timestamp() {
  long timestamp;
  pthread_mutex_lock(&mutex);
  if (num_records > 0) {
    timestamp = records[0]->timestamp;
  } else {
    timestamp = 0;
  }
  pthread_mutex_unlock(&mutex);
  return timestamp;
}

// Function to retrieve the timestamp of the newest record in the dataset
long get_newest_timestamp() {
  long timestamp;
  pthread_mutex_lock(&mutex);
  if (num_records > 0) {
    timestamp = records[num_records - 1]->timestamp;
  } else {
    timestamp = 0;
  }
  pthread_mutex_unlock(&mutex);
  return timestamp;
}

// Function to retrieve the value of a specific record in the dataset
char* get_value(int key) {
  Record* record = get_record(key);
  char* value = NULL;
  if (record != NULL) {
    value = strdup(record->value);
  }
  return value;
}
