// Custom memory pool for efficient transaction allocation and reuse
typedef struct {
    size_t capacity;  // total number of transactions in the pool
    size_t free;      // number of free transactions in the pool
    void **transactions;  // array of transaction pointers
} mempool_t;

// initialize a memory pool with a given capacity
static int mempool_init(mempool_t *pool, size_t capacity) {
    if (capacity == 0) {
        return -1;
    }
    pool->capacity = capacity;
    pool->free = capacity;
    pool->transactions = calloc(capacity, sizeof(void*));
    return 0;
}

// destroy a memory pool and release all allocated transactions
static int mempool_destroy(mempool_t *pool) {
    free(pool->transactions);
    pool->transactions = NULL;
    return 0;
}

// allocate a transaction from the memory pool
static void* mempool_alloc(mempool_t *pool) {
    if (pool->free == 0) {
        return NULL;
    }
    pool->free--;
    return pool->transactions[pool->free];
}

// deallocate a transaction back to the memory pool
static void mempool_dealloc(mempool_t *pool, void *transaction) {
    if (pool->free == pool->capacity) {
        return;
    }
    pool->transactions[pool->free++] = transaction;
}

