    while (transaction_count < capacity) {
        transaction_t *transaction = mempool_alloc(&pool);
        if (!transaction) {
            break;
        }
        transaction->id = generate_unique_id(transaction_count);
        transaction->amount = 0.0;
        transaction->location.latitude = 0.0f;
        transaction->location.longitude = 0.0f;
        array[transaction_count++] = transaction;
    }

    // handle transactions concurrently using pthreads
    pthread_t threads[16];
    for (size_t i = 0; i < 16; i++) {
        if (pthread_create(&threads[i], NULL, handle_transaction, &pool)) {
            printf("Error: failed to create thread %zu\n", i);
            return;
        }
    }
    for (size_t i = 0; i < 16; i++) {
        if (pthread_join(threads[i], NULL)) {
            printf("Error: failed to join thread %zu\n", i);
            return;
        }
    }

    // free all transactions back to the memory pool
    for (size_t i = 0; i < transaction_count; i++) {
        mempool_dealloc(&pool, array[i]);
    }

    // destroy the memory pool and release all allocated transactions
    mempool_destroy(&pool);
}

// generate a unique ID for each transaction based on its index
static char* generate_unique_id(size_t index) {
    static char alphabet[] = "abcdefghijklmnopqrstuvwxyz";
    size_t id_len = 10;
    char *id = malloc(id_len + 1);
    if (!id) {
        return NULL;
    }
    for (size_t i = 0; i < id_len - 1; i++) {
        id[i] = alphabet[index % 26];
        index /= 26;
    }
    id[id_len - 1] = '\0';
    return id;
}

// handle a single transaction concurrently using a pthread
void* handle_transaction(void *arg) {
    mempool_t *pool = (mempool_t*)arg;
    while (true) {
        transaction_t *transaction = mempool_alloc(pool);
        if (!transaction) {
            break;
        }
