#include <pthread.h>

// Define a struct to represent a record in the hash table
struct Record {
    int key;
    char *value;
};

// Define a linked list node for the dynamic resizing strategy
struct Node {
    struct Record *record;
    struct Node *next;
};

// Define a hash table with separate chaining
struct HashTable {
    struct Node **buckets;
    int bucket_count;
    int record_count;
    pthread_mutex_t mutex;
};

// Function to initialize the hash table
void init_hash_table(struct HashTable *ht) {
    ht->bucket_count = 16; // Initial number of buckets
    ht->record_count = 0; // Initial number of records
    ht->buckets = malloc(sizeof(struct Node *) * ht->bucket_count);
    for (int i = 0; i < ht->bucket_count; i++) {
        ht->buckets[i] = NULL;
    }
}

// Function to insert a record into the hash table
void insert(struct HashTable *ht, int key, char *value) {
    // Calculate the bucket index for the given key
    int bucket_index = key % ht->bucket_count;

    // Check if there is already a record in this bucket
    if (ht->buckets[bucket_index] != NULL) {
        struct Node *node = ht->buckets[bucket_index];
        while (node != NULL) {
            if (node->record->key == key) {
                // Record already exists, update the value
                free(node->record->value);
                node->record->value = strdup(value);
                return;
            }
            node = node->next;
        }
    }

    // No record found, allocate a new one and insert it
    struct Node *node = malloc(sizeof(struct Node));
    node->record = malloc(sizeof(struct Record));
    node->record->key = key;
    node->record->value = strdup(value);
    node->next = ht->buckets[bucket_index];
    ht->buckets[bucket_index] = node;

    // Increment the record count
    ht->record_count++;
}

// Function to delete a record from the hash table
void delete(struct HashTable *ht, int key) {
    // Calculate the bucket index for the given key
    int bucket_index = key % ht->bucket_count;

    // Check if there is already a record in this bucket
    if (ht->buckets[bucket_index] != NULL) {
        struct Node *node = ht->buckets[bucket_index];
        while (node != NULL) {
            if (node->record->key == key) {
                // Record found, delete it
                free(node->record->value);
                free(node->record);
                node->next = NULL;
                ht->record_count--;
                return;
            }
            node = node->next;
        }
    }
}

// Function to lookup a record in the hash table
struct Record *lookup(struct HashTable *ht, int key) {
    // Calculate the bucket index for the given key
    int bucket_index = key % ht->bucket_count;

    // Check if there is already a record in this bucket
    if (ht->buckets[bucket_index] != NULL) {
        struct Node *node = ht->buckets[bucket_index];
        while (node != NULL) {
            if (node->record->key == key) {
                // Record found, return it
                return node->record;
            }
            node = node->next;
        }
    }
    return NULL;
}

// Function to resize the hash table when it gets too full
void resize(struct HashTable *ht) {
    // Calculate the new bucket count and allocate memory for the new buckets
    int new_bucket_count = ht->bucket_count * 2;
    struct Node **new_buckets = malloc(sizeof(struct Node *) * new_bucket_count);
    for (int i = 0; i < new_bucket_count; i++) {
        new_buckets[i] = NULL;
    }

    // Move all the records from the old buckets to the new ones
    for (int i = 0; i < ht->bucket_count; i++) {
        struct Node *node = ht->buckets[i];
        while (node != NULL) {
            int new_bucket_index = node->record->key % new_bucket_count;
            struct Node *new_node = malloc(sizeof(struct Node));
            new_node->record = node->record;
            new_node->next = new_buckets[new_bucket_index];
            new_buckets[new_bucket_index] = new_node;
            node = node->next;
        }
    }

    // Free the old buckets and update the hash table with the new ones
    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->bucket_count = new_bucket_count;
}

// Function to handle memory allocation failures gracefully
void handle_alloc_failure() {
    // Handle the failure by logging an error message and exiting the program
    printf("Memory allocation failed! Exiting...\n");
    exit(1);
}

// Function to validate and sanitize key inputs
int validate_key(int key) {
    if (key < 0) {
        return -1;
    }
    // Sanitize the key by ensuring it's positive and less than the bucket count
    return key % ht->bucket_count;
}
