int populate_arrays(const char* hostname, long* offset_array, int* key_array, record** record_array) {
    // Initialize random number generator
    srand(time(NULL));

    // Get DNS resolution for the given hostname
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_DGRAM;
    struct addrinfo* res;
    int error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", gai_strerror(error));
        return -1;
    }

    // Allocate memory for the offset and key arrays
    size_t num_records = res->ai_addrlen / sizeof(struct in_addr);
    *offset_array = (long*)malloc(num_records * sizeof(long));
    if (*offset_array == NULL) {
        freeaddrinfo(res);
        return -1;
    }
    *key_array = (int*)malloc(num_records * sizeof(int));
    if (*key_array == NULL) {
        free(*offset_array);
        freeaddrinfo(res);
        return -1;
    }

    // Allocate memory for the record array
    size_t record_size = num_records * sizeof(record);
    *record_array = (record*)malloc(record_size);
    if (*record_array == NULL) {
        free(*offset_array);
        free(*key_array);
        freeaddrinfo(res);
        return -1;
    }

    // Populate the offset and key arrays with random values
    for (int i = 0; i < num_records; ++i) {
        (*offset_array)[i] = rand() % 100;
        (*key_array)[i] = rand() % 1000;
    }

    // Populate the record array with random values
    for (int i = 0; i < num_records; ++i) {
        (*record_array)[i].value = rand() % 10000;
    }

    freeaddrinfo(res);
    return 0;
}
