// Function to dynamically allocate memory for and initialize the book and patron collections
void init_library(int num_books, int num_patrons) {
    // Allocate memory for the books array
    struct book** books = (struct book**)malloc(num_books * sizeof(struct book*));
    if (!books) {
        perror("Error allocating memory for books");
        exit(EXIT_FAILURE);
    }

    // Initialize each book structure and link it to its respective patrons
    for (int i = 0; i < num_books; i++) {
        struct book* book = (struct book*)malloc(sizeof(struct book));
        if (!book) {
            perror("Error allocating memory for book");
            exit(EXIT_FAILURE);
        }
        strcpy(book->title, "Book Title");
        book->id = i;
        book->patrons = NULL;
        books[i] = book;
    }

    // Allocate memory for the patrons array and link each patron to its respective book
    struct patron** patrons = (struct patron**)malloc(num_patrons * sizeof(struct patron*));
    if (!patrons) {
        perror("Error allocating memory for patrons");
        exit(EXIT_FAILURE);
    }

    // Initialize each patron structure and link it to its respective book
    for (int i = 0; i < num_patrons; i++) {
        struct patron* patron = (struct patron*)malloc(sizeof(struct patron));
        if (!patron) {
            perror("Error allocating memory for patron");
            exit(EXIT_FAILURE);
        }
        strcpy(patron->name, "Patron Name");
        strcpy(patron->contact_info, "Contact Information");
        time_t now = time(NULL);
        patron->borrowing_time = now;
        int book_id = rand() % num_books; // Assign random book to patron
        struct book* book = books[book_id];
        if (book->patrons) { // Add patron to end of linked list for book
            struct patron* current = book->patrons;
            while (current->next) {
                current = current->next;
            }
            current->next = patron;
        } else {
            book->patrons = patron;
        }
        patrons[i] = patron;
    }
}

// Function to safely free all allocated memory for the book and patron collections
void free_library() {
    // Free each book structure and its linked list of patrons
    for (int i = 0; i < num_books; i++) {
        struct book* book = books[i];
        if (book->patrons) {
            while (book->patrons) {
                struct patron* current = book->patrons;
                book->patrons = current->next;
                free(current);
            }
        }
        free(book);
    }
    // Free each patron structure and its linked list of books
    for (int i = 0; i < num_patrons; i++) {
        struct patron* patron = patrons[i];
        if (patron->books) {
            while (patron->books) {
                struct book* current = patron->books;
                patron->books = current->next;
                free(current);
            }
        }
        free(patron);
    }
}

// Function to randomly assign patrons to books, ensuring no patron is assigned to more than one book
void random_assignment() {
    // Initialize each book's linked list of patrons with a random patron
    for (int i = 0; i < num_books; i++) {
        struct book* book = books[i];
        int patron_id = rand() % num_patrons;
        struct patron* patron = patrons[patron_id];
        if (!book->patrons) { // Add patron to end of linked list for book
            struct patron* current = book->patrons;
            while (current->next) {
                current = current->next;
            }
            current->next = patron;
        } else {
            book->patrons = patron;
        }
    }
}

// Function to verify that all books are correctly linked to their respective patrons and that the linked lists within each book maintain data integrity
void validation() {
    // Iterate through each book's linked list of patrons, checking for consistency in linked list structure and data integrity
    for (int i = 0; i < num_books; i++) {
        struct book* book = books[i];
        if (book->patrons) {
            struct patron* current = book->patrons;
            while (current) {
                // Check that each patron is linked to the correct book
                if (current->book != book) {
                    printf("Error: Patron %d is not correctly linked to book %s\n", current->id, book->title);
                    exit(EXIT_FAILURE);
                }
                // Check that each patron's next pointer points to the correct node in the linked list
                if (current->next && current->next != book->patrons) {
                    printf("Error: Patron %d's next pointer does not point to the correct node in the linked list\n", current->id);
                    exit(EXIT_FAILURE);
                }
                // Check that each patron's borrowing time is consistent with the book's linked list
                if (current->borrowing_time != book->patrons->borrowing_time) {
                    printf("Error: Patron %d's borrowing time does not match the borrowing time of the head patron in the linked list\n", current->id);
                    exit(EXIT_FAILURE);
                }
                // Check that each patron's book pointer points to the correct book
                if (current->book != current->next->book) {
                    printf("Error: Patron %d's book pointer does not point to the correct book\n", current->id);
                    exit(EXIT_FAILURE);
                }
                // Move to next patron in linked list
                current = current->next;
            }
        }
    }
}
