// Custom memory pool allocator for efficient dynamic memory allocation
struct MemoryPool {
    void** blocks;
    uint32_t block_size;
    uint32_t num_blocks;
};

void initMemoryPool(struct MemoryPool* pool, uint32_t block_size) {
    assert(pool != NULL);
    pool->block_size = block_size;
    pool->num_blocks = 0;
}

void destroyMemoryPool(struct MemoryPool* pool) {
    assert(pool != NULL);
    free(pool->blocks);
}

void* memoryPoolAlloc(struct MemoryPool* pool) {
    assert(pool != NULL);
    if (pool->num_blocks == 0) {
        return malloc(pool->block_size);
    } else {
        void* block = pool->blocks[--pool->num_blocks];
        return block;
    }
}

void memoryPoolFree(struct MemoryPool* pool, void* block) {
    assert(pool != NULL);
    if (pool->num_blocks < pool->blocks.length) {
        pool->blocks[pool->num_blocks++] = block;
    } else {
        free(block);
    }
}

// Hash table for active sessions, balancing memory overhead and access speed
struct SessionTable {
    uint32_t num_buckets;
    struct Session* buckets[];
};

void initSessionTable(struct SessionTable* table) {
    assert(table != NULL);
    table->num_buckets = 1000; // Default number of buckets
}

void destroySessionTable(struct SessionTable* table) {
    assert(table != NULL);
    for (int i = 0; i < table->num_buckets; ++i) {
        struct Session* session = table->buckets[i];
        if (session != NULL) {
            freeSession(session);
        }
    }
    free(table);
}

struct Session* getSession(struct SessionTable* table, uint32_t key) {
    assert(table != NULL);
    struct Session* session = NULL;
    for (int i = 0; i < table->num_buckets; ++i) {
        if (table->buckets[i] != NULL && table->buckets[i]->key == key) {
            session = table->buckets[i];
            break;
        }
    }
    return session;
}

void addSession(struct SessionTable* table, uint32_t key, struct Session* session) {
    assert(table != NULL);
    if (getSession(table, key) == NULL) {
        session->key = key;
        table->buckets[hash(key) % table->num_buckets] = session;
    }
}

void removeSession(struct SessionTable* table, uint32_t key) {
    assert(table != NULL);
    struct Session* session = getSession(table, key);
    if (session != NULL) {
        freeSession(session);
        table->buckets[hash(key) % table->num_buckets] = NULL;
    }
}

