// Lock-free data structures for concurrent access and fine-grained locking
struct ConcurrentQueue {
    struct Node* head;
    struct Node* tail;
};

struct Node {
    void* value;
    struct Node* next;
};

void initConcurrentQueue(struct ConcurrentQueue* queue) {
    assert(queue != NULL);
    queue->head = NULL;
    queue->tail = NULL;
}

bool enqueue(struct ConcurrentQueue* queue, void* value) {
    assert(queue != NULL);
    struct Node* node = malloc(sizeof(struct Node));
    if (node == NULL) {
        return false;
    }
    node->value = value;
    node->next = NULL;
    bool success = false;
    while (!success) {
        struct Node* current_tail = queue->tail;
        if (current_tail != NULL) {
            struct Node* new_node = malloc(sizeof(struct Node));
            if (new_node == NULL) {
                free(node);
                return false;
            }
            new_node->value = value;
            new_node->next = NULL;
            success = compareAndSwap(&queue->tail, current_tail, new_node);
            if (!success) {
                free(new_node);
            }
        } else {
            success = compareAndSwap(&queue->head, queue->tail, node);
            if (success) {
                queue->tail = node;
            }
        }
    }
    return true;
}

void* dequeue(struct ConcurrentQueue* queue) {
    assert(queue != NULL);
    struct Node* current_head = queue->head;
    if (current_head == NULL) {
        return NULL;
    }
    void* value = current_head->value;
    bool success = compareAndSwap(&queue->head, current_head, current_head->next);
    if (success) {
        free(current_head);
    }
    return value;
}

bool compareAndSwap(void** target, void* expected, void* new_value) {
    assert(target != NULL);
    bool success = false;
    while (!success) {
        if (*target == expected) {
            *target = new_value;
            success = true;
        } else {
            expected = *target;
        }
    }
    return success;
}

