#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "node.h" // custom struct node definition

// Dynamic collection of tree objects with thread safety and memory optimization
struct tree {
    double* values;
    char** strings;
    size_t capacity;
    pthread_mutex_t lock;
};

void init_tree(struct tree* t) {
    // Initialize the structure
    t->values = NULL;
    t->strings = NULL;
    t->capacity = 0;

    // Initialize mutex for thread-safe access
    pthread_mutex_init(&t->lock, NULL);
}

void destroy_tree(struct tree* t) {
    // Release memory allocated by the structure
    free(t->values);
    free(t->strings);

    // Destroy mutex
    pthread_mutex_destroy(&t->lock);
}

int resize_tree(struct tree* t, size_t new_capacity) {
    // Check if the new capacity is valid
    if (new_capacity < t->capacity) {
        return -1;
    }

    // Allocate new memory for values and strings
    double* new_values = realloc(t->values, sizeof(double) * new_capacity);
    char** new_strings = realloc(t->strings, sizeof(char*) * new_capacity);
    if (!new_values || !new_strings) {
        return -1;
    }

    // Initialize the newly allocated memory to zeros
    memset(new_values, 0, sizeof(double) * new_capacity);
    memset(new_strings, 0, sizeof(char*) * new_capacity);

    // Free the old values and strings if they exist
    if (t->values) {
        free(t->values);
    }
    if (t->strings) {
        free(t->strings);
    }

    // Update the structure with the new memory pointers
    t->values = new_values;
    t->strings = new_strings;
    t->capacity = new_capacity;

    return 0;
}

int add_node(struct tree* t, double value, const char* string) {
    // Acquire the lock to ensure thread-safe access
    pthread_mutex_lock(&t->lock);

    // Check if we need to resize the structure
    if (t->capacity == 0 || t->size >= t->capacity) {
        if (resize_tree(t, t->capacity * 2) < 0) {
            pthread_mutex_unlock(&t->lock);
            return -1;
        }
    }

    // Insert the new node at the end of the list
    t->values[t->size] = value;
    t->strings[t->size] = strdup(string);

    // Update the size and release the lock
    t->size++;
    pthread_mutex_unlock(&t->lock);

    return 0;
}

int remove_node(struct tree* t, double value) {
    int index = -1;

    // Acquire the lock to ensure thread-safe access
    pthread_mutex_lock(&t->lock);

    // Find the node with the given value and get its index
    for (size_t i = 0; i < t->capacity; i++) {
        if (t->values[i] == value) {
            index = i;
            break;
        }
    }

    // If the node was found, remove it from the list
    if (index >= 0) {
        t->size--;
        free(t->strings[index]);
        memmove(t->values + index, t->values + index + 1, sizeof(double) * (t->capacity - index - 1));
        memmove(t->strings + index, t->strings + index + 1, sizeof(char*) * (t->capacity - index - 1));
    }

    // Update the size and release the lock
    pthread_mutex_unlock(&t->lock);

    return index;
}

int lookup_node(struct tree* t, double value) {
    int index = -1;

    // Acquire the lock to ensure thread-safe access
    pthread_mutex_lock(&t->lock);

    // Find the node with the given value and get its index
    for (size_t i = 0; i < t->capacity; i++) {
        if (t->values[i] == value) {
            index = i;
            break;
        }
    }

    // Release the lock
    pthread_mutex_unlock(&t->lock);

    return index;
}

int update_node(struct tree* t, double value, const char* string) {
    int index = -1;

    // Acquire the lock to ensure thread-safe access
    pthread_mutex_lock(&t->lock);

    // Find the node with the given value and get its index
    for (size_t i = 0; i < t->capacity; i++) {
        if (t->values[i] == value) {
            index = i;
            break;
        }
    }

    // Update the string if the node was found
    if (index >= 0) {
        free(t->strings[index]);
        t->strings[index] = strdup(string);
    }

    // Release the lock
    pthread_mutex_unlock(&t->lock);

    return index;
}
