// add a new UEContext to the UEContexts structure
bool add_ue_context(UEContexts* ue_contexts, RRC_Connection_Reconfiguration* rrc_connection_reconfiguration, NAS_Message* nas_message) {
    // acquire write lock on UE context array
    pthread_rwlock_wrlock(&ue_contexts->rwlock);
    // check if capacity has been reached
    if (ue_contexts->num_ue_contexts == ue_contexts->capacity) {
        // double the capacity of the UE context array if it's full
        size_t new_capacity = ue_contexts->capacity * 2;
        UEContext** new_ue_contexts = (UEContext**)realloc(ue_contexts->ue_contexts, sizeof(UEContext*) * new_capacity);
        if (!new_ue_contexts) {
            perror("Failed to allocate memory for UE context array");
            pthread_rwlock_unlock(&ue_contexts->rwlock);
            return false;
        }
        ue_contexts->ue_contexts = new_ue_contexts;
        ue_contexts->capacity = new_capacity;
    }
    // allocate memory for the new UE context
    UEContext* new_ue_context = (UEContext*)malloc(sizeof(UEContext));
    if (!new_ue_context) {
        perror("Failed to allocate memory for new UE context");
        pthread_rwlock_unlock(&ue_contexts->rwlock);
        return false;
    }
    // copy the RRC connection reconfiguration message and NAS message into the new UE context
    new_ue_context->rrc_connection_reconfiguration = rrc_connection_reconfiguration;
    new_ue_context->nas_message = nas_message;
    // add the new UE context to the array of UE contexts
    ue_contexts->ue_contexts[ue_contexts->num_ue_contexts++] = new_ue_context;
    // release write lock on UE context array
    pthread_rwlock_unlock(&ue_contexts->rwlock);
    return true;
}

// remove an existing UEContext from the UEContexts structure
bool remove_ue_context(UEContexts* ue_contexts, int index) {
    // acquire write lock on UE context array
    pthread_rwlock_wrlock(&ue_contexts->rwlock);
    // check if the index is valid
    if (index < 0 || index >= ue_contexts->num_ue_contexts) {
        fprintf(stderr, "Invalid UE context index\n");
        pthread_rwlock_unlock(&ue_contexts->rwlock);
        return false;
