    // remove the specified UE context from the array of UE contexts
    UEContext* ue_context = ue_contexts->ue_contexts[index];
    free(ue_context);
    memmove(&ue_contexts->ue_contexts[index], &ue_contexts->ue_contexts[index + 1], (ue_contexts->num_ue_contexts - index - 1) * sizeof(UEContext*));
    ue_contexts->num_ue_contexts--;
    // release write lock on UE context array
    pthread_rwlock_unlock(&ue_contexts->rwlock);
    return true;
}

// get the number of UEContexts in the UEContexts structure
int get_num_ue_contexts(UEContexts* ue_contexts) {
    // acquire read lock on UE context array
