```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the data structure to store records in the hash table
typedef struct {
    int key;      // integer key
    char *value;  // string value
} Record;

// Define the hash table structure
typedef struct {
    int size;             // current size of the hash table
    int max_size;         // maximum size of the hash table
    float load_factor;   // threshold for dynamic resizing
    pthread_mutex_t lock;  // mutex for protecting concurrent access
    Record **table;      // pointer to the array of records
} HashTable;

// Initialize the hash table with a specified initial size and load factor
void initialize(HashTable *ht, int size, float load_factor) {
    ht->size = size;
    ht->max_size = size;
    ht->load_factor = load_factor;
    ht->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    ht->table = (Record **)malloc(ht->size * sizeof(Record *));
}

// Insert a record into the hash table with the specified integer key and string value
void insert(HashTable *ht, int key, char *value) {
    pthread_mutex_lock(&ht->lock);
    // Check if the record already exists in the table
    int index = find_index(ht, key);
    if (index != -1) {
        free((ht->table)[index].value);
        (ht->table)[index].value = strdup(value);
    } else {
        // Grow the hash table if necessary
        if (ht->size == ht->max_size) {
            grow(ht);
        }
        // Insert the new record into the table
        index = find_index(ht, key);
        (ht->table)[index].key = key;
        (ht->table)[index].value = strdup(value);
    }
    pthread_mutex_unlock(&ht->lock);
}

// Find the record with the specified integer key in the hash table, or return -1 if not found
int find(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    // Check if the record already exists in the table
    int index = find_index(ht, key);
    if (index != -1) {
        pthread_mutex_unlock(&ht->lock);
        return index;
    } else {
        pthread_mutex_unlock(&ht->lock);
        return -1;
    }
}

// Delete the record with the specified integer key from the hash table, or do nothing if not found
void delete(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    // Check if the record already exists in the table
    int index = find_index(ht, key);
    if (index != -1) {
        free((ht->table)[index].value);
        (ht->table)[index] = NULL;
        ht->size--;
    }
    pthread_mutex_unlock(&ht->lock);
}

// Find the index of a record with the specified integer key in the hash table, or return -1 if not found
int find_index(HashTable *ht, int key) {
    int index = 0;
    while (index < ht->size && ht->table[index].key != key) {
        index++;
    }
    if (index == ht->size) {
        return -1;
    } else {
        return index;
    }
}

// Grow the hash table by a factor of two to accommodate more records
void grow(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    // Double the size of the hash table and allocate new memory for the records
    ht->max_size = 2 * ht->max_size;
    ht->table = (Record **)realloc(ht->table, ht->max_size * sizeof(Record *));
    // Initialize the new records to NULL
    memset(ht->table + ht->size, 0, (ht->max_size - ht->size) * sizeof(Record *));
    pthread_mutex_unlock(&ht->lock);
}

// Shrink the hash table by a factor of two to accommodate fewer records
void shrink(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    // Half the size of the hash table and reallocate memory for the records
    ht->max_size = (ht->max_size + 1) / 2;
    ht->table = (Record **)realloc(ht->table, ht->max_size * sizeof(Record *));
    // Initialize the new records to NULL
    memset(ht->table + ht->size, 0, (ht->max_size - ht->size) * sizeof(Record *));
    pthread_mutex_unlock(&ht->lock);
}

// Implement a strategy for dynamic resizing to accommodate varying data loads while minimizing memory fragmentation and optimizing performance
void resize(HashTable *ht, int new_size) {
    if (new_size < ht->max_size) {
        shrink(ht);
    } else {
        grow(ht);
    }
}
