void initialize_weather_data_with_nas_messages(struct UEContext **records) {
    // Initialize a lock for synchronizing access to the records array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize an empty buffer for storing the NAS messages
    struct NAS_Message *buffer[BUFFER_SIZE];

    // Initialize a counter for tracking the number of records in the buffer
    int count = 0;

    // Loop until all records are processed
    while (count < MAX_RECORDS) {
        // Acquire the lock to ensure thread-safe access to the records array
        pthread_mutex_lock(&mutex);

        // Check if there is a free space in the buffer
        if (count < BUFFER_SIZE) {
            // Allocate memory for the next NAS message
            struct NAS_Message *message = malloc(sizeof(struct NAS_Message));

            // Validate the allocated memory
            if (message == NULL) {
                // Log a failure to allocate memory
                fprintf(stderr, "Failed to allocate memory for NAS message\n");
            } else {
                // Add the new NAS message to the buffer
                buffer[count] = message;
                count++;
            }
        }

        // Release the lock to allow other threads to access the records array
        pthread_mutex_unlock(&mutex);
    }

    // Initialize a counter for tracking the number of records in the output array
    int output_count = 0;

    // Loop through the buffer and add the valid NAS messages to the output array
