// Define the data structures used in the function
typedef struct {
    offset_t offset;
    key_t key;
} record_t;

typedef struct {
    size_t size;
    record_t *records;
} array_t;

// Define the hash function used to derive keys from strings
unsigned int hash(const char *str) {
    unsigned int hash = 5381;
    for (int i = 0; str[i]; ++i) {
        hash = (hash << 5) + hash + str[i];
    }
    return hash;
}

// Define the function to manage dynamic memory allocation and initialization
void initialize(array_t *array, size_t size, const char **strings, int num_strings, unsigned long max_mem) {
    // Check if the input parameters are valid
    assert(array != NULL && size > 0 && strings != NULL && num_strings > 0 && max_mem > 0);

    // Calculate the total memory required for all records and file paths
    unsigned long total_mem = 0;
    for (int i = 0; i < num_strings; ++i) {
        total_mem += strlen(strings[i]) + 1;
    }
    if (total_mem > max_mem) {
        printf("Error: Total memory required exceeds the maximum limit.\n");
        return;
    }

    // Initialize the arrays of offsets, keys, and records
    array->size = size;
    array->records = (record_t *)malloc(sizeof(record_t) * size);
    if (!array->records) {
        printf("Error: Unable to allocate memory for record array.\n");
        return;
    }
    memset(array->records, 0, sizeof(record_t) * size);

    // Iterate over each string and initialize the corresponding record
    int i = 0;
    while (i < num_strings && total_mem < max_mem) {
        char *str = strdup(strings[i]);
        if (!str) {
            printf("Error: Unable to allocate memory for string.\n");
            return;
        }
        array->records[i].key = hash(str);
        array->records[i].offset = total_mem;
        total_mem += strlen(str) + 1;
        ++i;
    }

    // Validate the existence and accessibility of file paths before finalizing the allocation
    for (int i = 0; i < array->size; ++i) {
        char *path = (char *)malloc(sizeof(char) * PATH_MAX);
        if (!path) {
            printf("Error: Unable to allocate memory for file path.\n");
            return;
        }
        snprintf(path, PATH_MAX, "./%d.txt", array->records[i].key);
        if (access(path, R_OK)) {
            free(path);
