void manage_memory(int size) {
    // Allocate memory for an array of 'offset_t' types representing file offsets
    offset_t* offsets = (offset_t*)malloc(size * sizeof(offset_t));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
