    // Initialize each element of the array with a unique value starting from zero up to the size minus one
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
    }

    // Consider memory fragmentation and optimize for both initial allocation and subsequent updates
    if (size > 1000000) {
        // Handle large sizes with multiple allocations to minimize fragmentation
        int alloc_size = size / 10000;
        while (alloc_size >= 1000) {
            offset_t* tmp = (offset_t*)malloc(alloc_size * sizeof(offset_t));
            if (!tmp) {
                printf("Error: Failed to allocate memory for offsets\n");
