// Function to allocate memory for the arrays and initialize them with random values
void allocate_memory(int size, unsigned seed) {
    srand(seed); // Seed the random number generator

    // Allocate memory for the offsets array
    long *offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for offsets array\n");
        exit(EXIT_FAILURE);
    }

    // Populate the offsets array with random values between 0 and size-1
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % size;
    }

    // Allocate memory for the keys array
    int *keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for keys array\n");
        exit(EXIT_FAILURE);
    }

    // Populate the keys array with unique integer values between 0 and 1000
    for (int i = 0; i < size; i++) {
        int key = rand() % 1000;
        while (contains(keys, key)) {
            key = rand() % 1000;
        }
        keys[i] = key;
    }

    // Allocate memory for the records array and initialize each record with a random integer value
    Record *records = malloc(size * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for records array\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        int int_value = rand() % 1000 - 500;
        while (!unique_int(records, int_value)) {
            int_value = rand() % 1000 - 500;
        }
        records[i].int_value = malloc(sizeof(int));
        if (records[i].int_value == NULL) {
            fprintf(stderr, "Error: unable to allocate memory for record\n");
            exit(EXIT_FAILURE);
        }
        records[i].int_value = &int_value;
        records[i].key_index = i;
    }
}

// Function to deallocate all dynamically allocated memory
void cleanup() {
    for (int i = 0; i < size; i++) {
        free(records[i].int_value);
    }
    free(offsets);
    free(keys);
    free(records);
}

// Function to iterate over the records array and print each record's integer value along with its corresponding key index
void print_records() {
    for (int i = 0; i < size; i++) {
        printf("%d %d\n", *(records[i].int_value), records[i].key_index);
    }
}

// Helper function to check if an integer is already present in the keys array
int contains(int *keys, int key) {
    for (int i = 0; i < size; i++) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

// Helper function to check if an integer is unique across all records
int unique_int(Record *records, int int_value) {
    for (int i = 0; i < size; i++) {
        if (records[i].int_value == &int_value) {
            return 0;
        }
    }
    return 1;
}
