      return NULL;
    }
    configs[i]->radioResources = (RadioResourceBlock*)malloc(numRBs * sizeof(RadioResourceBlock));
    if (!configs[i]->radioResources) {
      fprintf(stderr, "Error: failed to allocate memory for radio resource blocks in cell configuration %d\n", i);
      return NULL;
    }
    configs[i]->phyChannels = (PHY_Channel*)malloc(numRBs * sizeof(PHY_Channel));
    if (!configs[i]->phyChannels) {
      fprintf(stderr, "Error: failed to allocate memory for PHY channels in cell configuration %d\n", i);
      return NULL;
    }
  }

  // Initialize the radio resource blocks and PHY channels
  for (int i = 0; i < numCells; i++) {
    for (int j = 0; j < numRBs; j++) {
      configs[i]->radioResources[j].channel = -1;
      configs[i]->phyChannels[j].modulationScheme = QPSK;
      configs[i]->phyChannels[j].codingRate = 0.5;
    }
  }

  // Return the initialized cell configurations
  return configs;
