// Data structure for storing records
typedef struct record {
    int id;
    double value;
    char* buffer;
} Record;

// Function to dynamically allocate memory for a record
Record* create_record(int id, double value, char* buffer) {
    Record* record = (Record*) malloc(sizeof(Record));
    record->id = id;
    record->value = value;
    record->buffer = buffer;
    return record;
}

// Function to initialize a record with default values
void init_record(Record* record) {
    record->id = 0;
    record->value = 0.0;
    record->buffer = NULL;
}

// Function to free the memory allocated for a record
void destroy_record(Record* record) {
    if (record != NULL) {
        free(record->buffer);
        free(record);
    }
}

// Data structure for storing records in an array
typedef struct record_array {
    int size;
    Record** records;
} RecordArray;

// Function to create a new empty record array
RecordArray* create_record_array() {
    RecordArray* record_array = (RecordArray*) malloc(sizeof(RecordArray));
    record_array->size = 0;
    record_array->records = NULL;
    return record_array;
}

// Function to add a new record to the end of a record array
void append_record(RecordArray* record_array, Record* record) {
    // Double the size of the records array if it is full
    if (record_array->size == 0 || record_array->size % 2 == 0) {
        record_array->records = realloc(record_array->records, record_array->size * 2 * sizeof(Record*));
    }
    // Add the new record to the end of the array
    record_array->records[record_array->size++] = record;
}

// Function to remove a record from a record array by its index
void remove_record(RecordArray* record_array, int index) {
    // Shift all records after the specified index one position to the left
    for (int i = index + 1; i < record_array->size; i++) {
        record_array->records[i - 1] = record_array->records[i];
    }
    // Decrement the size of the array by one
    record_array->size--;
}

// Function to free the memory allocated for a record array
void destroy_record_array(RecordArray* record_array) {
    if (record_array != NULL) {
        for (int i = 0; i < record_array->size; i++) {
            destroy_record(record_array->records[i]);
        }
        free(record_array->records);
        free(record_array);
    }
}

// Function to dynamically allocate memory for a collection of records
void* create_records(int num_records) {
    RecordArray* record_array = create_record_array();
    for (int i = 0; i < num_records; i++) {
        Record* record = create_record(i, 0.0, NULL);
        append_record(record_array, record);
    }
    return record_array;
}

// Function to initialize a collection of records with default values
void init_records(void* records) {
    RecordArray* record_array = (RecordArray*) records;
    for (int i = 0; i < record_array->size; i++) {
        init_record(record_array->records[i]);
    }
}

// Function to free the memory allocated for a collection of records
void destroy_records(void* records) {
    RecordArray* record_array = (RecordArray*) records;
    destroy_record_array(record_array);
}

// Function to process a single record in parallel using a thread-safe mechanism
void process_record_parallel(Record* record, void (*callback)(Record*)) {
    // Acquire a lock on the record to prevent concurrent access
    pthread_mutex_lock(&record->mutex);
    // Process the record using the callback function
    callback(record);
    // Release the lock on the record
    pthread_mutex_unlock(&record->mutex);
}

// Function to process a collection of records in parallel using thread-safe mechanisms
void process_records_parallel(void* records, void (*callback)(Record*)) {
    RecordArray* record_array = (RecordArray*) records;
    pthread_t threads[record_array->size];
    for (int i = 0; i < record_array->size; i++) {
        // Create a new thread to process the current record
        pthread_create(&threads[i], NULL, (void* (*)(void*))process_record_parallel, record_array->records[i]);
    }
    for (int i = 0; i < record_array->size; i++) {
        // Join the current thread with the main thread to ensure completion
        pthread_join(threads[i], NULL);
    }
}

