LockFreeArray *create_lockfree_array(size_t capacity) {
  struct LockFreeArray *arr = malloc(sizeof(struct LockFreeArray));
  arr->elements = calloc(capacity, sizeof(UEContext*));
  arr->capacity = capacity;
  arr->count = 0;
  return arr;
}

void lockfree_array_insert(LockFreeArray *arr, UEContext *ctx) {
  // Use a atomic operation to insert the element into the array
  pthread_spinlock_t lock;
  pthread_spin_init(&lock, PTHREAD_PROCESS_SHARED);
  while (true) {
    size_t idx = arr->count++;
    if (idx < arr->capacity) {
      arr->elements[idx] = ctx;
      break;
    } else {
      // Resize the array if it's full
      size_t new_capacity = arr->capacity * 2;
      UEContext **new_elements = realloc(arr->elements, sizeof(UEContext*) * new_capacity);
      if (new_elements) {
        arr->elements = new_elements;
        arr->capacity = new_capacity;
      } else {
        // Unable to resize the array, need to find a different solution
        pthread_spin_unlock(&lock);
        return;
      }
    }
  }
  pthread_spin_unlock(&lock);
}

void lockfree_array_remove(LockFreeArray *arr, size_t index) {
  // Use a atomic operation to remove the element from the array
  pthread_spinlock_t lock;
  pthread_spin_init(&lock, PTHREAD_PROCESS_SHARED);
  while (true) {
