      UEContext *tmp = arr->elements[index];
      arr->elements[index] = arr->elements[arr->count - 1];
      arr->count--;
      break;
    } else {
      // Element not found, need to find a different solution
      pthread_spin_unlock(&lock);
      return;
    }
  }
  pthread_spin_unlock(&lock);
}

