#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
#include <memory>

using namespace std;

struct ImageMetadata {
    string id;
    vector<char> data;
};

class ImageProcessingManager {
private:
    struct Node {
        unique_ptr<ImageMetadata> metadata;
        unique_ptr<Node> next;
    };

    unique_ptr<Node> head;
    size_t count = 0;

public:
    void insert(const string& id, const vector<char>& data) {
        auto node = make_unique<Node>();
        node->metadata = make_unique<ImageMetadata>(id, data);

        if (head == nullptr) {
            head = move(node);
        } else {
            Node* current = head.get();
            while (current->next != nullptr) {
                current = current->next.get();
            }
            current->next = move(node);
        }

        count++;
    }

    void remove(const string& id) {
        if (head == nullptr) {
            return;
        }

        Node* current = head.get();
        while (current != nullptr && current->metadata->id != id) {
            current = current->next.get();
        }

        if (current == nullptr) {
            return;
        }

        // Remove the node from the list
        if (head->metadata->id == id) {
            head = move(head->next);
        } else {
            Node* previous = current->previous.get();
            previous->next = move(current->next);
        }

        count--;
    }

    void update(const string& id, const vector<char>& data) {
        if (head == nullptr) {
            return;
        }

        Node* current = head.get();
        while (current != nullptr && current->metadata->id != id) {
            current = current->next.get();
        }

        if (current == nullptr) {
            return;
        }

        // Update the data in the node
        current->metadata->data = move(data);
    }

    void print() const {
        if (head == nullptr) {
            cout << "The list is empty." << endl;
            return;
        }

        Node* current = head.get();
        while (current != nullptr) {
            cout << current->metadata->id << ": ";
            for (auto c : current->metadata->data) {
                cout << c;
            }
            cout << endl;
            current = current->next.get();
        }
    }

    size_t size() const {
        return count;
    }
};

int main() {
    ImageProcessingManager manager;

    // Insert some images
    manager.insert("image1", vector<char>{'a', 'b', 'c'});
    manager.insert("image2", vector<char>{'d', 'e', 'f'});
    manager.insert("image3", vector<char>{'g', 'h', 'i'});

    // Remove an image
    manager.remove("image2");

    // Update an image
    manager.update("image1", vector<char>{'j', 'k', 'l'});

    // Print the list
    manager.print();

    return 0;
}']

