    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Allocate memory for an array of record structures
    record* records = (record*)malloc(num_records * sizeof(record));

    // Populate each record structure's offset field with a value from the offsets array
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
    }

    // Implement a caching mechanism to avoid redundant allocations for repeated requests
    long last_offset = -1;
    int last_key = 0;
    for (int i = 0; i < num_records; ++i) {
        if (records[i].offset == last_offset && records[i].key == last_key) {
            // If the offset and key of this record are the same as the previous one, reuse the buffer
            records[i].buffer = records[i - 1].buffer;
        } else {
            // Allocate a new buffer for this record if it is different from the previous one
            records[i].buffer = (char*)malloc(1024);

            // Initialize the buffer with a random ASCII string
            srand(seed + i);
            for (int j = 0; j < 1024; ++j) {
                records[i].buffer[j] = rand() % 26 + 'a';
            }
