// Define a struct to represent each record in the list
struct Record {
    int value;
};

// Define a struct to represent the entire list of records
struct List {
    int size;
    struct Record* data;
};

// Define a function to allocate and initialize a new list
struct List* createList() {
    struct List* list = malloc(sizeof(struct List));
    list->size = 0;
    list->data = NULL;
    return list;
}

// Define a function to append a new record to the end of the list
void appendRecord(struct List* list, int value) {
    // If the list is empty, allocate space for one record
    if (list->size == 0) {
        list->data = malloc(sizeof(struct Record));
        list->size++;
    } else {
        // Otherwise, reallocate space for the new record
        list->data = realloc(list->data, sizeof(struct Record) * (list->size + 1));
        list->size++;
    }
    // Set the value of the new record to the given value
    list->data[list->size - 1].value = value;
}

// Define a function to print the maximum integer value in the list
void printMax(struct List* list) {
    int maxValue = INT_MIN;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].value > maxValue) {
            maxValue = list->data[i].value;
        }
    }
    printf("Maximum value in the list: %d\n", maxValue);
}

// Define a function to serialize the list into a binary file
void saveList(struct List* list, const char* filename) {
    // Open the file for writing and check for errors
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    // Write the size of the list to the beginning of the file
    int size = sizeof(int);
    fwrite(&size, 1, sizeof(int), file);
    // Write each record in the list to the file
    for (int i = 0; i < list->size; i++) {
        struct Record* record = &list->data[i];
        size = sizeof(struct Record);
        fwrite(&record, 1, sizeof(struct Record), file);
    }
    // Close the file and check for errors
    if (fclose(file) == EOF) {
        perror("Error closing file");
        exit(EXIT_FAILURE);
    }
}

// Define a function to deserialize the list from a binary file
struct List* loadList(const char* filename) {
    // Open the file for reading and check for errors
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    // Read the size of the list from the beginning of the file
    int size;
    fread(&size, 1, sizeof(int), file);
    // Allocate space for the list and read each record into it
    struct List* list = createList();
    for (int i = 0; i < size; i++) {
        struct Record record;
        fread(&record, 1, sizeof(struct Record), file);
        appendRecord(list, record.value);
    }
    // Close the file and check for errors
    if (fclose(file) == EOF) {
        perror("Error closing file");
        exit(EXIT_FAILURE);
    }
    return list;
}

// Define a function to free the memory allocated by the list
void freeList(struct List* list) {
    free(list->data);
    free(list);
}

int main() {
    struct List* list = createList();
    appendRecord(list, 10);
    appendRecord(list, 20);
    appendRecord(list, 30);
    printMax(list);
    saveList(list, "mylist.bin");
    freeList(list);
    list = loadList("mylist.bin");
    printMax(list);
    freeList(list);
    return 0;
}
