use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::error::Error;

struct Record {
    value: i32,
    key: String,
}

struct OffsetMap {
    offsets: HashMap<i64, usize>,
}

struct KeyMap {
    keys: HashMap<String, i32>,
}

struct RecordManager {
    offset_map: Arc<Mutex<OffsetMap>>,
    key_map: Arc<Mutex<KeyMap>>,
}

impl RecordManager {
    fn new() -> Self {
        Self {
            offset_map: HashMap::new(),
            key_map: HashMap::new(),
        }
    }

    fn add_record(&mut self, record: &Record) -> Result<(), Box<Error>> {
        let mut offset_map = self.offset_map.lock().unwrap();
        let mut key_map = self.key_map.lock().unwrap();

        if let Some(offset) = offset_map.get(&record.value) {
            // check if record exists in cache
            return Ok(());
        } else {
            // create new record and store it in cache
            offset_map.insert(record.value, 0);
            key_map.insert(record.key.clone(), 0);
        }

        Ok(())
    }

    fn get_record(&mut self, value: i64) -> Option<Record> {
        let mut offset_map = self.offset_map.lock().unwrap();
        let mut key_map = self.key_map.lock().unwrap();

        if let Some(offset) = offset_map.get(&value) {
            // retrieve record from cache
            let record = Record { value, key: key_map.get(&value).unwrap().clone() };
            return Some(record);
        } else {
            // create new record and store it in cache
            offset_map.insert(value, 0);
            key_map.insert(String::from(""), 0);
        }

        None
    }
}
```
