int create_session(int id) {
    // Allocate memory for the session context structure
    struct SessionContext *ctx = malloc(sizeof(struct SessionContext));
    if (ctx == NULL) {
        return -1;
    }

    // Initialize the mutex and lock it
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&ctx->mutex, &attr);
    pthread_mutex_lock(&ctx->mutex);

    // Initialize the session ID and allocate memory for the PDU sessions and NAS messages arrays
    ctx->id = id;
    ctx->pdusessions = malloc(sizeof(struct PDUSession *) * MAX_PDU_SESSIONS);
    ctx->nasmessages = malloc(sizeof(struct NASMessage *) * MAX_NAS_MESSAGES);

    // Initialize the PDU sessions and NAS messages arrays with NULL pointers
    for (int i = 0; i < MAX_PDU_SESSIONS; i++) {
        ctx->pdusessions[i] = NULL;
    }
    for (int i = 0; i < MAX_NAS_MESSAGES; i++) {
        ctx->nasmessages[i] = NULL;
    }

    // Return the pointer to the session context structure
    return ctx;
}

void destroy_session(struct SessionContext *ctx) {
    // Release the mutex and deallocate memory for the PDU sessions and NAS messages arrays
    pthread_mutex_unlock(&ctx->mutex);
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx->pdusessions);
    free(ctx->nasmessages);
