}

void add_pdu_session(struct SessionContext *ctx, struct PDUSession *session) {
    // Acquire the mutex lock and check if there is space in the PDU sessions array
    pthread_mutex_lock(&ctx->mutex);
    int i;
    for (i = 0; i < MAX_PDU_SESSIONS && ctx->pdusessions[i] != NULL; i++);
    if (i == MAX_PDU_SESSIONS) {
        pthread_mutex_unlock(&ctx->mutex);
        return;
    }

    // Add the PDU session to the array and increment the number of active sessions
    ctx->pdusessions[i] = session;
    ctx->num_active_sessions++;

    // Release the mutex lock
    pthread_mutex_unlock(&ctx->mutex);
}

void remove_pdu_session(struct SessionContext *ctx, struct PDUSession *session) {
    // Acquire the mutex lock and find the index of the session in the array
    pthread_mutex_lock(&ctx->mutex);
    int i;
    for (i = 0; i < MAX_PDU_SESSIONS && ctx->pdusessions[i] != NULL; i++) {
        if (ctx->pdusessions[i] == session) {
            break;
        }
    }
    if (i == MAX_PDU_SESSIONS) {
        pthread_mutex_unlock(&ctx->mutex);
        return;
    }

    // Remove the PDU session from the array and decrement the number of active sessions
    ctx->pdusessions[i] = NULL;
    ctx->num_active_sessions--;

    // Release the mutex lock
    pthread_mutex_unlock(&ctx->mutex);
}

