    struct record_node *new_node = malloc(sizeof(struct record_node));
    init_record_node(new_node, value);
    new_node->next = NULL;
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        struct record_node *curr_node = list->head;
        while (curr_node->next != NULL) {
            curr_node = curr_node->next;
        }
        curr_node->next = new_node;
