static bool validate_RNTIs(const char *file_path, const char *library_name) {
    // Load the external library and create a handle for it
    void *handle = dlopen(library_name, RTLD_NOW);
    if (!handle) {
        printf("Error loading library: %s\n", dlerror());
        return false;
