    int key;
    char* string;
} record;

void initialize_data_records(void) {
    long* offset_array = malloc(MAX_RECORDS * sizeof(long));
    int* key_array = malloc(MAX_RECORDS * sizeof(int));
    record* records = malloc(MAX_RECORDS * sizeof(record));

    if (!offset_array || !key_array || !records) {
        printf("Error: Failed to allocate memory for data records\n");
        return;
    }

    // Initialize offset and key arrays
    for (int i = 0; i < MAX_RECORDS; i++) {
        offset_array[i] = 0;
        key_array[i] = 0;
    }

    // Initialize record structures
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].key = generate_random_number(1, 100);
        records[i].string = generate_string_for_record(i);
    }
}

int generate_random_number(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

char* generate_string_for_record(int index) {
    char* string = NULL;

    // Generate a random string prefixed with "record_"
    const int string_length = strlen(STRING_PREFIX);
    const int max_length = 100;
    string = malloc(string_length + max_length * sizeof(char));
    if (!string) {
        printf("Error: Failed to allocate memory for generated string\n");
        return NULL;
    }

    // Generate a random string
    int i;
    char* rand_string = OpenSSL_RandomBytes(10);
    for (i = 0; i < max_length && rand_string[i] != '\0'; i++) {
        string[i + string_length] = rand_string[i];
    }
    if (i >= max_length) {
        printf("Error: Generated random string is too long\n");
        return NULL;
    }

    // Free the random string and return the generated string
    free(rand_string);
    return string;
}

void print_record_details(record* record) {
    printf("Record: %d, String: %s\n", record->key, record->string);
}
