void populate_ue_context(UEContext** ue_context, size_t num_uplink, const char* nas_message) {
    for (size_t i = 0; i < num_uplink; ++i) {
        UEContext* context = &(*ue_context)[i];
        // allocate memory for NAS message
        context->nas_message = (char*) malloc(strlen(nas_message));
        memcpy(context->nas_message, nas_message, strlen(nas_message));
    }
}

void cleanup_ue_context(UEContext** ue_context, size_t num_uplink) {
    for (size_t i = 0; i < num_uplink; ++i) {
        UEContext* context = &(*ue_context)[i];
        free(context->nas_message);
    }
}

void handle_memory_fragmentation(UEContext** ue_context, size_t num_uplink) {
    for (size_t i = 0; i < num_uplink; ++i) {
        UEContext* context = &(*ue_context)[i];
        if (context->nas_message != NULL) {
            // reallocate memory to avoid fragmentation
            size_t new_size = strlen(context->nas_message);
            context->nas_message = (char*) realloc(context->nas_message, new_size);
        }
