use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct Record {
    offset: i64,
    key: i32,
    data: f32,
}

fn generate_records(
    num_offsets: usize,
    min_offset: i64,
    max_offset: i64,
    num_keys: usize,
    min_key: i32,
    max_key: i32,
    num_data: usize,
    min_data: f32,
    max_data: f32,
) -> Vec<Record> {
    let mut rng = rand::thread_rng();
    (0..num_offsets)
        .map(|_| {
            let offset = rng.gen_range(min_offset, max_offset);
            (0..num_keys).map(|_| {
                let key = rng.gen_range(min_key, max_key);
                (0..num_data)
                    .map(|_| rng.gen_range(min_data, max_data))
                    .collect::<Vec<f32>>()
            }).collect::<Vec<_>>()
        })
        .collect::<Vec<_>>()
}
```
The `generate_records` function takes in several parameters that define the ranges of values to generate for each field of the record. It then uses a loop to set the value of each record's fields to random values within these ranges. The function ensures memory efficiency by using a vector of vectors, where each inner vector represents a single record and contains the offset, key, and data values.
