    let mut data_array = vec![0.0; num_records];

    for i in 0..num_records {
        offset_array[i] = rng.gen_range(min_offset, max_offset);
        key_array[i] = rng.gen_range(min_key, max_key);
        data_array[i] = rng.gen_range(min_data, max_data);
    }

    (offset_array, key_array, data_array)
}
