// Scheduler.h
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <map>
#include <set>
#include <chrono>

class Scheduler {
public:
    static Scheduler& getInstance();

    void submitTask(const Task& task);
    bool executeNextTask();

private:
    Scheduler();
    ~Scheduler();

    // Singleton pattern
    Scheduler(const Scheduler&) = delete; // Prevent copying
    Scheduler& operator=(const Scheduler&) = delete; // Prevent assignment

    // Mutexes and condition variables for thread safety
    std::mutex taskQueueMutex, runningTaskMutex, priorityThresholdsMutex, rejectedTasksMutex;
    std::condition_variable taskQueueCondVar, runningTaskCondVar, priorityThresholdsCondVar, rejectedTasksCondVar;

    // Task queue and running task map for scheduling
    std::vector<Task> taskQueue;
    std::map<std::thread::id, Task> runningTasks;

    // Priority thresholds and task rejection policies
    std::set<int> priorityThresholds;
    std::map<std::thread::id, int> rejectedTasks;

    // Load balancing strategy
    std::vector<std::thread::id> availableThreads;
    std::map<std::thread::id, int> threadLoads;

    // Monitoring and logging
    int numTotalTasks = 0, numSubmittedTasks = 0, numExecutedTasks = 0;
    std::chrono::steady_clock::time_point startTime;
};

// Scheduler.cpp
#include "Scheduler.h"

Scheduler& Scheduler::getInstance() {
    static Scheduler instance;
    return instance;
}

void Scheduler::submitTask(const Task& task) {
    // Acquire mutex for task queue and condition variable for task submission
    std::lock_guard<std::mutex> lock(taskQueueMutex);
    taskQueueCondVar.notify_one();
}

bool Scheduler::executeNextTask() {
    // Acquire mutex for running tasks, condition variable for task execution, and priority thresholds
    std::lock_guard<std::mutex> lock1(runningTasksMutex), lock2(taskQueueMutex), lock3(priorityThresholdsMutex);

    // Check if there are any tasks to execute
    if (taskQueue.empty()) {
        return false;
    }

    // Get the next task from the queue and remove it
    Task task = taskQueue[0];
    taskQueue.erase(taskQueue.begin());
    numSubmittedTasks--;

    // Check if the task should be rejected based on priority thresholds
    if (rejectedTasks.count(std::this_thread::get_id()) &&
        task.priority <= priorityThresholds.find(std::this_thread::get_id())->second) {
        // Reject the task and add it to the rejected tasks map
        rejectedTasks[std::this_thread::get_id()]++;
        return false;
    }

    // Assign the task to a thread based on load balancing strategy
    std::thread::id threadId = availableThreads.back();
    availableThreads.pop_back();
    threadLoads[threadId]++;

    // Add the task to the running tasks map and execute it in a separate thread
    runningTasks[std::this_thread::get_id()] = task;
    std::thread(runTask, std::ref(task)).detach();
    numExecutedTasks++;

    return true;
}

void Scheduler::runTask(const Task& task) {
    // Execute the task and notify the scheduler that it has finished
    task.execute();
    runningTasksMutex.lock();
    runningTasks.erase(std::this_thread::get_id());
    runningTasksMutex.unlock();
}

Scheduler::Scheduler() {
    // Initialize the scheduler with default priority thresholds and task rejection policies
    priorityThresholds[std::this_thread::get_id()] = 0;
    rejectedTasks[std::this_thread::get_id()] = 0;
}

Scheduler::~Scheduler() {
    // Clean up any running tasks and notify the condition variable for task submission
    runningTasksMutex.lock();
    for (const auto& entry : runningTasks) {
        entry.second.cancel();
    }
    runningTasks.clear();
    runningTasksMutex.unlock();
    taskQueueCondVar.notify_all();
}

// Load balancing strategy implementation
void Scheduler::balanceLoad() {
    // Calculate the average load for each thread and select threads with the highest load to execute tasks
    std::vector<std::thread::id> bestThreads;
    int maxLoad = 0;
    for (const auto& entry : threadLoads) {
        if (entry.second > maxLoad) {
            bestThreads.clear();
            bestThreads.push_back(entry.first);
            maxLoad = entry.second;
        } else if (entry.second == maxLoad) {
            bestThreads.push_back(entry.first);
        }
    }

    // Assign tasks to the selected threads based on the load balancing strategy
    for (const auto& threadId : bestThreads) {
        while (!taskQueue.empty()) {
            Task task = taskQueue[0];
            if (task.priority > priorityThresholds.find(threadId)->second) {
                break;
            }
            taskQueue.erase(taskQueue.begin());
            runningTasks[threadId] = task;
        }
    }
}']

