    srand(time(NULL));
    for (int i = 0; i < 4; i++) {
        r = (r << 8) | rand();
    }
    return r;
}

// Data structure to store the records with offset and key
typedef struct record_t {
    long offset;
    int key;
} record_t;

// Function to add a new record to the data store
void add_record(long offset, int key) {
    // Check if there is enough memory for the new record
    if (mem_usage > MAX_MEMORY_USAGE) {
        printf("Memory usage exceeds maximum limit. Unable to add new record.\n");
        return;
    }

    // Allocate memory for the new record and initialize its fields
    record_t *new_record = malloc(sizeof(record_t));
    new_record->offset = offset;
    new_record->key = key;

    // Add the new record to the data store
    records[num_records++] = new_record;

    // Update the memory usage and free up any unused memory if necessary
    mem_usage += sizeof(record_t);
    if (mem_usage > MAX_MEMORY_USAGE) {
        int num_records_to_free = mem_usage - MAX_MEMORY_USAGE;
        for (int i = 0; i < num_records_to_free; i++) {
            free(records[i]);
        }
        num_records -= num_records_to_free;
    }
}

// Function to delete a record from the data store by its offset
void delete_record(long offset) {
    // Find the index of the record to be deleted
    int i = 0;
    while (i < num_records && records[i]->offset != offset) {
        i++;
    }

    // Check if the record was found and delete it if so
    if (i < num_records) {
        free(records[i]);
        for (int j = i; j < num_records - 1; j++) {
            records[j] = records[j + 1];
        }
        num_records--;
    } else {
        printf("Record with offset %ld not found in data store.\n", offset);
    }
}

// Function to update the value of a record's key
void update_record(long offset, int new_key) {
    // Find the index of the record to be updated
    int i = 0;
    while (i < num_records && records[i]->offset != offset) {
        i++;
    }

    // Check if the record was found and update its key if so
    if (i < num_records) {
        records[i]->key = new_key;
    } else {
        printf("Record with offset %ld not found in data store.\n", offset);
    }
}

// Function to retrieve the value of a record's key
int get_record(long offset) {
    // Find the index of the record to be retrieved
    int i = 0;
    while (i < num_records && records[i]->offset != offset) {
        i++;
    }

    // Check if the record was found and return its key if so
    if (i < num_records) {
        return records[i]->key;
    } else {
        printf("Record with offset %ld not found in data store.\n", offset);
        return 0;
    }
}

// Function to encrypt the data store using a symmetric encryption algorithm
void encrypt_data(const EVP_CIPHER *cipher, const EVP_MD *digest) {
    // Allocate memory for the encrypted data and initialize it to zeroes
    unsigned char *encrypted = malloc(MAX_MEMORY_USAGE);
    memset(encrypted, 0, MAX_MEMORY_USAGE);

    // Loop over each record in the data store and encrypt its key using the specified symmetric encryption algorithm
    for (int i = 0; i < num_records; i++) {
        int key = records[i]->key;
        int encrypted_key = EVP_Cipher(cipher, &key, sizeof(key), NULL);
        if (encrypted_key == -1) {
