int initArrays(size_t offsetSize, size_t keySize, size_t recordSize) {
    // Allocate memory for the arrays
    long *offsets = malloc(offsetSize * sizeof(long));
    int *keys = malloc(keySize * sizeof(int));
    Record *records = malloc(recordSize * sizeof(Record));

    // Check for memory allocation errors
    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the arrays
    srand(time(NULL));
    for (size_t i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % 100;
    }
    for (size_t i = 0; i < keySize; i++) {
        keys[i] = rand() % 100;
    }
    for (size_t i = 0; i < recordSize; i++) {
        records[i].buffer = malloc(sizeof(char) * 10);
        if (records[i].buffer == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return MEMORY_ALLOCATION_ERROR;
        }
        records[i].value = rand() % 100;
        records[i].offset = offsets[rand() % offsetSize];
    }

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    for (size_t i = 0; i < recordSize; i++) {
        free(records[i].buffer);
    }
    free(records);

    return 0;
}
