// Global Variables
int num_workers = 0; // Number of worker threads
int max_tasks = 100; // Maximum number of tasks to be processed in parallel
int total_tasks = 0; // Total number of tasks received so far
int completed_tasks = 0; // Total number of tasks completed so far
int num_sources = 3; // Number of sources of tasks (web API, message broker, etc.)
int source_task_count[num_sources]; // Array to store the number of tasks from each source
double avg_task_time = 0.0; // Average time taken by a task to complete
double avg_source_utilization = 0.0; // Average utilization of each source
int num_workers_active = 0; // Number of worker threads currently active

// Structure to store information about a task
struct Task {
    int id;
    double time;
    int source;
    int priority;
};

// Array to store the tasks in order of their arrival time
struct Task *task_queue = NULL;
int queue_size = 0;
int queue_head = -1; // Head of the queue (the first task that needs to be processed)
int queue_tail = -1; // Tail of the queue (the last task that has been processed)

// Function to add a task to the queue
void add_task(struct Task *task) {
    if (queue_size == max_tasks) {
        printf("ERROR: Maximum number of tasks reached. Cannot add more tasks.\n");
        return;
    }
    // Add the new task at the end of the queue
    queue_tail++;
    task_queue[queue_tail] = *task;
    queue_size++;
}

// Function to remove a task from the queue and return its index
int remove_task() {
    if (queue_head == -1) {
        // No tasks in the queue
        return -1;
    }
    int task_index = queue_head;
    // Remove the head of the queue
    queue_head++;
    // If the head reached the end of the queue, wrap around to the beginning
    if (queue_head == max_tasks) {
        queue_head = 0;
    }
    // Update the size of the queue
    queue_size--;
    return task_index;
}

// Function to get the next task to be processed from the queue
struct Task *get_next_task() {
    int task_index = remove_task();
    if (task_index == -1) {
        // No tasks left in the queue
        return NULL;
    }
    return &task_queue[task_index];
}

// Function to handle a new task arrival and add it to the queue
void handle_new_task(struct Task *task) {
    add_task(task);
    // Update the number of tasks from each source
    source_task_count[task->source]++;
    total_tasks++;
}

// Function to update the average task time and average utilization for a given source
void update_avg_time_util(int source, double time) {
    avg_task_time = (avg_task_time * (total_tasks - 1)) / total_tasks + time / total_tasks;
    avg_source_utilization += (double)(source_task_count[source] - source_task_count[source-1]) / (total_tasks - source_task_count[source-1]);
}

// Function to handle a completed task and update the queue and counters accordingly
void handle_completed_task(struct Task *task) {
    // Update the number of completed tasks
    completed_tasks++;
    // Update the average task time and average utilization for each source
    update_avg_time_util(task->source, task->time);
}

// Function to handle a failed task and update the queue and counters accordingly
void handle_failed_task(struct Task *task) {
    // Update the number of completed tasks (not used in this function but kept for future reference)
    completed_tasks++;
    // Update the average task time and average utilization for each source
    update_avg_time_util(task->source, task->time);
}

// Function to handle a new worker node joining the system and update the number of active workers accordingly
void handle_new_worker() {
    num_workers++;
    num_workers_active++;
}

// Function to handle a worker node leaving the system and update the number of active workers accordingly
void handle_dead_worker() {
    if (num_workers == 0) {
        // No workers left in the system
        return;
    }
    num_workers--;
    if (num_workers_active > 0) {
        num_workers_active--;
    }
}

