// Define the struct for UserSession
typedef struct {
    long id;
    char* name;
    float latency;
} UserSession;

// Function to initialize and populate an array of UserSession structures
UserSession* init_session_pool(int session_count) {
    // Allocate memory for the Session Initiation Request message
    int message_size = sizeof(long) + sizeof(char*) + sizeof(float);
    void* message_buffer = malloc(message_size * session_count);
    if (message_buffer == NULL) {
        perror("Failed to allocate memory for Session Initiation Request");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the Session Data fields
    int data_size = 1024; // arbitrary size, adjust as needed
    void* data_buffer = malloc(data_size * session_count);
    if (data_buffer == NULL) {
        perror("Failed to allocate memory for Session Data");
        exit(EXIT_FAILURE);
    }

    // Initialize the UserSession structures and populate them with data
    UserSession* sessions = malloc(sizeof(UserSession) * session_count);
    if (sessions == NULL) {
        perror("Failed to allocate memory for UserSession array");
        exit(EXIT_FAILURE);
    }

    // Dynamically allocate memory for the Session Data content and release it upon completion
    int i;
    for (i = 0; i < session_count; i++) {
        sessions[i].id = i + 1;
        sessions[i].name = malloc(strlen("user") + 1);
        strcpy(sessions[i].name, "user");
        sessions[i].latency = (float)i / 10.0f;

        // Allocate memory for the Session Data content
        void* data_content = malloc(data_size);
        if (data_content == NULL) {
            perror("Failed to allocate memory for Session Data content");
            exit(EXIT_FAILURE);
        }

        // Populate the Session Data content
        memset(data_content, 0, data_size);
        strcpy((char*)data_content, "This is a sample Session Data");
        sessions[i].data = data_content;
    }

    return sessions;
}

// Function to manage memory for the three pools: long IDs, char* session names, and float latency metrics
void free_session_pool(UserSession* sessions) {
    // Free the Session Initiation Request message buffer
    free(sessions);

    // Free the Session Data fields
    int i;
    for (i = 0; i < session_count; i++) {
        free(sessions[i].name);
        free(sessions[i].data);
    }
}

// Function to handle dynamic changes in session_count efficiently
void adjust_session_pool(int new_session_count) {
    // Free the old Session Initiation Request message buffer and reset the counters
    free_session_pool(sessions);
    sessions = NULL;

    // Allocate memory for the new Session Initiation Request message and populate it
    sessions = init_session_pool(new_session_count);
}

// Function to track allocations and deallocations, ensuring minimal performance impact during normal operation
void log_memory_usage() {
    // Log the memory usage for each pool
    printf("Memory usage: %lu bytes allocated for Session Initiation Request\n", message_buffer);
    printf("Memory usage: %lu bytes allocated for Session Data\n", data_buffer);
}

// Function to handle unexpected increases in session_count, potentially increasing the number of sessions by 50%, without causing memory exhaustion or performance degradation
void gracefully_handle_increase() {
    // Calculate the new session count and allocate memory for it
    int new_session_count = (int)(session_count * 1.5f);
    adjust_session_pool(new_session_count);

    // Free any excess memory from the old pool
    free_session_pool(sessions);
}

