    for (int i = 0; i < num_uecontexts; i++) {
        (*uecontexts)[i].rrc_reconfig.header.version = 1;
        (*uecontexts)[i].rrc_reconfig.header.message_type = RRC_CONNECTION_RECONFIGURATION;
        (*uecontexts)[i].nas_message.header.protocol_discriminator = 0x20;
        (*uecontexts)[i].nas_message.header.security_header_type = 1;
        (*uecontexts)[i].nas_message.header.sequence_number = i + 1;
