// Define function to handle RRC Connection Reconfiguration message
int process_rrc_connection_reconfiguration(UEContext *uecontext, RRC_Connection_Reconfiguration rrc_reconfig) {
    // Check if input is valid
    if (uecontext == NULL || rrc_reconfig.header.message_type != RRC_CONNECTION_RECONFIGURATION) {
        return -1;
    }

    // Update the UEContext structure with the new RRC Connection Reconfiguration message
    uecontext->rrc_reconfig = rrc_reconfig;

    // Return success
