    return 0;
}

// Define function to handle edge cases such as insufficient memory and malformed input
int handle_edge_cases(UEContext **uecontexts, int *num_uecontexts, RRC_Connection_Reconfiguration rrc_reconfig, NAS_Message nas_message) {
    // Check if input is valid
    if (uecontexts == NULL || *uecontexts == NULL || num_uecontexts == NULL || rrc_reconfig.header.message_type != RRC_CONNECTION_RECONFIGURATION || nas_message.header.protocol_discriminator != 0x20) {
        return -1;
    }

    // Handle insufficient memory by reallocating memory for the array of UEContext structures
    if (*num_uecontexts >= num_uecontexts) {
        resize_uecontext(uecontexts, *num_uecontexts + 1);
        if (resize_uecontext != 0) {
            return -2;
        }
