#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <sys/time.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>

#define MAX_RECORDS 1000000
#define RECORD_SIZE sizeof(struct record)
#define MAX_THREADS 8

struct record {
    int value;
};

struct records {
    struct record *data;
    size_t count;
    size_t capacity;
};

struct filters {
    struct {
        int min, max;
    } range;
    struct {
        int status;
    } flag;
};

void process_real_time_records(int fd) {
    // Initialize variables
    struct records *records = malloc(sizeof(struct records));
    records->data = NULL;
    records->count = 0;
    records->capacity = 0;

    struct filters filters = {
        .range.min = 1,
        .range.max = 100,
        .flag.status = 1
    };

    // Initialize mutex and condition variable for thread safety
    pthread_mutex_t lock;
    pthread_cond_t cond;
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);

    // Parse incoming data
    int bytes = 0;
    char *buffer = malloc(sizeof(char) * RECORD_SIZE);
    while ((bytes = read(fd, buffer, RECORD_SIZE)) > 0) {
        struct record *record = (struct record *)buffer;
        // Check if the received value is within the specified range and has the expected flag set
        if (filters.range.min <= record->value && record->value <= filters.range.max && record->flag == filters.flag.status) {
            // Add the record to the array of records
            pthread_mutex_lock(&lock);
            if (records->count >= records->capacity) {
                // If the capacity is exceeded, double it
                records->data = realloc(records->data, sizeof(struct record) * (records->capacity * 2));
                records->capacity *= 2;
            }
            records->data[records->count] = *record;
            records->count++;
            pthread_mutex_unlock(&lock);
        }
    }
    free(buffer);

    // Sort the records by timestamp and filter out duplicates
    qsort(records->data, records->count, sizeof(struct record), compare_records);
    struct record *unique = malloc(sizeof(struct record) * records->count);
    size_t unique_count = 0;
    for (size_t i = 0; i < records->count; i++) {
        if (i == 0 || memcmp(&records->data[i], &records->data[i - 1], sizeof(struct record)) != 0) {
            unique[unique_count++] = records->data[i];
        }
    }
    free(records);

    // Print the processed records
    for (size_t i = 0; i < unique_count; i++) {
        printf("%d\n", unique[i].value);
    }
    free(unique);
}

// Compare function for sorting records by timestamp
int compare_records(const void *a, const void *b) {
    struct record *ra = (struct record *)a;
    struct record *rb = (struct record *)b;
    return ra->timestamp - rb->timestamp;
}

// Function to handle network errors and recover from packet loss or corrupted data streams
void handle_network_errors(int fd) {
    int bytes = 0;
    char *buffer = malloc(sizeof(char) * RECORD_SIZE);
    while ((bytes = read(fd, buffer, RECORD_SIZE)) <= 0) {
        if (errno == EINTR || errno == EAGAIN) {
            // Interrupted by signal or blocking call was cancelled
            continue;
        } else {
            perror("read");
            break;
        }
    }
}

int main(void) {
    int fd = open("data.bin", O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    process_real_time_records(fd);

    close(fd);

    return 0;
}']

