    int command_id;
    char* command;
};

struct DeviceState {
    struct SensorReading sensor_reading;
    struct ActuatorCommand actuator_command;
};

// Function to initialize and populate an array of `DeviceState` structures
void init_device_state(int num_devices, int max_num_readings) {
    // Dynamically allocate memory for the array of `DeviceState` structures
    struct DeviceState* device_states = malloc(sizeof(struct DeviceState) * num_devices);
    if (device_states == NULL) {
        printf("Error: failed to allocate memory for device states\n");
        return;
    }

    // Initialize the `DeviceState` structures and populate them with sensor readings
    for (int i = 0; i < num_devices; i++) {
        struct SensorReading* sensor_reading = malloc(sizeof(struct SensorReading));
        if (sensor_reading == NULL) {
            printf("Error: failed to allocate memory for sensor reading\n");
            return;
        }
        sensor_reading->sensor_id = i + 1; // Assign a unique ID to each sensor reading
        sensor_reading->temperature = get_random_temperature(); // Generate random temperature values
        sensor_reading->humidity = get_random_humidity(); // Generate random humidity values
        device_states[i].sensor_reading = *sensor_reading;

        struct ActuatorCommand* actuator_command = malloc(sizeof(struct ActuatorCommand));
        if (actuator_command == NULL) {
            printf("Error: failed to allocate memory for actuator command\n");
            return;
        }
        actuator_command->command_id = i + 1; // Assign a unique ID to each actuator command
        actuator_command->command = get_random_actuator_command(); // Generate random actuator commands
        device_states[i].actuator_command = *actuator_command;
    }

    // Free the memory allocated for the `DeviceState` structures when we are done with them
    free(device_states);
}

