    if (sensor_readings == NULL) {
        printf("Error: failed to allocate memory for sensor readings\n");
        return;
    }

    // Sample and filter the `SensorReading` structures in the array
    for (int i = 0; i < num_devices; i++) {
        struct SensorReading* current_reading = &sensor_readings[i];
        if (current_reading->temperature > 30.0f) { // Filter out readings with temperature above 30.0F
            continue;
        } else if (current_reading->humidity < 50.0f) { // Filter out readings with humidity below 50.0F
            continue;
        }
        // Insert the filtered `SensorReading` structure into the array
    }

    // Free the memory allocated for the `SensorReading` structures when we are done with them
    free(sensor_readings);
}

// Function to handle asynchronous processing of sensor readings and actuator commands
void process_asynchronous_data(int num_devices, int max_num_readings) {
    // Dynamically allocate memory for an array of `DeviceState` structures
    struct DeviceState* device_states = malloc(sizeof(struct DeviceState) * num_devices);
    if (device_states == NULL) {
        printf("Error: failed to allocate memory for device states\n");
        return;
    }

    // Asynchronously process the `DeviceState` structures in the array
    for (int i = 0; i < num_devices; i++) {
        struct DeviceState* current_state = &device_states[i];
        process_sensor_reading(current_state->sensor_reading); // Process the current sensor reading
        process_actuator_command(current_state->actuator_command); // Process the current actuator command
    }

    // Free the memory allocated for the `DeviceState` structures when we are done with them
    free(device_states);
}

// Function to handle dynamic memory allocation and ensure that all allocated memory is freed upon completion of the function execution
void handle_dynamic_memory_allocation(int num_devices, int max_num_readings) {
    // Dynamically allocate memory for an array of `DeviceState` structures
    struct DeviceState* device_states = malloc(sizeof(struct DeviceState) * num_devices);
    if (device_states == NULL) {
        printf("Error: failed to allocate memory for device states\n");
        return;
    }

    // Dynamically allocate memory for an array of `SensorReading` structures
    struct SensorReading* sensor_readings = malloc(sizeof(struct SensorReading) * max_num_readings);
    if (sensor_readings == NULL) {
        printf("Error: failed to allocate memory for sensor readings\n");
        return;
    }

    // Dynamically allocate memory for an array of `ActuatorCommand` structures
    struct ActuatorCommand* actuator_commands = malloc(sizeof(struct ActuatorCommand) * max_num_readings);
    if (actuator_commands == NULL) {
        printf("Error: failed to allocate memory for actuator commands\n");
        return;
    }

    // Free the memory allocated for the `DeviceState` structures when we are done with them
    free(device_states);
    free(sensor_readings);
    free(actuator_commands);
}
