void logActivity(int stepSize, char* url) {
    // Allocate memory for arrays of counters, timestamps, and messages
    int* counters = malloc(sizeof(int) * 3);
    struct timeval* timestamps = malloc(sizeof(struct timeval) * 3);
    char** messages = malloc(sizeof(char*) * 3);

    // Initialize arrays of counters, timestamps, and messages
