        counters[i] = 0;
        timestamps[i].tv_sec = 0;
        timestamps[i].tv_usec = 0;
        messages[i] = malloc(sizeof(char) * 16); // Assumes each message is at most 15 characters long
    }

    // Set the current system time as the timestamp for all activities
    struct timeval now;
    gettimeofday(&now, NULL);

    // Populate the message field with a unique identifier derived from the activity index
    char* id = malloc(sizeof(char) * 16);
    sprintf(id, "%d", counters[0]);
    for (int i = 0; i < 3; i++) {
        sprintf(messages[i], "Activity %s", id);
    }

    // Increment the value of each activity's integer field by a specified step size
