        activity->counter = counters[i];
        activity->timestamp = timestamps[i];
        activity->message = messages[i];
        logActivityToStorage(activity);
    }

    // Free memory for arrays of counters, timestamps, and messages
    free(counters);
    free(timestamps);
    for (int i = 0; i < 3; i++) {
        free(messages[i]);
    }
}

