// Structure to hold RX_UE_INFORMATION_TAG data
typedef struct {
    unsigned int rnti;
    unsigned char crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a list of NFAPI_CRC_INDICATION_PDU_T structures with RX_UE_INFORMATION_TAG data
void init_rx_ue_information(NFAPI_CRC_INDICATION_PDU_T *list, int num_files) {
    // Initialize variables for tracking stats
    int total_rnti = 0;
    int duplicate_rnti = 0;
    double avg_time = 0.0;

    // Loop through each file and read RX_UE_INFORMATION_TAG data
    for (int i = 0; i < num_files; i++) {
        // Open compressed file for reading
        FILE *fp = fopen("rx_ue_information.dat", "rb");
        if (!fp) {
            perror("Error opening rx_ue_information.dat");
            continue;
        }

        // Decompress file using zlib library
        gzFile infile = gzdopen(fileno(fp), "rb");
        unsigned char buffer[1024];
        int ret = 0;
        while ((ret = gzread(infile, buffer, sizeof(buffer))) > 0) {
            // Process decompressed data
            for (int j = 0; j < ret; j++) {
                NFAPI_CRC_INDICATION_PDU_T *pdu = &list[total_rnti];
                pdu->rnti = buffer[j];
                pdu->crcFlag = rand() % 2;
                total_rnti++;
            }
        }

        // Close compressed file and handle any errors
        if (infile) {
            gzclose(infile);
        } else {
            perror("Error closing rx_ue_information.dat");
        }
    }

    // Print statistics about the initialization process
    printf("Total RNTIs: %d\n", total_rnti);
    printf("Duplicate RNTIs: %d\n", duplicate_rnti);
    printf("Average time per file: %.3f seconds\n", avg_time / num_files);
}

// Helper function to find and print the largest integer among the RNTI values within the structures
void find_largest_rnti(NFAPI_CRC_INDICATION_PDU_T *list, int num_pdu) {
    int largest = 0;
    for (int i = 0; i < num_pdu; i++) {
        if (list[i].rnti > largest) {
            largest = list[i].rnti;
        }
    }
    printf("Largest RNTI: %d\n", largest);
}
```
