// Define the struct for storing entries
typedef struct entry {
    double value;
    unsigned long id;
    char name[32];
} entry_t;

// Function to dynamically allocate memory and initialize arrays
entry_t* init_arrays(size_t num_entries) {
    // Allocate memory for the double array
    double* values = malloc(sizeof(double) * num_entries);
    if (values == NULL) {
        printf("Error: unable to allocate memory for values\n");
        return NULL;
    }

    // Allocate memory for the unsigned long array
    unsigned long* ids = malloc(sizeof(unsigned long) * num_entries);
    if (ids == NULL) {
        free(values);
        printf("Error: unable to allocate memory for ids\n");
        return NULL;
    }

    // Allocate memory for the entry struct array
    entry_t* entries = malloc(sizeof(entry_t) * num_entries);
    if (entries == NULL) {
        free(values);
        free(ids);
        printf("Error: unable to allocate memory for entries\n");
        return NULL;
    }

    // Initialize the values array with random double precision floating-point numbers
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_entries; i++) {
        values[i] = (double)rand() / RAND_MAX * 10.0;
    }

    // Initialize the ids array with random unique identifiers
    for (size_t i = 0; i < num_entries; i++) {
        ids[i] = rand();
    }

    // Initialize the entries struct array with data derived from user input
    for (size_t i = 0; i < num_entries; i++) {
        char name[32];
        printf("Enter name for entry %zu: ", i + 1);
        scanf("%s", &name);
        entries[i].value = values[i];
        entries[i].id = ids[i];
        strcpy(entries[i].name, name);
    }

    // Free memory for the double array since it is no longer needed
    free(values);

    return entries;
}
