void *allocate_memory(size_t size) {
    void *ptr = NULL;
    ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (ptr == MAP_FAILED) {
        handle_error("mmap");
    }
    return ptr;
}

void initialize_memory(struct record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = i;
        records[i].key = RAND_RANGE(1, 100);
    }
}

void allocate_and_initialize_memory() {
    size_t num_records = 1000; // arbitrary value
    struct record *records = allocate_memory(sizeof(struct record) * num_records);
    initialize_memory(records, num_records);
}

int main() {
    allocate_and_initialize_memory();
    return 0;
