// C function that manages memory for three dynamically allocated data structures
void* initMemory(size_t maxSize, size_t numRecords) {
    // Initialize random seed based on current time
    srand(time(NULL));

    // Allocate memory for the array of offset values
    long* offsets = malloc(numRecords * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    // Initialize random values for the offset array
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % maxSize;
    }

    // Allocate memory for the array of keys
    int* keys = malloc(numRecords * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize random values for the key array
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % MAX_KEY;
    }

    // Allocate memory for the array of record structures
    struct Record* records = malloc(numRecords * sizeof(struct Record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize random values for the long field in each record structure
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % maxSize;
    }

    // Create a data structure that encapsulates all three arrays and their associated data
    struct MemoryManager* mm = malloc(sizeof(struct MemoryManager));
    if (!mm) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    mm->offsets = offsets;
    mm->keys = keys;
    mm->records = records;
    mm->numRecords = numRecords;
    mm->maxSize = maxSize;

    // Return a pointer to the data structure that manages the memory for the three arrays
    return (void*)mm;
}

// Function to deallocate memory for the three dynamically allocated arrays
void freeMemory(struct MemoryManager* mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    free(mm);
}

// Structure that encapsulates all three dynamically allocated arrays and their associated data
struct MemoryManager {
    long* offsets; // Array of offset values
    int* keys; // Array of key values
    struct Record* records; // Array of record structures
    size_t numRecords; // Number of elements in each array
    size_t maxSize; // Maximum size constraint for memory allocation
};

// Structure that represents a single record with a long value
struct Record {
