typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_NFAPI_CRC_INDICATION_PDU];
    int count;
} NFAPI_CRC_INDICATION_LIST_T;

void init_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->count = 0;
}

int add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t RNTI) {
    if (list->count >= MAX_NFAPI_CRC_INDICATION_PDU) {
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entry == NULL) {
        return -2;
