    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->entries[list->count] = entry;
    list->count++;
    return 0;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
}

void print_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        printf("RNTI: %d\n", list->entries[i]->RNTI);
    }
}

void *decompress_thread(void *args) {
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *) args;
    while (1) {
        int RNTI;
        if (!fread(&RNTI, sizeof(uint32_t), 1, stdin)) {
            break;
        }
        add_crc_indication(list, RNTI);
    }
}

void *monitor_thread(void *args) {
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *) args;
    while (1) {
        sem_wait(&sem);
        if (list->count == 0) {
            continue;
        }
        int highest = -1;
        for (int i = 0; i < list->count; i++) {
            if (highest < list->entries[i]->RNTI) {
                highest = list->entries[i]->RNTI;
            }
        }
        printf("Highest RNTI: %d\n", highest);
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T list;
    init_crc_indication_list(&list);
    pthread_t decompress, monitor;
    sem_init(&sem, 0, 0);
    pthread_create(&decompress, NULL, decompress_thread, &list);
    pthread_create(&monitor, NULL, monitor_thread, &list);
    while (1) {
        int RNTI;
        if (!fread(&RNTI, sizeof(uint32_t), 1, stdin)) {
            break;
        }
        add_crc_indication(&list, RNTI);
        sem_post(&sem);
    }
    pthread_join(decompress, NULL);
    pthread_join(monitor, NULL);
    free_crc_indication_list(&list);
}
