// define a function for generating an array of events with dynamic sizing
struct event* generate_events(long num_offsets, int min_key, int max_key, double timestamp_min, double timestamp_max, char* text_data, size_t text_data_len, int value_min, int value_max) {
    struct event* events = malloc(num_offsets * sizeof(struct event)); // allocate memory for the array of events
