}

// define a function for processing events and updating statistics
void process_events(struct event* events, size_t num_events) {
    struct event_stats stats = {0}; // initialize the event statistics structure

    size_t i;
    for (i = 0; i < num_events; i++) {
        struct event* event = &events[i];

        if (!validate_event(event)) { // validate the event against predefined criteria
            printf("Event %lu does not meet predefined criteria\n", i);
            continue; // skip to the next event if the validation fails
        }

        stats.num_events++; // increment the number of events processed
        stats.min_value = MIN(stats.min_value, event->value); // update the minimum value in the statistics structure
        stats.max_value = MAX(stats.max_value, event->value); // update the maximum value in the statistics structure
        stats.mean_value += event->value; // update the mean value in the statistics structure

        if (stats.num_events % 2 == 0) { // if the number of events is even
            stats.median_value = event->value; // set the median value to the current value
        } else { // if the number of events is odd
            stats.median_value = (stats.median_value + event->value) / 2; // update the median value as the average of the two values
        }

        if (event->text_data != NULL) { // if the event has text data
            free(event->text_data); // release the memory for the text data
        }
    }

    printf("Processed %lu events\n", stats.num_events); // print the number of processed events
    printf("Minimum value: %d\n", stats.min_value); // print the minimum value
    printf("Maximum value: %d\n", stats.max_value); // print the maximum value
    printf("Mean value: %.2lf\n", stats.mean_value / (double)stats.num_events); // print the mean value
    printf("Median value: %d\n", stats.median_value); // print the median value
}

