void mange_rx_frame_pdus(LTE_PHY_RX_FRAME_PDU_T *pdu_list, int num_pdu) {
    // Mutex for synchronizing access to the list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Semaphore for signaling when a new PDU is available
    semaphore_t semaphore;

    // List of LTE PHY RX Frame PDUs
    LTE_PHY_RX_FRAME_PDU_T *pdu_list = NULL;

    // Function to read data from the channel simulator and populate a LTE PHY RX Frame PDU
    int read_data(LTE_PHY_RX_FRAME_PDU_T *pdu) {
