    }

    // Function to deallocate memory for a LTE PHY RX Frame PDU
    void deallocate_pdu(LTE_PHY_RX_FRAME_PDU_T *pdu) {
        free(pdu);
    }

    // Main loop to manage the list of LTE PHY RX Frame PDUs
    while (1) {
        // Acquire the mutex
        pthread_mutex_lock(&mutex);

        // Check if a new PDU is available
        semaphore_wait(semaphore, 0);

        // If no new PDU is available, release the mutex and sleep for a short period of time
        if (pdu_list == NULL) {
            pthread_mutex_unlock(&mutex);
            usleep(100000); // 100 ms
            continue;
        }

        // If a new PDU is available, read data from the channel simulator and populate it in the list
        LTE_PHY_RX_FRAME_PDU_T *pdu = allocate_pdu();
        read_data(pdu);
        pthread_mutex_unlock(&mutex);

        // Add the PDU to the end of the list
        semaphore_post(semaphore, 1);
    }
}
