std::vector<Item> generateItems(int numItems, int maxValue, int minValue) {
    std::vector<Item> items;
    for (int i = 0; i < numItems; ++i) {
        Item item;
        item.value = rand() % (maxValue - minValue + 1) + minValue;
        item.identifier = "string" + std::to_string(i);
        item.itemSet.push_back(rand() % maxValue);
        items.push_back(item);
    }
    return items;
}

std::vector<ItemContainer> generateItemContainers(int numItems, int maxValue, int minValue) {
    std::vector<ItemContainer> itemContainers;
    for (int i = 0; i < numItems; ++i) {
        ItemContainer container;
        container.item = generateItems(1, maxValue, minValue).front();
        itemContainers.push_back(container);
    }
    return itemContainers;
}

