// Compression framework function
int compress(const char* data, size_t len, int chunk_size, int compression_type) {
    // Initialize memory for compressed sizes, chunk indices, and records
    size_t* compressed_sizes = malloc(len * sizeof(*compressed_sizes));
    int* chunk_indices = malloc(len * sizeof(*chunk_indices));
    record* records = malloc(len * sizeof(*records));

    // Set the value of each record's int field to a random value within the user-defined range
    for (int i = 0; i < len; ++i) {
        compressed_sizes[i] = rand() % MAX_COMPRESSED_SIZE + MIN_COMPRESSED_SIZE;
        chunk_indices[i] = rand() % MAX_CHUNK_INDEX + MIN_CHUNK_INDEX;
        records[i].int_field = rand() % MAX_INT_VALUE + MIN_INT_VALUE;
    }

    // Allocate memory for the compressed data and compress each chunk
    char* compressed_data = malloc(len * sizeof(*compressed_data));
    int compressed_len = 0;
    for (int i = 0; i < len; ++i) {
        // Compress each chunk with the appropriate compression algorithm
        if (compression_type == ZLIB) {
            compressed_sizes[i] = zlib_compress(data + (i * chunk_size), chunk_size, compressed_data + compressed_len);
        } else if (compression_type == BZIP2) {
            compressed_sizes[i] = bzip2_compress(data + (i * chunk_size), chunk_size, compressed_data + compressed_len);
        } else if (compression_type == LZ4) {
            compressed_sizes[i] = lz4_compress(data + (i * chunk_size), chunk_size, compressed_data + compressed_len);
        }
        // Update the compressed length and record the compression algorithm used
        compressed_len += compressed_sizes[i];
        records[i].compression_type = compression_type;
    }

    // Free memory for unused parts of arrays
    free(data);
    free(chunk_indices);
    free(records);

    return compressed_len;
}

// Decompression framework function
int decompress(const char* compressed_data, size_t len, int chunk_size) {
    // Initialize memory for the decompressed data and a record for each chunk
    char* decompressed_data = malloc(len * sizeof(*decompressed_data));
    record* records = malloc(len * sizeof(*records));

    // Decompress each chunk with the appropriate compression algorithm
    int decompressed_len = 0;
    for (int i = 0; i < len; ++i) {
        if (records[i].compression_type == ZLIB) {
            decompressed_len += zlib_decompress(compressed_data + (i * chunk_size), compressed_sizes[i], decompressed_data + decompressed_len);
        } else if (records[i].compression_type == BZIP2) {
            decompressed_len += bzip2_decompress(compressed_data + (i * chunk_size), compressed_sizes[i], decompressed_data + decompressed_len);
        } else if (records[i].compression_type == LZ4) {
            decompressed_len += lz4_decompress(compressed_data + (i * chunk_size), compressed_sizes[i], decompressed_data + decompressed_len);
        }
    }

    // Free memory for unused parts of arrays
    free(compressed_data);
    free(records);

    return decompressed_len;
}

