        snprintf(strings[i], buf_len, "%d", val);
        files[i] = fopen("temp.txt", "w");
    }

    // Free any unused buffers and close any open files when the function exits
    atexit(cleanup);
}

// Cleanup function to free memory allocated for the arrays and clean up resources
void cleanup() {
    int *offsets = malloc(num_offsets);
    int *keys = malloc(num_keys);
    char **strings = malloc(num_strings);
