typedef struct transaction {
    int id;
    long timestamp;
    double amount;
} transaction_t;

void process_transactions(const char* json_data) {
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return;
    }

    size_t num_transactions = json_array_size(root);
    transaction_t** transactions = calloc(num_transactions, sizeof(transaction_t*));
    for (size_t i = 0; i < num_transactions; i++) {
        json_t *transaction = json_array_get(root, i);
        if (!transaction) {
            fprintf(stderr, "Failed to get transaction %zu\n", i + 1);
            continue;
        }

        transactions[i] = calloc(1, sizeof(transaction_t));
        json_unpack(transaction, "{s:i, s:l, s:f}", "id", &transactions[i]->id, "timestamp", &transactions[i]->timestamp, "amount", &transactions[i]->amount);
    }

    // Process the transactions here...

    for (size_t i = 0; i < num_transactions; i++) {
        free(transactions[i]);
    }
    free(transactions);
}
```
