['```java
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ProductMetadataCache {
    private static final Logger LOGGER = LoggerFactory.getLogger(ProductMetadataCache.class);

    // Map to store the product metadata in memory
    private Map<String, ProductMetadata> cache;

    // Lock to synchronize access to the cache
    private Lock lock;

    public ProductMetadataCache() {
        this.cache = new ConcurrentHashMap<>();
        this.lock = new ReentrantLock();
    }

    /**
     * Adds a product metadata entry to the cache.
     */
    public void add(String productId, ProductMetadata metadata) {
        lock.lock();
        try {
            // Check if the product is already in the cache
            if (cache.containsKey(productId)) {
                LOGGER.warn("Product {} is already in the cache", productId);
                return;
            }

            // Add the product metadata to the cache
            cache.put(productId, metadata);
        } finally {
            lock.unlock();
        }
    }

    /**
     * Updates a product metadata entry in the cache.
     */
    public void update(String productId, ProductMetadata metadata) {
        lock.lock();
        try {
            // Check if the product is in the cache
            if (!cache.containsKey(productId)) {
                LOGGER.warn("Product {} is not in the cache", productId);
                return;
            }

            // Update the product metadata in the cache
            cache.put(productId, metadata);
        } finally {
            lock.unlock();
        }
    }

    /**
     * Retrieves a product metadata entry from the cache.
     */
    public ProductMetadata get(String productId) {
        lock.lock();
        try {
            // Check if the product is in the cache
            if (!cache.containsKey(productId)) {
                LOGGER.warn("Product {} is not in the cache", productId);
                return null;
            }

            // Retrieve the product metadata from the cache
            return cache.get(productId);
        } finally {
            lock.unlock();
        }
    }

    /**
     * Removes a product metadata entry from the cache.
     */
    public void remove(String productId) {
        lock.lock();
        try {
            // Check if the product is in the cache
            if (!cache.containsKey(productId)) {
                LOGGER.warn("Product {} is not in the cache", productId);
                return;
            }

            // Remove the product metadata from the cache
            cache.remove(productId);
        } finally {
            lock.unlock();
        }
    }
}
```
