#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <assert.h>

// Data structure for a record in the collection
struct Record {
    int key;
    long offset;
    void* data_payload;
};

// Data structure for the collection
struct Collection {
    struct Record** records;
    int num_records;
    sem_t mutex;
    pthread_cond_t cv;
};

// Initialize a new collection with the given number of records
void init_collection(struct Collection* col, int num_records) {
    // Allocate memory for the array of records
    col->records = (struct Record**)malloc(num_records * sizeof(struct Record*));
    if (!col->records) {
        perror("Failed to allocate memory for collection");
        exit(1);
    }

    // Initialize the mutex and condition variable for synchronization
    sem_init(&col->mutex, 0, 1);
    pthread_cond_init(&col->cv, NULL);

    // Set the number of records to 0
    col->num_records = 0;
}

// Add a new record to the collection
void add_record(struct Collection* col, int key, long offset, void* data_payload) {
    struct Record* rec = (struct Record*)malloc(sizeof(struct Record));
    if (!rec) {
        perror("Failed to allocate memory for record");
        exit(1);
    }

    // Set the fields of the new record
    rec->key = key;
    rec->offset = offset;
    rec->data_payload = data_payload;

    // Acquire the mutex and signal the condition variable to wake up any waiting threads
    sem_wait(&col->mutex);
    col->num_records++;
    pthread_cond_signal(&col->cv);

    // Add the record to the end of the array
    col->records[col->num_records - 1] = rec;

    // Release the mutex and return
    sem_post(&col->mutex);
}

// Remove a record from the collection based on its key
void remove_record(struct Collection* col, int key) {
    struct Record** rec = NULL;

    // Acquire the mutex and search for the record to be removed
    sem_wait(&col->mutex);
    for (int i = 0; i < col->num_records; i++) {
        if (col->records[i]->key == key) {
            rec = &col->records[i];
            break;
        }
    }

    // If the record was found, remove it from the array and free its memory
    if (rec) {
        *rec = col->records[--col->num_records];
        free(*rec);
    }

    // Release the mutex and return
    sem_post(&col->mutex);
}

// Retrieve a record from the collection based on its key
void* retrieve_record(struct Collection* col, int key) {
    struct Record* rec = NULL;

    // Acquire the mutex and search for the record to be retrieved
    sem_wait(&col->mutex);
    for (int i = 0; i < col->num_records; i++) {
        if (col->records[i]->key == key) {
            rec = col->records[i];
            break;
        }
    }

    // If the record was found, return a copy of its data payload
    if (rec) {
        void* data_payload = malloc(sizeof(void*));
        memcpy(data_payload, rec->data_payload, sizeof(void*));
        return data_payload;
    }

    // If the record was not found, return NULL
    return NULL;
}

// Clean up a collection and free its resources
void destroy_collection(struct Collection* col) {
    // Acquire the mutex and signal the condition variable to wake up any waiting threads
    sem_wait(&col->mutex);
    pthread_cond_signal(&col->cv);

    // Free all records in the collection
    for (int i = 0; i < col->num_records; i++) {
        free(col->records[i]);
    }

    // Free the mutex and condition variable
    sem_destroy(&col->mutex);
    pthread_cond_destroy(&col->cv);

    // Free the memory for the collection
    free(col->records);
}
