    char shipping_method[100];
    char status[100];
    time_t order_date;
} Order;

// Define a function to filter and sort the orders based on the given criteria
void filterAndSortOrders(Order* orders, int num_orders) {
    // Initialize variables for filtering and sorting
    int num_qualifying_orders = 0;
    Order* qualifying_orders = (Order*)malloc(num_orders * sizeof(Order));

    // Iterate through each order and check if it meets the criteria
    for (int i = 0; i < num_orders; i++) {
        Order current_order = orders[i];

        // Check if the order date is within the last six months
        time_t now = time(NULL);
        if ((now - current_order.order_date) <= (6 * 30 * 24 * 60 * 60)) {
            // Check if the shipping method is 'Express'
            if (strcmp(current_order.shipping_method, "Express") == 0) {
                // Check if the customer status is 'Active'
                if (strcmp(current_order.status, "Active") == 0) {
                    // Add the order to the list of qualifying orders
                    qualifying_orders[num_qualifying_orders++] = current_order;
                }
            }
        }
    }

    // Sort the list of qualifying orders by order date
    qsort(qualifying_orders, num_qualifying_orders, sizeof(Order), compareOrdersByDate);

    // Print the report on the number of qualifying orders
    printf("Number of qualifying orders: %d\n", num_qualifying_orders);

    // Free the memory allocated for the list of qualifying orders
    free(qualifying_orders);
}

// Define a function to compare two orders by order date
int compareOrdersByDate(const void* order1, const void* order2) {
    Order* o1 = (Order*)order1;
    Order* o2 = (Order*)order2;

    if (o1->order_date < o2->order_date) {
        return -1;
    } else if (o1->order_date > o2->order_date) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    // Define a list of orders to be processed
    Order orders[] = {
        {1, "Customer 1", "Express", "Active", time(NULL) - (6 * 30 * 24 * 60 * 60)},
        {2, "Customer 2", "Standard", "Inactive", time(NULL) - (5 * 30 * 24 * 60 * 60)},
        {3, "Customer 3", "Express", "Active", time(NULL) - (4 * 30 * 24 * 60 * 60)},
        {4, "Customer 4", "Standard", "Inactive", time(NULL) - (3 * 30 * 24 * 60 * 60)},
        {5, "Customer 5", "Express", "Active", time(NULL) - (2 * 30 * 24 * 60 * 60)},
        {6, "Customer 6", "Standard", "Inactive", time(NULL) - (1 * 30 * 24 * 60 * 60)}
    };

    // Call the filter and sort function with the list of orders
    int num_orders = sizeof(orders) / sizeof(Order);
    filterAndSortOrders(orders, num_orders);

    return 0;
}
