#define MAX_POINTS 10000
#define NUM_THREADS 4

typedef struct data_point {
    long timestamp;
    double value;
    int status;
    void *metadata;
} data_point_t;

typedef struct file_io_context {
    char *filepath;
    size_t file_size;
    size_t offset;
    int fd;
} file_io_ctx_t;

typedef struct data_filter {
    double min_value;
    double max_value;
    bool has_min_value;
    bool has_max_value;
} data_filter_t;

typedef struct thread_context {
    pthread_t tid;
    file_io_ctx_t *file_ctx;
    data_filter_t *filter;
    int num_points;
    bool error;
} thread_ctx_t;

void enhanced_data_pipeline(char *filepath, data_filter_t *filter) {
    // Initialize file I/O context
    file_io_ctx_t file_ctx = {NULL, 0, 0, -1};
    if (strcmp(filepath, "-") == 0) {
        file_ctx.fd = STDIN_FILENO;
    } else {
        struct stat st = {0};
        int fd = open(filepath, O_RDONLY);
        if (fd < 0) {
            printf("Error opening file %s: %s\n", filepath, strerror(errno));
            exit(-1);
        }
        if (fstat(fd, &st) < 0) {
            printf("Error statting file %s: %s\n", filepath, strerror(errno));
            close(fd);
            exit(-1);
        }
        file_ctx.file_size = st.st_size;
        file_ctx.fd = fd;
    }

    // Initialize data points array and filter
    data_point_t *data_points = malloc(sizeof(data_point_t) * MAX_POINTS);
    int num_points = 0;
    bool error = false;

    // Initialize thread pool and work queues
    pthread_t threads[NUM_THREADS];
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Read and parse file data in parallel using multiple threads
    for (int i = 0; i < NUM_THREADS && !error; ++i) {
        thread_ctx_t *thread_ctx = malloc(sizeof(thread_ctx_t));
        thread_ctx->file_ctx = &file_ctx;
        thread_ctx->filter = filter;
        thread_ctx->num_points = 0;
        thread_ctx->error = false;

        if (pthread_create(&threads[i], NULL, read_and_parse_file_data, thread_ctx) < 0) {
            error = true;
            printf("Error creating thread %d: %s\n", i + 1, strerror(errno));
        } else {
            pthread_mutex_lock(&lock);
            while (!thread_ctx->error && thread_ctx->num_points == 0) {
                pthread_cond_wait(&cond, &lock);
            }
            if (thread_ctx->error) {
                error = true;
                printf("Error reading file data in thread %d: %s\n", i + 1, strerror(errno));
            } else {
                num_points += thread_ctx->num_points;
            }
            pthread_mutex_unlock(&lock);
        }
    }

    // Join threads and free resources
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) < 0) {
            printf("Error joining thread %d: %s\n", i + 1, strerror(errno));
        }
    }
    free(file_ctx.filepath);
    close(file_ctx.fd);
    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond);

    // Filter and sort data points
    if (filter) {
        for (int i = 0; i < num_points; ++i) {
            bool pass = true;
            if (filter->has_min_value && data_points[i].value < filter->min_value) {
                pass = false;
            } else if (filter->has_max_value && data_points[i].value > filter->max_value) {
                pass = false;
            }
            if (!pass) {
                continue;
            }
        }
    }

    // Output data points
    for (int i = 0; i < num_points; ++i) {
        printf("%ld %f %d\n", data_points[i].timestamp, data_points[i].value, data_points[i].status);
    }

    // Free memory
    free(data_points);
}

void *read_and_parse_file_data(void *thread_ctx) {
    thread_ctx_t *ctx = (thread_ctx_t *)thread_ctx;
    file_io_ctx_t *file_ctx = ctx->file_ctx;
    data_filter_t *filter = ctx->filter;
    int num_points = 0;
    bool error = false;

    // Read and parse file data in chunks
    size_t read_size = MIN(file_ctx->file_size - file_ctx->offset, MAX_READ_SIZE);
    char *buffer = malloc(read_size + 1);
    if (read(file_ctx->fd, buffer, read_size) < 0) {
        error = true;
        printf("Error reading from file %s: %s\n", file_ctx->filepath, strerror(errno));
    } else {
        buffer[read_size] = '\0';
        char *cursor = buffer;
        while (cursor < buffer + read_size) {
            // Parse data point from current cursor position
            long timestamp = 0;
            double value = NAN;
            int status = -1;
            if (sscanf(cursor, "%ld,%lf,%d", &timestamp, &value, &status) == 3) {
                if (filter && filter->has_min_value && value < filter->min_value) {
                    // Skip data point if it does not pass the filter
                    continue;
                } else if (filter && filter->has_max_value && value > filter->max_value) {
                    continue;
                }
                data_point_t *data_point = &data_points[num_points];
                data_point->timestamp = timestamp;
                data_point->value = value;
                data_point->status = status;
                cursor += strcspn(cursor, ",");
            } else {
                // Malformed record or incomplete file
                error = true;
                break;
            }
            num_points++;
        }
    }
    free(buffer);

    // Update thread context and signal completion
    ctx->num_points = num_points;
    ctx->error = error;
    pthread_mutex_lock(&lock);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
    return NULL;
}
