// Define a struct to represent each connection
typedef struct {
    char client_ip[16];
    int server_port;
    int state;
    time_t last_active;
} tcp_connection_info_t;

// Define a hash table to store the connections
typedef struct {
    tcp_connection_info_t** buckets;
    size_t num_buckets;
} connection_table_t;

// Initialize the connection table with a given number of buckets
void init_connection_table(connection_table_t* table, size_t num_buckets) {
    table->num_buckets = num_buckets;
    table->buckets = (tcp_connection_info_t**)malloc(sizeof(tcp_connection_info_t*) * num_buckets);
    for (size_t i = 0; i < num_buckets; i++) {
        table->buckets[i] = NULL;
    }
}

// Insert a new connection into the table
void insert_connection(connection_table_t* table, tcp_connection_info_t* conn) {
    // Calculate the hash value for the given IP and port
    size_t hash = conn->server_port % table->num_buckets;
    // If there is already a connection with the same IP and port in the bucket, replace it
    if (table->buckets[hash] != NULL && strcmp(table->buckets[hash]->client_ip, conn->client_ip) == 0 && table->buckets[hash]->server_port == conn->server_port) {
        free(table->buckets[hash]);
    }
    // Allocate memory for the new connection and copy its data
    tcp_connection_info_t* new_conn = (tcp_connection_info_t*)malloc(sizeof(tcp_connection_info_t));
    memcpy(new_conn, conn, sizeof(tcp_connection_info_t));
    // Insert the new connection into the bucket
    table->buckets[hash] = new_conn;
}

// Delete a connection from the table
void delete_connection(connection_table_t* table, const char* client_ip, int server_port) {
    // Calculate the hash value for the given IP and port
    size_t hash = server_port % table->num_buckets;
    // If there is a connection with the same IP and port in the bucket, remove it
    if (table->buckets[hash] != NULL && strcmp(table->buckets[hash]->client_ip, client_ip) == 0 && table->buckets[hash]->server_port == server_port) {
        free(table->buckets[hash]);
        table->buckets[hash] = NULL;
    }
}

// Retrieve a connection from the table based on its IP and port
tcp_connection_info_t* get_connection(connection_table_t* table, const char* client_ip, int server_port) {
    // Calculate the hash value for the given IP and port
    size_t hash = server_port % table->num_buckets;
    // If there is a connection with the same IP and port in the bucket, return it
    if (table->buckets[hash] != NULL && strcmp(table->buckets[hash]->client_ip, client_ip) == 0 && table->buckets[hash]->server_port == server_port) {
        return table->buckets[hash];
    }
    // Otherwise, return NULL
    return NULL;
}

// Periodically checkpoint the connection table to disk
void checkpoint_table(connection_table_t* table) {
    // Allocate memory for a temporary file name
    char* tmp_filename = (char*)malloc(256);
    // Generate a random file name using the current time and the number of buckets in the table
    sprintf(tmp_filename, "/tmp/connection-table.%d-%ld", table->num_buckets, time(NULL));
    // Open the temporary file for writing
    FILE* tmp_file = fopen(tmp_filename, "wb");
    // Serialize each bucket in the table to the file
    for (size_t i = 0; i < table->num_buckets; i++) {
        tcp_connection_info_t* conn = table->buckets[i];
        if (conn != NULL) {
            fwrite(conn, sizeof(tcp_connection_info_t), 1, tmp_file);
        }
    }
    // Close the temporary file and rename it to the actual checkpoint filename
    fclose(tmp_file);
    char* checkpoint_filename = (char*)malloc(256);
    sprintf(checkpoint_filename, "/tmp/connection-table.%d", table->num_buckets);
    if (rename(tmp_filename, checkpoint_filename) != 0) {
        perror("Error renaming temporary file");
    }
}

// Load the connection table from a checkpoint file on disk
void load_table_from_checkpoint(connection_table_t* table, const char* checkpoint_filename) {
    // Open the checkpoint file for reading
    FILE* checkpoint_file = fopen(checkpoint_filename, "rb");
    if (checkpoint_file == NULL) {
        perror("Error opening checkpoint file");
        return;
    }
    // Read each bucket from the file and insert it into the table
    while (!feof(checkpoint_file)) {
        tcp_connection_info_t* conn = (tcp_connection_info_t*)malloc(sizeof(tcp_connection_info_t));
        fread(conn, sizeof(tcp_connection_info_t), 1, checkpoint_file);
        insert_connection(table, conn);
    }
    // Close the checkpoint file
    fclose(checkpoint_file);
}
```
