// Define the function that constructs a gRPC request to a given service endpoint, providing the flexibility to disable authentication when making the request
void createGrpcRequest(string& requestMessage, string& serviceEndpoint, bool disableAuthentication) {
    // Create a new gRPC client using Google's gRPC libraries
    grpc::ClientContext context;
    std::shared_ptr<grpc::Channel> channel = grpc::CreateChannel(serviceEndpoint, grpc::InsecureChannelCredentials());
    std::unique_ptr<grpc::Greeter::Stub> stub = greeter::NewStub(channel);

    // Disable authentication if requested
    if (disableAuthentication) {
        context.set_authorization_metadata("", "");
    }

    // Create a new gRPC request using the provided message and service endpoint
    grpc::HelloRequest request;
    request.set_message(requestMessage);
    grpc::HelloReply response;

    // Send the gRPC request to the server and get the response
    stub->SayHello(&context, request, &response);

    // Get the message from the gRPC reply
    string replyMessage = response.message();

    // Return the reply message
    return replyMessage;
}
