// Custom hash table implementation for quick key lookups
struct HashTable {
  int size; // number of buckets in the hash table
  struct Node **buckets; // array of pointers to linked lists
};

// Linked list node for storing records
struct Node {
  int key; // integer key
  long offset; // long offset value
  struct Node *next; // pointer to next node in the linked list
};

int create_record(long offset, int key, struct HashTable *ht) {
  // allocate memory for the new record
  struct Node *new_node = malloc(sizeof(struct Node));
  if (!new_node) {
    return ENOMEM; // out of memory error
  }

  // set the key and offset values
  new_node->key = key;
  new_node->offset = offset;

  // add the record to the linked list for this key
  int index = hash(key, ht);
  new_node->next = ht->buckets[index];
  ht->buckets[index] = new_node;

  return 0; // success
}

int resize_record(long offset, int key, struct HashTable *ht) {
  // check if the record exists in the hash table
  struct Node *node = find_record(key, ht);
  if (!node) {
    return ENOENT; // record not found error
  }

  // update the offset value of the existing record
  node->offset = offset;

  return 0; // success
}

int remove_record(long offset, int key, struct HashTable *ht) {
  // check if the record exists in the hash table
  struct Node *node = find_record(key, ht);
  if (!node) {
    return ENOENT; // record not found error
  }

  // remove the node from the linked list
  int index = hash(key, ht);
  struct Node **prev = &ht->buckets[index];
  while (*prev != NULL && *prev != node) {
    prev = &(*prev)->next;
  }
  if (*prev == NULL) {
    return ENOENT; // record not found error
  }
  *prev = node->next;

  free(node);

  return 0; // success
}

int find_record(long offset, int key, struct HashTable *ht) {
  // check if the record exists in the hash table
  struct Node *node = NULL;
  int index = hash(key, ht);
  for (struct Node *curr = ht->buckets[index]; curr != NULL; curr = curr->next) {
    if (curr->key == key && curr->offset == offset) {
      node = curr;
      break;
    }
  }

  return node; // success or ENOENT error code
}

int hash(int key, struct HashTable *ht) {
  // use a simple modulo method for distributing keys across the buckets
  return key % ht->size;
}

void init_hash_table(struct HashTable *ht, int size) {
  // allocate memory for the hash table and initialize the buckets to NULL
  ht->buckets = malloc(sizeof(struct Node *) * size);
  if (!ht->buckets) {
    perror("Failed to allocate memory for the hash table");
    exit(EXIT_FAILURE);
  }
  ht->size = size;
}

void destroy_hash_table(struct HashTable *ht) {
  // free the memory allocated for the hash table and the linked lists
  for (int i = 0; i < ht->size; i++) {
    struct Node *curr = ht->buckets[i];
    while (curr != NULL) {
      struct Node *next = curr->next;
      free(curr);
