#define MAX_OFFSETS 10000
#define MAX_KEYS 10000

typedef struct {
    long *offsets;
    int *keys;
} DataStore;

static void *initialize_data_store(void) {
    // Dynamically allocate memory for the offset and key arrays
    DataStore *store = malloc(sizeof(DataStore));
    store->offsets = calloc(MAX_OFFSETS, sizeof(long));
    store->keys = calloc(MAX_KEYS, sizeof(int));

    // Initialize the mutexes for thread-safe access to the arrays
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&store->lock, &attr);

    // Initialize the counter for duplicate keys
    store->duplicate_key_counter = 0;

    return store;
}

static void destroy_data_store(DataStore *store) {
    free(store->offsets);
    free(store->keys);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

// Thread-safe function to add an offset and key to the data store
static void add_offset_and_key(DataStore *store, long offset, int key) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Check if the offset and key already exist in the data store
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (store->offsets[i] == offset && store->keys[i] == key) {
            store->duplicate_key_counter++;
            pthread_mutex_unlock(&store->lock);
            return;
        }
    }

    // Add the offset and key to the data store
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (store->offsets[i] == 0) {
            store->offsets[i] = offset;
            store->keys[i] = key;
            break;
        }
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);
}

// Thread-safe function to get the highest offset value in the data store
static long get_highest_offset(DataStore *store) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Get the highest offset value from the data store
    long highest_offset = 0;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (highest_offset < store->offsets[i]) {
            highest_offset = store->offsets[i];
        }
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);

    return highest_offset;
}

// Thread-safe function to get the total number of unique keys in the data store
static int get_total_unique_keys(DataStore *store) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Get the total number of unique keys from the data store
    int total_unique_keys = 0;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (store->offsets[i] != 0) {
            total_unique_keys++;
        }
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);

    return total_unique_keys;
}

// Thread-safe function to get the number of duplicate keys in the data store
static int get_duplicate_key_counter(DataStore *store) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Get the number of duplicate keys from the data store
    int duplicate_key_counter = store->duplicate_key_counter;

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);

    return duplicate_key_counter;
}

// Thread-safe function to get the average time taken to process each file
static float get_average_file_processing_time(DataStore *store) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Get the total number of files processed from the data store
    int total_files = 0;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (store->offsets[i] != 0) {
            total_files++;
        }
    }

    // Get the total time taken to process all files from the data store
    float total_processing_time = 0.0f;
    for (int i = 0; i < MAX_OFFSETS; i++) {
        if (store->offsets[i] != 0) {
            total_processing_time += store->offsets[i];
        }
    }

    // Calculate the average time taken to process each file
    float average_file_processing_time = 0.0f;
    if (total_files > 0) {
        average_file_processing_time = total_processing_time / total_files;
    }

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);

    return average_file_processing_time;
}

// Thread-safe function to log errors encountered during file processing
static void log_error(DataStore *store, const char *message) {
    // Acquire the lock on the data store
    pthread_mutex_lock(&store->lock);

    // Log the error message
    printf("%s\n", message);

    // Release the lock on the data store
    pthread_mutex_unlock(&store->lock);
}
