// Function to manage the flexible configuration structure
void manage_config(struct config_record *records, size_t num_records) {
    // Dynamic memory allocation for records
    struct config_record *record = malloc(sizeof(struct config_record) * num_records);

    if (!record) {
        fprintf(stderr, "Error: Failed to allocate memory for configuration records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the records with random values
    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        record[i].id = rand() % 100 + 1;
        record[i].value = rand() % 100 + 1;
        record[i].record.offset = rand() % 10000 + 1;
        record[i].record.key = rand() % 100 + 1;
        record[i].record.precision = (float)rand() / RAND_MAX;
    }

