        if (!is_valid(&record[i])) {
            fprintf(stderr, "Error: Invalid configuration record\n");
            exit(EXIT_FAILURE);
        }
    }

    // Sort the records based on their associated key values using a custom comparator function
    int (*compare)(const void *, const void *) = compare_records;

    qsort(record, num_records, sizeof(struct config_record), compare);

    // Free all allocated memory when done
    free(record);
}

// Custom comparator function for sorting records based on their key values
int compare_records(const void *a, const void *b) {
    struct config_record *r1 = (struct config_record *)a;
    struct config_record *r2 = (struct config_record *)b;

    return r1->record.key - r2->record.key;
}

// Function to generate an HTTP request to a given URL with option for certificate validation
void http_request(const char *url, int validate) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Error: Failed to initialize HTTP client\n");
        exit(EXIT_FAILURE);
    }

    // Set the URL for the request
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Disable certificate validation if requested
    if (!validate) {
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    // Perform the request and check for errors
    res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "Error: Failed to perform HTTP request\n");
        exit(EXIT_FAILURE);
    }

    // Free the CURL handle when done
    curl_easy_cleanup(curl);
}

// Function to create an HTTP client in Rust with option for disabling certificate validation
void http_client(const char *url, int validate) {
    struct HttpClient client;

    // Initialize the HTTP client
    client = init_http_client();

    // Set the URL for the request
    client.url = url;

    // Disable certificate validation if requested
    if (!validate) {
        client.ssl.verifypeer = false;
        client.ssl.verifyhost = false;
    }

    // Perform the request and check for errors
    res = http_request(client);

    if (res != CURLE_OK) {
        fprintf(stderr, "Error: Failed to perform HTTP request\n");
        exit(EXIT_FAILURE);
    }

    // Free the HTTP client when done
    free_http_client(client);
}
