// Define a custom data structure for network nodes
struct Node {
    std::string ip_address;
    int port;
    enum Status { UP, DOWN } status;
};

// Define a vector to store all the nodes
std::vector<Node> nodes;

// Define a map to store the mapping between IP addresses and node indices
std::map<std::string, size_t> ip_addresses;

// Define a mutex for thread safety
std::mutex mtx;

// Function to add a new node
void addNode(const std::string& ip_address, int port) {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Check if the IP address already exists in the map
    auto it = ip_addresses.find(ip_address);
    if (it != ip_addresses.end()) {
        // If the IP address already exists, update the node instead of adding a new one
        nodes[it->second].port = port;
    } else {
        // Add a new node to the vector and map
        Node node{ip_address, port, Status::UP};
        nodes.push_back(node);
        ip_addresses[ip_address] = nodes.size() - 1;
    }
}

// Function to remove an existing node
void removeNode(const std::string& ip_address) {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Find the index of the node with the given IP address in the map
    auto it = ip_addresses.find(ip_address);
    if (it != ip_addresses.end()) {
        // Remove the node from the vector and map
        nodes.erase(nodes.begin() + it->second);
        ip_addresses.erase(it);
    }
}

// Function to update the status of a node
void updateStatus(const std::string& ip_address, Node::Status status) {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Find the index of the node with the given IP address in the map
    auto it = ip_addresses.find(ip_address);
    if (it != ip_addresses.end()) {
        // Update the status of the node
        nodes[it->second].status = status;
    }
}

// Function to search for a node with a given IP address
Node* findNode(const std::string& ip_address) {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Find the index of the node with the given IP address in the map
    auto it = ip_addresses.find(ip_address);
    if (it != ip_addresses.end()) {
        // Return a pointer to the node
        return &nodes[it->second];
    } else {
        // Return nullptr if the IP address is not found
        return nullptr;
    }
}

// Function to iterate over all nodes and perform an operation on each one
void forEachNode(std::function<void(Node&)> f) {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Iterate over all nodes in the vector and apply the given function to each one
    for (auto& node : nodes) {
        f(node);
    }
}

// Function to clean up memory and deallocate resources
void cleanup() {
    // Acquire the lock before modifying the vector
    std::lock_guard<std::mutex> lk(mtx);

    // Clear the map and vector of nodes
    ip_addresses.clear();
    nodes.clear();
}
```
