struct DataStore {
    long *offsets;
    int *keys;
    size_t capacity;
};

void initialize_data_store(struct DataStore *ds) {
    // Allocate memory for the offset and key arrays
    ds->offsets = (long *)malloc(sizeof(long) * 10000);
    ds->keys = (int *)malloc(sizeof(int) * 10000);

    // Initialize the capacity of the arrays to the maximum allowed value
    ds->capacity = 10000;
}

void resize_data_store(struct DataStore *ds, size_t new_capacity) {
    // Check if the new capacity is valid
    if (new_capacity > ULONG_MAX / sizeof(long)) {
        fprintf(stderr, "Error: Invalid new capacity\n");
        return;
    }

    // Reallocate memory for the offset and key arrays
    long *new_offsets = (long *)realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(ds->keys, new_capacity * sizeof(int));

    // Check if reallocation failed
    if (!new_offsets || !new_keys) {
        fprintf(stderr, "Error: Failed to resize data store\n");
        return;
    }

    // Update the capacity of the arrays
    ds->capacity = new_capacity;
    ds->offsets = new_offsets;
    ds->keys = new_keys;
}

void read_file(struct DataStore *ds, FILE *file) {
    // Read the file line by line and insert key-value pairs into the data store
    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        int key = atoi(strtok(buffer, "="));
        long offset = ftell(file);
        insert_key_value(ds, key, offset);
    }
}

void insert_key_value(struct DataStore *ds, int key, long offset) {
    // Check if the data store is full
    if (ds->capacity == 0) {
        fprintf(stderr, "Error: Data store is full\n");
        return;
    }

    // Insert the key-value pair into the appropriate arrays
    ds->offsets[ds->capacity] = offset;
    ds->keys[ds->capacity] = key;
    ds->capacity--;
}

void update_highest_offset(struct DataStore *ds) {
    // Calculate the highest offset value across all files
    long highest_offset = 0;
    for (size_t i = 0; i < ds->capacity; i++) {
        if (ds->offsets[i] > highest_offset) {
            highest_offset = ds->offsets[i];
        }
    }

    // Update the value in the data store
    ds->highest_offset = highest_offset;
}
