    const int num_patrons = 20;

    // Initialize the books and patrons
    initialize_books(num_books);
    initialize_patrons(num_patrons);

    // Assign random patrons to books
    assign_random_patrons();

    // Validate the records
    validate_records();

    // Populate the handler with books
    populate_handler(0, 2);

    // Free the memory allocated for the books and patrons
    free_memory();

    return 0;
}

// Function to initialize the books
void initialize_books(int num_books) {
    struct book* books = malloc(sizeof(struct book) * num_books);
    if (books == NULL) {
        printf("Error: unable to allocate memory for books\n");
        return;
    }

    // Initialize the books
    int i;
    for (i = 0; i < num_books; i++) {
        sprintf(books[i].title, "Book %d", i + 1);
        books[i].id = i + 1;
        books[i].patrons = NULL;
    }
}

// Function to initialize the patrons
void initialize_patrons(int num_patrons) {
    struct patron* patrons = malloc(sizeof(struct patron) * num_patrons);
    if (patrons == NULL) {
        printf("Error: unable to allocate memory for patrons\n");
        return;
    }

    // Initialize the patrons
    int i;
    for (i = 0; i < num_patrons; i++) {
        sprintf(patrons[i].name, "Patron %d", i + 1);
        patrons[i].id = i + 1;
        patrons[i].contact = NULL;
        patrons[i].borrowed = time(NULL);
    }
}

// Function to assign random patrons to books
void assign_random_patrons() {
    // Create a list of all the books and patrons
    struct book* all_books = malloc(sizeof(struct book) * num_books);
    if (all_books == NULL) {
        printf("Error: unable to allocate memory for all books\n");
        return;
    }

    struct patron* all_patrons = malloc(sizeof(struct patron) * num_patrons);
    if (all_patrons == NULL) {
        free(all_books);
        printf("Error: unable to allocate memory for all patrons\n");
        return;
    }

    // Assign random patrons to books
    int i, j;
    for (i = 0; i < num_books; i++) {
        struct book* book = &all_books[i];
        int patron_id = rand() % num_patrons + 1;
        while (book->patrons != NULL) {
            // Check if the patron is already assigned to another book
            j = 0;
            while (j < num_patrons && book->patrons[j].id != patron_id) {
                j++;
            }
            if (j == num_patrons) {
                break;
            } else {
                patron_id = rand() % num_patrons + 1;
            }
        }

        // Assign the patron to the book
        struct patron* patron = &all_patrons[patron_id - 1];
        if (book->patrons == NULL) {
            book->patrons = malloc(sizeof(struct patron));
            if (book->patrons == NULL) {
                printf("Error: unable to allocate memory for patrons\n");
                return;
            }
            book->patrons[0] = *patron;
        } else {
            int num_patrons = 1;
            while (book->patrons[num_patrons - 1].id != patron_id) {
                num_patrons++;
            }
            book->patrons = realloc(book->patrons, sizeof(struct patron) * num_patrons);
            if (book->patrons == NULL) {
                printf("Error: unable to allocate memory for patrons\n");
                return;
            }
            book->patrons[num_patrons - 1] = *patron;
        }
    }
}

// Function to validate the records
void validate_records() {
    // Check that all books are correctly linked to their patrons
    int i, j;
    for (i = 0; i < num_books; i++) {
        struct book* book = &all_books[i];
        if (book->patrons != NULL) {
            for (j = 0; j < num_patrons; j++) {
                if (book->patrons[j].id == all_patrons[j].id && strcmp(book->patrons[j].name, all_patrons[j].name) == 0) {
                    // Check that the linked list within each book maintains data integrity
                    if (book->patrons[j].current_book != book || book->patrons[j].borrowed != all_patrons[j].borrowed) {
                        printf("Error: data integrity issue in book %d, patron %d\n", i + 1, j + 1);
                    }
                } else {
                    // Check that no patron is assigned to more than one book
                    if (book->patrons[j].current_book == book) {
                        printf("Error: patron %d has multiple assignments\n", j + 1);
                    }
                }
            }
        }
    }
}

// Function to populate the handler with books
void populate_handler(int id, int num_handlers) {
    // Create a list of all the books and patrons
    struct book* all_books = malloc(sizeof(struct book) * num_books);
    if (all_books == NULL) {
        printf("Error: unable to allocate memory for all books\n");
        return;
    }

    // Populate the handler with books
    struct handler* handler = &handlers[id];
    int i, j;
    for (i = 0; i < num_books; i++) {
        struct book* book = &all_books[i];
        if (book->patrons != NULL) {
            for (j = 0; j < num_patrons; j++) {
                if (book->patrons[j].current_book == book) {
                    handler->books[id] = book;
                }
            }
        }
    }
}

// Function to free the memory allocated for the books and patrons
void free_memory() {
    free(all_books);
    free(all_patrons);
    free(handlers);
}
