void processStringBatch(int num_records, int range_start, int range_end,
                        int step_size, const char *format_str, unsigned seed) {
    // Allocate memory for the offset and key arrays
    int *offsets = (int *)malloc(sizeof(int) * num_records);
    char **keys = (char **)malloc(sizeof(char *) * num_records);

    // Initialize the offsets and keys with values from the specified range and step size
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = range_start + (step_size * i);
        keys[i] = (char *)malloc(1024); // Allocate memory for the string buffer
    }

    // Generate a random integer value within the specified range for each record
    for (int i = 0; i < num_records; ++i) {
        int rand_int = rand() % (range_end - range_start + 1);
        records[i].random_int = rand_int;
    }

    // Populate the string buffers with unique strings generated based on the record index and format string
    for (int i = 0; i < num_records; ++i) {
        snprintf(keys[i], 1024, format_str, i);
    }

    // Cache the MD5 hash of processed strings to handle duplicates
    // Use a linked list to store the cached hashes and their corresponding records
    typedef struct {
        char *hash;
        Record record;
        struct Node *next;
    } Node;
    Node *head = NULL;

    for (int i = 0; i < num_records; ++i) {
        // Calculate the MD5 hash of the current string
        char *hash = md5(keys[i]);

        // Check if the hash is already in the cache
        Node *node = head;
        while (node != NULL) {
            if (strcmp(hash, node->hash) == 0) {
                // If the hash is found in the cache, return the first occurrence's record
                printf("Found duplicate: %d\n", i);
                return head->record;
            }
            node = node->next;
        }

        // Add the hash to the cache and its corresponding record
        Node *new_node = (Node *)malloc(sizeof(Node));
        new_node->hash = hash;
        new_node->record = records[i];
        new_node->next = head;
        head = new_node;
    }

    // Clean up memory allocation for the offset and key arrays
    free(offsets);
    free(keys);
}
