function copyEventData() {
  // Set up logging capabilities using a third-party library
  const log = require('log');

  // Initialize arrays for timestamp, event ID, and duration values
  let timestampArr = [];
  let eventIDArr = [];
  let durationArr = [];

  // Initialize linked list of 'event' structures (each containing a 'char*' for event name and a 'float' for event duration)
  let eventList = new LinkedList();

  // Initialize hash table for efficient event lookup by ID
  let eventHashTable = {};

  // Loop through each buffered event data chunk
  for (let i = 0; i < numChunks; i++) {
    const currentChunk = chunks[i];

    // Copy timestamp, event ID, and duration values from the current chunk to the arrays
    timestampArr.push(currentChunk.timestamp);
    eventIDArr.push(currentChunk.eventID);
    durationArr.push(currentChunk.duration);

    // Add 'event' structure to the linked list for each event ID
    let newEvent = { name: currentChunk.name, duration: currentChunk.duration };
    eventList.add(newEvent);

    // Add event ID and corresponding event structure to the hash table
    eventHashTable[currentChunk.eventID] = newEvent;
  }

  // Allocate memory for the copied data in a new buffer
  const copiedDataBuffer = Buffer.alloc(numBytes);

  // Copy timestamp, event ID, and duration values from the arrays to the new buffer
  let offset = 0;
  for (let i = 0; i < numEvents; i++) {
    const timestamp = timestampArr[i];
    const eventID = eventIDArr[i];
    const duration = durationArr[i];

    // Write timestamp, event ID, and duration values to the new buffer
    copiedDataBuffer.writeUInt32BE(timestamp, offset);
    offset += 4;
    copiedDataBuffer.writeUInt16LE(eventID, offset);
    offset += 2;
    copiedDataBuffer.writeFloatLE(duration, offset);
    offset += 4;

    // Get the corresponding event structure from the hash table and write its name and duration to the new buffer
    const event = eventHashTable[eventID];
    copiedDataBuffer.writeString(event.name, offset);
    offset += event.name.length;
    copiedDataBuffer.writeFloatLE(event.duration, offset);
    offset += 4;
  }

  // Clean up memory allocations and deallocations
  timestampArr = null;
  eventIDArr = null;
  durationArr = null;
  eventList = null;
  eventHashTable = null;

  return copiedDataBuffer;
}
```
