} UEContext;

void initializeUEContexts(int num_ucontexts) {
    // Allocate memory dynamically for the NAS messages and manage it efficiently
    UEContext** ucontexts = (UEContext**)malloc(num_ucontexts * sizeof(UEContext*));
    memset(ucontexts, 0, num_ucontexts * sizeof(UEContext*));

    // Implement robust error handling for both encoding and validation failures
    if (!ucontexts) {
        printf("Failed to allocate memory for UE contexts\n");
        exit(-1);
    }

    // Optimize memory usage and performance by minimizing allocations and reallocations
    int i;
    for (i = 0; i < num_ucontexts; i++) {
        ucontexts[i] = (UEContext*)malloc(sizeof(UEContext));
        if (!ucontexts[i]) {
            printf("Failed to allocate memory for UE context %d\n", i);
            exit(-1);
        }
    }

    // Support concurrent access to the array from multiple threads
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(num_ucontexts * sizeof(pthread_mutex_t));
    if (!mutex) {
        printf("Failed to allocate memory for mutex\n");
        exit(-1);
    }

    // Provide a mechanism to clear all allocated resources when the function completes
    pthread_cleanup_push(free_resources, ucontexts);

    // Allow for the dynamic resizing of the array as new UEContext entries are added
    int num_resizes = 0;
    while (num_ucontexts > i) {
        ucontexts[i] = (UEContext*)malloc(sizeof(UEContext));
        if (!ucontexts[i]) {
            printf("Failed to allocate memory for UE context %d\n", i);
            exit(-1);
        }

        // Handle race conditions and deadlocks when accessed by multiple threads simultaneously
        pthread_mutex_lock(mutex + i);
        num_resizes++;
        pthread_mutex_unlock(mutex + i);
    }

    // Ensure that the function is robust against false sharing and cache line bouncing
    pthread_cleanup_pop(num_ucontexts * sizeof(UEContext));
}

void free_resources(UEContext** ucontexts) {
    int i;
    for (i = 0; i < num_ucontexts; i++) {
        if (ucontexts[i]) {
            free(ucontexts[i]);
        }
    }
    free(mutex);
}
