// Function to implement a caching mechanism to store frequently accessed environmental data, balancing memory usage and performance
void cacheEnvironmentalData(environmentalData* data, size_t size) {
    // Use the LRU cache eviction policy to ensure efficient use of memory
    if (cache.size() > CACHE_SIZE || cache.size() * 1.0 / CACHE_SIZE > CACHE_REPLACEMENT_THRESHOLD) {
        // Evict the least recently used item from the cache
        environmentalData evictedItem = cache.back();
        cache.pop_back();
        freeEnvironmentalDataArray(evictedItem, 1);
