int check_duplicate(LTE_DL_CCCH_Message* messages, size_t i, int cell_id) {
    // Check if any other LTE_DL_CCCH_Message structure in the array shares the same cell id as the current one being checked
    for (size_t j = 0; j < i; ++j) {
