struct ImageMetadata {
    std::string imageId;
    std::string format;
    std::string decodingFunction;
    std::string encodingFunction;
    std::vector<unsigned char> data;
};

class ImageMetadataManager {
private:
    std::unordered_map<std::string, ImageMetadata> metadataMap;
    std::map<std::string, int> formatSupported;
    std::set<std::string> imageIds;

public:
    ImageMetadataManager() {}

    void insertImageMetadata(const std::string& imageId, const std::string& format, const std::string& decodingFunction, const std::string& encodingFunction) {
        if (imageIds.find(imageId) != imageIds.end()) {
            return;
        }

        ImageMetadata metadata;
        metadata.imageId = imageId;
        metadata.format = format;
        metadata.decodingFunction = decodingFunction;
        metadata.encodingFunction = encodingFunction;
        metadataMap[imageId] = metadata;
        imageIds.insert(imageId);
    }

    void updateImageMetadata(const std::string& imageId, const std::string& format, const std::string& decodingFunction, const std::string& encodingFunction) {
        if (metadataMap.find(imageId) == metadataMap.end()) {
            return;
        }

        ImageMetadata& metadata = metadataMap[imageId];
        metadata.format = format;
        metadata.decodingFunction = decodingFunction;
        metadata.encodingFunction = encodingFunction;
