#define MAX_CELLS 1024 // maximum number of cells supported
#define MAX_UE_PER_CELL 32 // maximum number of UEs per cell
#define MAX_LTE_DL_CCCH_MESSAGES 1024 // maximum number of LTE DL CCCH messages
#define MAX_UE_CONTEXT 16384 // maximum number of UE contexts
#define MAX_PHY_STATS_ID 1024 // maximum number of PHY stats IDs
#define MAX_CELL_ID 1024 // maximum number of cell IDs
#define MAX_SESSION_ID 1024 // maximum number of session IDs

typedef struct {
    long offset;
} long_t;

typedef struct {
    int key;
} int_t;

typedef struct {
    int value;
} record_t;

typedef struct {
    long phy_stats_id;
    int cell_id;
    int channel_quality_tag;
} LTE_DL_CCCH_Message_t;

typedef struct {
    int ue_id;
    int logical_channel_group;
    int ue_stats_id;
    int session_id;
    int ue_location_tag;
} UE_CONTEXT_t;

// hash table for cell IDs
typedef struct {
    int key;
    long value;
} CellIDMap;

// hash table for PHY stats IDs
typedef struct {
    int key;
    long value;
} PhyStatsIDMap;

// data structures
long_t* offset_array = NULL;
int_t* key_array = NULL;
record_t* record_array = NULL;
LTE_DL_CCCH_Message_t* lte_dl_ccch_message_array = NULL;
UE_CONTEXT_t* ue_context_array = NULL;
CellIDMap** cell_id_map = NULL;
PhyStatsIDMap** phy_stats_id_map = NULL;
pthread_rwlock_t rwlock; // reader-writer lock for shared resources
sem_t sem; // semaphore for synchronizing access to shared resources
size_t num_cells = 0;
size_t num_lte_dl_ccch_messages = 0;
size_t num_ue_contexts = 0;
size_t num_phy_stats_ids = 0;
size_t num_cell_ids = 0;
size_t num_session_ids = 0;

// function to dynamically allocate and initialize data structures
void init_data_structures(int cell_id, int phy_stats_id) {
    // acquire reader-writer lock for shared resources
    pthread_rwlock_wrlock(&rwlock);
    // check if cell ID already exists in hash table
    CellIDMap* cell_id_map = find_cell_id(cell_id);
    if (cell_id_map == NULL) {
        // allocate memory for new cell ID map entry
        cell_id_map = malloc(sizeof(CellIDMap));
        // initialize hash table entry with new cell ID and offset value
        cell_id_map->key = cell_id;
        cell_id_map->value = num_cells++;
        // update hash table with new entry
        insert_cell_id(cell_id_map);
    }
    // check if PHY stats ID already exists in hash table
    PhyStatsIDMap* phy_stats_id_map = find_phy_stats_id(phy_stats_id);
    if (phy_stats_id_map == NULL) {
        // allocate memory for new PHY stats ID map entry
        phy_stats_id_map = malloc(sizeof(PhyStatsIDMap));
        // initialize hash table entry with new PHY stats ID and offset value
        phy_stats_id_map->key = phy_stats_id;
        phy_stats_id_map->value = num_phy_stats_ids++;
        // update hash table with new entry
        insert_phy_stats_id(phy_stats_id_map);
    }
    // allocate memory for LTE DL CCCH message and UE context arrays
    lte_dl_ccch_message_array = malloc(sizeof(LTE_DL_CCCH_Message_t) * MAX_LTE_DL_CCCH_MESSAGES);
    ue_context_array = malloc(sizeof(UE_CONTEXT_t) * MAX_UE_CONTEXT);
    // initialize LTE DL CCCH messages and UE contexts with new values
    for (int i = 0; i < MAX_LTE_DL_CCCH_MESSAGES; i++) {
        lte_dl_ccch_message_array[i].phy_stats_id = phy_stats_id;
        lte_dl_ccch_message_array[i].cell_id = cell_id;
        lte_dl_ccch_message_array[i].channel_quality_tag = rand() % 100;
    }
    for (int i = 0; i < MAX_UE_CONTEXT; i++) {
        ue_context_array[i].ue_id = i + 1;
        ue_context_array[i].logical_channel_group = cell_id_map->value;
        ue_context_array[i].ue_stats_id = phy_stats_id_map->value;
        ue_context_array[i].session_id = i + 1;
        ue_context_array[i].ue_location_tag = rand() % 100;
    }
    // link LTE DL CCCH messages and UE contexts to each other
    for (int i = 0; i < MAX_LTE_DL_CCCH_MESSAGES; i++) {
        ue_context_array[i].logical_channel_group = cell_id_map->value;
    }
    // release reader-writer lock for shared resources
    pthread_rwlock_unlock(&rwlock);
}

// function to dynamically allocate and initialize data structures when a new PHY stats ID is received
void handle_new_phy_stats_id(int phy_stats_id) {
    // acquire reader-writer lock for shared resources
    pthread_rwlock_wrlock(&rwlock);
    // check if PHY stats ID already exists in hash table
    PhyStatsIDMap* phy_stats_id_map = find_phy_stats_id(phy_stats_id);
    if (phy_stats_id_map == NULL) {
        // allocate memory for new PHY stats ID map entry
        phy_stats_id_map = malloc(sizeof(PhyStatsIDMap));
        // initialize hash table entry with new PHY stats ID and offset value
        phy_stats_id_map->key = phy_stats_id;
        phy_stats_id_map->value = num_phy_stats_ids++;
        // update hash table with new entry
        insert_phy_stats_id(phy_stats_id_map);
    }
    // release reader-writer lock for shared resources
    pthread_rwlock_unlock(&rwlock);
}

// function to dynamically allocate and initialize data structures when a new UE is detected
void handle_new_ue(int ue_id, int cell_id) {
