#include <stdlib.h> // for malloc() and free()
#include <time.h> // for srand() and rand()
#include <assert.h> // for assert()
#include "loguru.h" // for logging framework
#include "libnas.h" // for NAS message validation

// structure to represent a UE context
typedef struct {
    int key; // integer key used for indexing the UE context
    RRC_Connection_Reconfiguration msg; // validated RRC connection reconfiguration message
    NAS_Message nas_msg; // validated NAS message
} UEContext;

// array of UE contexts
UEContext ue_contexts[10000];

// memory pool for managing dynamic memory allocation
struct MemoryPool {
    void* block; // pointer to the memory block allocated
    size_t capacity; // maximum number of elements that can be stored in the block
    size_t num_elements; // current number of elements stored in the block
};
MemoryPool mempool[10]; // array of memory pools with 10 memory blocks each

// initialize the UE contexts
void initializeUEContexts(int num_ue) {
    int i;
    for (i = 0; i < num_ue; ++i) {
        // allocate memory for NAS message content
        ue_contexts[i].nas_msg.content = malloc(sizeof(NAS_Message));
        assert(ue_contexts[i].nas_msg.content != NULL);

        // initialize random integer key for the UE context
        srand(time(NULL));
        ue_contexts[i].key = rand() % 10000;

        // validate NAS message content before insertion into the array
        nas_msg_t msg;
        memset(&msg, 0, sizeof(msg));
        if (libnas_validate_message(&msg)) {
            ue_contexts[i].nas_msg = msg;
        } else {
            // log error message and discard NAS message
            loguru::error("Failed to validate NAS message");
            free(ue_contexts[i].nas_msg.content);
            ue_contexts[i].nas_msg.content = NULL;
        }
    }
}

// reset the UE contexts to their initial state
void resetUEContexts() {
    int i;
    for (i = 0; i < num_ue; ++i) {
        if (ue_contexts[i].nas_msg.content != NULL) {
            free(ue_contexts[i].nas_msg.content);
            ue_contexts[i].nas_msg.content = NULL;
        }
    }
}

// deallocate memory pools
void releaseMemoryPools() {
    int i;
    for (i = 0; i < num_mempool; ++i) {
        if (mempool[i].block != NULL) {
            free(mempool[i].block);
            mempool[i].block = NULL;
        }
    }
}
