#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Custom resize strategy:
// Reallocate the array with a new size that is 50% larger than the current size,
// but not smaller than the minimum capacity specified by the user.
void custom_resize(long** arr, int* len, int* capacity, int min_capacity) {
    if (*len > *capacity / 2 && *capacity < min_capacity) {
        // Reallocate with a new size that is 50% larger than the current size.
        *capacity = *capacity * 2;
        *arr = realloc(*arr, (*capacity) * sizeof(long));
    }
}

// Record structure containing an offset, a key, and a value.
typedef struct {
    long offset;
    int key;
    double value;
} record_t;

// Function to manage an array of records with dynamic resizing based on a configurable threshold.
void manage_records(record_t** arr, int* len, int* capacity, int min_capacity, int threshold) {
    // Initialize the array with random values within specified ranges for offsets and keys.
    srand(time(NULL));
    for (int i = 0; i < *len; i++) {
        arr[i]->offset = rand() % 100 + 1;
        arr[i]->key = rand() % 100 + 1;
        arr[i]->value = (double)rand() / RAND_MAX;
    }

    // Reallocate the array with a new size that is 50% larger than the current size, but not smaller than the minimum capacity specified by the user.
    custom_resize((long**)arr, len, capacity, min_capacity);

    // Add a record to the end of the array if it exceeds the configurable threshold.
    if (*len > threshold && *capacity < min_capacity) {
        arr[*len] = malloc(sizeof(record_t));
        arr[*len]->offset = rand() % 100 + 1;
        arr[*len]->key = rand() % 100 + 1;
        arr[*len]->value = (double)rand() / RAND_MAX;
        *len += 1;
    }
}

int main() {
    // Initialize the array with a fixed size and capacity.
    int min_capacity = 8;
    int len = 5;
    int capacity = 8;
    record_t* arr = malloc(len * sizeof(record_t));

    // Initialize each element of the array with a random value within specified ranges for offsets and keys.
    srand(time(NULL));
    for (int i = 0; i < len; i++) {
        arr[i].offset = rand() % 100 + 1;
        arr[i].key = rand() % 100 + 1;
        arr[i].value = (double)rand() / RAND_MAX;
    }

    // Call the manage_records function to add a record and resize the array if necessary.
    int threshold = 7;
    manage_records((long**)&arr, &len, &capacity, min_capacity, threshold);

    // Print the contents of the array.
    for (int i = 0; i < len; i++) {
        printf("Record %d: offset=%ld key=%d value=%.2f\n", i + 1, arr[i].offset, arr[i].key, arr[i].value);
    }

    // Free the memory allocated for the array.
    free(arr);

    return 0;
}']

