// Define data structures for offset, key, and record
typedef struct {
    long *offset;
    int *key;
    Record *record;
} DataStructures;

DataStructures allocateMemory(int numOffsets, int maxKey, int minValue, int maxValue) {
    // Allocate memory for each data structure based on user-provided size parameters
    long *offset = malloc(numOffsets * sizeof(long));
    int *key = malloc(maxKey * sizeof(int));
    Record *record = malloc(sizeof(Record) * maxKey);

    // Initialize the 'offset' array with sequential integer values starting from 0
    for (int i = 0; i < numOffsets; i++) {
        offset[i] = i;
    }

    // Initialize the 'key' array with unique integer values ranging from 0 to maxKey
    srand(time(NULL));
    int keyIdx = 0;
    while (keyIdx < maxKey) {
        int newKey = rand() % (maxValue - minValue + 1) + minValue;
        if (!contains(key, keyIdx, newKey)) {
            key[keyIdx++] = newKey;
        }
    }

    // Initialize the 'record' array by setting each 'int' field to a random value within [minValue, maxValue]
    for (int i = 0; i < maxKey; i++) {
        record[i].key = key[i];
        record[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Ensure all allocated memory is properly freed after use
    free(offset);
    free(key);
    free(record);

    return DataStructures { offset, key, record };
}

// Implement bounds checking for all array accesses
bool contains(int *array, int size, int value) {
    for (int i = 0; i < size; i++) {
        if (array[i] == value) {
            return true;
        }
    }
    return false;
}

// Handle potential overflow conditions when generating unique keys
bool generateUniqueKey(int *key, int maxKey, int minValue, int maxValue) {
    srand(time(NULL));
    while (true) {
        int newKey = rand() % (maxValue - minValue + 1) + minValue;
        if (!contains(key, maxKey, newKey)) {
            return true;
        }
