typedef struct {
    LTE_RRC_CU_TRANSPORT_PDU *head;
    LTE_RRC_CU_TRANSPORT_PDU *tail;
} DoublyLinkedList;

DoublyLinkedList *create_list() {
    // Initialize the list head and tail pointers to NULL.
    DoublyLinkedList *list = (DoublyLinkedList *)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;

    return list;
}

void destroy_list(DoublyLinkedList *list) {
    // Free all the nodes in the list.
    while (list->head != NULL) {
        LTE_RRC_CU_TRANSPORT_PDU *node = list->head;
        list->head = node->next;
        free(node);
    }

    // Free the list structure itself.
    free(list);
}

int insert_node(DoublyLinkedList *list, LTE_RRC_CU_TRANSPORT_PDU *node) {
    // Add a new node to the tail of the list.
    if (list->tail == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        LTE_RRC_CU_TRANSPORT_PDU *tail = list->tail;
        tail->next = node;
        list->tail = node;
    }

    return 0;
}

LTE_RRC_CU_TRANSPORT_PDU *remove_node(DoublyLinkedList *list, int UE_ID) {
    // Remove a node from the list.
    LTE_RRC_CU_TRANSPORT_PDU *node = NULL;
    if (list->head == NULL) {
        return node;
    } else if (list->head->UE_ID == UE_ID) {
        node = list->head;
        list->head = list->head->next;
        if (list->tail == node) {
            list->tail = NULL;
        }
    } else {
        LTE_RRC_CU_TRANSPORT_PDU *prev = list->head;
        while (prev->next != NULL && prev->next->UE_ID != UE_ID) {
            prev = prev->next;
        }
        if (prev->next == NULL) {
            return node;
        } else {
            node = prev->next;
            prev->next = node->next;
            if (list->tail == node) {
                list->tail = prev;
            }
        }
    }

    return node;
}
```
This function uses a doubly linked list to manage the LTE_RRC_CU_TRANSPORT_PDU structures. The `insert_node` and `remove_node` functions allow for adding and removing nodes from the list, respectively. The `destroy_list` function frees all the nodes in the list when it is no longer needed.

