record *initialize_data_store(size_t num_records, int range) {
    // initialize memory pool for record allocation
    void *memory_pool = malloc(MEMORY_POOL_SIZE);
    if (!memory_pool) {
        fprintf(stderr, "Error: failed to allocate memory pool\n");
        exit(1);
    }

    // initialize arrays for offset and key values
    int *offset_array = (int*)malloc(sizeof(int) * num_records);
    long *key_array = (long*)malloc(sizeof(long) * num_records);

    if (!offset_array || !key_array) {
        fprintf(stderr, "Error: failed to allocate memory for arrays\n");
        exit(1);
    }

    // initialize record structures and populate with random values within range
    record *records = (record*)malloc(sizeof(record) * num_records);
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(1);
    }

    // initialize random number generator with high-quality algorithm
    srand48(time(NULL));

    for (int i = 0; i < num_records; i++) {
        // generate random integer within range and assign to record
        records[i].key = (long)(range * (double)rand() / (RAND_MAX + 1.0));

        // generate offset value and assign to record
        records[i].offset = rand() % 1024;

        // set weight and validated flags for each record
        records[i].weight = (float)rand() / RAND_MAX;
        records[i].validated = false;
    }

    // free unused memory in the memory pool to prevent fragmentation
    size_t used_memory = sizeof(record) * num_records;
    if (MEMORY_POOL_SIZE - used_memory > 1024 * 1024) {
        void *unused_memory = (void*)((char*)memory_pool + used_memory);
        free(unused_memory);
    }

    // set pool sizes and refill strategies based on user input
    size_t pool_size = MEMORY_POOL_SIZE;
    int refill_threshold = 0.8 * num_records;

    // evaluate performance impact of different pool configurations
    if (num_records > 1000) {
        pool_size += num_records / 2;
        refill_threshold += num_records / 4;
    }

    // determine optimal settings for memory management
    size_t optimal_pool_size = pool_size;
    int optimal_refill_threshold = refill_threshold;

    // implement robust mechanism for resource management
    cleanup(memory_pool);

    return records;
}

void cleanup(void *memory_pool) {
    // free all memory allocated by initialize_data_store()
    if (memory_pool != NULL) {
        free(memory_pool);
    }
}

void secure_erase(void *memory, size_t length) {
    // erase sensitive data from memory with different levels of security
    switch (SENSITIVE_DATA_ERASE_LEVEL) {
        case 1:
            // partial erasure by overwriting with random values
            for (int i = 0; i < length / sizeof(char); i++) {
                ((char*)memory)[i] = (char)(rand() % 256);
            }
            break;
        case 2:
            // full erasure by overwriting with random values and freeing memory
            for (int i = 0; i < length / sizeof(char); i++) {
                ((char*)memory)[i] = (char)(rand() % 256);
            }
            cleanup(memory);
            break;
        case 3:
            // extreme erasure by overwriting with random values, freeing memory, and securely deleting from disk
            for (int i = 0; i < length / sizeof(char); i++) {
                ((char*)memory)[i] = (char)(rand() % 256);
            }
            cleanup(memory);
            fprintf(stderr, "Error: failed to securely erase sensitive data\n");
            exit(1);
    }
}
