// Structure to represent a mapping between QoS class and buffer status
typedef struct TID_TO_BUFFER_MAPPING {
    uint16_t qos_class;
    bool buffer_status;
    int net_id;
} TID_TO_BUFFER_MAPPING_T;

// Structure to represent a linked list of TID_TO_BUFFER_MAPPING structures
typedef struct LIST {
    TID_TO_BUFFER_MAPPING_T *head;
    TID_TO_BUFFER_MAPPING_T *tail;
    size_t size;
} LIST_T;

// Function to initialize a linked list of TID_TO_BUFFER_MAPPING structures
void init_list(LIST_T **list) {
    // Allocate memory for the list structure
    *list = (LIST_T *) malloc(sizeof(LIST_T));
    if (*list == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for list\n");
        return;
    }
    // Initialize the head and tail pointers to NULL
    (*list)->head = NULL;
    (*list)->tail = NULL;
    // Initialize the size of the list to 0
    (*list)->size = 0;
}

// Function to add a TID_TO_BUFFER_MAPPING structure to the linked list
void add_mapping(LIST_T *list, uint16_t qos_class, bool buffer_status, int net_id) {
    // Allocate memory for the new mapping structure
    TID_TO_BUFFER_MAPPING_T *new_mapping = (TID_TO_BUFFER_MAPPING_T *) malloc(sizeof(TID_TO_BUFFER_MAPPING_T));
    if (new_mapping == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for new mapping\n");
        return;
    }
    // Set the QoS class, buffer status, and network interface ID for the new mapping structure
    new_mapping->qos_class = qos_class;
    new_mapping->buffer_status = buffer_status;
    new_mapping->net_id = net_id;
    // If the list is empty, set the head and tail pointers to point to the new mapping structure
    if (list->size == 0) {
        list->head = new_mapping;
        list->tail = new_mapping;
    } else {
        // Otherwise, add the new mapping structure to the end of the list
        list->tail->next = new_mapping;
        list->tail = new_mapping;
    }
    // Increment the size of the list by 1
    list->size++;
}

// Function to remove a TID_TO_BUFFER_MAPPING structure from the linked list
void remove_mapping(LIST_T *list, uint16_t qos_class) {
    // If the list is empty, do nothing
    if (list->size == 0) {
        return;
    }
    // Otherwise, iterate through the list until we find a mapping with the specified QoS class
    TID_TO_BUFFER_MAPPING_T *curr = list->head;
    while (curr != NULL) {
        if (curr->qos_class == qos_class) {
            // If we find a matching mapping, remove it from the list
            if (curr == list->head) {
                list->head = curr->next;
            } else if (curr == list->tail) {
                list->tail = curr->prev;
            } else {
                curr->prev->next = curr->next;
                curr->next->prev = curr->prev;
            }
            // Decrement the size of the list by 1
            list->size--;
            break;
        }
        curr = curr->next;
    }
}

// Function to retrieve a TID_TO_BUFFER_MAPPING structure from the linked list
TID_TO_BUFFER_MAPPING_T *get_mapping(LIST_T *list, uint16_t qos_class) {
    // If the list is empty, return NULL
    if (list->size == 0) {
        return NULL;
    }
    // Otherwise, iterate through the list until we find a mapping with the specified QoS class
    TID_TO_BUFFER_MAPPING_T *curr = list->head;
    while (curr != NULL) {
        if (curr->qos_class == qos_class) {
            return curr;
        }
        curr = curr->next;
    }
    // If we didn't find a matching mapping, return NULL
    return NULL;
}

// Function to update the buffer status of a TID_TO_BUFFER_MAPPING structure in the linked list
void update_buffer_status(LIST_T *list, uint16_t qos_class, bool buffer_status) {
    // If the list is empty, do nothing
    if (list->size == 0) {
        return;
    }
    // Otherwise, iterate through the list until we find a mapping with the specified QoS class
    TID_TO_BUFFER_MAPPING_T *curr = list->head;
    while (curr != NULL) {
        if (curr->qos_class == qos_class) {
            curr->buffer_status = buffer_status;
            break;
        }
        curr = curr->next;
    }
}

// Function to clear the linked list of TID_TO_BUFFER_MAPPING structures
void clear_list(LIST_T **list) {
    // If the list is empty, do nothing
    if ((*list)->size == 0) {
        return;
    }
    // Otherwise, iterate through the list and free each mapping structure
    TID_TO_BUFFER_MAPPING_T *curr = (*list)->head;
    while (curr != NULL) {
        TID_TO_BUFFER_MAPPING_T *next = curr->next;
        free(curr);
        curr = next;
    }
    // Free the list structure and set its head and tail pointers to NULL
    free(*list);
    (*list)->head = NULL;
    (*list)->tail = NULL;
    // Reset the size of the list to 0
    (*list)->size = 0;
}
