["Here is an example implementation of the C function that dynamically allocates memory for and initializes two arrays: one for 'long' offset values and another for 'int' keys. Allocate memory for and initialize an array of 'record' structures, where each record contains a single 'int' value. Use a loop to set the value of each record's int field to a random value within a specified range. Ensure that the function manages memory efficiently to avoid leaks, considering scenarios where the size of the offset and key arrays may vary at runtime:
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Structure for record with an int field
typedef struct {
    int value;
} record;

// Function to dynamically allocate memory for and initialize two arrays: offset and key, and an array of records
void *init_arrays(long *offset, int *key, int num_records) {
    // Calculate the size of each array based on the number of records
    long offset_size = sizeof(long) * num_records;
    int key_size = sizeof(int) * num_records;

    // Allocate memory for the arrays and initialize them to zero
    offset = (long *)malloc(offset_size);
    memset(offset, 0, offset_size);
    key = (int *)malloc(key_size);
    memset(key, 0, key_size);

    // Initialize the values of each record's int field to a random value within a specified range
    for (int i = 0; i < num_records; i++) {
        offset[i] = rand() % 100;
        key[i] = rand() % 100;
    }

    // Allocate memory for the array of records and initialize them to zero
    record *records = (record *)malloc(sizeof(record) * num_records);
    memset(records, 0, sizeof(record) * num_records);

    // Set the value of each record's int field to a random value within a specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    return records;
}
```
