void insert_item(int key, Data* data) {
    // Create a new Item structure and allocate memory for its Data structure
    Item* item = alloc_item(key, data);
    if (item == NULL) {
        return;
    }

    // If the linked list is empty, set head and tail to point to the new Item
    if (head == NULL) {
        head = tail = item;
    } else {
        // Otherwise, append the new Item to the end of the linked list
        tail->next = item;
        tail = item;
    }

    // Update the total size of the Data structures by adding the size of the new Data structure
    total_size += sizeof(Data);
}

// Function to remove an Item from the linked list, updating the total size of the Data structures as needed
void remove_item(int key) {
    // Find the Item with the given key and its preceding and succeeding Items in the linked list
    Item* item = find_item(key);
    if (item == NULL) {
        return;
    }

    // Update the total size of the Data structures by subtracting the size of the removed Data structure
    total_size -= sizeof(Data);

    // If the Item is at the head or tail of the linked list, update the pointer to point to its successor or predecessor
    if (item == head) {
        head = item->next;
    } else if (item == tail) {
        tail = item->previous;
    }

    // Free the Item and its associated memory
    free_item(item);
}

// Function to update the value of a Data structure for a specific key, allocating new memory as needed
void update_data(int key, double value) {
    // Find the Item with the given key and its associated Data structure
    Item* item = find_item(key);
    if (item == NULL) {
        return;
    }

    // If the new value is different from the current value, update the Data structure
    if (item->data->value != value) {
        free_data(item->data); // Free the old Data structure
        item->data = alloc_data(value); // Allocate a new Data structure with the new value
    }
}

// Function to safely free all allocated memory when the Item array is no longer needed
void free_items() {
    // Iterate through each Item in the linked list and free its associated memory
    for (Item* item = head; item != NULL; item = item->next) {
        free_data(item->data);
        free(item);
    }
}

// Function to find an Item with a given key, returning NULL if not found
Item* find_item(int key) {
    // Iterate through each Item in the linked list and compare its key with the given key
    for (Item* item = head; item != NULL; item = item->next) {
        if (item->key == key) {
            return item;
        }
    }
    return NULL;
}
