  entry->event_type = rand_range('A', 'Z');

  // Initialize event log data
  event_log* event = &entry->event;
  event->status_flags = rand_range(0, 10) ? 1 : 0;

  return entry;
}

// Define function to manage memory for arrays
void* mem_manage(void* ptr, size_t size, char* type) {
  if (!ptr) {
