    exit(EXIT_FAILURE);
  }

  // Check for overflow
  if (size > 1024 * 1024) {
    fprintf(stderr, "Error: Memory allocation would exceed %zu bytes\n", size);
    exit(EXIT_FAILURE);
  }

  // Allocate memory for arrays
  void* new_ptr = realloc(ptr, size);
  if (!new_ptr) {
    fprintf(stderr, "Error: Failed to reallocate %zu bytes of %s\n", size, type);
    exit(EXIT_FAILURE);
  }

  return new_ptr;
}

