    }
}

// Function to insert a new task into the task list
int insert_task(Task** tasks, int num_tasks, Task* task) {
    if (!tasks || !num_tasks) {
        fprintf(stderr, "Error: unable to insert task (null pointer or invalid argument)\n");
        return -1;
    }

    // Check if the new task has any dependencies that are not already in the list
    int num_dependencies = task->num_dependencies;
    for (int i = 0; i < num_dependencies; i++) {
        bool found = false;
        for (int j = 0; j < num_tasks && !found; j++) {
            if (task->dependencies[i] == tasks[j]->id) {
                found = true;
            }
        }
        if (!found) {
            fprintf(stderr, "Error: unable to insert task with non-existent dependency\n");
            return -1;
        }
    }

    // Check if the new task has any conflicts with existing tasks in the list
    for (int i = 0; i < num_tasks; i++) {
        Task* current_task = tasks[i];
        if (current_task->id == task->id) {
            fprintf(stderr, "Error: unable to insert duplicate task\n");
            return -1;
        }
    }

    // Insert the new task into the list
    Task* new_task = create_task(task->id, task->priority, task->dependencies);
    if (!new_task) {
        fprintf(stderr, "Error: unable to insert new task\n");
        return -1;
    }

    // Update the number of tasks in the list and resize the array if necessary
    num_tasks++;
    if (num_tasks > tasks->length) {
        int new_length = tasks->length * 2;
        Task** new_tasks = realloc(tasks, sizeof(Task*) * new_length);
        if (!new_tasks) {
            fprintf(stderr, "Error: unable to resize task list\n");
            return -1;
        }
        tasks = new_tasks;
    }

    // Add the new task to the end of the list
    tasks[num_tasks - 1] = new_task;

    return num_tasks;
}

// Function to validate a schedule for the tasks in the list
int validate_schedule(Task** tasks, int num_tasks) {
    // Check if there are any cycles in the dependencies of the tasks
    for (int i = 0; i < num_tasks; i++) {
        Task* current_task = tasks[i];
        for (int j = 0; j < current_task->num_dependencies; j++) {
            int dependent_task_id = current_task->dependencies[j];
            bool found = false;
            for (int k = 0; k < num_tasks && !found; k++) {
                if (dependent_task_id == tasks[k]->id) {
                    found = true;
                }
            }
            if (!found) {
                fprintf(stderr, "Error: unable to validate schedule with non-existent dependency\n");
                return -1;
            }
        }
    }

    // Check if there are any conflicts between the tasks in the list
    for (int i = 0; i < num_tasks; i++) {
        Task* current_task = tasks[i];
        for (int j = 0; j < num_tasks; j++) {
            if (current_task->id != tasks[j]->id) {
                // Check for conflicts between the two tasks
                int conflict = check_conflict(current_task, tasks[j]);
                if (conflict) {
                    fprintf(stderr, "Error: unable to validate schedule with conflict\n");
                    return -1;
                }
            }
        }
    }

    return 0;
}

// Function to check for conflicts between two tasks
int check_conflict(Task* task1, Task* task2) {
    // Check if the two tasks have any overlapping dependencies
    int conflict = 0;
    for (int i = 0; i < task1->num_dependencies && !conflict; i++) {
        for (int j = 0; j < task2->num_dependencies && !conflict; j++) {
            if (task1->dependencies[i] == task2->dependencies[j]) {
                conflict = 1;
            }
        }
    }

    // Check if the two tasks have any overlapping execution times
    for (int i = 0; i < task1->num_execution_times && !conflict; i++) {
        for (int j = 0; j < task2->num_execution_times && !conflict; j++) {
            if (task1->execution_times[i] == task2->execution_times[j]) {
                conflict = 1;
            }
        }
    }

    return conflict;
}
```
