    // Periodically flush records to disk to prevent data loss in case of a program crash
    for (int i = 0; i < num_records; i++) {
        if (i % 100 == 0) {
            printf("Flushing records to disk...\n");
            // Flush the records to disk every 100 records
            flush_records(offset_array, key_array, record_array, i + 1);
        }
