            printf("Generating record at index %d...\n", i);
        }
    }
    printf("Generation completed at %s\n", get_time_str());

    // Optimize memory usage by reusing previously allocated memory structures when possible
    if (num_records > 100000) {
        free(offset_array);
        free(key_array);
        free(record_array);
    }

    return record_array;
}

