// Define the structure of a UE context
typedef struct {
    NFAPI_UE_CONTEXT_T *ue_context;
    MAC_RLC_ENTITY *mac_rlc_entity;
} UE_CONTEXT_STRUCT;

// Define an array to store the UE contexts
UE_CONTEXT_STRUCT ue_contexts[NFAPI_MAX_NUM_UES];

// Define a function to initialize the UE contexts
void initialize_ue_contexts(void) {
    // Loop through each UE in the array and perform initialization
    for (int i = 0; i < NFAPI_MAX_NUM_UES; i++) {
        ue_contexts[i].ue_context = NULL;
        ue_contexts[i].mac_rlc_entity = NULL;
    }
}

// Define a function to handle RRC connection establishment events
void rrc_connection_establishment(NFAPI_UE_CONTEXT_T *ue_context) {
    // Check if the UE context is already initialized
    if (ue_contexts[ue_context->ue_id].ue_context != NULL) {
        // The UE context has already been initialized, log a warning message
        printf("WARNING: RRC connection establishment event received for UE %d, but the UE context has already been initialized\n", ue_context->ue_id);
    } else {
        // Allocate memory for the new UE context and initialize it
        ue_contexts[ue_context->ue_id].ue_context = malloc(sizeof(NFAPI_UE_CONTEXT_T));
        memcpy(ue_contexts[ue_context->ue_id].ue_context, ue_context, sizeof(NFAPI_UE_CONTEXT_T));

        // Allocate memory for the new MAC RLC entity and initialize it
        ue_contexts[ue_context->ue_id].mac_rlc_entity = malloc(sizeof(MAC_RLC_ENTITY));
        memset(ue_contexts[ue_context->ue_id].mac_rlc_entity, 0, sizeof(MAC_RLC_ENTITY));

        // Set the MAC RLC configuration and AMBR for the new UE context
        ue_contexts[ue_context->ue_id].mac_rlc_entity->mac_rlc_config = *(&NFAPI_MAC_RLC_CONFIG);
        ue_contexts[ue_context->ue_id].mac_rlc_entity->mac_ambr = *(&NFAPI_MAC_AMBR);
    }
}

// Define a function to handle RRC disconnection events
void rrc_disconnection(NFAPI_UE_CONTEXT_T *ue_context) {
    // Check if the UE context is already initialized
    if (ue_contexts[ue_context->ue_id].ue_context != NULL) {
        // Free the memory allocated for the UE context and MAC RLC entity
        free(ue_contexts[ue_context->ue_id].ue_context);
        free(ue_contexts[ue_context->ue_id].mac_rlc_entity);

        // Set the UE context to NULL
        ue_contexts[ue_context->ue_id].ue_context = NULL;
    } else {
        // The UE context has not been initialized, log a warning message
        printf("WARNING: RRC disconnection event received for UE %d, but the UE context has not been initialized\n", ue_context->ue_id);
    }
}

// Define a function to handle dynamic changes in the number of UEs
void handle_dynamic_ue_count_changes(int num_ues) {
    // Check if the new number of UEs is greater than the current size of the UE context array
    if (num_ues > NFAPI_MAX_NUM_UES) {
        // Resize the UE context array to accommodate the new number of UEs
        ue_contexts = realloc(ue_contexts, sizeof(UE_CONTEXT_STRUCT) * num_ues);
    }

    // Initialize the new UE contexts if necessary
    for (int i = NFAPI_MAX_NUM_UES; i < num_ues; i++) {
        ue_contexts[i].ue_context = NULL;
        ue_contexts[i].mac_rlc_entity = NULL;
    }
}

// Define a function to handle the logging of initialization statuses
