  // Initialize the integer keys within a specified range and ensure their cumulative sum does not exceed a given threshold.
  int key = 0;
  bool done = false;
  while (!done) {
    for (size_t i = 0; i < num_records; i++) {
      records[i].key = key++;
      if (key > array_size) {
        // Cumulative sum exceeds threshold, stop initialization.
        done = true;
        break;
      }
