};

void handle_session(struct Session* session, struct ExternalDataStore* external_data_store) {
    switch (session->sub_action) {
        case CREATE:
            // Create new session in external data store
            if (external_data_store->type == RELATIONAL) {
                sqlite3_prepare(external_data_store->relational.db, "INSERT INTO sessions VALUES(?, ?)", -1, &stmt);
                sqlite3_bind_int(stmt, 1, session->session_id);
                sqlite3_bind_blob(stmt, 2, session->data, strlen(session->data));
                if (sqlite3_step(stmt) != SQLITE_DONE) {
                    // Handle error
                }
            } else if (external_data_store->type == KEY_VALUE) {
                const char* key = malloc(strlen(session->session_id) + strlen(external_data_store->key_value.key_prefix));
                sprintf(key, "%s%d", external_data_store->key_value.key_prefix, session->session_id);
                // Store session data in key-value store
            }
            break;
        case RETRIEVE:
            // Retrieve session from external data store
            if (external_data_store->type == RELATIONAL) {
