                const char* key = malloc(strlen(session->session_id) + strlen(external_data_store->key_value.key_prefix));
                sprintf(key, "%s%d", external_data_store->key_value.key_prefix, session->session_id);
                // Delete session data from key-value store
            }
            break;
        default:
            // Handle invalid sub_action gracefully
    }
}

struct Session* create_session(int session_id, void* data, time_t expiry_time, enum ExternalDataStoreType external_data_store_type) {
    struct Session* session = malloc(sizeof(struct Session));
    session->session_id = session_id;
