    session->session_id = session_id;
    session->sub_action = RETRIEVE;
    struct ExternalDataStore external_data_store = {
        .type = external_data_store_type,
        // Initialize external data store based on type
    };
    handle_session(session, &external_data_store);
    return session;
}

void update_session(struct Session* session) {
    session->sub_action = UPDATE;
    struct ExternalDataStore external_data_store = {
        .type = session->external_data_store_type,
        // Initialize external data store based on type
    };
    handle_session(session, &external_data_store);
}

void delete_session(struct Session* session) {
    session->sub_action = DELETE;
    struct ExternalDataStore external_data_store = {
