// Header file: transaction_manager.h
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <stdlib.h>
#include <json-c/json.h>

typedef enum {
    TRANSACTION_SUCCESS = 0,
    TRANSACTION_FAILURE = 1
} transaction_status_t;

typedef struct {
    uint64_t id;
    double amount;
    char* user_id;
    struct json_object* json; // JSON object containing the transaction data
    bool is_processed; // Indicates if the transaction has been processed or not
} transaction_t;

// Function to dynamically manage memory for and process transaction records received from an external REST API in JSON format
transaction_status_t process_transactions(const char* json_data, int num_transactions, bool is_async);

// Header file: transaction_manager.c
#include "transaction_manager.h"

// Global variables for managing transactions and memory allocation
static transaction_t* transactions = NULL; // Array of transactions
static size_t num_transactions = 0; // Number of transactions currently being processed
static bool is_processing = false; // Indicates if transactions are being processed or not

// Function to dynamically manage memory for and process transaction records received from an external REST API in JSON format
transaction_status_t process_transactions(const char* json_data, int num_transactions, bool is_async) {
    // Check if there are any ongoing transactions being processed
    if (is_processing) {
        return TRANSACTION_FAILURE;
    }

    // Parse the JSON data and retrieve the transaction records
    json_object* json = json_tokener_parse(json_data);
    if (!json) {
        return TRANSACTION_FAILURE;
    }

    // Allocate memory for the transactions
    transactions = malloc(sizeof(transaction_t) * num_transactions);
    if (!transactions) {
        json_object_put(json);
        return TRANSACTION_FAILURE;
    }

    // Initialize the transaction structures and populate them with data from the JSON object
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = json->id;
        transactions[i].amount = json->amount;
        transactions[i].user_id = strdup(json->user_id);
        transactions[i].is_processed = false;
        transactions[i].json = json_object_get(json);
    }

    // Free the JSON object, as it is no longer needed
    json_object_put(json);

    // Set the processing flag to true
    is_processing = true;

    if (is_async) {
        // Asynchronous processing mode: spawn a new thread to process the transactions
        pthread_t thread;
        int ret = pthread_create(&thread, NULL, transaction_processor, NULL);
        if (ret != 0) {
            free(transactions);
            return TRANSACTION_FAILURE;
        }
    } else {
        // Synchronous processing mode: process the transactions in the current thread
        transaction_status_t status = transaction_processor();
        if (status != TRANSACTION_SUCCESS) {
            free(transactions);
            return status;
        }
    }

    return TRANSACTION_SUCCESS;
}

// Function to process transactions in a separate thread or synchronously
transaction_status_t transaction_processor() {
    // Process the transactions one by one, checking for any errors during processing
    for (int i = 0; i < num_transactions; i++) {
        if (!transactions[i].is_processed) {
            // Process the transaction and update the is_processed flag
            transaction_status_t status = process_transaction(&transactions[i]);
            if (status != TRANSACTION_SUCCESS) {
                return status;
            }
        }
    }

    // Free the memory allocated for the transactions
    free(transactions);
    transactions = NULL;

    // Set the processing flag to false
    is_processing = false;

    return TRANSACTION_SUCCESS;
}

// Function to process a single transaction and update its status accordingly
transaction_status_t process_transaction(transaction_t* transaction) {
    // Check if the transaction has already been processed or not
    if (transaction->is_processed) {
        return TRANSACTION_SUCCESS;
    }

    // Process the transaction and update its status
    json_object* json = transaction->json;
    if (!json) {
        return TRANSACTION_FAILURE;
    }

    // TODO: Implement your code to process the transaction here

    // Update the is_processed flag and return success
    transaction->is_processed = true;
    return TRANSACTION_SUCCESS;
}
