Here is an example of a C function that dynamically allocates memory for and initializes three arrays: one for 'long' offset values, another for 'int' keys, and a third for 'double' precision values. The function also initializes an array of 'record' structures, where each record contains a 'long', an 'int', and a 'double'. The function sets the value of each record's fields to random values within specified ranges using a loop.
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Define the structure for records with long, int, and double fields
typedef struct {
    long offset;
    int key;
    double precision;
} record;

// Function to dynamically allocate memory for arrays and initialize them
void init_arrays(long *offset_arr, int *key_arr, double *precision_arr, size_t num_records) {
    // Allocate memory for offset array
    long *offset_ptr = (long *)malloc(num_records * sizeof(long));
    if (!offset_ptr) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize offset values in the array
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 1000 + 1;
    }

    // Allocate memory for key array
    int *key_ptr = (int *)malloc(num_records * sizeof(int));
    if (!key_ptr) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

