        (*measurements)[i]->timestamp = time(NULL);
        (*measurements)[i]->temperature = (*temperature)[i];
        (*measurements)[i]->humidity = (*humidity)[i];
    }
}

// Define the function to dynamically free memory for arrays of temperature, humidity, and measurement records
