// Define a structure to represent an event with timestamp, type, and message
typedef struct Event {
    time_t timestamp;
    int type;
    char *message;
} Event;

// Define a dynamic array to store events
typedef struct EventArray {
    size_t capacity;
    size_t count;
    Event **events;
} EventArray;

// Create an empty event array with a given initial capacity
EventArray *event_array_create(size_t capacity) {
    EventArray *array = malloc(sizeof(EventArray));
    if (array == NULL) {
        return NULL;
    }
    array->capacity = capacity;
    array->count = 0;
    array->events = calloc(capacity, sizeof(Event*));
    if (array->events == NULL) {
        free(array);
        return NULL;
    }
    return array;
}

// Add a new event to the array by timestamp, maintaining order
void event_array_add(EventArray *array, Event *event) {
    if (array->count == array->capacity) {
        // If the array is full, double its capacity
        size_t new_capacity = array->capacity * 2;
        Event **new_events = realloc(array->events, new_capacity * sizeof(Event*));
        if (new_events == NULL) {
            // If reallocation fails, return early without modifying the array
            return;
        }
        array->capacity = new_capacity;
        array->events = new_events;
    }
    // Add the event to the end of the array
    array->events[array->count++] = event;
}

// Remove an event from the array by timestamp, maintaining order
void event_array_remove(EventArray *array, time_t timestamp) {
    size_t index = 0;
    while (index < array->count && array->events[index]->timestamp != timestamp) {
        index++;
    }
    if (index < array->count) {
        // If the event is found, shift all subsequent events back one position
        size_t i = index + 1;
        while (i < array->count) {
            array->events[i - 1] = array->events[i];
            i++;
        }
        // Decrement the count of events by one
        array->count--;
    }
}

// Retrieve the most recent event from the array
Event *event_array_get_latest(EventArray *array) {
    if (array->count == 0) {
        return NULL;
    } else {
        return array->events[array->count - 1];
    }
}

// Periodically prune old events from the array to maintain a fixed size limit
void event_array_prune(EventArray *array, size_t max_size) {
    if (array->capacity <= max_size) {
        return;
    }
    // Sort the array by timestamp in descending order
    qsort(array->events, array->count, sizeof(Event*), event_compare);
    size_t i = 0;
    while (i < array->count && array->events[i]->timestamp < time(NULL) - max_size) {
        // Remove all events older than the maximum allowed age
        free(array->events[i]);
        i++;
    }
    if (i > 0) {
        // If any events were removed, shrink the capacity of the array by half
        size_t new_capacity = array->count * 2;
        Event **new_events = realloc(array->events, new_capacity * sizeof(Event*));
        if (new_events == NULL) {
            return;
        }
        array->capacity = new_capacity;
        array->events = new_events;
    }
}

// Compare two events by their timestamps in descending order
int event_compare(const void *a, const void *b) {
    return ((Event *)b)->timestamp - ((Event *)a)->timestamp;
}

// Free the memory used by an event array
void event_array_free(EventArray *array) {
    if (array == NULL) {
        return;
    }
    for (size_t i = 0; i < array->count; i++) {
        free(array->events[i]);
    }
    free(array->events);
    free(array);
}
