    long *offset_array = (long *)malloc(num_keys * sizeof(long));
    if (offset_array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for offset array\n");
        exit(EXIT_FAILURE);
    }
    int *key_array = (int *)malloc(num_keys * sizeof(int));
    if (key_array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for key array\n");
        exit(EXIT_FAILURE);
    }
    double *precision_array = (double *)malloc(num_keys * sizeof(double));
    if (precision_array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for precision array\n");
        exit(EXIT_FAILURE);
    }
    unsigned long *integer_array = (unsigned long *)malloc(num_keys * sizeof(unsigned long));
    if (integer_array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for integer array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (int i = 0; i < num_keys; i++) {
        offset_array[i] = offset + i * precision;
        key_array[i] = i;
        precision_array[i] = precision;
        integer_array[i] = integer + i * precision;
    }

    // Allocate memory for record array
    record *record_array = (record *)malloc(num_keys * sizeof(record));
    if (record_array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records
    for (int i = 0; i < num_keys; i++) {
        record_array[i].key = key_array[i];
        record_array[i].data_point.precision = precision_array[i];
        record_array[i].data_point.integer = integer_array[i];
    }

    // Free memory
    free(offset_array);
    free(key_array);
    free(precision_array);
    free(integer_array);
}

// Function to acquire data from external source and populate record array
void acquire_data(record *record_array) {
    // Acquire data from external source
    // ...

    // Populate records with acquired data
    for (int i = 0; i < num_keys; i++) {
        record_array[i].key = key_array[i];
        record_array[i].data_point.precision = precision_array[i];
        record_array[i].data_point.integer = integer_array[i];
    }
}

// Function to retrieve data from record array
void get_data(record *record_array, long offset, int key) {
    // Search for the record with the given key in the record array
    int index = -1;
    for (int i = 0; i < num_keys; i++) {
        if (record_array[i].key == key) {
            index = i;
            break;
        }
    }

    // If the record is found, retrieve its data
    if (index != -1) {
        printf("Offset: %ld\n", offset);
        printf("Key: %d\n", key);
        printf("Precision: %f\n", record_array[index].data_point.precision);
        printf("Integer: %lu\n", record_array[index].data_point.integer);
    } else {
        // Log error and return NULL
        fprintf(stderr, "Error: unable to find record with key %d\n", key);
        exit(EXIT_FAILURE);
    }
}
```
