// Event structure definition
typedef struct {
    long timestamp;
    int event_type;
    char* message;
} event_t;

// Event collection structure definition
struct event_collection {
    event_t** events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

// Initialize a new event collection with the given capacity
void init_event_collection(struct event_collection* coll, size_t capacity) {
    coll->events = malloc(capacity * sizeof(event_t*));
    memset(coll->events, 0, capacity * sizeof(event_t*));
    coll->capacity = capacity;
    coll->size = 0;
    pthread_mutex_init(&coll->lock, NULL);
}

// Add a new event to the collection, maintaining order based on timestamp
void add_event(struct event_collection* coll, long timestamp, int event_type, char* message) {
    // Lock the mutex before modifying the collection
    pthread_mutex_lock(&coll->lock);

    // Check if the collection is full and needs to be resized
    if (coll->size == coll->capacity) {
        // Resize the collection by 50% to prevent frequent resizing
        size_t new_capacity = coll->capacity * 3 / 2;
        event_t** new_events = realloc(coll->events, new_capacity * sizeof(event_t*));
        if (new_events == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        coll->events = new_events;
        coll->capacity = new_capacity;
    }

    // Add the new event to the end of the collection
    size_t index = coll->size++;
    coll->events[index] = malloc(sizeof(event_t));
    memset(coll->events[index], 0, sizeof(event_t));
    coll->events[index]->timestamp = timestamp;
    coll->events[index]->event_type = event_type;
    coll->events[index]->message = strdup(message);

    // Unlock the mutex after modifying the collection
    pthread_mutex_unlock(&coll->lock);
}

// Retrieve the total number of events currently stored in the collection
size_t get_event_count(struct event_collection* coll) {
    return coll->size;
}

// Filter events based on the 'event type' and retrieve all events within a specified time range
void filter_events(struct event_collection* coll, int event_type, long start_timestamp, long end_timestamp) {
    // Lock the mutex before modifying the collection
    pthread_mutex_lock(&coll->lock);

    size_t index = 0;
    while (index < coll->size && coll->events[index]->timestamp <= end_timestamp) {
        if (coll->events[index]->event_type == event_type) {
            // Print the current event
            printf("%ld: %d - %s\n", coll->events[index]->timestamp, coll->events[index]->event_type, coll->events[index]->message);
        }
        index++;
    }

    // Unlock the mutex after modifying the collection
    pthread_mutex_unlock(&coll->lock);
}

// Free the resources allocated by the event collection
void free_event_collection(struct event_collection* coll) {
    // Lock the mutex before modifying the collection
    pthread_mutex_lock(&coll->lock);

    for (size_t i = 0; i < coll->size; i++) {
        free(coll->events[i]);
    }
    free(coll->events);
    coll->size = 0;

    // Unlock the mutex after modifying the collection
    pthread_mutex_unlock(&coll->lock);
}
```
