// Define the event structure to hold timestamp, type, source module identifier, and description
typedef struct Event {
    long long timestamp; // Timestamp in milliseconds since epoch
    int type; // Event type (e.g., 1 for warning, 2 for error)
    char *source_module_id; // Source module identifier
    char *description; // Variable-length description string
} Event;

// Define the event collection data structure to hold a list of events
typedef struct EventCollection {
    int num_events; // Number of events in the collection
    int max_size; // Maximum size of the event collection
    Event *events; // Array of events
} EventCollection;

// Initialize an empty event collection with a fixed maximum size
EventCollection *init_event_collection(int max_size) {
    EventCollection *ec = malloc(sizeof(EventCollection));
    ec->num_events = 0;
    ec->max_size = max_size;
    ec->events = calloc(max_size, sizeof(Event));
    return ec;
}

// Add a new event to the collection, maintaining order based on timestamp
void add_event(EventCollection *ec, long long timestamp, int type, char *source_module_id, char *description) {
    // Check if the collection is full and needs to be resized
    if (ec->num_events == ec->max_size) {
        Event *new_events = realloc(ec->events, 2 * ec->max_size * sizeof(Event));
        if (!new_events) {
            // Reallocation failed, return and try again later
            return;
        }
        ec->events = new_events;
        ec->max_size *= 2;
    }
    Event *event = &ec->events[ec->num_events];
    event->timestamp = timestamp;
    event->type = type;
    event->source_module_id = strdup(source_module_id);
    event->description = strdup(description);
    ec->num_events++;
}

// Prune old events from the collection to maintain a fixed size limit
void prune_old_events(EventCollection *ec, long long max_timestamp) {
    int i;
    for (i = 0; i < ec->num_events; i++) {
        if (ec->events[i].timestamp < max_timestamp) {
            break;
        }
    }
    if (i > 0) {
        // Remove events up to and including the last pruned event
        ec->num_events -= i;
        memmove(ec->events, &ec->events[i], ec->num_events * sizeof(Event));
    }
}

// Get the most recent event from the collection
Event *get_recent_event(EventCollection *ec) {
    return &ec->events[ec->num_events - 1];
}

// Release the memory used by the event collection and all events
void free_event_collection(EventCollection *ec) {
    int i;
    for (i = 0; i < ec->num_events; i++) {
        free(ec->events[i].source_module_id);
        free(ec->events[i].description);
    }
    free(ec->events);
    free(ec);
}']

