// Structure for storing items
struct item {
    double value;
    char* key;
    int ref_count;
};

// Arrays to store data
double *doubles = NULL;
char **strings = NULL;
struct item *items = NULL;

// Function to increment reference count for an item
void inc_ref(int index) {
    items[index].ref_count++;
}

// Function to decrement reference count for an item
void dec_ref(int index) {
    if (--items[index].ref_count == 0) {
        free(items[index].key);
        free(items[index].value);
        items[index] = NULL;
    }
}

// Function to allocate memory for the arrays
void init() {
    srand(time(NULL));
    int num_doubles = 1000; // Number of doubles in the array
    int num_strings = 2000; // Number of strings in the array
    int num_items = 3000; // Number of items in the array

    doubles = (double*)malloc(num_doubles * sizeof(double));
    if (!doubles) {
        fprintf(stderr, "Error: Failed to allocate memory for doubles\n");
        exit(1);
    }
    memset(doubles, 0, num_doubles * sizeof(double));

    strings = (char**)malloc(num_strings * sizeof(char*));
    if (!strings) {
        fprintf(stderr, "Error: Failed to allocate memory for strings\n");
        exit(1);
    }
    memset(strings, 0, num_strings * sizeof(char*));

    items = (struct item*)malloc(num_items * sizeof(struct item));
    if (!items) {
        fprintf(stderr, "Error: Failed to allocate memory for items\n");
        exit(1);
    }
    memset(items, 0, num_items * sizeof(struct item));
}

// Function to generate a unique identifier for a string key
int gen_key(char* prefixes[], int prefix_count) {
    int i;
    char key[10]; // Maximum length of the key
    srand(time(NULL));

    // Generate a random integer between 0 and prefix_count-1
    int index = rand() % prefix_count;
    strcpy(key, prefixes[index]);

    // Append the next integer to the key
    for (i = 0; i < prefix_count - 1; i++) {
        sprintf(key + strlen(key), "%d", index);
    }

    return strdup(key);
}

// Function to add a new item to the arrays
void add_item(double value, char* key) {
    // Check if the key already exists in the array
    int i;
    for (i = 0; i < num_items; i++) {
        if (strcmp(key, items[i].key) == 0) {
            break;
        }
    }

    // If the key already exists, increment its reference count and return
    if (i < num_items) {
        inc_ref(i);
        return;
    }

    // Otherwise, allocate a new item and initialize it with the given value and key
    struct item *new_item = malloc(sizeof(struct item));
    if (!new_item) {
        fprintf(stderr, "Error: Failed to allocate memory for new item\n");
        exit(1);
    }
    new_item->value = value;
    new_item->key = key;
    new_item->ref_count = 1;

    // Add the new item to the array and return its index
    for (i = 0; i < num_items; i++) {
        if (!items[i].value) {
            items[i] = *new_item;
            free(new_item);
            break;
        }
    }
}

// Function to remove an item from the arrays
void remove_item(int index) {
    // Decrement the reference count of the item and release its memory if necessary
    dec_ref(index);

    // If the item is still referenced, return
    if (items[index].ref_count > 0) {
        return;
    }

    // Otherwise, remove it from the array and free its memory
    free(items[index].key);
    free(items[index].value);
    items[index] = NULL;
}

// Main function to demonstrate the usage of the arrays
int main() {
    init();

    // Generate a list of prefixes for unique identifier generation
    char* prefixes[] = {"A", "B", "C"};
    int prefix_count = sizeof(prefixes) / sizeof(char*);

    // Add items to the arrays
    add_item(1.0, gen_key(prefixes, prefix_count));
    add_item(2.0, gen_key(prefixes, prefix_count));
    add_item(3.0, gen_key(prefixes, prefix_count));
    add_item(4.0, gen_key(prefixes, prefix_count));

    // Print the arrays to demonstrate their usage
    for (int i = 0; i < num_items; i++) {
        printf("%d: %f - %s\n", i, items[i].value, items[i].key);
    }

    // Remove an item from the arrays
    remove_item(1);

    return 0;
}
