    int iterations = MAX_PBKDF2_ITERATIONS;

    // Derive a key for PBKDF2
    deriveKey(password, session->salt, 16, iterations, session->key, 32);

    // Generate an IV using the custom callback function
    uint8_t iv[16];
    customIvGen(password, session->salt, 16, iterations, iv, 16);

    // Select the appropriate encryption/decryption functions based on the algorithm and cipher mode
    void (*encryptFunc)(const uint8_t*, int, const uint8_t*, int, uint8_t*, int) = NULL;
    void (*decryptFunc)(const uint8_t*, int, const uint8_t*, int, uint8_t*, int) = NULL;

    if (alg == AES_128 || alg == AES_256) {
        encryptFunc = aesEncrypt;
        decryptFunc = aesDecrypt;
    } else if (alg == ChaCha20) {
        encryptFunc = chachaEncrypt;
        decryptFunc = chachaDecrypt;
    }

    // Encrypt the plaintext using the derived key and IV
    uint8_t* ciphertext = malloc(ptLen);
    encryptFunc(plaintext, ptLen, session->key, 32, iv, 16);

    // Calculate the HMAC using the derived key and plaintext
    uint8_t mac[64];
    hmacSha(session->key, 32, plaintext, ptLen, mac);

    // Write the ciphertext and MAC to the output stream
    fwrite(ciphertext, 1, ptLen + 64, stdout);
}

void decrypt(const char* password, const uint8_t* ciphertext, int ctLen, enum Algorithm alg, enum CipherMode mode, enum HashFunction hf) {
    // Initialize the session data if not already done
    if (sd.numSessions == 0) {
        sd.numSessions = 1;
        sd.sessions = malloc(sizeof(struct Session));
    } else {
        // Increment the number of sessions
        sd.numSessions++;

        // Reallocate memory for the session array
        sd.sessions = realloc(sd.sessions, sizeof(struct Session) * sd.numSessions);
    }

    // Initialize the new session struct
    struct Session* session = &sd.sessions[sd.numSessions - 1];
    session->alg = alg;
    session->mode = mode;
    session->hf = hf;
    session->password = password;

    // Read the MAC from the input stream
    uint8_t mac[64];
    fread(mac, 1, 64, stdin);

    // Verify the integrity of the ciphertext using HMAC
    hmacSha(session->key, 32, ciphertext, ctLen - 64, mac);

    // Select the appropriate encryption/decryption functions based on the algorithm and cipher mode
    void (*encryptFunc)(const uint8_t*, int, const uint8_t*, int, uint8_t*, int) = NULL;
    void (*decryptFunc)(const uint8_t*, int, const uint8_t*, int, uint8_t*, int) = NULL;

    if (alg == AES_128 || alg == AES_256) {
        encryptFunc = aesEncrypt;
        decryptFunc = aesDecrypt;
    } else if (alg == ChaCha20) {
        encryptFunc = chachaEncrypt;
        decryptFunc = chachaDecrypt;
    }

    // Decrypt the ciphertext using the derived key and IV
    uint8_t* plaintext = malloc(ctLen - 64);
    decryptFunc(ciphertext, ctLen - 64, session->key, 32, iv, 16);

    // Write the plaintext to the output stream
    fwrite(plaintext, 1, ctLen - 64, stdout);
}

void deriveKey(const char* password, const uint8_t* salt, int saltLen, int iterations, uint8_t* key, int keyLen) {
    // Generate a random IV for PBKDF2
    RAND_bytes(key, keyLen);

    // Derive the key using PBKDF2
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, saltLen, iterations, keyLen, key);
}

void aesEncrypt(const uint8_t* plaintext, int ptLen, const uint8_t* key, int keyLen, uint8_t* ciphertext, int ctLen) {
    // Select the appropriate cipher mode based on the algorithm and mode
    if (keyLen == 16 && mode == CBC) {
        AES_cbc_encrypt(plaintext, ciphertext, ptLen, &key, NULL, AES_ENCRYPT);
    } else if (keyLen == 32 && mode == GCM) {
        AES_gcm128_encrypt(plaintext, ciphertext, ptLen, key, NULL, NULL, NULL, 0, NULL, 0, 0, 0);
    } else {
        // Invalid cipher parameters
    }
}

void aesDecrypt(const uint8_t* ciphertext, int ctLen, const uint8_t* key, int keyLen, uint8_t* plaintext, int ptLen) {
    // Select the appropriate cipher mode based on the algorithm and mode
    if (keyLen == 16 && mode == CBC) {
        AES_cbc_encrypt(ciphertext, plaintext, ctLen, &key, NULL, AES_DECRYPT);
    } else if (keyLen == 32 && mode == GCM) {
        AES_gcm128_decrypt(ciphertext, plaintext, ctLen, key, NULL, NULL, NULL, 0, NULL, 0, 0, 0);
    } else {
        // Invalid cipher parameters
    }
}

void chachaEncrypt(const uint8_t* plaintext, int ptLen, const uint8_t* key, int keyLen, uint8_t* ciphertext, int ctLen) {
    if (keyLen == 32) {
        ChaCha20_ctr32(plaintext, ciphertext, ptLen, &key, NULL);
    } else {
        // Invalid key length
    }
}

void chachaDecrypt(const uint8_t* ciphertext, int ctLen, const uint8_t* key, int keyLen, uint8_t* plaintext, int ptLen) {
    if (keyLen == 32) {
        ChaCha20_ctr32(ciphertext, plaintext, ctLen, &key, NULL);
    } else {
        // Invalid key length
    }
}

void sha256(const uint8_t* data, int len, uint8_t* digest) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data, len);
    SHA256_Final(digest, &ctx);
}

void sha384(const uint8_t* data, int len, uint8_t* digest) {
    SHA384_CTX ctx;
    SHA384_Init(&ctx);
    SHA384_Update(&ctx, data, len);
    SHA384_Final(digest, &ctx);
}

void hmacSha(const uint8_t* key, int keyLen, const uint8_t* message, int msgLen, uint8_t* mac) {
    HMAC_CTX ctx;
    HMAC_Init(&ctx, key, keyLen);
    HMAC_Update(&ctx, message, msgLen);
    HMAC_Final(&ctx, mac);
}

void customIvGen(const char* password, const uint8_t* salt, int saltLen, int iterations, uint8_t* iv, int ivLen) {
    // Generate a random IV for PBKDF2
    RAND_bytes(iv, ivLen);

    // Derive the key using PBKDF2
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, saltLen, iterations, ivLen, iv);
}

void logVerbose(const char* message) {
    printf("[VERBOSE] %s\n", message);
}

void logMinimal(const char* message) {
    printf("%s\n", message);
}

void rotateKeys() {
    // Rotate the keys for all sessions
    for (int i = 0; i < sd.numSessions; i++) {
        struct Session* session = &sd.sessions[i];

        // Generate a new key using PBKDF2
        deriveKey(session->password, session->salt, 16, session->iterations + 1, session->key, 32);

        // Delete the old key
        deleteOldKeys();
    }
}

void deleteOldKeys() {
    // Shift all sessions one position to the left and reallocate memory for the array
    sd.numSessions--;

    sd.sessions = realloc(sd.sessions, sizeof(struct Session) * sd.numSessions);
}']

