// Define constants for network interface configuration
#define INTERFACE_NAME "eth0"
#define IPV4_ADDR "192.168.1.100"
#define NETMASK "255.255.255.0"
#define GATEWAY_IP "192.168.1.1"
#define DNS1 "8.8.8.8"
#define DNS2 "8.8.4.4"
#define MTU 1500

// Define constants for error handling and logging
#define LOG_FILENAME "network-interface-config.log"
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_ERROR 2

// Define function to initialize and configure network interface
int init_network_interface(void) {
    // Initialize variables for network interface configuration
    struct ifreq ifr;
    int sockfd, ret;
    char *ifname = INTERFACE_NAME;
    struct in_addr ipaddr, netmask, gateway;
    struct in_addr dns1, dns2;

    // Open a socket to configure the network interface
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket");
        return -1;
    }

    // Set up the ifreq structure for the network interface configuration
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ);
    ipaddr = inet_aton(IPV4_ADDR, &(ifr.ifr_addr));
    netmask = inet_aton(NETMASK, &(ifr.ifr_netmask));
    gateway = inet_aton(GATEWAY_IP, &(ifr.ifr_gateway));
    dns1 = inet_aton(DNS1, &(ifr.ifr_dnsaddr[0]));
    dns2 = inet_aton(DNS2, &(ifr.ifr_dnsaddr[1]));
    ifr.ifr_mtu = MTU;

    // Configure the network interface using ioctl calls
    ret = ioctl(sockfd, SIOCSIFADDR, &ifr);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }
    ret = ioctl(sockfd, SIOCSIFNETMASK, &ifr);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }
    ret = ioctl(sockfd, SIOCSIFDSTADDR, &ifr);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }
    ret = ioctl(sockfd, SIOCSIFMTU, &ifr);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }
    ret = ioctl(sockfd, SIOCSIFDNSADDR, &ifr);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }

    // Close the socket to configure the network interface
    close(sockfd);

    // Log success or error message based on configuration outcome
    FILE *log_file = fopen(LOG_FILENAME, "a+");
    if (ret == 0) {
        fprintf(log_file, "Successfully initialized and configured network interface %s\n", ifname);
    } else {
        fprintf(log_file, "Failed to initialize or configure network interface %s: %s\n", ifname, strerror(errno));
    }
    fclose(log_file);

    return ret;
}
```
