// Define the struct for each item in the array
struct item {
    double value;
    char* key;
    int ref_count;
};

// Define the hash table for the keys
struct hash_table {
    struct item** items;
    size_t capacity;
    size_t load_factor;
};

// Function to initialize the hash table
void init_hash_table(struct hash_table* table, size_t capacity) {
    table->items = (struct item**)calloc(capacity, sizeof(struct item));
    table->capacity = capacity;
    table->load_factor = 0.75;
}

// Function to insert an item into the hash table
void insert_item(struct hash_table* table, struct item* item) {
    // Calculate the hash value for the key
    size_t hash = hash_key(item->key);

    // Check if the hash table is full
    if (table->load_factor > 0.75) {
        // Resize the hash table
        resize_hash_table(table, table->capacity * 2);
    }

    // Insert the item into the hash table
    table->items[hash] = item;
}

// Function to find an item in the hash table by key
struct item* find_item(struct hash_table* table, char* key) {
    // Calculate the hash value for the key
    size_t hash = hash_key(key);

    // Check if the item exists in the hash table
    if (table->items[hash] != NULL) {
        return table->items[hash];
    } else {
        return NULL;
    }
}

// Function to increment the reference count of an item
void inc_ref_count(struct item* item) {
    item->ref_count++;
}

// Function to decrement the reference count of an item
void dec_ref_count(struct item* item) {
    item->ref_count--;
}

// Function to resize the hash table
void resize_hash_table(struct hash_table* table, size_t capacity) {
    // Create a new hash table with the new capacity
    struct hash_table* new_table = (struct hash_table*)malloc(sizeof(struct hash_table));
    init_hash_table(new_table, capacity);

    // Iterate over the items in the old hash table
    for (int i = 0; i < table->capacity; i++) {
        struct item* item = table->items[i];

        // If the item exists in the old hash table, insert it into the new hash table
        if (item != NULL) {
            insert_item(new_table, item);
        }
    }

    // Free the memory for the old hash table and assign the new hash table to it
    free(table->items);
    table = new_table;
}

// Function to generate a unique identifier for a char* key
char* gen_key(size_t seed, size_t len) {
    // Generate a random string of the specified length
    char* str = (char*)malloc(len + 1);
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + ((seed * i) % 26);
    }
    str[len] = '\0';

    // Return the generated string
    return str;
}

// Function to hash a char* key
size_t hash_key(char* key) {
    // Calculate the hash value for the key
    size_t hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i] * pow(31, i);
    }

    // Return the hash value
    return hash % 1000000;
}

// Function to release an item from memory
void release_item(struct item* item) {
    // Decrement the reference count of the item
    dec_ref_count(item);

    // If the reference count is zero, free the item's memory
    if (item->ref_count == 0) {
        free(item->key);
        free(item);
    }
}
