void simulate_environment(sensor_data* sensor_data, int num_sensors) {
    // Allocate memory for an array of sensor data structures
    sensor_data = (sensor_data*) malloc(num_sensors * sizeof(sensor_data));

    // Initialize each sensor with simulated data within the specified range
    for (int i = 0; i < num_sensors; i++) {
        // Generate a random temperature and humidity reading
        float temp = MIN_TEMPERATURE + ((float)rand() / RAND_MAX) * (MAX_TEMPERATURE - MIN_TEMPERATURE);
        float humi = MIN_HUMIDITY + ((float)rand() / RAND_MAX) * (MAX_HUMIDITY - MIN_HUMIDITY);

        // Set the timestamp to the current time
        sensor_data[i].timestamp = time(NULL);

        // Set the sensor ID to a random value
        sensor_data[i].sensor_id = (uint64_t) rand();

        // Validate the temperature and humidity readings against thresholds
        if (temp < VALIDATION_THRESHOLD || temp > (100.0f - VALIDATION_THRESHOLD)) {
            printf("Temperature reading outside of threshold: %f\n", temp);
        }
        if (humi < VALIDATION_THRESHOLD || humi > (100.0f - VALIDATION_THRESHOLD)) {
            printf("Humidity reading outside of threshold: %f\n", humi);
        }

        // Set the temperature and humidity readings
        sensor_data[i].temperature = temp;
        sensor_data[i].humidity = humi;
    }
}

// Define the function to log detailed information about system operation
