    FILE* log_file = fopen("log.txt", "a");

    // Write a header to the log file
    fprintf(log_file, "Log File - Environment Monitoring System\n\n");

    // Write detailed information about each sensor's operation status
    for (int i = 0; i < num_sensors; i++) {
        // Get the current timestamp
        time_t now = time(NULL);

        // Print a log message for each sensor, including initialization success/failure and anomalies detected during data validation
        if (sensor_data[i].timestamp != 0) {
            fprintf(log_file, "%ld - Sensor %d Initialized with Temperature: %f Humidity: %f\n", now, sensor_data[i].sensor_id, sensor_data[i].temperature, sensor_data[i].humidity);
        } else {
            fprintf(log_file, "%ld - Sensor %d Initialization Failed\n", now, sensor_data[i].sensor_id);
        }

        if (sensor_data[i].temperature < VALIDATION_THRESHOLD || sensor_data[i].temperature > (100.0f - VALIDATION_THRESHOLD)) {
            fprintf(log_file, "%ld - Temperature Reading Outside of Threshold: %f\n", now, sensor_data[i].temperature);
        }
        if (sensor_data[i].humidity < VALIDATION_THRESHOLD || sensor_data[i].humidity > (100.0f - VALIDATION_THRESHOLD)) {
            fprintf(log_file, "%ld - Humidity Reading Outside of Threshold: %f\n", now, sensor_data[i].humidity);
        }
    }

    // Close the log file
    fclose(log_file);
}
