// Define structs for arrays, strings, and structs containing a timestamp, status indicator, and reference count
typedef struct {
    double* data;
    size_t capacity;
} ArrayDouble;

typedef struct {
    char* data;
    size_t length;
} String;

typedef struct {
    time_t timestamp;
    int status;
    int refCount;
} StructWithTimeStampAndStatus;

// Define function to dynamically allocate and manage memory for arrays, strings, and structs
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: Failed to allocate %zu bytes of memory\n", size);
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

void freeMemory(void* ptr) {
    free(ptr);
}

// Define function to initialize arrays, strings, and structs with data from an external data source
void initData(void** dataPtr, size_t size, const char* type) {
    if (strcmp(type, "ArrayDouble") == 0) {
        ArrayDouble* array = allocateMemory(sizeof(ArrayDouble));
        array->data = allocateMemory(size * sizeof(double));
        array->capacity = size;
        // Initialize data from external data source
    } else if (strcmp(type, "String") == 0) {
        String* string = allocateMemory(sizeof(String));
        string->data = allocateMemory(size * sizeof(char));
        string->length = size;
        // Initialize data from external data source
    } else if (strcmp(type, "StructWithTimeStampAndStatus") == 0) {
        StructWithTimeStampAndStatus* structPtr = allocateMemory(sizeof(StructWithTimeStampAndStatus));
        structPtr->timestamp = time(NULL);
        // Initialize status indicator from external data source
        structPtr->refCount = 1;
    } else {
        printf("Error: Unsupported type %s\n", type);
    }
}

// Define function to update reference counts for arrays, strings, and structs
void updateRefCount(void** dataPtr) {
    if (strcmp(*dataPtr, "ArrayDouble") == 0) {
        ArrayDouble* array = *dataPtr;
        array->refCount++;
    } else if (strcmp(*dataPtr, "String") == 0) {
        String* string = *dataPtr;
        string->refCount++;
    } else if (strcmp(*dataPtr, "StructWithTimeStampAndStatus") == 0) {
        StructWithTimeStampAndStatus* structPtr = *dataPtr;
        structPtr->refCount++;
    }
}

// Define function to query latest available data for arrays, strings, and structs
void* getLatestData(void** dataPtr) {
    if (strcmp(*dataPtr, "ArrayDouble") == 0) {
        ArrayDouble* array = *dataPtr;
        return array->data;
    } else if (strcmp(*dataPtr, "String") == 0) {
        String* string = *dataPtr;
        return string->data;
    } else if (strcmp(*dataPtr, "StructWithTimeStampAndStatus") == 0) {
        StructWithTimeStampAndStatus* structPtr = *dataPtr;
        return structPtr->timestamp;
    } else {
        printf("Error: Unsupported type %s\n", *dataPtr);
    }
}
