#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

#define BUFFER_SIZE 4096
#define CHUNK_SIZE (1 << 20) // 1 MB

struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
    int num_extra_samples;
    struct extra_sample {
        int id;
        char *name;
        float value;
    } *extra_samples;
};

struct tiff_info extractTiffInfo(const char *filename) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    struct tiff_info info;
    info.bits_per_sample = 0;
    info.samples_per_pixel = 0;
    info.num_extra_samples = 0;
    info.extra_samples = NULL;

    // Determine the file size
    off_t filesize = lseek(fd, 0, SEEK_END);
    if (filesize == -1) {
        perror("Error determining file size");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Read the TIFF header to determine the number of bits per sample and samples per pixel
    off_t offset = lseek(fd, 0, SEEK_SET);
    char header[4];
    read(fd, &header, sizeof(header));
    if (strncmp(header, "II\x1a\x00", 4) == 0) { // little-endian
        info.bits_per_sample = 8;
        info.samples_per_pixel = 3;
    } else if (strncmp(header, "MM\x00\x2a", 4) == 0) { // big-endian
        info.bits_per_sample = 8;
        info.samples_per_pixel = 3;
    } else {
        fprintf(stderr, "Unsupported TIFF header format\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Process the file in chunks to manage large files efficiently
    off_t chunk_offset = 0;
    while (chunk_offset < filesize) {
        off_t chunk_size = CHUNK_SIZE;
        if (chunk_offset + chunk_size > filesize) {
            chunk_size = filesize - chunk_offset;
        }

        // Read the next chunk of data from the file
        char *buffer = malloc(chunk_size);
        ssize_t bytes_read = read(fd, buffer, chunk_size);
        if (bytes_read < 0) {
            perror("Error reading file");
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Parse the chunk of data to extract the number of extra samples and their information
        for (int i = 0; i < bytes_read - sizeof(header) + 1; i += sizeof(info.extra_samples[0])) {
            struct extra_sample *sample = &info.extra_samples[info.num_extra_samples];
            sample->id = buffer[i + 0];
            sample->name = buffer[i + 1];
            sample->value = buffer[i + 2] / (float)pow(2, info.bits_per_sample - 8);
        }

        // Update the number of extra samples and their information in the struct
        info.num_extra_samples += bytes_read - sizeof(header) + 1;

        // Update the offset for the next chunk
        chunk_offset += chunk_size;
    }

    close(fd);
    return info;
}

struct md5_hash {
    unsigned char hash[16];
};

struct md5_hash calculateMd5Hash(const char *input) {
    // Use the standard library cryptographic hash function to generate the MD5 hash of the input string
    struct md5_hash hash;
    MD5((unsigned char *)input, strlen(input), (unsigned char *)&hash);
    return hash;
}
