#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <pthread.h>

struct record {
    long offset;
    int key;
    int value;
};

typedef struct {
    pthread_mutex_t mutex;
    unsigned char* memory;
    size_t capacity;
    size_t used;
    size_t growth_factor;
    size_t max_capacity;
} record_pool_t;

void init_record_pool(record_pool_t* pool, size_t initial_size, size_t growth_factor, size_t max_capacity) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->memory = malloc(initial_size);
    pool->capacity = initial_size;
    pool->used = 0;
    pool->growth_factor = growth_factor;
    pool->max_capacity = max_capacity;
}

void destroy_record_pool(record_pool_t* pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->memory);
}

int record_pool_resize(record_pool_t* pool, size_t new_size) {
    // resize memory pool
    void* new_memory = realloc(pool->memory, new_size);
    if (new_memory == NULL) {
        return -1;
    }
    pool->memory = new_memory;
    pool->capacity = new_size;

    // update used space
    size_t new_used = pool->used;
    if (pool->used > new_size) {
        new_used = new_size;
    }
    pool->used = new_used;

    return 0;
}

int record_pool_alloc(record_pool_t* pool, struct record** rec, int key, int value) {
    // acquire mutex
    pthread_mutex_lock(&pool->mutex);

    // check if memory needs to be resized
    size_t new_size = pool->used + sizeof(struct record);
    if (new_size > pool->capacity) {
        int res = record_pool_resize(pool, new_size);
        if (res != 0) {
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }
    }

    // allocate memory for the new record
    *rec = (struct record*) pool->memory + pool->used;
    (*rec)->key = key;
    (*rec)->value = value;

    // update used space and release mutex
    pool->used += sizeof(struct record);
    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

int record_pool_free(record_pool_t* pool, struct record** rec) {
    // acquire mutex
    pthread_mutex_lock(&pool->mutex);

    // free memory for the record
    *rec = NULL;

    // update used space and release mutex
    pool->used -= sizeof(struct record);
    pthread_mutex_unlock(&pool->mutex);

    return 0;
}
```
