typedef struct {
    DataPacket** packets;   // Array of DataPacket pointers
    int capacity;           // Current capacity of the list
    int size;               // Current size of the list
} PacketList;

// Initialize an empty list with a given capacity
void packet_list_init(PacketList* list, int capacity) {
    assert(list != NULL);
    assert(capacity > 0);

    list->packets = (DataPacket**)malloc(sizeof(DataPacket*) * capacity);
    memset(list->packets, 0, sizeof(DataPacket*) * capacity);
    list->capacity = capacity;
    list->size = 0;
}

// Free the memory used by a list and reset its size to zero
void packet_list_free(PacketList* list) {
    assert(list != NULL);

    for (int i = 0; i < list->capacity; i++) {
        if (list->packets[i] != NULL) {
            free(list->packets[i]->payload);
            free(list->packets[i]);
        }
    }
    free(list->packets);
    list->packets = NULL;
    list->capacity = 0;
    list->size = 0;
}

// Add a new DataPacket to the list, allocating memory for its payload if necessary
void packet_list_add(PacketList* list, DataPacket* packet) {
    assert(list != NULL);
    assert(packet != NULL);

    // Allocate memory for the payload if it is not already allocated
    if (packet->payload == NULL) {
        packet->payload = (char*)malloc(MAX_PAYLOAD_SIZE * sizeof(char));
        memset(packet->payload, 0, MAX_PAYLOAD_SIZE * sizeof(char));
    }

    // Add the new DataPacket to the list
    if (list->size == list->capacity) {
        list->packets = (DataPacket**)realloc(list->packets, (list->capacity + 1) * sizeof(DataPacket*));
        assert(list->packets != NULL);

        list->packets[list->size] = packet;
        list->size++;
    } else {
        list->packets[list->size++] = packet;
    }
}

// Remove a DataPacket from the list by its sequence number
DataPacket* packet_list_remove(PacketList* list, uint32_t seq_num) {
    assert(list != NULL);

    for (int i = 0; i < list->size; i++) {
        if (list->packets[i]->seq_num == seq_num) {
            DataPacket* packet = list->packets[i];
            list->packets[i] = NULL;

