Profile* generate_profiles(unsigned int num_profiles) {
    // Check if the number of profiles is within the allowed range
    if (num_profiles > MAX_PROFILES) {
        fprintf(stderr, "Error: Number of profiles exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for the profiles and initialize the pointers to NULL
    Profile* profiles = (Profile*)malloc(num_profiles * sizeof(Profile));
    if (!profiles) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the profile identifiers, numerical values, and preference text descriptions arrays
    unsigned int* identifier_array = (unsigned int*)malloc(num_profiles * sizeof(unsigned int));
    float* numerical_value_array = (float*)malloc(num_profiles * sizeof(float));
    char** preference_text_description_array = (char**)malloc(num_profiles * sizeof(char*));
    for (int i = 0; i < num_profiles; ++i) {
        identifier_array[i] = 0;
        numerical_value_array[i] = 0.0f;
        preference_text_description_array[i] = NULL;
    }

    // Generate the profiles concurrently using a thread pool
    pthread_t* threads = (pthread_t*)malloc(MAX_THREADS * sizeof(pthread_t));
    for (int i = 0; i < MAX_THREADS && i < num_profiles; ++i) {
        int profile_idx = i;
        pthread_create(&threads[i], NULL, generate_profile, (void*)&profile_idx);
    }

    // Join the threads and check for any errors
    for (int i = 0; i < MAX_THREADS && i < num_profiles; ++i) {
        void* thread_retval = NULL;
        pthread_join(threads[i], &thread_retval);
        if (thread_retval != NULL) {
            fprintf(stderr, "Error: Thread %d failed with error code %p\n", i, thread_retval);
            free(profiles);
            return NULL;
        }
    }

    // Validate the generated profiles against predefined criteria using the external configuration management library
    for (int i = 0; i < num_profiles; ++i) {
        Profile* profile = &profiles[i];
        if (!config_validate_range(profile->identifier, IDENTIFIER_SIZE)) {
            fprintf(stderr, "Error: Identifier %u is outside the allowed range\n", profile->identifier);
            free(profiles);
            return NULL;
        }
        if (!config_validate_uniqueness(profile->identifier)) {
            fprintf(stderr, "Error: Identifier %u is not unique\n", profile->identifier);
            free(profiles);
            return NULL;
        }
        if (!config_validate_distribution(profile->numerical_value, NUMERICAL_VALUE_SIZE)) {
            fprintf(stderr, "Error: Numerical value %f is outside the allowed distribution\n", profile->numerical_value);
            free(profiles);
            return NULL;
        }
        if (!config_validate_text_description(profile->preference_text_description)) {
            fprintf(stderr, "Error: Text description '%s' is not valid\n", profile->preference_text_description);
            free(profiles);
            return NULL;
        }
    }

    // Free the memory for the identifier, numerical value, and preference text description arrays
    free(identifier_array);
    free(numerical_value_array);
    free(preference_text_description_array);

    // Return the generated profiles
    return profiles;
}

// Define a thread function that generates a single profile
void* generate_profile(void* arg) {
    int profile_idx = *((int*)arg);
    Profile* profile = &profiles[profile_idx];

    // Generate the identifier, numerical value, and preference text description for the profile
    profile->identifier = random() % MAX_IDENTIFIER;
    profile->numerical_value = (float)rand() / RAND_MAX;
    profile->preference_text_description = config_generate_text_description();

    // Return NULL to indicate that the thread has finished successfully
    return NULL;
}
