    // Include logging mechanism that records initialization process and errors
    log_init(INFO, "initialize_system");

    // Test the function in a realistic production-like environment
    for (int i = 0; i < num_records; i++) {
        Record record = records[i];
        int key = key_array[i];
        long offset = offset_array[i];

        // Perform cryptographic operations using OpenSSL functions
        EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
        EVP_Digest_CTX *digest_ctx = EVP_Digest_CTX_new();

        // Perform operations on the records and keys using the mutex for thread safety
        pthread_mutex_lock(&mutex);
        {
            // Encrypt the record using AES-128 CBC
            EVP_EncryptInit(cipher_ctx, EVP_aes_128_cbc(), NULL, NULL);
            EVP_EncryptUpdate(cipher_ctx, NULL, &offset, record.value);
            EVP_EncryptFinal(cipher_ctx, NULL, &offset);

            // Generate a digest using MD5 and SHA-1
            EVP_DigestInit(digest_ctx, EVP_md5());
            EVP_DigestUpdate(digest_ctx, record.value, sizeof(record.value));
            EVP_DigestFinal(digest_ctx, NULL, &offset);

            // Generate a digest using SHA-256 and RSA-MD5
            EVP_DigestInit(digest_ctx, EVP_sha256());
            EVP_DigestUpdate(digest_ctx, record.value, sizeof(record.value));
            EVP_DigestFinal(digest_ctx, NULL, &offset);

            // Generate a digest using Camellia-128 CBC and RSA-MD5
            EVP_DigestInit(digest_ctx, EVP_camellia_128_cbc());
            EVP_EncryptInit(cipher_ctx, EVP_rsa_md5(), NULL, NULL);
            EVP_EncryptUpdate(cipher_ctx, NULL, &offset, record.value);
            EVP_EncryptFinal(cipher_ctx, NULL, &offset);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free memory for arrays and records
    free(offset_array);
    free(key_array);
    free(records);
}
