void compress(const char *path, const char *out_path, int alg) {
    int fd_in = open(path, O_RDONLY);
    if (fd_in < 0) {
        perror("open failed");
        return;
    }
    int fd_out = open(out_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd_out < 0) {
        perror("open failed");
        close(fd_in);
        return;
    }
    size_t input_size = get_input_size(path);
    char *buffer = (char *) malloc(input_size + 1);
    if (!buffer) {
        perror("malloc failed");
        close(fd_in);
        close(fd_out);
        return;
    }
    ssize_t bytes_read = read(fd_in, buffer, input_size);
    if (bytes_read < 0) {
        perror("read failed");
        free(buffer);
        close(fd_in);
        close(fd_out);
        return;
    }
    buffer[bytes_read] = '\0';
    size_t output_size = compress_size(buffer, input_size, alg);
    char *output_buffer = (char *) malloc(output_size + 1);
    if (!output_buffer) {
        perror("malloc failed");
        free(buffer);
        close(fd_in);
        close(fd_out);
        return;
    }
    size_t bytes_written = compress(buffer, output_buffer, input_size, alg);
    if (bytes_written < 0) {
        perror("compress failed");
        free(buffer);
        free(output_buffer);
        close(fd_in);
        close(fd_out);
        return;
    }
    write(fd_out, output_buffer, bytes_written);
    free(buffer);
    free(output_buffer);
    close(fd_in);
    close(fd_out);
}

size_t get_input_size(const char *path) {
    struct stat sb;
    if (stat(path, &sb) == 0) {
        return sb.st_size;
    } else {
        perror("stat failed");
        return -1;
    }
}

