// Define the maximum number of interfaces that can be configured
#define MAX_INTERFACES 64

// Structure to hold information about a network interface
typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    char mac_address[17];
} network_interface;

// Array to store the network interfaces
network_interface* interfaces = NULL;
size_t num_interfaces = 0;

// Function to configure a network interface
int configure_network_interface(const char* ip_address, const char* subnet_mask, const char* gateway, const char* mac_address) {
    // Check if the number of interfaces has been reached
    if (num_interfaces >= MAX_INTERFACES) {
        return -1;
    }

    // Allocate memory for the new interface structure
    network_interface* new_interface = malloc(sizeof(network_interface));
    if (!new_interface) {
        return -2;
    }

    // Set the IP address, subnet mask, gateway, and MAC address of the interface
    strcpy(new_interface->ip_address, ip_address);
    strcpy(new_interface->subnet_mask, subnet_mask);
    strcpy(new_interface->gateway, gateway);
    strcpy(new_interface->mac_address, mac_address);

    // Add the new interface to the array of interfaces
    interfaces = realloc(interfaces, (num_interfaces + 1) * sizeof(network_interface));
    if (!interfaces) {
        return -3;
    }
    interfaces[num_interfaces++] = new_interface;

    return 0;
}

// Function to initialize the network interface
void init_network_interface() {
    // Set up the dynamic array of interfaces
    interfaces = calloc(MAX_INTERFACES, sizeof(network_interface));
    if (!interfaces) {
        fprintf(stderr, "Error: unable to allocate memory for network interfaces\n");
        exit(1);
    }
}

// Function to configure the network interface based on a configuration file
void config_network_interface_from_file(const char* filename) {
    // Open the configuration file and read it line by line
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: unable to open configuration file %s\n", filename);
        exit(1);
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Skip blank lines and comments
        if (buffer[0] == '\n' || buffer[0] == '#') {
            continue;
        }

        // Get the IP address, subnet mask, gateway, and MAC address from the configuration line
        char* ip_address = strtok(buffer, " \t");
        char* subnet_mask = strtok(NULL, "/");
        char* gateway = strtok(NULL, "\n");
        char* mac_address = strtok(NULL, "\n");

        // Configure the network interface
        int result = configure_network_interface(ip_address, subnet_mask, gateway, mac_address);
        if (result < 0) {
            fprintf(stderr, "Error: unable to configure network interface\n");
            exit(1);
        }
    }
}

// Function to read the configuration file and validate the network settings
void validate_network_configuration() {
    // Open the configuration file and read it line by line
    FILE* file = fopen("network.conf", "r");
    if (!file) {
        fprintf(stderr, "Error: unable to open configuration file\n");
        exit(1);
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Skip blank lines and comments
        if (buffer[0] == '\n' || buffer[0] == '#') {
            continue;
        }

        // Get the IP address, subnet mask, gateway, and MAC address from the configuration line
        char* ip_address = strtok(buffer, " \t");
        char* subnet_mask = strtok(NULL, "/");
        char* gateway = strtok(NULL, "\n");
        char* mac_address = strtok(NULL, "\n");

        // Validate the network settings
        int result = validate_network_settings(ip_address, subnet_mask, gateway, mac_address);
        if (result < 0) {
            fprintf(stderr, "Error: invalid network configuration\n");
            exit(1);
        }
    }
}

// Function to validate the network settings based on the input parameters
int validate_network_settings(const char* ip_address, const char* subnet_mask, const char* gateway, const char* mac_address) {
    // Check if the IP address is valid
    struct sockaddr_in sa;
    int rv = inet_pton(AF_INET, ip_address, &(sa.sin_addr));
    if (rv <= 0) {
        return -1;
    }

    // Check if the subnet mask is valid
    struct sockaddr_in sa2;
    rv = inet_pton(AF_INET, subnet_mask, &(sa2.sin_addr));
    if (rv <= 0) {
        return -2;
    }

    // Check if the gateway is valid
    struct sockaddr_in sa3;
    rv = inet_pton(AF_INET, gateway, &(sa3.sin_addr));
    if (rv <= 0) {
        return -3;
    }

    // Check if the MAC address is valid
    struct sockaddr_ll sa4;
    rv = ETH_P_ALL(mac_address, &(sa4.sll_addr));
    if (rv <= 0) {
        return -4;
    }

    // Check if the MAC address is unique
    for (size_t i = 0; i < num_interfaces; i++) {
        if (!strcmp(interfaces[i]->mac_address, mac_address)) {
            return -5;
        }
    }

    // If all validation checks pass, the network settings are valid
    return 0;
}
