        return;
    }

    // Initialize each element in the array with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_elements; ++i) {
        (*elements)[i] = rand() % (MAX_PLAYERS - MIN_PLAYERS) + MIN_PLAYERS;
    }
}

