// Define a function to handle concurrent access to shared resources safely
void handle_shared_resource(int* value) {
    // Acquire lock on the shared resource
    pthread_mutex_lock(&value->lock);

    // Read and modify the shared resource
    *value += 1;

    // Release lock on the shared resource
    pthread_mutex_unlock(&value->lock);
}

// Define a function to manage the cooldown state between attacks
void manage_cooldown(int* cooldown) {
    // Acquire lock on the cooldown variable
    pthread_mutex_lock(&cooldown->lock);

    // Check if the cooldown period has expired
    if (*cooldown > 0) {
        *cooldown -= 1;
    } else {
        // If the cooldown period has not expired, reset it to its maximum value
        *cooldown = MAX_COOLDOWN;
    }

    // Release lock on the cooldown variable
    pthread_mutex_unlock(&cooldown->lock);
}

