typedef struct {
    int user_id;
    char* username;
    char* password;
    char* preferences;
    char* activity_log[MAX_ACTIVITY_LOG];
} UserProfile;

UserProfile* profiles = (UserProfile*) malloc(sizeof(UserProfile) * MAX_USERS);
int num_profiles = 0;

void manageAndProcessUserProfiles(const char* method, const char* url, const char* body, int user_id) {
    // Parse the request and extract the relevant information
    RequestParser parser = parseRequest(method, url, body);
    char* username = parser.username;
    char* password = parser.password;

    // Check if the user exists and return 404 if not found
    int profile_index = getProfileIndexByUsername(username);
    if (profile_index == -1) {
        printf("User %s does not exist\n", username);
        sendResponse(404, "Not Found");
        return;
    }

    // Authenticate the user and retrieve their profile
    UserProfile* profile = &profiles[profile_index];
    if (strcmp(profile->username, username) == 0 && strcmp(profile->password, password) == 0) {
        printf("Authenticated user %s\n", username);
    } else {
        printf("Invalid credentials for user %s\n", username);
        sendResponse(401, "Unauthorized");
        return;
    }

    // Handle HTTP PUT requests to update the profile
    if (strcmp(method, "PUT") == 0) {
        char* updated_preferences = parser.preferences;
        char* updated_activity_log = parser.activity_log;

        // Update the user's preferences and activity log
        strcpy(profile->preferences, updated_preferences);
        for (int i = 0; i < MAX_ACTIVITY_LOG; i++) {
            strcpy(profile->activity_log[i], updated_activity_log[i]);
        }

        // Update the user's activity score and return the highest score
        updateUserActivityScore(profile);
        int highest_score = getHighestUserActivityScore();
        char* highest_score_str = (char*) malloc(sizeof(int) * 10);
        sprintf(highest_score_str, "%d", highest_score);
        sendResponse(200, "OK", highest_score_str);
    }

    // Handle HTTP DELETE requests to delete the profile
    else if (strcmp(method, "DELETE") == 0) {
        UserProfile new_profile = createDefaultUserProfile();
        strcpy(new_profile.username, username);
        strcpy(new_profile.password, password);

        // Delete the user's profile and return a new default profile
        deleteProfileByUsername(username);
        sendResponse(200, "OK", new_profile);
    }

    // Handle HTTP GET requests to retrieve the profile
    else if (strcmp(method, "GET") == 0) {
        UserProfile* response = malloc(sizeof(UserProfile));
        memcpy(response, profile, sizeof(UserProfile));
        sendResponse(200, "OK", response);
    }

    // Handle HTTP POST requests to create a new profile
    else if (strcmp(method, "POST") == 0) {
        char* new_username = parser.username;
        char* new_password = parser.password;

        // Create a new user profile and return the ID of the new profile
        UserProfile new_profile = createUserProfile(new_username, new_password);
        int new_profile_id = getNewProfileID();
        sendResponse(201, "Created", new_profile_id);
    }

    // Handle HTTP OPTIONS requests to return the server's capabilities
    else if (strcmp(method, "OPTIONS") == 0) {
        char* capabilities = "GET, POST, PUT, DELETE";
        sendResponse(200, "OK", capabilities);
    }

    // Handle HTTP HEAD requests to return the profile's metadata
    else if (strcmp(method, "HEAD") == 0) {
        UserProfile* response = malloc(sizeof(UserProfile));
        memcpy(response, profile, sizeof(UserProfile));
        sendResponse(200, "OK", response);
    }
}

int getProfileIndexByUsername(char* username) {
    for (int i = 0; i < num_profiles; i++) {
        if (strcmp(profiles[i].username, username) == 0) {
            return i;
        }
    }
    return -1;
}

UserProfile createUserProfile(char* username, char* password) {
    UserProfile new_profile = {
        .user_id = getNewProfileID(),
        .username = strdup(username),
        .password = strdup(password),
        .preferences = "",
        .activity_log = {}
    };
    return new_profile;
}

void deleteProfileByUsername(char* username) {
    int profile_index = getProfileIndexByUsername(username);
    if (profile_index != -1) {
        profiles[profile_index].user_id = 0;
        strcpy(profiles[profile_index].username, "");
        strcpy(profiles[profile_index].password, "");
        free(profiles[profile_index].preferences);
        for (int i = 0; i < MAX_ACTIVITY_LOG; i++) {
            free(profiles[profile_index].activity_log[i]);
        }
    }
}

void updateUserActivityScore(UserProfile* profile) {
    int activity_score = 0;
    for (int i = 0; i < MAX_ACTIVITY_LOG; i++) {
        activity_score += ACTIVITY_SCORE_WEIGHTING * atoi(profile->activity_log[i]);
    }
    profile->activity_score = activity_score;
}

int getHighestUserActivityScore() {
    int highest_score = 0;
    for (int i = 0; i < num_profiles; i++) {
        if (profiles[i].activity_score > highest_score) {
            highest_score = profiles[i].activity_score;
        }
    }
    return highest_score;
}

int getNewProfileID() {
    return num_profiles++;
}
