Record* generate_records(int num_records, int record_size) {
    // Allocate memory for the array of records
    Record *records = (Record *)malloc(sizeof(Record) * num_records);
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize each record with random data and categorical distribution for labels
    for (int i = 0; i < num_records; ++i) {
        Record *record = &records[i];
        record->offset = rand() % 10000;
        record->key = rand() % 100;
        record->weight = (float)(rand() % 1000) / 100.0f;
        record->validated = false;
        record->label = (char)(i % 3 + 'A'); // Categorical distribution for labels
    }

