}

// Function to initialize the list of RX_UE_INFORMATION_TAG structures with valid data from a compressed file stored on a remote server
int init_rx_ue_information(const char *filepath) {
    // Open the compressed file and read its contents into a buffer
    FILE *fp = fopen(filepath, "rb");
    if (fp == NULL) {
        perror("Failed to open file");
        return -1;
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    char *buffer = malloc(file_size);
    if (buffer == NULL) {
        perror("Failed to allocate memory for buffer");
        fclose(fp);
        return -1;
    }
    size_t bytes_read = fread(buffer, 1, file_size, fp);
    if (bytes_read != file_size) {
        perror("Failed to read entire file contents");
        free(buffer);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    // Decompress the buffer and populate the list of RX_UE_INFORMATION_TAG structures with valid data
    int rx_ue_information_size = 0;
    for (int i = 0; i < file_size; ++i) {
        if (buffer[i] == '\n') {
            NFAPI_CRC_INDICATION_PDU_T *rx_ue_information = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (rx_ue_information == NULL) {
                perror("Failed to allocate memory for rx_ue_information");
                free(buffer);
                return -1;
            }
            rx_ue_information->rx_ue_information_tag = i + 1;
            rx_ue_information->rnti = atoi(&buffer[i + 1]);
            rx_ue_information->crc_indication_rel8_tag = rand() % 2;
            if (rx_ue_information_size == 0) {
                rx_ue_information_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (rx_ue_information_list == NULL) {
                    perror("Failed to allocate memory for rx_ue_information_list");
                    free(buffer);
                    return -1;
                }
            } else {
                rx_ue_information_list = realloc(rx_ue_information_list, (rx_ue_information_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (rx_ue_information_list == NULL) {
                    perror("Failed to reallocate memory for rx_ue_information_list");
                    free(buffer);
                    return -1;
                }
            }
            rx_ue_information_list[rx_ue_information_size] = *rx_ue_information;
            ++rx_ue_information_size;
        }
    }

    // Clean up resources
    free(buffer);

    return 0;
}
