// Define a thread pool data structure to hold information about worker threads
typedef struct ThreadPool {
    pthread_mutex_t mutex; // Mutex for protecting the thread pool
    pthread_cond_t cond; // Condition variable for notifying available worker threads
    int size; // Number of worker threads in the pool
    int max_size; // Maximum number of worker threads that can be added to the pool
    int min_size; // Minimum number of worker threads that can be removed from the pool
} ThreadPool;

// Function to initialize a thread pool with a given number of worker threads
void init_thread_pool(ThreadPool* pool, int size) {
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->size = 0;
    pool->max_size = size;
    pool->min_size = size / 2; // Set the minimum number of worker threads to half the maximum size
}

// Function to add a new worker thread to the thread pool
void add_worker(ThreadPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size < pool->max_size) { // Check if there is still space in the pool for a new thread
        ++pool->size;
        pthread_create(&pool->threads[pool->size - 1], NULL, worker_function, NULL);
    } else { // Otherwise, notify any available worker threads that a new task has arrived
        pthread_cond_broadcast(&pool->cond);
