    pthread_mutex_unlock(&pool->mutex);
}

// Function to remove an idle worker thread from the thread pool
void remove_worker(ThreadPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size > pool->min_size) { // Check if there are any idle threads that can be removed
        --pool->size;
        pthread_cond_broadcast(&pool->cond);
    } else { // Otherwise, wait for an available worker thread to complete its current task
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    pthread_mutex_unlock(&pool->mutex);
}
