void manage_memory(long* offsets, int* keys, struct Record** records) {
    // Initialize a hash set to keep track of used strings
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    HashSet<string> used_strings;

    // Allocate memory for the arrays
    offsets = (long*)malloc(sizeof(long) * 3);
    keys = (int*)malloc(sizeof(int) * 3);
    records = (struct Record**)malloc(sizeof(struct Record*) * 3);

    // Initialize the hash set with the provided prefix and a random integer
    used_strings.insert("prefix");
    int random_int = rand() % 1000;
    used_strings.insert(to_string(random_int));

    // Allocate memory for each record structure
    for (int i = 0; i < 3; i++) {
        records[i] = (struct Record*)malloc(sizeof(struct Record));
        records[i]->value = i;
        records[i]->buffer = (char*)malloc(256);
    }

    // Generate unique strings from the prefix and random integer
    for (int i = 0; i < 3; i++) {
        string generated_string = "prefix" + to_string(random_int) + to_string(i);

        pthread_mutex_lock(&lock);

        // Check if the generated string is already in used_strings
        while (used_strings.find(generated_string) != used_strings.end()) {
            random_int = rand() % 1000;
            generated_string = "prefix" + to_string(random_int) + to_string(i);
        }

        // Insert the generated string into used_strings
        used_strings.insert(generated_string);

        pthread_mutex_unlock(&lock);

        records[i]->buffer = strdup(generated_string.c_str());
    }

    // Free memory when done
    for (int i = 0; i < 3; i++) {
        free(records[i]->buffer);
        free(records[i]);
    }
