```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Structure to hold record data
typedef struct {
    int key;
    int value;
    time_t timestamp;
} Record;

// Vector to store records
static pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
static std::vector<Record> records;

// Function to initialize a new record with random value and timestamp
void init_record(int key, int min_value, int max_value) {
    Record new_record = {key, (rand() % (max_value - min_value + 1)) + min_value, time(NULL)};
    pthread_mutex_lock(&record_lock);
    records.push_back(new_record);
    pthread_mutex_unlock(&record_lock);
}

// Function to retrieve a record by key
Record get_record(int key) {
    pthread_mutex_lock(&record_lock);
    for (auto it = records.begin(); it != records.end(); ++it) {
        if (it->key == key) {
            pthread_mutex_unlock(&record_lock);
            return *it;
        }
    }
    pthread_mutex_unlock(&record_lock);
    return {}; // Return empty record if not found
}

// Function to update a record by key with new value and timestamp
void update_record(int key, int new_value) {
    pthread_mutex_lock(&record_lock);
    for (auto it = records.begin(); it != records.end(); ++it) {
        if (it->key == key) {
            it->value = new_value;
            it->timestamp = time(NULL);
            pthread_mutex_unlock(&record_lock);
            return;
        }
    }
    pthread_mutex_unlock(&record_lock);
}

// Function to delete a record by key
void delete_record(int key) {
    pthread_mutex_lock(&record_lock);
    for (auto it = records.begin(); it != records.end(); ++it) {
        if (it->key == key) {
            records.erase(it);
            pthread_mutex_unlock(&record_lock);
            return;
        }
    }
    pthread_mutex_unlock(&record_lock);
}
```
