NFAPI_CRC_INDICATION_PDU_T *populate_array(int N, int max_limit) {
    // Validate input parameters
    if (N <= 0 || max_limit < N) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (array == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the array of structures with random data
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION.RNTI = rand() % INT32_MAX;
        array[i].CRC_INDICATION_REL8.CRCFLAG = rand() % 2;
    }

    // Ensure unique RNTIs within the array
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (array[i].RX_UE_INFORMATION.RNTI == array[j].RX_UE_INFORMATION.RNTI) {
                printf("Duplicate RNTIs found\n");
                free(array);
                return NULL;
            }
        }
    }

    // Ensure the total number of structures does not exceed the maximum limit
    if (N > max_limit) {
        printf("Exceeded maximum limit of %d structures\n", max_limit);
        free(array);
        return NULL;
    }

    // Return the populated array of structures
    return array;
}
