struct Record {
    long offset;
    int key;
    struct {
        int message_length;
        char* message;
        char* description;
    } record;
};

void manage_dynamic_memory(int num_records, char* prefix, struct Record** records) {
    // Initialize arrays for offsets, keys, and messages
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    char** messages = (char**)malloc(num_records * sizeof(char*));

    // Initialize default values for message and description in case of memory allocation failure
    const char* default_message = "Default Message";
    const char* default_description = "Default Description";

    // Initialize sequential number for unique message and description strings
    int seq_num = 0;

    // Iterate over records and allocate memory for each record
    for (int i = 0; i < num_records; ++i) {
        // Allocate memory for the offset, key, and message fields
        offsets[i] = (long)malloc(sizeof(long));
        keys[i] = (int)malloc(sizeof(int));
        messages[i] = (char*)malloc(256 * sizeof(char));

        // Initialize the offset field with the current index value
        offsets[i] = i;

        // Generate a unique key for each record using a hash function
        keys[i] = generate_key(prefix, seq_num);

        // Initialize the message and description fields with default values in case of memory allocation failure
        messages[i] = (char*)malloc(256 * sizeof(char));
        strcpy(messages[i], default_message);

        // Increment the sequential number for generating unique message and description strings
        seq_num++;
    }

    // Release memory for arrays when no longer needed
    free(offsets);
    free(keys);
    free(messages);
}

int generate_key(char* prefix, int seq_num) {
    // Generate a unique key using a hash function
    return (prefix == NULL ? 0 : strlen(prefix)) + seq_num;
