struct record {
    int value;
    char* string_buffer;
    size_t ref_count;
};

struct string_pool {
    pthread_mutex_t mutex;
    size_t max_size;
    size_t current_size;
    struct record** records;
};

void create_record(const char* prefix, int random_int) {
    // allocate memory for the new record
    struct record* new_record = malloc(sizeof(struct record));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return;
    }

    // generate a unique string from the prefix and random int
    char* string = gen_unique_string(prefix, random_int);

    // initialize the fields of the new record
    new_record->value = 0;
    new_record->string_buffer = string;
    new_record->ref_count = 1;

    // add the new record to the string pool
    pthread_mutex_lock(&string_pool.mutex);
    if (string_pool.current_size >= string_pool.max_size) {
        struct record* oldest_record = NULL;
        size_t oldest_age = SIZE_MAX;
        for (size_t i = 0; i < string_pool.current_size; i++) {
            if (string_pool.records[i]->ref_count == 1) {
                size_t age = get_record_age(string_pool.records[i]);
                if (age < oldest_age) {
                    oldest_age = age;
                    oldest_record = string_pool.records[i];
                }
            }
        }
        if (oldest_record != NULL) {
            free(oldest_record->string_buffer);
            string_pool.current_size--;
        }
    }
    string_pool.records = realloc(string_pool.records, sizeof(struct record*) * (string_pool.current_size + 1));
    if (string_pool.records == NULL) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        free(new_record);
        return;
    }
    string_pool.records[string_pool.current_size] = new_record;
    string_pool.current_size++;
    pthread_mutex_unlock(&string_pool.mutex);
}

void destroy_record(struct record* record) {
    // decrement the reference count of the record
    pthread_mutex_lock(&record->mutex);
    record->ref_count--;
    if (record->ref_count == 0) {
        free(record->string_buffer);
        record->string_buffer = NULL;
    }
    pthread_mutex_unlock(&record->mutex);
}

char* gen_unique_string(const char* prefix, int random_int) {
    // generate a unique string from the prefix and random int
    char buffer[256];
    sprintf(buffer, "%s%d", prefix, random_int);
    return strdup(buffer);
}

size_t get_record_age(struct record* record) {
    // calculate the age of the record based on its creation time
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (now.tv_sec - record->creation_time.tv_sec) * 1000 + (now.tv_nsec - record->creation_time.tv_nsec) / 1000000;
}
```
