    char* command;
    pid_t pid;
    int status;
    time_t startTime;
};

int runCommandWithNfaradiusSession(char* command, struct NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (command == NULL || pdu == NULL) {
        return -1;
    }

    char defaultCmd[1024];
    sprintf(defaultCmd, "%s", DEFAULT_CMD);

    char* cmd = command != NULL ? command : defaultCmd;

    pid_t pid;
    int status;
    time_t startTime;

    // Check for BACKGROUND_COMMAND environment variable
    if (getenv("BACKGROUND_COMMAND") != NULL) {
        cmd = getenv("BACKGROUND_COMMAND");
    }

    // Temporarily switch to root user if not running as root
    uid_t uid = getuid();
    gid_t gid = getgid();
    if (uid != 0) {
        seteuid(0);
        setegid(0);
    }

    // Execute command in background and wait for it to finish
    pid = fork();
    if (pid == 0) {
        execvp(cmd, NULL);
        exit(1);
    } else {
        waitpid(pid, &status, 0);
    }

    // Revert to original user and group
    if (uid != 0) {
        seteuid(uid);
        setegid(gid);
    }

    // Handle signals gracefully
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Log detailed execution information
    startTime = time(NULL);
    printf("Command %s started at %lld with status %d\n", cmd, startTime, status);

    // Populate NFAPI_CRC_INDICATION_PDU_T structure
    pdu->command = cmd;
    pdu->pid = pid;
    pdu->status = status;
    pdu->startTime = startTime;

    return 1;
}
