        if (!(pdu->RNTI >= MIN_RNTI && pdu->RNTI <= MAX_RNTI)) {
            printf("ERROR: crcValidate - Invalid RNTI value provided\n");
        } else {
            // Check if the RNTI value is already in use in the pool of structures
            for (int i = 0; i < nextAvailableIndex; i++) {
                if (crcPool[i].CRCFLAG == 1 && crcPool[i].RNTI == pdu->RNTI) {
                    printf("ERROR: crcValidate - Duplicate RNTI value provided\n");
                    break;
                }
            }
        }
    } else {
        // Log an error message if the structure is invalid or has not been initialized
        printf("ERROR: crcValidate - Invalid structure provided\n");
    }

    // Unlock the mutex to release access to the pool of structures
    pthread_mutex_unlock(&crcPoolMutex);
}

// Function for logging information about a NFAPI_CRC_INDICATION_PDU_T structure allocation or deallocation
void crcLog(NFAPI_CRC_INDICATION_PDU_T* pdu, char* operation) {
    // Lock the mutex to synchronize access to the pool of structures
    pthread_mutex_lock(&crcPoolMutex);

    // Check if the structure is valid and has been initialized
    if (pdu != NULL && crcPool[pdu->RX_UE_INFORMATION_TAG].CRCFLAG == 1) {
        // Log information about the operation and the current state of the pool of structures
        printf("INFO: %s - RX_UE_INFORMATION_TAG = %d, RNTI = %u\n", operation, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    } else {
        // Log an error message if the structure is invalid or has not been initialized
        printf("ERROR: crcLog - Invalid structure provided\n");
    }

    // Unlock the mutex to release access to the pool of structures
    pthread_mutex_unlock(&crcPoolMutex);
}

// Function for flushing the log buffer to persistent storage
void crcFlushLog(char* filename) {
    // Lock the mutex to synchronize access to the pool of structures
    pthread_mutex_lock(&crcPoolMutex);

    // Open a file for writing and write the contents of the log buffer to it
    FILE* fp = fopen(filename, "w");
    if (fp != NULL) {
        fprintf(fp, "%s", logBuffer);
        fclose(fp);
    } else {
        printf("ERROR: crcFlushLog - Failed to open file for writing\n");
    }

    // Clear the log buffer and unlock the mutex to release access to the pool of structures
    memset(logBuffer, 0, LOG_BUFFER_SIZE);
    pthread_mutex_unlock(&crcPoolMutex);
}
