    int64_t current_time = (int64_t)time(NULL);
    if (current_time > data->expires_in) {
        printf("Error: Token has expired\n");
        return false;
    }

    // Free the memory used by the parsed data
    json_decref(root);
    free(data);

    // Return true if the token is valid
    return true;
}

