        ue_contexts[i].nas_message[2] = (ue_contexts[i].rnti & 0xFF);

        // Set the header of the RRC Connection Reconfiguration message to include the RNTI value
        ue_contexts[i].rrc_reconfig.rnti = ue_contexts[i].rnti;
    }

    return ue_contexts;
}

// Function to free memory allocated for an array of UEContext structures
void free_ue_contexts(UEContext *ue_contexts, int num_structures) {
    // Check if the requested number of structures is within the maximum limit
    if (num_structures > MAX_STRUCTURES || !ue_contexts) {
        printf("Error: Requested number of structures exceeds maximum limit\n");
        return;
    }

    // Free memory for each structure in the array
    for (int i = 0; i < num_structures; i++) {
        free(ue_contexts[i].nas_message);
    }

    // Free memory for the array of UEContext structures
    free(ue_contexts);
}
