// Define the structure for holding CRC indication information
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a function for generating random numbers within a specified range
uint16_t generate_random(uint16_t min, uint16_t max) {
    // Generate a pseudo-random number using the system time and process ID
    uint32_t seed = (uint32_t)time(NULL) + getpid();
    // Use the random function to generate a value within the specified range
    return (uint16_t)(min + rand_r(&seed) % (max - min + 1));
}

// Define a function for initializing the list of CRC indication structures
void init_crc_list(NFAPI_CRC_INDICATION_PDU_T **crc_list, int size) {
    // Allocate memory for the list of CRC indication structures
    *crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_list == NULL) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize each structure in the list with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG value
    for (int i = 0; i < size; i++) {
        (*crc_list)[i].RX_UE_INFORMATION_TAG = generate_random(1, 65535);
        (*crc_list)[i].RNTI = generate_random(1, 65535);
        (*crc_list)[i].CRCFLAG = generate_random(0, 255);
    }
}

// Define a function for adding a new CRC indication structure to the list
void add_crc_structure(NFAPI_CRC_INDICATION_PDU_T **crc_list, int size) {
    // Allocate memory for the new structure in the list
    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_struct == NULL) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize the new structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG value
    new_struct->RX_UE_INFORMATION_TAG = generate_random(1, 65535);
    new_struct->RNTI = generate_random(1, 65535);
    new_struct->CRCFLAG = generate_random(0, 255);

    // Add the new structure to the end of the list
    (*crc_list)[size].next = NULL;
    size++;
}

// Define a function for removing an existing CRC indication structure from the list
void remove_crc_structure(NFAPI_CRC_INDICATION_PDU_T **crc_list, int *size) {
    // Check if there are any structures in the list
    if (*size == 0) {
        printf("No structures to remove\n");
        return;
    }

    // Find the last structure in the list and set its next pointer to NULL
    NFAPI_CRC_INDICATION_PDU_T *last_struct = *crc_list;
    while (last_struct->next != NULL) {
        last_struct = last_struct->next;
    }
    last_struct->next = NULL;

    // Decrease the size of the list and free the memory for the removed structure
    (*size)--;
    free(last_struct);
}

// Define a function for validating that each RX_UE_INFORMATION_TAG is within a specified range
bool validate_rx_ue_information_tag(NFAPI_CRC_INDICATION_PDU_T *crc_list, int size) {
    // Iterate over the list of CRC indication structures and check that each RX_UE_INFORMATION_TAG is within a specified range
    for (int i = 0; i < size; i++) {
        if (crc_list[i].RX_UE_INFORMATION_TAG < 1 || crc_list[i].RX_UE_INFORMATION_TAG > 65535) {
            return false;
        }
    }
    return true;
}

// Define a function for ensuring no duplicate RNTI values across structures
bool validate_rnti(NFAPI_CRC_INDICATION_PDU_T *crc_list, int size) {
    // Initialize an empty set of seen RNTIs
    bool seen[65536] = {false};

    // Iterate over the list of CRC indication structures and check that each RNTI is unique
