#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Define the log entry struct
typedef struct {
    time_t timestamp;
    int userID;
    struct {
        char* actionType;
        char* detailString;
    } actions[];
} LogEntry;

// Define the logging system struct
struct LoggingSystem {
    pthread_mutex_t mutex; // Mutex for thread safety
    semaphore_t semaphore; // Semaphore for synchronization
    int numUsers; // Number of users in the system
    int numActions[]; // Number of actions per user
    LogEntry* logEntries[]; // Array of log entries
};

// Function to initialize the logging system
void initLoggingSystem(struct LoggingSystem** loggingSystem) {
    *loggingSystem = (struct LoggingSystem*) malloc(sizeof(struct LoggingSystem));
    (*loggingSystem)->mutex = PTHREAD_MUTEX_INITIALIZER;
    semaphore_init(&((*loggingSystem)->semaphore), 0, SEMAPHORE_MAX);
    (*loggingSystem)->numUsers = 0;
}

// Function to add a new user to the logging system
void addUser(struct LoggingSystem* loggingSystem, int userID) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Check if the user already exists
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (userID == loggingSystem->logEntries[i]->userID) {
            pthread_mutex_unlock(&loggingSystem->mutex);
            return; // User already exists, nothing to do
        }
    }
    // Add the new user to the system
    int* numActions = (int*) malloc(sizeof(int));
    *numActions = 0;
    LogEntry* logEntries = (LogEntry*) malloc(sizeof(LogEntry));
    logEntries->timestamp = time(NULL);
    logEntries->userID = userID;
    loggingSystem->logEntries[loggingSystem->numUsers] = logEntries;
    loggingSystem->numActions[loggingSystem->numUsers] = numActions;
    loggingSystem->numUsers++;
    pthread_mutex_unlock(&loggingSystem->mutex);
}

// Function to delete a user from the logging system
void deleteUser(struct LoggingSystem* loggingSystem, int userID) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Find the index of the user in the logEntries array
    int index = -1;
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (userID == loggingSystem->logEntries[i]->userID) {
            index = i;
            break;
        }
    }
    // Check if the user exists and delete it if necessary
    if (index != -1) {
        free(loggingSystem->logEntries[index]);
        free(loggingSystem->numActions[index]);
        loggingSystem->numUsers--;
        for (int i = index; i < loggingSystem->numUsers; i++) {
            loggingSystem->logEntries[i] = loggingSystem->logEntries[i + 1];
            loggingSystem->numActions[i] = loggingSystem->numActions[i + 1];
        }
    }
    pthread_mutex_unlock(&loggingSystem->mutex);
}

// Function to insert a new log entry into the logging system
void insertLogEntry(struct LoggingSystem* loggingSystem, int userID, char* actionType, char* detailString) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Find the index of the user in the logEntries array
    int index = -1;
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (userID == loggingSystem->logEntries[i]->userID) {
            index = i;
            break;
        }
    }
    // Check if the user exists and insert the new log entry if necessary
    if (index != -1) {
        LogEntry* logEntry = (LogEntry*) malloc(sizeof(LogEntry));
        logEntry->timestamp = time(NULL);
        logEntry->userID = userID;
        logEntry->actions[loggingSystem->numActions[index]] = actionType;
        loggingSystem->logEntries[index] = logEntry;
        loggingSystem->numActions[index]++;
    }
    pthread_mutex_unlock(&loggingSystem->mutex);
}

// Function to delete a log entry from the logging system
void deleteLogEntry(struct LoggingSystem* loggingSystem, int userID, char* actionType) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Find the index of the user in the logEntries array
    int index = -1;
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (userID == loggingSystem->logEntries[i]->userID) {
            index = i;
            break;
        }
    }
    // Check if the user exists and delete the log entry if necessary
    if (index != -1) {
        int count = 0;
        for (int j = 0; j < loggingSystem->numActions[index]; j++) {
            if (strcmp(actionType, loggingSystem->logEntries[index]->actions[j].actionType) == 0) {
                count++;
            }
        }
        if (count > 0) {
            for (int j = 0; j < loggingSystem->numActions[index]; j++) {
                if (strcmp(actionType, loggingSystem->logEntries[index]->actions[j].actionType) == 0) {
                    count--;
                    loggingSystem->logEntries[index]->actions[j] = loggingSystem->logEntries[index]->actions[count];
                }
            }
            loggingSystem->numActions[index] = count;
        }
    }
    pthread_mutex_unlock(&loggingSystem->mutex);
}

// Function to query log entries from the logging system based on user ID
void queryLogEntries(struct LoggingSystem* loggingSystem, int userID) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Find the index of the user in the logEntries array
    int index = -1;
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (userID == loggingSystem->logEntries[i]->userID) {
            index = i;
            break;
        }
    }
    // Check if the user exists and query the log entries if necessary
    if (index != -1) {
        printf("Log entries for user %d:\n", userID);
        for (int j = 0; j < loggingSystem->numActions[index]; j++) {
            printf("\t%s\n", loggingSystem->logEntries[index]->actions[j].actionType);
        }
    }
    pthread_mutex_unlock(&loggingSystem->mutex);
}

// Function to query log entries from the logging system based on time range
void queryLogEntries(struct LoggingSystem* loggingSystem, int startTime, int endTime) {
    pthread_mutex_lock(&loggingSystem->mutex);
    // Find the index of the user in the logEntries array
    int index = -1;
    for (int i = 0; i < loggingSystem->numUsers; i++) {
        if (startTime <= loggingSystem->logEntries[i]->timestamp && endTime >= loggingSystem->logEntries[i]->timestamp) {
            index = i;
            break;
        }
    }
    // Check if the user exists and query the log entries if necessary
    if (index != -1) {
        printf("Log entries for users between %d and %d:\n", startTime, endTime);
        for (int j = 0; j < loggingSystem->numActions[index]; j++) {
            printf("\t%s\n", loggingSystem->logEntries[index]->actions[j].actionType);
        }
    }
    pthread_mutex_unlock(&loggingSystem->mutex);
}
```
