} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a list of NFAPI_CRC_INDICATION_PDU structures
void init_list(NFAPI_CRC_INDICATION_PDU_T *list, int num) {
    // Allocate memory for the list
    list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Error: Failed to allocate memory for the list\n");
        return;
    }

    // Initialize the elements of the list with default values
    for (int i = 0; i < num; i++) {
        list[i].RX_UE_INFORMATION_TAG = -1;
        list[i].RNTI = -1;
        list[i].CRC_INDICATION_REL8_TAG = -1;
    }
}

// Function to populate the list of NFAPI_CRC_INDICATION_PDU structures with values from compressed files
void populate_list(NFAPI_CRC_INDICATION_PDU_T *list, int num) {
    // Open the compressed file and read it line by line
    FILE *file = fopen("compressed_file.gz", "r");
    if (!file) {
        printf("Error: Failed to open the compressed file\n");
        return;
    }

    int RNTI, CRCFLAG;
    char line[1024];
    for (int i = 0; fgets(line, sizeof(line), file); i++) {
        // Extract the RNTI and CRCFLAG values from the line
        sscanf(line, "%d,%d", &RNTI, &CRCFLAG);

        // Check for duplicate RNTIs and update the list accordingly
        bool duplicate = false;
        for (int j = 0; j < i; j++) {
            if (list[j].RNTI == RNTI) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            list[i].RX_UE_INFORMATION_TAG = 0; // Set the RX_UE_INFORMATION_TAG to a fixed value
            list[i].RNTI = RNTI; // Update the RNTI in the list
            list[i].CRC_INDICATION_REL8_TAG = CRCFLAG; // Update the CRCFLAG in the list
        }
    }

    // Close the file and free the memory allocated for the list
    fclose(file);
}

// Function to find and print the largest integer among the RNTI values within the structures
void print_largest_rnti(NFAPI_CRC_INDICATION_PDU_T *list, int num) {
    // Initialize the largest RNTI value with a minimum value to ensure it is updated
    int largest = INT_MIN;
    for (int i = 0; i < num; i++) {
        if (list[i].RNTI > largest) {
            largest = list[i].RNTI;
        }
    }
    printf("The largest RNTI value is %d\n", largest);
}

// Main function to read the compressed files and populate the list of NFAPI_CRC_INDICATION_PDU structures
int main() {
    // Initialize the list with a fixed size
    int num = 1024;
    NFAPI_CRC_INDICATION_PDU_T *list;
    init_list(list, num);

    // Populate the list with values from the compressed files
    populate_list(list, num);

    // Find and print the largest RNTI value in the list
    print_largest_rnti(list, num);

    // Free the memory allocated for the list
    free(list);

    return 0;
}
