// DataProcessor class to manage a dynamic collection of records
class DataProcessor {
public:
    // Constructor to initialize the data store and register ciphers and hash functions with OpenSSL
    DataProcessor(int numRecords, int keySize, int valueSize, int seed) {
        this->numRecords = numRecords;
        this->keySize = keySize;
        this->valueSize = valueSize;
        this->seed = seed;

        // Initialize the data store with random records
        for (int i = 0; i < numRecords; i++) {
            Record* record = new Record();
            record->key = rand() % keySize;
            record->offset = rand() % valueSize;
            record->value = rand() % seed;
            records.push_back(record);
        }

        // Register ciphers and hash functions with OpenSSL
        EVP_add_cipher("AES-128", "CBC", NULL, NULL);
        EVP_add_cipher("AES-256", "GCM", NULL, NULL);
        EVP_add_digest("SHA-256", NULL, NULL);
        EVP_add_digest("SHA-384", NULL, NULL);
    }

    // Destructor to free the data store
    ~DataProcessor() {
        for (int i = 0; i < records.size(); i++) {
            delete records[i];
        }
    }

    // Function to encrypt a record using the specified algorithm and key
    void encryptRecord(const Record* record, const std::string& algo, const unsigned char* key) {
        int algoId = EVP_get_digestbyname(algo.c_str());
        if (algoId == NID_undef) {
            printf("Invalid algorithm %s\n", algo.c_str());
            return;
        }

        unsigned char* ciphertext = NULL;
        int ciphertextLen = 0;
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == NULL) {
            printf("Failed to create encryption context\n");
            return;
        }

        // Set the cipher and key for the encryption operation
        int res = EVP_EncryptInit(ctx, algoId, key, NULL);
        if (res != 1) {
            printf("Failed to initialize encryption operation\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Encrypt the record value using the specified algorithm and key
        res = EVP_EncryptUpdate(ctx, ciphertext, &ciphertextLen, record->value, record->length);
        if (res != 1) {
            printf("Failed to encrypt record\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Free the encryption context
        EVP_CIPHER_CTX_free(ctx);
    }

    // Function to decrypt a record using the specified algorithm and key
    void decryptRecord(const Record* record, const std::string& algo, const unsigned char* key) {
        int algoId = EVP_get_digestbyname(algo.c_str());
        if (algoId == NID_undef) {
            printf("Invalid algorithm %s\n", algo.c_str());
            return;
        }

        unsigned char* plaintext = NULL;
        int plaintextLen = 0;
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == NULL) {
            printf("Failed to create decryption context\n");
            return;
        }

        // Set the cipher and key for the decryption operation
        int res = EVP_DecryptInit(ctx, algoId, key, NULL);
        if (res != 1) {
            printf("Failed to initialize decryption operation\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Decrypt the record value using the specified algorithm and key
        res = EVP_DecryptUpdate(ctx, plaintext, &plaintextLen, record->value, record->length);
        if (res != 1) {
            printf("Failed to decrypt record\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Free the decryption context
        EVP_CIPHER_CTX_free(ctx);
    }

    // Function to hash a record using the specified algorithm
    void hashRecord(const Record* record, const std::string& algo) {
        int algoId = EVP_get_digestbyname(algo.c_str());
        if (algoId == NID_undef) {
            printf("Invalid algorithm %s\n", algo.c_str());
            return;
        }

        unsigned char* hash = NULL;
        int hashLen = 0;
        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        if (ctx == NULL) {
            printf("Failed to create hash context\n");
            return;
        }

        // Set the hash algorithm for the operation
        int res = EVP_DigestInit(ctx, algoId);
        if (res != 1) {
            printf("Failed to initialize hash operation\n");
            EVP_MD_CTX_free(ctx);
            return;
        }

        // Hash the record value using the specified algorithm
        res = EVP_DigestUpdate(ctx, record->value, record->length);
        if (res != 1) {
            printf("Failed to hash record\n");
            EVP_MD_CTX_free(ctx);
            return;
        }

        // Finalize the hash operation and obtain the resulting hash value
        res = EVP_DigestFinal(ctx, hash, &hashLen);
        if (res != 1) {
            printf("Failed to finalize hash operation\n");
            EVP_MD_CTX_free(ctx);
            return;
        }

        // Free the hash context
        EVP_MD_CTX_free(ctx);
    }

    // Function to update a record with the specified value and offset
    void updateRecord(const int key, const unsigned char* value, const long offset) {
        Record* record = getRecordByKey(key);
        if (record == NULL) {
            printf("Invalid key %d\n", key);
            return;
        }

        // Update the record with the new value and offset
        memcpy(record->value + offset, value, strlen((const char*)value));
    }

    // Function to retrieve a record by its key
    Record* getRecordByKey(const int key) {
        for (int i = 0; i < records.size(); i++) {
            if (records[i]->key == key) {
                return records[i];
            }
        }
        return NULL;
    }

private:
    // Data structure to store the records
    struct Record {
        int key;
        long offset;
        unsigned char* value;
    };

    // Vector to hold the records
    std::vector<Record*> records;

    // Number of records in the data store
    int numRecords;

    // Size of each record's key
    int keySize;

    // Size of each record's value
    int valueSize;

    // Seed for generating random values
    int seed;
};
