// Define the function to manage memory allocation for multiple data structures
void *manageMemory(size_t size, size_t align, Allocator* allocator) {
    // Check if the requested size exceeds the maximum limit
    if (size > MAX_MEMORY_LIMIT) {
        printf("Requested memory exceeds the maximum limit. Prioritizing critical data structures.");
        return NULL;
    }

    // Allocate memory for the offset and key arrays
    size_t offsetSize = sizeof(long) * size;
    size_t keySize = sizeof(int) * size;
    void* offsetMem = allocator->mem + (align - 1) & ~(align - 1);
    void* keyMem = offsetMem + offsetSize;

    // Initialize the offset and key arrays
    memset(offsetMem, 0, offsetSize);
    memset(keyMem, 0, keySize);

    // Allocate memory for the record structures
    size_t recordSize = sizeof(Record) * size;
    void* recordMem = malloc(recordSize);

    // Initialize the record structures
    Record* records = (Record*)recordMem;
    for (size_t i = 0; i < size; i++) {
        records[i].offset = offsetMem;
        records[i].key = keyMem;
        records[i].timestamp = 0.0;
    }

    // Merge adjacent free blocks to mitigate fragmentation issues
    size_t blockSize = sizeof(Record) * size;
    void* currentBlock = recordMem;
    while (currentBlock < recordMem + recordSize) {
        if ((uintptr_t)currentBlock % align == 0) {
            break;
        }
        currentBlock += blockSize;
    }

    // Update the metadata for each allocation
    allocator->size = size;
    allocator->mem = recordMem;

    // Return a pointer to the first element of the record array
    return records;
}
