// Define a struct to store RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
typedef struct {
  uint16_t rx_ue_information_tag;
  uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Initialize a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
size_t pdu_count = 0;

// Function to read M RNTI values from standard input and store them in a dynamically allocated array of integers
void read_rnti(int m) {
  // Allocate memory for the array of integers
  int *rnti_array = malloc(m * sizeof(int));

  // Read M RNTI values from standard input and store them in the array
  for (int i = 0; i < m; i++) {
    int rnti;
    scanf("%d", &rnti);
    rnti_array[i] = rnti;
  }

  // Check that each RNTI entered is unique and within a valid range
  for (int i = 0; i < m; i++) {
    if (!(1 <= rnti_array[i] && rnti_array[i] <= 1000)) {
      printf("Error: RNTI value %d is not within the valid range (1-1000)\n", rnti_array[i]);
      return;
    }

    for (int j = i + 1; j < m; j++) {
      if (rnti_array[i] == rnti_array[j]) {
        printf("Error: RNTI value %d is not unique\n", rnti_array[i]);
        return;
      }
    }
  }

  // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures and populate them with the RNTI values
  pdu_list = malloc(m * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  for (int i = 0; i < m; i++) {
    pdu_list[i].rx_ue_information_tag = rnti_array[i];
    pdu_list[i].crc_indication_rel8_tag = 123456789; // Randomly set CRCFLAG
  }

  // Free the memory allocated for the array of integers
  free(rnti_array);
}

// Function to identify and print the largest RNTI value present in the list of NFAPI_CRC_INDICATION_PDU_T structures
void print_largest_rnti() {
  // Initialize a variable to store the largest RNTI value found
  int largest_rnti = INT_MIN;
  for (int i = 0; i < pdu_count; i++) {
    if (pdu_list[i].rx_ue_information_tag > largest_rnti) {
      largest_rnti = pdu_list[i].rx_ue_information_tag;
    }
  }

  // If no such value exists, print an appropriate message and exit
  if (largest_rnti == INT_MIN) {
    printf("No largest RNTI value found\n");
    return;
  }

  // Print the largest RNTI value and the indices of all structures where this maximum RNTI occurs
  printf("Largest RNTI value: %d\n", largest_rnti);
  for (int i = 0; i < pdu_count; i++) {
    if (pdu_list[i].rx_ue_information_tag == largest_rnti) {
      printf("Structure %d: RNTI value %d\n", i, pdu_list[i].rx_ue_information_tag);
    }
  }
}

// Function to determine if there are any duplicate RNTI values within the structures and report the number of duplicates found
void count_duplicates() {
  // Initialize a variable to store the number of duplicates found
  int duplicate_count = 0;
  for (int i = 0; i < pdu_count; i++) {
    for (int j = i + 1; j < pdu_count; j++) {
      if (pdu_list[i].rx_ue_information_tag == pdu_list[j].rx_ue_information_tag) {
        duplicate_count++;
      }
    }
  }

  // Print the number of duplicates found
  printf("Number of duplicates: %d\n", duplicate_count);
}

// Function to process the list of NFAPI_CRC_INDICATION_PDU_T structures to identify any missing CRCFLAG values and log an internal message indicating the index of the structure and the corresponding RNTI value
void log_missing_crcflags() {
  // Initialize a variable to store the number of missing CRCFLAG values found
  int missing_count = 0;
  for (int i = 0; i < pdu_count; i++) {
    if (pdu_list[i].crc_indication_rel8_tag == 0) {
      missing_count++;
      printf("Missing CRCFLAG at structure %d: RNTI value %d\n", i, pdu_list[i].rx_ue_information_tag);
    }
  }

  // Print the number of missing CRCFLAG values found
  printf("Number of missing CRCFLAG values: %d\n", missing_count);
}
