struct log_entry {
    struct event* event;
    int ref_count;
    int access_count;
};

void init_log(int num_events, int num_logs) {
    // Allocate memory for the events and logs arrays
    events = (struct event*)malloc(sizeof(struct event) * num_events);
    logs = (struct log_entry*)malloc(sizeof(struct log_entry) * num_logs);

    // Initialize the events and logs arrays
    for (int i = 0; i < num_events; ++i) {
        events[i].type = UNKNOWN;
        events[i].message = NULL;
        events[i].timestamp = 0;
    }
    for (int i = 0; i < num_logs; ++i) {
        logs[i].event = &events[i];
        logs[i].ref_count = 0;
        logs[i].access_count = 0;
    }
}

void add_log(struct event* event, int log_index) {
    // Increment the reference count for the corresponding log entry
    std::lock_guard<std::mutex> lock(logs_mutex);
    logs[log_index].ref_count++;
}

void remove_log(struct event* event, int log_index) {
    // Decrement the reference count for the corresponding log entry
    std::lock_guard<std::mutex> lock(logs_mutex);
    logs[log_index].ref_count--;
}

void access_log(struct event* event, int log_index) {
    // Increment the access count for the corresponding log entry
    std::lock_guard<std::mutex> lock(logs_mutex);
    logs[log_index].access_count++;
}

void free_log() {
    // Free the events and logs arrays
    std::lock_guard<std::mutex> lock(logs_mutex);
    for (int i = 0; i < num_events; ++i) {
        if (events[i].message != NULL) {
            free(events[i].message);
        }
    }
    free(events);
    free(logs);
}
