// Function to manage dynamic memory allocation for an array of `entry` structures
summary_t* allocate_summary(size_t num_entries) {
    // Allocate memory for the summary structure and its array of pointers
    summary_t* summary = malloc(sizeof(summary_t));
    if (!summary) {
        return NULL;
    }
    summary->num_entries = 0;
    summary->entries = malloc(num_entries * sizeof(entry_t**));
    if (!summary->entries) {
        free(summary);
        return NULL;
    }

    // Initialize the array of pointers to NULL
    for (size_t i = 0; i < num_entries; i++) {
        summary->entries[i] = NULL;
    }

    return summary;
}

// Function to populate a `summary` structure with pointers to specific `entry` structures
void populate_summary(summary_t* summary, entry_t* entries) {
    // Loop through each `entry` structure in the input array and assign a pointer to it in the `summary` structure
    for (size_t i = 0; i < summary->num_entries; i++) {
        size_t idx = 0;
        while (idx < num_entries && entries[i].timestamp > entries[idx].timestamp) {
            idx++;
        }
        summary->entries[i] = &entries[idx];
    }
}

// Function to deallocate memory for an `entry` structure and its corresponding `summary` structure
