  if (*records == NULL) {
    return -2;
  }
  *lte_dl_ccch_messages = malloc(sizeof(LTE_DL_CCCH_Message) * num_lte_dl_ccch_messages);
  if (*lte_dl_ccch_messages == NULL) {
    free(*records);
    return -3;
  }

