  for (size_t i = 0; i < num_records; ++i) {
    (*records)[i].key = rand() % INT_MAX + 1;
    (*lte_dl_ccch_messages)[i].nas_message.length = 256;
    memset((*lte_dl_ccch_messages)[i].nas_message.msg, 0, sizeof(NAS_MESSAGE));
    (*lte_dl_ccch_messages)[i].logical_channel_group = rand() % UCHAR_MAX + 1;
    (*lte_dl_ccch_messages)[i].phy_stats_id = rand() % UINT64_MAX + 1;
