    (*lte_dl_ccch_messages)[i].channel_quality_tag.ber = ((double)rand() / (double)(RAND_MAX)) * 0.5 + 0.5;
  }

  // Validate the integrity of the generated records and LTE_DL_CCCH_Message structures
  for (size_t i = 0; i < num_records; ++i) {
    if ((*records)[i].key <= 0 || (*lte_dl_ccch_messages)[i].nas_message.length <= 0 ||
        (*lte_dl_ccch_messages)[i].logical_channel_group <= 0 ||
        (*lte_dl_ccch_messages)[i].phy_stats_id <= 0 ||
        (*lte_dl_ccch_messages)[i].cell_id <= 0) {
      free(*records);
      free(*lte_dl_ccch_messages);
      return -4;
    }
  }

  // Return the allocated arrays
  return 0;
}
