// Define an array of transaction logs, with dynamic resizing support
TransactionLog *transaction_logs = NULL;
int transaction_log_count = 0;
int transaction_log_capacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the dynamic array of transaction logs with a given initial capacity
void init_transaction_logs(int initial_capacity) {
    // Allocate memory for the initial array of transaction logs
    transaction_log_count = 0;
    transaction_log_capacity = initial_capacity;
    transaction_logs = (TransactionLog *)malloc(sizeof(TransactionLog) * transaction_log_capacity);
}

// Release all memory used by the dynamic array of transaction logs
void free_transaction_logs() {
    // Free the array of transaction logs
    free(transaction_logs);
    transaction_logs = NULL;
    transaction_log_count = 0;
    transaction_log_capacity = 0;
}

// Append a new transaction log entry to the dynamic array, resizing it if necessary
void append_transaction_log(TransactionLog *new_log) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // If the current capacity of the array is exceeded, resize it to accommodate more entries
    if (transaction_log_count == transaction_log_capacity) {
        transaction_log_capacity *= 2;
        transaction_logs = (TransactionLog *)realloc(transaction_logs, sizeof(TransactionLog) * transaction_log_capacity);
    }

    // Copy the new log entry into the next available slot in the array
    memcpy(&transaction_logs[transaction_log_count++], new_log, sizeof(TransactionLog));

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

// Clear all allocated resources when the function completes
void processTransactionLogs() {
    // Free the array of transaction logs and reset the count and capacity to 0
    free_transaction_logs();
}

