// Function to initialize the logging capabilities
void initLogging() {
    // Initialize a vector to store the log messages
    vector<string> logMessages;

    // Set the initial logging level to INFO
    LOG_LEVEL = LOG_INFO;
}

// Function to update the logging level based on user input
void updateLoggingLevel(LOG_LEVEL newLevel) {
    // Update the logging level if it's valid
    if (newLevel == LOG_DEBUG || newLevel == LOG_INFO || newLevel == LOG_WARNING || newLevel == LOG_ERROR) {
        LOG_LEVEL = newLevel;
    }
}

// Function to log a message based on the current logging level
void logMessage(string message) {
    // Check if the message should be logged based on the current logging level
    if (LOG_LEVEL == LOG_DEBUG || (LOG_LEVEL == LOG_INFO && !message.empty()) || (LOG_LEVEL == LOG_WARNING && !message.empty()) || (LOG_LEVEL == LOG_ERROR && !message.empty())) {
        // Add the message to the log messages vector
        logMessages.push_back(message);
    }
}

// Function to print the logged messages based on the current logging level
void printLogMessages() {
    // Check if there are any logged messages
    if (logMessages.empty()) {
        return;
    }

    // Print the logged messages based on the current logging level
    switch(LOG_LEVEL) {
        case LOG_DEBUG:
            for (auto& message : logMessages) {
                printf("[DEBUG] %s\n", message.c_str());
            }
            break;
        case LOG_INFO:
            for (auto& message : logMessages) {
                printf("[INFO] %s\n", message.c_str());
            }
            break;
        case LOG_WARNING:
            for (auto& message : logMessages) {
                printf("[WARNING] %s\n", message.c_str());
            }
            break;
        case LOG_ERROR:
            for (auto& message : logMessages) {
                printf("[ERROR] %s\n", message.c_str());
            }
            break;
    }
}
