int generate_records(int num_records) {
    int i;
    long *offsets = NULL;
    int *keys = NULL;
    int *timestamps = NULL;
    double *values = NULL;
    struct metadata *metadata = NULL;
    enum status *statuses = NULL;

    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    timestamps = (int*)malloc(num_records * sizeof(int));
    values = (double*)malloc(num_records * sizeof(double));
    metadata = (struct metadata *)malloc(num_records * sizeof(struct metadata));
    statuses = (enum status *)malloc(num_records * sizeof(enum status));

    for (i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000 + 1; // random offset between 1 and 1000
        keys[i] = rand() % 100 + 1; // random key between 1 and 100
        timestamps[i] = (int)time(NULL) * 1000; // current timestamp in milliseconds
        values[i] = (double)rand() / RAND_MAX; // random double value between 0 and 1
        metadata[i].id = rand() % 100 + 1; // random id between 1 and 100
        metadata[i].latitude = rand() % 90 - 45; // random latitude between -45 and 45 degrees
        metadata[i].name = (char*)malloc(sizeof("random name")); // random string of length 8
        statuses[i] = OK; // set status to "OK"
    }

    record *records = (record*)malloc(num_records * sizeof(record));
    for (i = 0; i < num_records; i++) {
        records[i].value = values[i];
        records[i].offsets[i] = offsets[i];
        records[i].keys[i] = keys[i];
        records[i].timestamps[i] = timestamps[i];
        records[i].metadata = metadata[i];
        records[i].status = statuses[i];
    }

    // validate generated records against predefined criteria before returning them
    // ...

    free(offsets);
    free(keys);
    free(timestamps);
    free(values);
    free(metadata);
    free(statuses);
    return records;
}
```
The function uses the `rand()` and `time()` functions to generate random values for each record. The `rand() % 100 + 1` expression generates a random integer between 1 and 100, while the `(int)time(NULL) * 1000` expression generates a current timestamp in milliseconds.
The function also uses the `malloc()` function to dynamically allocate memory for each record's metadata, which consists of an integer id, a double latitude, and a string name of length 8. The allocated memory is freed using the `free()` function when it is no longer needed.
