        keys[i] = std::rand() % (keyMax - keyMin + 1) + keyMin;
        timestamps[i] = std::rand() % (timestampMax - timestampMin + 1) + timestampMin;
        detailedRecords[i] = {keys[i], offsets[i], detailRecordChar};
