struct sensor_reading {
    int timestamp;
    float value;
};

struct device_metadata {
    char* name;
    int id;
    struct sensor_reading* readings;
    size_t num_readings;
};

struct log_entry {
    int timestamp;
    char* message;
};

struct configuration {
    int sampling_frequency;
    float range[2];
};

void initialize_core_components(struct device_metadata* metadata, struct configuration config) {
    // Initialize timestamp array
    size_t num_timestamps = 5;
    int* timestamps = (int*)malloc(num_timestamps * sizeof(int));
    for (size_t i = 0; i < num_timestamps; i++) {
        timestamps[i] = time(NULL);
    }

    // Initialize sensor reading array
    size_t num_readings = 5;
    struct sensor_reading* readings = (struct sensor_reading*)malloc(num_readings * sizeof(struct sensor_reading));
    for (size_t i = 0; i < num_readings; i++) {
        readings[i].timestamp = timestamps[i];
        readings[i].value = i % 2 ? 1.5 : 3.7;
    }

    // Initialize device metadata structure
    metadata->name = "Device 1";
    metadata->id = 1;
    metadata->readings = readings;
    metadata->num_readings = num_readings;

    // Initialize log entry array
    size_t num_log_entries = 5;
    struct log_entry* log_entries = (struct log_entry*)malloc(num_log_entries * sizeof(struct log_entry));
    for (size_t i = 0; i < num_log_entries; i++) {
        log_entries[i].timestamp = timestamps[i];
        log_entries[i].message = "Log entry";
    }

    // Initialize configuration structure
    config.sampling_frequency = 10;
    config.range[0] = 0.5;
    config.range[1] = 10.5;

    // Cleanup
    free(timestamps);
}

void generate_sensor_data(struct device_metadata* metadata, struct configuration config) {
    int current_timestamp = time(NULL);
    float current_value = 0;

    while (current_timestamp < metadata->readings[metadata->num_readings - 1].timestamp + config.sampling_frequency) {
        // Generate sensor data
        if (current_value > config.range[1]) {
            current_value = config.range[0];
        } else {
            current_value += 0.5;
        }

        // Update timestamp and value in metadata structure
        struct sensor_reading* new_reading = (struct sensor_reading*)malloc(sizeof(struct sensor_reading));
        new_reading->timestamp = current_timestamp;
        new_reading->value = current_value;
        metadata->readings[metadata->num_readings++] = *new_reading;

        // Add log entry to log array
        struct log_entry* new_log_entry = (struct log_entry*)malloc(sizeof(struct log_entry));
        new_log_entry->timestamp = current_timestamp;
        new_log_entry->message = "Sensor data generated";
        metadata->log_entries[metadata->num_log_entries++] = *new_log_entry;

        // Update current timestamp and value
        current_timestamp += config.sampling_frequency;
    }
}

void process_sensor_data(struct device_metadata* metadata) {
    // Process sensor data
    printf("Processing sensor data for device %s\n", metadata->name);
    for (size_t i = 0; i < metadata->num_readings; i++) {
        struct sensor_reading* reading = &metadata->readings[i];
        printf("%d: %.2f\n", reading->timestamp, reading->value);
    }
}

void log_message(struct device_metadata* metadata) {
    // Log message to various destinations
    printf("Logging message for device %s\n", metadata->name);
    for (size_t i = 0; i < metadata->num_log_entries; i++) {
        struct log_entry* entry = &metadata->log_entries[i];
        printf("%d: %s\n", entry->timestamp, entry->message);
    }
}

void handle_errors(struct device_metadata* metadata) {
    // Handle potential resource limitations and data discrepancies
    if (metadata->num_readings > 10) {
        printf("Too many sensor readings for device %s\n", metadata->name);
    }
    if (metadata->log_entries[metadata->num_log_entries - 1].message == "Sensor data generated") {
        printf("Unexpected log entry for device %s\n", metadata->name);
    }
}

void cleanup(struct device_metadata* metadata) {
    // Cleanup resources allocated during initialization and processing
    free(metadata->readings);
    free(metadata->log_entries);
}

int main() {
    struct device_metadata metadata;
    struct configuration config = {10, {0.5, 10.5}};

    initialize_core_components(&metadata, config);
    generate_sensor_data(&metadata, config);
    process_sensor_data(&metadata);
    log_message(&metadata);
    handle_errors(&metadata);
    cleanup(&metadata);

    return 0;
}
