// Custom allocator for thread-safe memory allocation
struct mem_alloc {
    void* ptr;
    size_t size;
};

struct mem_alloc* allocate(size_t size) {
    struct mem_alloc* alloc = (struct mem_alloc*) malloc(sizeof(struct mem_alloc));
    if (alloc == NULL) {
        return NULL;
    }
    alloc->ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (alloc->ptr == MAP_FAILED) {
        free(alloc);
        return NULL;
    }
    alloc->size = size;
    return alloc;
}

void deallocate(struct mem_alloc* alloc) {
    munmap(alloc->ptr, alloc->size);
    free(alloc);
}

// Lock-free allocator for thread-safe concurrent access to memory
struct lock_free_alloc {
    struct mem_alloc** allocs;
    size_t num_allocs;
};

struct lock_free_alloc* create_lock_free_alloc(size_t num_allocs) {
    struct lock_free_alloc* alloc = (struct lock_free_alloc*) malloc(sizeof(struct lock_free_alloc));
    if (alloc == NULL) {
        return NULL;
    }
    alloc->allocs = (struct mem_alloc**) calloc(num_allocs, sizeof(struct mem_alloc*));
    if (alloc->allocs == NULL) {
        free(alloc);
        return NULL;
    }
    alloc->num_allocs = num_allocs;
    return alloc;
}

void destroy_lock_free_alloc(struct lock_free_alloc* alloc) {
    for (size_t i = 0; i < alloc->num_allocs; i++) {
        if (alloc->allocs[i] != NULL) {
            deallocate(alloc->allocs[i]);
        }
    }
    free(alloc->allocs);
    free(alloc);
}

void* lock_free_malloc(struct lock_free_alloc* alloc, size_t size) {
    for (size_t i = 0; i < alloc->num_allocs; i++) {
        if (alloc->allocs[i] == NULL || alloc->allocs[i]->size >= size) {
            struct mem_alloc* new_alloc = allocate(size);
            if (new_alloc == NULL) {
                continue;
            }
            if (alloc->allocs[i] != NULL) {
                deallocate(alloc->allocs[i]);
            }
            alloc->allocs[i] = new_alloc;
            return new_alloc->ptr;
        }
    }
    return NULL;
}

