void encrypt_record(struct Record *rec) {
  // Encrypt the record using the specified cipher and hash function
  EVP_CIPHER_CTX *ctx;
  EVP_CIPHER *cipher;
  EVP_MD *hash;
  unsigned char key[32];
  unsigned char iv[16];

