  hash = EVP_get_digestbyname(this->hash);
  EVP_CIPHER_CTX_init(ctx);

  // Initialize the key and IV
  RAND_bytes((unsigned char *) key, this->key_size / 8);
  RAND_bytes((unsigned char *) iv, this->block_size / 8);

  // Encrypt the record using the specified cipher and hash function
  EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
  EVP_EncryptUpdate(ctx, rec->data, &size, rec->data, size);
  EVP_EncryptFinal_ex(ctx, rec->data + size, &size);

  // Free the encryption context
  EVP_CIPHER_CTX_cleanup(ctx);
}

void decrypt_record(struct Record *rec) {
