  RAND_bytes((unsigned char *) iv, this->block_size / 8);

  // Decrypt the record using the specified cipher and hash function
  EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv);
  EVP_DecryptUpdate(ctx, rec->data, &size, rec->data, size);
  EVP_DecryptFinal_ex(ctx, rec->data + size, &size);

  // Free the decryption context
  EVP_CIPHER_CTX_cleanup(ctx);
}

