    return (min + (rand() % (max - min + 1)));
}

int getRandomInt(int min, int max) {
    return (min + (rand() % (max - min + 1)));
}

float getRandomFloat(float min, float max) {
    return (min + ((float) rand() / (RAND_MAX)) * (max - min));
}

// Function to initialize a record with random values and validate it against validation criteria
void initRecord(Record* record, long offset, int key, float value, char* identifier) {
    // Generate random values within specified ranges for each field
    record->offset = getRandomLong(0, 1000);
    record->key = getRandomInt(1, 10);
    record->value = getRandomFloat(0.1, 10.0);
    record->identifier = malloc(strlen(identifier) + 1);
