    } else {
        printf("Failed to validate record with offset %ld and key %d\n", record->offset, record->key);
    }
}

// Function to validate a record against validation criteria
bool validateRecord(Record* record) {
    // Check if the record's offset is within the expected range
    if (record->offset < 0 || record->offset > 1000) {
        return false;
    }

    // Check if the record's key is within the expected range
    if (record->key < 1 || record->key > 10) {
        return false;
    }

    // Check if the record's value is within the expected range
