        return false;
    }

    // Check if the record's identifier is valid
    if (!isValidIdentifier(record->identifier)) {
        return false;
    }

    // If all validation criteria are met, return true
    return true;
}

// Function to check if an identifier is valid
bool isValidIdentifier(char* identifier) {
    // Check if the identifier contains only alphanumeric characters
    for (int i = 0; i < strlen(identifier); i++) {
        if (!isalnum(identifier[i])) {
            return false;
        }
    }

    // If the identifier is valid, return true
    return true;
}

