#define MAX_FILE_DESCRIPTORS 1024 // Maximum number of file descriptors that can be managed by the function
#define MIN_ALIGNMENT 8 // Minimum alignment requirement for memory allocation

// File descriptor structure to hold information about each open file
typedef struct {
    int fd; // File descriptor
    int type; // Type of file (text, binary, compressed, etc.)
    char* path; // Path to the file
} file_descriptor_t;

// Memory pool structure to hold small object allocations
typedef struct {
    size_t size; // Size of the memory block
    void* ptr; // Pointer to the memory block
} memory_pool_t;

// File descriptor collection structure to manage the file descriptors
typedef struct {
    file_descriptor_t* fds; // Array of file descriptors
    size_t capacity; // Capacity of the file descriptor array
    size_t count; // Number of file descriptors in use
} file_descriptor_collection_t;

// Lock for synchronizing access to the file descriptor collection
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Custom allocator function that uses the memory pool to allocate small objects
void* custom_alloc(size_t size) {
    // Check if the requested size is greater than the maximum alignment requirement
    if (size > MIN_ALIGNMENT) {
        return malloc(size);
    }

    // Check if there is space available in the memory pool
    if (memory_pool.size - memory_pool.ptr >= size) {
        void* ptr = memory_pool.ptr;
        memory_pool.ptr += size;
        return ptr;
    }

    // If no space is available, allocate a new block from the standard library allocator
    return malloc(size);
}

// Custom deallocator function that returns objects to the memory pool
void custom_dealloc(void* ptr) {
    if (ptr != NULL) {
        size_t size = (*(size_t*)ptr);
        if (size > MIN_ALIGNMENT) {
            free(ptr);
        } else {
            memory_pool.ptr -= size;
        }
    }
}

// Open a file and add it to the file descriptor collection
int handleDynamicFileOperations(char* path, int type) {
    // Acquire the lock for synchronizing access to the file descriptor collection
    pthread_mutex_lock(&lock);

    // Check if there is space available in the file descriptor collection
    if (file_descriptor_collection.count >= file_descriptor_collection.capacity) {
        // If no space is available, double the capacity of the file descriptor array
        size_t new_capacity = file_descriptor_collection.capacity * 2;
        file_descriptor_t* new_fds = realloc(file_descriptor_collection.fds, new_capacity * sizeof(file_descriptor_t));
        if (new_fds == NULL) {
            // If the reallocation fails, free all allocated memory and return an error
            for (int i = 0; i < file_descriptor_collection.count; ++i) {
                close(file_descriptor_collection.fds[i].fd);
            }
            free(file_descriptor_collection.fds);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        // Update the file descriptor collection with the new capacity and array
        file_descriptor_collection.capacity = new_capacity;
        file_descriptor_collection.fds = new_fds;
    }

    // Open the file using the standard library open function
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        // If the file cannot be opened, free all allocated memory and return an error
        for (int i = 0; i < file_descriptor_collection.count; ++i) {
            close(file_descriptor_collection.fds[i].fd);
        }
        free(file_descriptor_collection.fds);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Add the file descriptor to the collection and update the count
    file_descriptor_t* fd = &file_descriptor_collection.fds[file_descriptor_collection.count++];
    fd->fd = fd;
    fd->type = type;
    fd->path = path;

    // Release the lock and return success
    pthread_mutex_unlock(&lock);
    return 0;
}

// Close a file descriptor and remove it from the collection
int closeFileDescriptor(int fd) {
    // Acquire the lock for synchronizing access to the file descriptor collection
    pthread_mutex_lock(&lock);

    // Find the file descriptor in the collection and update the count
    for (size_t i = 0; i < file_descriptor_collection.count; ++i) {
        if (file_descriptor_collection.fds[i].fd == fd) {
            --file_descriptor_collection.count;
            close(file_descriptor_collection.fds[i].fd);
            break;
        }
    }

    // Release the lock and return success
    pthread_mutex_unlock(&lock);
    return 0;
}

// Read from a file descriptor using the standard library read function
ssize_t readFileDescriptor(int fd, void* buffer, size_t count) {
    // Acquire the lock for synchronizing access to the file descriptor collection
    pthread_mutex_lock(&lock);

    // Find the file descriptor in the collection and update the count
    for (size_t i = 0; i < file_descriptor_collection.count; ++i) {
        if (file_descriptor_collection.fds[i].fd == fd) {
            ssize_t bytes_read = read(fd, buffer, count);
            if (bytes_read == -1) {
                // If the read operation fails, return an error code
                pthread_mutex_unlock(&lock);
                return -1;
            } else {
                // If the read operation is successful, update the buffer and return the number of bytes read
                pthread_mutex_unlock(&lock);
                return bytes_read;
            }
        }
    }

    // Release the lock and return an error code if the file descriptor was not found in the collection
    pthread_mutex_unlock(&lock);
    return -1;
}

// Write to a file descriptor using the standard library write function
ssize_t writeFileDescriptor(int fd, const void* buffer, size_t count) {
    // Acquire the lock for synchronizing access to the file descriptor collection
    pthread_mutex_lock(&lock);

    // Find the file descriptor in the collection and update the count
    for (size_t i = 0; i < file_descriptor_collection.count; ++i) {
        if (file_descriptor_collection.fds[i].fd == fd) {
            ssize_t bytes_written = write(fd, buffer, count);
            if (bytes_written == -1) {
                // If the write operation fails, return an error code
                pthread_mutex_unlock(&lock);
