void partition_data() {
    // Acquire the lock for thread-safe access to the records array
    pthread_mutex_lock(&mutex);
    // Calculate the number of segments required to process the data store in parallel
    int num_segments = (num_records / num_threads) + 1;
    // Allocate memory for each segment
    record* segments[num_segments];
    for (int i = 0; i < num_segments; i++) {
