    // Copy records from the main data store to each segment in parallel
    for (int i = 0; i < num_segments; i++) {
        int start_index = i * (num_records / num_segments);
        int end_index = (i + 1) * (num_records / num_segments) - 1;
        memcpy(segments[i], records + start_index, sizeof(record) * (end_index - start_index + 1));
    }
    // Release the lock when finished
    pthread_mutex_unlock(&mutex);
