// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t capacity; // The maximum number of elements in the list
    size_t count; // The current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T *elements; // An array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_PDU_LIST;

// Define a function to initialize an empty list
void initList(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    list->capacity = 0;
    list->count = 0;
    list->elements = NULL;
}

// Define a function to add an element to the end of a list
void addElement(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // If the list is empty, allocate memory for the first element
    if (list->count == 0) {
        list->capacity = 1;
        list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    // If the list is full, allocate more memory for elements
    else if (list->count == list->capacity) {
        list->capacity *= 2;
        list->elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    }
    // Add the element to the end of the list
    list->elements[list->count] = *element;
    list->count++;
}

// Define a function to read up to 10,000 RNTIs from standard input and add them to the list
void readRNTIs(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // Loop until 10,000 RNTIs have been read or EOF is reached
    for (int i = 0; i < 10000 && !feof(stdin); i++) {
        // Read the next RNTI from standard input
        uint16_t rnti;
        if (fread(&rnti, sizeof(uint16_t), 1, stdin) != 1) {
            fprintf(stderr, "Error reading RNTI\n");
            exit(EXIT_FAILURE);
        }
        // Create a new element for the RNTI and add it to the list
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        element->RX_UE_INFORMATION_TAG = 0; // Set the RX_UE_INFORMATION_TAG to zero
        element->RNTI = rnti; // Set the RNTI to the value read from standard input
        element->CRC_INDICATION_REL8_TAG = (rand() % 256) + 1; // Set the CRC_INDICATION_REL8_TAG to a random value between 1 and 256
        addElement(list, element);
    }
}

// Define a function to print the largest RNTI value present in the list
void printLargestRNTI(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // If the list is empty, return
    if (list->count == 0) {
        return;
    }
    // Find the largest RNTI value in the list
    uint16_t largestRNTI = list->elements[0].RNTI;
    for (size_t i = 1; i < list->count; i++) {
        if (list->elements[i].RNTI > largestRNTI) {
            largestRNTI = list->elements[i].RNTI;
        }
    }
    // Print the largest RNTI value and its indices in the list
    printf("Largest RNTI: %d\n", largestRNTI);
    for (size_t i = 0; i < list->count; i++) {
        if (list->elements[i].RNTI == largestRNTI) {
            printf("%zu\n", i);
        }
    }
}

// Define a function to print the number of duplicate RNTIs found in the list
void printDuplicateRNTIs(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // If the list is empty, return
    if (list->count == 0) {
        return;
    }
    // Count the number of duplicate RNTIs in the list
    size_t duplicates = 0;
    for (size_t i = 1; i < list->count; i++) {
        for (size_t j = 0; j < i; j++) {
            if (list->elements[i].RNTI == list->elements[j].RNTI) {
                duplicates++;
                break;
            }
        }
    }
    // Print the number of duplicate RNTIs found in the list
    printf("Number of duplicate RNTIs: %zu\n", duplicates);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    initList(list);
    readRNTIs(list);
    printLargestRNTI(list);
    printDuplicateRNTIs(list);
    free(list);
    return 0;
}']

