    // Flag indicating whether the context is active or not
    int active;
} MarketContext;

typedef struct {
    // Price data for the trade order
    double price;
    // Tag indicating market conditions for the trade order
    char tag;
    // Linked list of node structures for order history
    Node* history;
} TradeOrder;

// Define data structure for the linked list of nodes
typedef struct {
    // Pointer to the next node in the list
    struct Node* next;
    // Pointer to the previous node in the list
    struct Node* prev;
    // Data stored in the node
    void* data;
} Node;

// Function for initializing and populating an array of MarketContext structures
void init_market_contexts(MarketContext** contexts, size_t num_contexts) {
    // Allocate memory for the array of MarketContext structures
    *contexts = (MarketContext*) malloc(num_contexts * sizeof(MarketContext));
    if (*contexts == NULL) {
        // Handle error for failed memory allocation
        printf("Failed to allocate memory for market contexts\n");
        return;
    }

    // Initialize each MarketContext structure and populate it with valid trade orders and price data
    for (size_t i = 0; i < num_contexts; i++) {
        // Allocate memory for the PriceData buffer
        (*contexts)[i].price_data = (unsigned char*) malloc(1024 * sizeof(unsigned char));
        if ((*contexts)[i].price_data == NULL) {
            // Handle error for failed memory allocation
            printf("Failed to allocate memory for price data in market context %lu\n", i);
            return;
        }
        (*contexts)[i].price_data_size = 1024 * sizeof(unsigned char);

        // Initialize the active flag to true
        (*contexts)[i].active = 1;
    }
}

// Function for generating a random double within a specified trading range
double generate_random_double(double min, double max) {
    // Calculate the difference between the minimum and maximum values
    double diff = max - min;
    // Generate a random number within the range of the difference
    double rand_num = (double) rand() / RAND_MAX * diff + min;
    return rand_num;
}

// Function for generating a random tag indicating market conditions
char generate_random_tag(void) {
    // Generate a random number between 0 and 26, inclusive
    int rand_num = (int) ((double) rand() / RAND_MAX * 26);
    if (rand_num <= 10) {
        return 'A';
    } else if (rand_num <= 18) {
        return 'B';
    } else if (rand_num <= 22) {
        return 'C';
    } else {
        return 'D';
    }
}

// Function for generating a linked list of nodes containing trade orders and order history data
void generate_order_history(Node** head, size_t num_orders) {
    // Allocate memory for the linked list of nodes
    *head = (Node*) malloc(num_orders * sizeof(Node));
    if (*head == NULL) {
        // Handle error for failed memory allocation
        printf("Failed to allocate memory for order history\n");
        return;
    }

    // Initialize each node in the linked list and populate it with trade orders and order history data
    Node* current = *head;
    for (size_t i = 0; i < num_orders; i++) {
        // Allocate memory for the data stored in the node
        current->data = (void*) malloc(sizeof(TradeOrder));
        if (current->data == NULL) {
            // Handle error for failed memory allocation
            printf("Failed to allocate memory for trade order %lu\n", i);
            return;
        }

        // Initialize the data stored in the node and populate it with valid trade orders and price data
        TradeOrder* order = (TradeOrder*) current->data;
        order->price = generate_random_double(0.0, 100.0);
        order->tag = generate_random_tag();
        order->history = NULL;
    }
}

// Function for tracking the health of the data structure and monitoring performance metrics
void monitor_data_structure(MarketContext* contexts, size_t num_contexts) {
    // Calculate the number of active contexts and the average size of the PriceData buffers
    int active_contexts = 0;
    double avg_price_data_size = 0.0;
    for (size_t i = 0; i < num_contexts; i++) {
        if (contexts[i].active) {
            active_contexts++;
            avg_price_data_size += contexts[i].price_data_size;
        }
    }
    avg_price_data_size /= active_contexts;

    // Print the health of the data structure and monitoring performance metrics
    printf("Active Contexts: %d\n", active_contexts);
    printf("Average Price Data Size: %.2f bytes\n", avg_price_data_size);
}

// Function for gracefully shutting down the data structure and releasing all resources
void shutdown_market_contexts(MarketContext* contexts, size_t num_contexts) {
    // Release memory allocated for each MarketContext structure
    for (size_t i = 0; i < num_contexts; i++) {
        free(contexts[i].price_data);
    }
    // Release memory allocated for the array of MarketContext structures
    free(contexts);
}
```
