struct metric {
    double value;
    char identifier[10];
};

void initializeMetrics() {
    // Initialize arrays for storing float precision values and char identifiers
    struct metric *metrics = malloc(sizeof(struct metric) * 10);
    char **identifiers = malloc(sizeof(char *) * 10);

    // Set up random number generator for generating uniformly distributed random numbers
    srand(time(NULL));

    // Loop through each metric and generate a randomly generated double value within the specified range
    for (int i = 0; i < 10; i++) {
        metrics[i].value = ((double) rand() / RAND_MAX) * 10.0;

        // Generate a random identifier using a combination of letters and numbers
        char identifier[10];
        for (int j = 0; j < 9; j++) {
            int r = rand() % 62;
            if (r < 26) {
                identifier[j] = 'a' + r;
            } else {
                identifier[j] = 'A' + (r - 26);
            }
        }
        identifier[9] = '\0';
        strcpy(metrics[i].identifier, identifier);
    }

    // Parse and generate JSON data for the metrics using the JSON-C library
    json_object *json = json_object_new();
    json_object_object_add(json, "metrics", json_object_array());
    for (int i = 0; i < 10; i++) {
        json_object *metric_obj = json_object_new();
        json_object_object_add(metric_obj, "value", json_object_new_double(metrics[i].value));
        json_object_object_add(metric_obj, "identifier", json_object_new_string(metrics[i].identifier));
        json_object_array_add(json_object_object_get(json, "metrics"), metric_obj);
    }

    // Free memory allocated for the arrays and the JSON data
    free(metrics);
    free(identifiers);
    json_object_put(json);
}
