import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class FileStorage {
    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService threadPool;
    private Map<String, FileMetadata> fileMetadataMap;
    private List<FileProcessor> fileProcessors;

    public FileStorage() {
        this.threadPool = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        this.fileMetadataMap = new HashMap<>();
        this.fileProcessors = new ArrayList<>();
    }

    public void addFile(String fileName, byte[] fileContents) {
        FileMetadata fileMetadata = new FileMetadata(fileName, System.currentTimeMillis(), fileContents.length);
        fileMetadataMap.put(fileName, fileMetadata);
        threadPool.submit(() -> processFile(fileMetadata));
    }

    public void getFile(String fileName) {
