void http_post(const char* url, const char* json, int length) {
    // Set up an HTTP client to send the POST request
    struct http_client client = {
        .url = url,
        .json_payload = json,
        .length = length,
        .status = 0,
    };

    // Retry logic with exponential backoff
    int retry_count = 3;
    while (retry_count > 0) {
        if (http_client_send(&client)) {
            break;
        } else {
            retry_count--;
            sleep(pow(2, retry_count - 1));
        }
    }

