    }
    // Add the record to the linked list and signal
    pthread_mutex_lock(&mutex);
    insert_node(&head, rec);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    srand(time(NULL));
    struct record *rec = malloc(sizeof(struct record));
    if (rec == NULL) {
        perror("malloc");
        return -1;
    }
    init_record(rec, rand() % (MAX_RNTI-MIN_RNTI+1) + MIN_RNTI);
    pthread_t workers[num_workers];
    for (int i = 0; i < num_workers; ++i) {
        int ret = pthread_create(&workers[i], NULL, worker, rec);
        if (ret != 0) {
            perror("pthread_create");
            return -1;
        }
    }
    struct node *node = head;
    while (node != NULL) {
        // Process the record
        int val = node->data->value;
        log("INFO", "Processing RNTI %d", val);
        // Remove the node from the linked list
        pthread_mutex_lock(&mutex);
        struct node *next = remove_node(&head);
        pthread_mutex_unlock(&mutex);
        free(node);
        node = next;
    }
    for (int i = 0; i < num_workers; ++i) {
        int ret = pthread_join(workers[i], NULL);
        if (ret != 0) {
            perror("pthread_join");
            return -1;
        }
    }
    return 0;
}
