    time_t timestamp;
    char message[LOG_ENTRY_LEN];
} LogEntry;

struct Sessions {
    Session sessions[MAX_SESSIONS];
    int numSessions;
    bool initialized;
};

void initSessions(Sessions *sessions) {
    if (!sessions->initialized) {
        for (int i = 0; i < MAX_SESSIONS; i++) {
            sessions->sessions[i].sessionID[0] = '\0';
            sessions->sessions[i].user.name[0] = '\0';
            sessions->sessions[i].logEntry.timestamp = 0;
            sessions->sessions[i].logEntry.message[0] = '\0';
        }
        sessions->numSessions = 0;
        sessions->initialized = true;
    }
}

void addSession(Sessions *sessions, char sessionID[SESSION_ID_LEN], User user) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    int i = 0;
    while (i < MAX_SESSIONS && strcmp(sessions->sessions[i].sessionID, sessionID) != 0) {
        i++;
    }

    if (i == MAX_SESSIONS) {
        fprintf(stderr, "Error: maximum number of sessions exceeded\n");
        return;
    }

    strcpy(sessions->sessions[i].sessionID, sessionID);
    sessions->sessions[i].user = user;
}

