    if (!sessions->initialized) {
        initSessions(sessions);
    }

    int i = 0;
    while (i < MAX_SESSIONS && strcmp(sessions->sessions[i].sessionID, sessionID) != 0) {
        i++;
    }

    if (i == MAX_SESSIONS) {
        fprintf(stderr, "Error: session not found\n");
        return;
    }

    sessions->sessions[i].logEntry = entry;
}

void removeSession(Sessions *sessions, char sessionID[SESSION_ID_LEN]) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    int i = 0;
    while (i < MAX_SESSIONS && strcmp(sessions->sessions[i].sessionID, sessionID) != 0) {
        i++;
    }

    if (i == MAX_SESSIONS) {
        fprintf(stderr, "Error: session not found\n");
        return;
    }

    for (int j = i; j < MAX_SESSIONS - 1; j++) {
        sessions->sessions[j] = sessions->sessions[j + 1];
    }
    sessions->numSessions--;
}

void invalidateCache(Sessions *sessions) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        sessions->sessions[i].logEntry.timestamp = 0;
    }
}

void handleExternalDependency(Sessions *sessions, char sessionID[SESSION_ID_LEN], User user) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

