void releaseAccess(Sessions *sessions) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_mutex_unlock(&sessions->sessions[i].mutex);
    }
}

void terminateSession(Sessions *sessions, char sessionID[SESSION_ID_LEN]) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    int i = 0;
    while (i < MAX_SESSIONS && strcmp(sessions->sessions[i].sessionID, sessionID) != 0) {
        i++;
    }

    if (i == MAX_SESSIONS) {
        fprintf(stderr, "Error: session not found\n");
        return;
    }

