}

void freeResources(Sessions *sessions) {
    if (!sessions->initialized) {
        initSessions(sessions);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_mutex_destroy(&sessions->sessions[i].mutex);
