        return;
    }

    // get the lock for the thread
    pthread_mutex_lock(&manager->locks[thread_id]);

    // validate the message
    int validation_result = validate_nas_message(message);
    if (validation_result != 0) {
        printf("Error: unable to validate NAS message\n");
        pthread_mutex_unlock(&manager->locks[thread_id]);
        return;
    }

    // encode the message
    void *encoded = nas_alloc(sizeof(NAS_Message));
    if (!encoded) {
        printf("Error: unable to allocate memory for NAS message\n");
        pthread_mutex_unlock(&manager->locks[thread_id]);
        return;
    }
    memcpy(encoded, message, sizeof(NAS_Message));

    // associate the encoded message with a unique identifier
    ULONG id = generate_unique_identifier();
    if (!id) {
        printf("Error: unable to generate unique identifier for NAS message\n");
        nas_free(encoded);
        pthread_mutex_unlock(&manager->locks[thread_id]);
        return;
    }

    // add the new UE context to the end of the array
    add_ue_context(manager, thread_id);

    // set the data for the new UE context
    manager->data[manager->num_threads - 1] = id;

    // unlock the mutex
    pthread_mutex_unlock(&manager->locks[thread_id]);
}

// function for generating a unique identifier
ULONG generate_unique_identifier(void) {
    static ULONG next_id = 0;
    return __sync_fetch_and_add(&next_id, 1);
}
