#define TASK_ID_MIN 1000 /* minimum ID value */
#define TASK_ID_MAX 9999 /* maximum ID value */
#define PRIORITY_MIN 1 /* minimum priority level */
#define PRIORITY_MAX 5 /* maximum priority level */
#define LOGGING_ENABLED true /* enable/disable logging */

/* structure to represent a task object */
typedef struct {
    int id;
    int priority;
    void* data;
} Task;

/* function to initialize and return a new task object with unique ID and priority level */
Task* init_task(int priority) {
    /* allocate memory for the task object */
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        log("ERROR: Failed to allocate memory for task\n");
        return NULL;
    }

    /* generate a unique ID value within the specified range */
    int id = TASK_ID_MIN + rand() % (TASK_ID_MAX - TASK_ID_MIN);
    while (idExists(task, id)) {
        id = TASK_ID_MIN + rand() % (TASK_ID_MAX - TASK_ID_MIN);
    }

    /* initialize the task object */
    task->id = id;
    task->priority = priority;
    task->data = NULL;

    return task;
}

/* function to set the priority level of a given task object within a specified range */
bool set_task_priority(Task* task, int priority) {
    /* check if the provided priority value is within the valid range */
    if (priority < PRIORITY_MIN || priority > PRIORITY_MAX) {
        log("ERROR: Provided priority level is out of range\n");
        return false;
    }

    /* set the priority level of the task object */
    task->priority = priority;

    return true;
}

