} nfapi_crc_indication_list_t;

void nfapi_crc_indication_list_init(nfapi_crc_indication_list_t* list) {
    list->size = 0;
    list->data = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

int nfapi_crc_indication_list_insert(nfapi_crc_indication_list_t* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    int index = list->size;
    if (index == 0 || index >= list->size * 2) {
        list->data = realloc(list->data, sizeof(nfapi_crc_indication_pdu_t) * list->size * 2);
        if (!list->data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }
    list->data[index].rx_ue_info = pdu.rx_ue_info;
    list->data[index].crcflag = pdu.crcflag;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t* list, int index) {
    if (index >= list->size || index < 0) {
        printf("Error: invalid index\n");
        return;
    }
    pthread_mutex_lock(&list->lock);
    for (int i = index + 1; i < list->size - 1; i++) {
        list->data[i - 1] = list->data[i];
    }
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

int nfapi_crc_indication_list_resize(nfapi_crc_indication_list_t* list, int new_size) {
    if (new_size < 0 || new_size > list->size * 2) {
        printf("Error: invalid new size\n");
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    list->data = realloc(list->data, sizeof(nfapi_crc_indication_pdu_t) * new_size);
    if (!list->data) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->size = new_size;
    pthread_mutex_unlock(&list->lock);
    return 0;
}
