// Function to generate random records with specified ranges and populate an array of 'record' structures
fn generate_records(offset_min: i64, offset_max: i64, key_min: i32, key_max: i32, timestamp_min: f64, timestamp_max: f64) -> Vec<Record> {
    // Initialize an array of 'record' structures to hold the generated records
    let mut records: Vec<Record> = vec![];

    // Generate random values within specified ranges for each record
    for _ in 0..1000 {
        // Generate a random long offset value between the minimum and maximum specified values
        let offset = rand::thread_rng().gen_range(offset_min, offset_max);

        // Generate a random integer key between the minimum and maximum specified values
        let key = rand::thread_rng().gen_range(key_min, key_max);

        // Generate a random double precision timestamp value between the minimum and maximum specified values
        let timestamp = (rand::thread_rng().gen_range(timestamp_min, timestamp_max) * 1000.0) as f64;

        // Create a new 'record' structure with the generated values
        records.push(Record {
            offset: offset,
            key: key,
            timestamp: timestamp,
        });
    }

    // Return the array of generated records
    records
}
