// Dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    // Unique tag for each element in the array
    uint32_t rx_ue_information_tag;
    // Unique identifier derived from rx_ue_information_tag
    uint16_t rnti;
    // Random value for crcflag field
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage the dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_array(NFAPI_CRC_INDICATION_PDU_T **p_array, size_t *capacity, size_t max_size) {
    // Check if the array is NULL or has a capacity of 0
    if (*p_array == NULL || *capacity == 0) {
        // Allocate memory for the initial array with at least N elements
        *capacity = N;
        *p_array = malloc(*capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        assert(*p_array != NULL);
    } else if (max_size > 0 && *capacity >= max_size) {
        // Do not allow the array to grow beyond a certain maximum size
        return;
    } else {
        // Double the capacity of the array if it is half full
        if (*capacity / 2 >= N) {
            *capacity *= 2;
        } else {
            // Otherwise, increment the capacity by 1
            *capacity += 1;
        }
        void* tmp = realloc(*p_array, *capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        assert(tmp != NULL);
        *p_array = tmp;
    }

    // Initialize the array with at least N elements
    for (size_t i = 0; i < (*capacity > N ? *capacity : N); ++i) {
        // Assign a unique tag for each element in the array
        (*p_array)[i].rx_ue_information_tag = i + 1;
        // Populate the rnti field with a unique identifier derived from rx_ue_information_tag
        (*p_array)[i].rnti = (*p_array)[i].rx_ue_information_tag + 10000;
        // Set crcflag to a random value for each element, ensuring no two elements share the same crcflag
        (*p_array)[i].crcflag = rand() % 256;
    }
}

// Method to iterate over the array and print the contents of each NFAPI_CRC_INDICATION_PDU_T structure
void print_crc_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        printf("rx_ue_information_tag: %u\nrnti: %u\ncrcflag: %u\n", array[i].rx_ue_information_tag, array[i].rnti, array[i].crcflag);
    }
}
