#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <curl/curl.h>

// Define a structure to represent an element in the data structure
struct element {
    double price;
    char market_state;
    struct node* order_history;
};

// Define a structure to represent a linked list of nodes for order history
struct node {
    int order_id;
    double order_price;
    struct node* next;
};

// Define a function to generate random numbers within a specified range
double generate_random_number(int min, int max) {
    return (((double)rand() / RAND_MAX) * (max - min)) + min;
}

// Define a function to generate a random letter indicating market conditions
char generate_market_state() {
    char states[] = {'A', 'B', 'C', 'D'};
    return states[rand() % 4];
}

// Define a function to dynamically allocate memory for and initialize an array of elements
struct element* generate_elements(int num_elements) {
    struct element* elements = malloc(sizeof(struct element) * num_elements);
    if (!elements) {
        return NULL;
    }

    for (int i = 0; i < num_elements; i++) {
        elements[i].price = generate_random_number(100, 500);
        elements[i].market_state = generate_market_state();
        elements[i].order_history = NULL;
    }

    return elements;
}

// Define a function to release memory allocated for an element array
void free_elements(struct element* elements) {
    if (!elements) {
        return;
    }

    for (int i = 0; i < num_elements; i++) {
        struct node* current = elements[i].order_history;
        while (current != NULL) {
            struct node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(elements);
}

