// Thread-safe mechanism to handle simultaneous access from multiple threads
void synchronize_threads(struct MemoryPool* pool, struct Record* record) {
  // Acquire a lock on the memory pool
  pthread_mutex_lock(&pool->mutex);

  // Allocate memory for the record within the pool
  record->data = (unsigned char*)malloc(sizeof(unsigned char) * record->size);

  // Release the lock on the memory pool
  pthread_mutex_unlock(&pool->mutex);
}

