// Function to add a new entry to the list with specified value and identifier
int list_add(List *list, long value, char id) {
    Entry *new_entry = malloc(sizeof(Entry));
    if (new_entry == NULL) {
        return -1; // allocation failed
    }
    new_entry->data = malloc(sizeof(long));
    if (new_entry->data == NULL) {
        free(new_entry);
        return -2; // allocation failed
    }
    *((long *) new_entry->data) = value;
    new_entry->id = id;

    pthread_mutex_lock(&list->lock); // acquire lock for thread-safety
    if (list->size == list->max_size) { // check if maximum size has been reached
        // increase size of entries array by a factor of 2
        Entry **new_entries = realloc(list->entries, 2 * list->size * sizeof(Entry));
        if (new_entries == NULL) {
            free(new_entry->data);
            free(new_entry);
            pthread_mutex_unlock(&list->lock); // release lock
            return -3; // reallocation failed
        }
        list->entries = new_entries;
    }
    list->entries[list->size] = new_entry;
    list->size++;
    pthread_mutex_unlock(&list->lock); // release lock
    return 0;
}

// Function to iterate over the entries in the list and print their values
void list_iterate(List *list) {
    for (int i = 0; i < list->size; i++) {
        Entry *entry = list->entries[i];
        printf("%ld\n", *((long *) entry->data));
    }
}

// Function to remove an entry from the list with specified identifier
void list_remove(List *list, char id) {
    pthread_mutex_lock(&list->lock); // acquire lock for thread-safety
    for (int i = 0; i < list->size; i++) {
        Entry *entry = list->entries[i];
        if (entry->id == id) {
            free(entry->data);
            free(entry);
            // shift remaining entries in the array to fill the gap
            for (int j = i; j < list->size - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock); // release lock
}

// Function to remove unused entries from the list periodically
void list_garbage_collect(List *list) {
    for (int i = 0; i < list->size; i++) {
        Entry *entry = list->entries[i];
        if (!entry->data) { // check if entry is unused
            free(entry);
            // shift remaining entries in the array to fill the gap
            for (int j = i; j < list->size - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->size--;
        }
    }
}
