} Record;

// A data structure to store the Union-Find data structure for disjoint sets of keys
typedef struct UFNode {
    int rank; // The rank of the node in the Union-Find tree
    int parent; // The parent node of the current node, or -1 if it is a root node
} UFNode;

// A data structure to store the key array and the Union-Find data structure
typedef struct KeyArrayAndUF {
    Record **key_array; // An array of pointers to records with unique keys
    int num_records; // The number of records in the key array
    UFNode *uf; // The Union-Find data structure for disjoint sets of keys
} KeyArrayAndUF;

// A function to initialize and manage a dynamic collection of records, each containing a unique int key, long offset, and RX_UE_INFORMATION_TAG with a CRC indication flag
void initKeyArrayAndUF(int initial_size, int max_num_operations) {
    // Initialize the key array and the Union-Find data structure
    KeyArrayAndUF *key_array_and_uf = (KeyArrayAndUF *)malloc(sizeof(KeyArrayAndUF));
    key_array_and_uf->key_array = (Record **)malloc(initial_size * sizeof(Record *));
    key_array_and_uf->num_records = 0;
    key_array_and_uf->uf = (UFNode *)malloc(initial_size * sizeof(UFNode));

    // Set the rank of each node in the Union-Find tree to 1
    for (int i = 0; i < initial_size; i++) {
        key_array_and_uf->uf[i].rank = 1;
    }

    // Set the parent of each node to itself
    for (int i = 0; i < initial_size; i++) {
        key_array_and_uf->uf[i].parent = i;
    }
}

// A function to handle the creation and population of records in a scalable manner, ensuring efficient memory usage and performance under varying input sizes
void populateKeyArrayAndUF(int num_records, int initial_size) {
    // Allocate memory for the key array and initialize it with random values within the specified range
    Record **key_array = (Record **)malloc(num_records * sizeof(Record *));
    srand((unsigned)time(NULL));

    for (int i = 0; i < num_records; i++) {
        int random_value = rand() % initial_size;
        key_array[i] = (Record *)malloc(sizeof(Record));
        key_array[i]->key = random_value;
    }

    // Allocate memory for the Union-Find data structure and initialize it with the key array
    UFNode *uf = (UFNode *)malloc(num_records * sizeof(UFNode));
    for (int i = 0; i < num_records; i++) {
        uf[i].rank = 1;
        uf[i].parent = -1;
    }

    // Union the key array with itself to create disjoint sets of keys
    for (int i = 0; i < num_records; i++) {
        uf[i].parent = i;
    }

    // Set the initial size of the key array and the Union-Find data structure
    int current_size = initial_size;
    while (current_size < num_records) {
        current_size *= 2;
    }
    KeyArrayAndUF *key_array_and_uf = (KeyArrayAndUF *)malloc(sizeof(KeyArrayAndUF));
    key_array_and_uf->key_array = key_array;
    key_array_and_uf->num_records = num_records;
    key_array_and_uf->uf = uf;
}

// A function to handle the dynamic resizing of the data structures to accommodate additional records while minimizing memory fragmentation and maximizing cache utilization
void resizeKeyArrayAndUF(int new_size) {
    // Allocate memory for the new key array and Union-Find data structure
    Record **new_key_array = (Record **)malloc(new_size * sizeof(Record *));
    UFNode *new_uf = (UFNode *)malloc(new_size * sizeof(UFNode));

    // Copy the contents of the old key array and Union-Find data structure to the new ones
    for (int i = 0; i < key_array_and_uf->num_records; i++) {
        new_key_array[i] = key_array_and_uf->key_array[i];
        new_uf[i].rank = uf[i].rank;
        new_uf[i].parent = uf[i].parent;
