Here is an example of how to implement a dynamic array of `data_entry` structures that manages log messages, using a linked list for efficient memory allocation and deallocation under high-load conditions:
```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure to hold log message data
typedef struct {
    char *buffer; // dynamically allocated buffer for log messages
    int key; // integer key representing the log level
    time_t timestamp; // timestamp for the log message
} data_entry;

// Linked list node structure for managing data entries
typedef struct node {
    data_entry *data;
    struct node *next;
} node;

// Function to add a new entry to the linked list
void add_entry(node **head, int key, char *buffer) {
    // Allocate memory for the new node
    node *new_node = malloc(sizeof(node));
    if (!new_node) {
        // Handle memory allocation failure
        return;
    }

    // Set the data for the new node
    new_node->data = malloc(sizeof(data_entry));
    if (!new_node->data) {
        free(new_node);
        // Handle memory allocation failure
        return;
    }
    new_node->data->key = key;
    new_node->data->buffer = buffer;

    // Add the new node to the beginning of the linked list
    new_node->next = *head;
    *head = new_node;
}

// Function to update an existing entry in the linked list
void update_entry(node **head, int key, char *buffer) {
    // Find the node with the matching key
    node *current = *head;
    while (current != NULL && current->data->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // No entry found, add a new one
        add_entry(head, key, buffer);
    } else {
        // Update the existing node with the new data
        free(current->data->buffer);
        current->data->buffer = buffer;
    }
}

// Function to retrieve an entry from the linked list based on the key
void get_entry(node *head, int key) {
    // Find the node with the matching key
    node *current = head;
    while (current != NULL && current->data->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // No entry found, return an empty data entry
        return;
    } else {
        // Return the data for the matching node
        return current->data;
    }
}

// Function to deallocate all allocated memory when the function is destroyed or when the application shuts down gracefully
void destroy_entries(node *head) {
    while (head != NULL) {
        // Free the data buffer and the node itself
        free(head->data->buffer);
        free(head);
        head = head->next;
    }
}
```
This implementation uses a linked list to efficiently manage memory allocation and deallocation under high-load conditions. The `add_entry` function adds a new entry to the beginning of the linked list, while the `update_entry` function updates an existing entry in the linked list based on the key. The `get_entry` function retrieves an entry from the linked list based on the key and returns it. The `destroy_entries` function deallocates all allocated memory when the function is destroyed or when the application shuts down gracefully.

Note that this implementation assumes that the log messages are added and updated in order, with the most recent message being at the beginning of the linked list. If the log messages are not guaranteed to be added and updated in order, a separate data structure such as a hash table or a tree might be more appropriate for storing and retrieving the log entries.']

