    size_t capacity; // Maximum number of elements in the array
    size_t size; // Current number of elements in the array
    NFAPI_CRC_INDICATION_PDU_T* elements; // Array of CRC indication structures
} NFAPI_CRC_INDICATION_ARRAY;

// Function to initialize and allocate memory for the dynamic array
NFAPI_CRC_INDICATION_ARRAY* manage_crc_indications(size_t max_size) {
    // Allocate memory for the structure that stores the array
    NFAPI_CRC_INDICATION_ARRAY* crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY));
    if (crc_indications == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for CRC indications\n");
        return NULL;
    }

    // Initialize the structure members
    crc_indications->capacity = max_size;
    crc_indications->size = 0;
    crc_indications->elements = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications->elements == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for CRC indication elements\n");
        free(crc_indications);
        return NULL;
    }

    // Initialize each element of the array with unique values
    for (size_t i = 0; i < crc_indications->capacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &(crc_indications->elements[i]);

        // Generate a unique value for rx_ue_information_tag based on the index and a static offset
        uint16_t rx_ue_info_tag = (uint16_t)(i + 0x3214);

        // Derive a unique identifier from rx_ue_information_tag to ensure each RNTI is distinct
        uint16_t rnti = (uint16_t)(rx_ue_info_tag % 65536 + 1);

        // Set the crc_indication_rel8_tag field to a random value for each element
        uint8_t crcflag = (uint8_t)((rand() % 255) + 1);

        // Store the generated values in the array element
        element->rx_ue_information_tag = rx_ue_info_tag;
        element->rnti = rnti;
        element->crc_indication_rel8_tag = crcflag;
    }

    return crc_indications;
}

// Function to insert a new CRC indication into the dynamic array
