// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication(NFAPI_CRC_INDICATION_LL **head, uint16_t RNTI, uint8_t CRCFLAG) {
    // Allocate memory for the new NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        // Handle insufficient memory for allocation
        printf("Error: Insufficient memory for allocation\n");
        return;
    }

    // Initialize the new NFAPI_CRC_INDICATION_PDU_T structure with the input parameters
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_pdu->CRCFLAG = CRCFLAG;

    // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the linked list
    NFAPI_CRC_INDICATION_LL *curr = *head;
    while (curr != NULL && curr->next != NULL) {
        curr = curr->next;
    }
    if (curr == NULL) {
        // The linked list is empty, so add the new structure to the head of the list
        curr = malloc(sizeof(NFAPI_CRC_INDICATION_LL));
        if (curr == NULL) {
            // Handle insufficient memory for allocation
            printf("Error: Insufficient memory for allocation\n");
            free(new_pdu);
            return;
        }
        curr->next = NULL;
        *head = curr;
    } else {
        // Add the new structure to the end of the linked list
        NFAPI_CRC_INDICATION_LL *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_LL));
        if (new_node == NULL) {
            // Handle insufficient memory for allocation
            printf("Error: Insufficient memory for allocation\n");
            free(new_pdu);
            return;
        }
        curr->next = new_node;
    }
    new_node->pdu = new_pdu;

    // Iterate over the linked list and modify the CRCFLAG of specific entries based on the value of RNTI
    NFAPI_CRC_INDICATION_LL *curr_node = *head;
    while (curr_node != NULL) {
        if (curr_node->pdu->RNTI == RNTI) {
            curr_node->pdu->CRCFLAG = CRCFLAG;
        }
        curr_node = curr_node->next;
    }
}

// Function to iterate over the linked list and free memory for all allocated NFAPI_CRC_INDICATION_PDU_T structures
void free_nfapi_crc_indication(NFAPI_CRC_INDICATION_LL **head) {
    // Iterate over the linked list and free memory for each NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_LL *curr = *head;
    while (curr != NULL) {
        NFAPI_CRC_INDICATION_LL *next = curr->next;
        free(curr->pdu);
        free(curr);
        curr = next;
    }
}
