// Function to dynamically allocate memory for and initialize the arrays of 'long', 'int', and 'record' structures
void init_arrays(long **offset_arr, int **key_arr, record_t ***rec_arr) {
    // Allocate memory for the offset array
    *offset_arr = (long *)malloc(sizeof(long) * 10);
    if (*offset_arr == NULL) {
        perror("Failed to allocate memory for offset array");
        return;
    }

    // Initialize the offset array with random values within a given range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 10; i++) {
        (*offset_arr)[i] = rand() % 100;
    }

    // Allocate memory for the key array
    *key_arr = (int *)malloc(sizeof(int) * 10);
    if (*key_arr == NULL) {
        perror("Failed to allocate memory for key array");
        return;
    }

    // Initialize the key array with random values within a given range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 10; i++) {
        (*key_arr)[i] = rand() % 100;
    }

    // Allocate memory for the record array
    *rec_arr = (record_t **)malloc(sizeof(record_t *) * 10);
    if (*rec_arr == NULL) {
        perror("Failed to allocate memory for record array");
        return;
    }

    // Initialize the record array with random values within a given range and allocate memory for each record's char buffer
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 10; i++) {
        (*rec_arr)[i] = malloc(sizeof(record_t));
        if ((*rec_arr)[i] == NULL) {
            perror("Failed to allocate memory for record structure");
            return;
        }

        // Set the value of each record's int field to a random value within a given range
        (*rec_arr)[i]->value = rand() % 100;

        // Allocate memory for each record's char buffer and initialize it with random values
        size_t buf_size = sizeof(char) * (rand() % 50 + 1);
        (*rec_arr)[i]->buffer = malloc(buf_size);
        if ((*rec_arr)[i]->buffer == NULL) {
            perror("Failed to allocate memory for record buffer");
            return;
        }

        memset((*rec_arr)[i]->buffer, 0, buf_size);
    }
}

int main() {
    long *offset_arr = NULL;
    int *key_arr = NULL;
    record_t **rec_arr = NULL;

    init_arrays(&offset_arr, &key_arr, &rec_arr);

    // Use the arrays for your desired purpose...

    free(offset_arr);
    free(key_arr);
    for (int i = 0; i < 10; i++) {
        free((*rec_arr)[i]->buffer);
        free((*rec_arr)[i]);
    }
    free(rec_arr);

    return 0;
}
